('yks-2026-tarih#16', 'yks-2026-tarih', '11. Sınıf · 5. XIX ve XX. Yüzyılda Değişen Sosyo-Ekonomik Hayat', 16, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00')
INSERT INTO public.curriculum_outcomes (id, program_id, unit_id, code, text, topic, limitations, quotas, sort_order, source_id, quota_source_id, text_similarity, source_url, program_version, sha256, fetched_at) VALUES
('yks-2026-biyoloji#1', 'yks-2026-biyoloji', 'yks-2026-biyoloji#1', '9.1.1.1', 'Canlıların ortak özelliklerini irdeler.', NULL, '["a. Canlı kavramı üzerinden biyolojinin günümüzdeki anlamı ile nasıl kullanıldığı kısaca belirtilir. b. Canlıların; hücresel yapı, beslenme, solunum, boşaltım, hareket, uyarılara tepki, metabolizma, homeostazi, uyum, organizasyon, üreme, büyüme ve gelişme özellikleri vurgulanır."]'::jsonb, '{}'::jsonb, 1, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#2', 'yks-2026-biyoloji', 'yks-2026-biyoloji#1', '9.1.2.1', 'Canlıların yapısını oluşturan organik ve inorganik bileşikleri açıklar.', NULL, '["a. Su, mineraller, asitler, bazlar ve tuzların canlılar için önemi belirtilir. b. Kalsiyum, potasyum, demir, iyot, flor, magnezyum, sodyum, fosfor, klor, kükürt, çinko minerallerinin canlılar için önemi vurgulanır. c. Karbonhidratların, lipitlerin, proteinlerin, nükleik asitlerin, enzimlerin yapısı, görevi ve canlılar için önemi belirtilir. ç. DNA’nın tüm canlı türlerinde bulunduğu ve aynı nükleotitleri içerdiği vurgulanır. d. ATP''nin ve hormonların kimyasal formüllerine yer verilmeden canlılar için önemi sorgulanır. e. Vitaminlerin genel özellikleri verilir. A, D, E, K, B ve C vitaminlerinin görevleri ve canlılar için önemi belirtilir. B grubu vitaminlerinin çeşitlerine girilmez. f. Öğrencilerin besinlerdeki karbonhidrat, lipit ve proteinin varlığını tespit edebilecekleri deneyler yapmaları sağlanır. g. Enzim aktivitesine etki eden faktörlerle ilgili deneyler yapılması sağlanır."]'::jsonb, '{}'::jsonb, 2, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#3', 'yks-2026-biyoloji', 'yks-2026-biyoloji#1', '9.1.2.2', 'Lipit, karbonhidrat, protein, vitamin, su ve minerallerin sağlıklı beslenme ile ilişkisini kurar.', NULL, '["a. İnsülin direnci, diyabet ve obeziteye sağlıklı beslenme bağlamında değinilir. b. Öğrencilerin kendi yaş grubu için bir haftalık sağlıklı beslenme programı hazırlamaları sağlanır."]'::jsonb, '{}'::jsonb, 3, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#4', 'yks-2026-biyoloji', 'yks-2026-biyoloji#2', '9.2.1.1', 'Hücre teorisine ilişkin çalışmaları açıklar.', NULL, '["a. Hücreye ilişkin bilgilere tarihsel süreç içerisinde katkı sağlayan bilim insanlarına (Robert Hooke, Antonie van Leeuwenhoek, Matthias Schleiden, Theodor Schwann ve Rudolf Virchow) örnekler verilir. Ancak bu isimlerin ezberlenmesi ve kronolojik sırasının bilinmesi beklenmez. b. Mikroskop çeşitleri ve ileri görüntüleme teknolojilerinin kullanmasının hücre teorisine katkıları araştırılır."]'::jsonb, '{}'::jsonb, 4, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#5', 'yks-2026-biyoloji', 'yks-2026-biyoloji#2', '9.2.1.2', 'Hücresel yapıları ve görevlerini açıklar.', NULL, '["a. Prokaryot hücrelerin kısımları gösterilir. b. Ökaryot hücrelerin yapısı ve bu yapıyı oluşturan kısımlar gösterilir. c. Organellerin hücrede aldıkları görevler bakımından incelenmesi sağlanır. ç. Hücre örneklerinin mikroskop ile incelenmesi sağlanır. d. Hücre içi iş birliği ve organizasyona dikkat çekilerek herhangi bir organelde oluşan problemin hücreye olası etkilerinin tartışılması sağlanır. e. Farklı hücre örnekleri karşılaştırılırken öncelikle mikroskop, görsel ögeler (fotoğraflar, resimler, çizimler, karikatürler vb.), grafik düzenleyiciler (kavram haritaları, zihin haritaları, şemalar vb.), e- öğrenme nesnesi ve uygulamalarından (animasyon, video, simülasyon, infografik, artırılmış ve sanal gerçeklik uygulamaları vb.) yararlanılır."]'::jsonb, '{}'::jsonb, 5, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#6', 'yks-2026-biyoloji', 'yks-2026-biyoloji#2', '9.2.1.3', 'Hücre zarından madde geçişine ilişkin kontrollü bir deney yapar.', NULL, '["a. Hücre zarından madde geçişine ilişkin deney öncesi bilimsel yöntem basamakları bir örnekle açıklanır. b. Biyoloji laboratuvarında kullanılan temel araç gereçler tanıtılarak laboratuvar güvenliği vurgulanır. c. Hücre zarından madde geçişini etkileyen faktörlerden (yüzey alanı, konsantrasyon farkı, sıcaklık) biri hakkında kontrollü deney yaptırılır."]'::jsonb, '{}'::jsonb, 6, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#7', 'yks-2026-biyoloji', 'yks-2026-biyoloji#3', '9.3.1.1', 'Canlıların çeşitliliğinin anlaşılmasında sınıflandırmanın önemini açıklar.', NULL, '["a. Canlıların sınıflandırılmasında bilim insanlarının kullandığı farklı ölçüt ve yaklaşımlar tartışılır. b. Canlı çeşitliliğindeki değişimler nesli tükenmiş canlılar örneği üzerinden tartışılır."]'::jsonb, '{}'::jsonb, 7, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#8', 'yks-2026-biyoloji', 'yks-2026-biyoloji#3', '9.3.1.2', 'Canlıların sınıflandırılmasında kullanılan kategorileri ve bu kategoriler arasındaki hiyerarşiyi örneklerle açıklar.', NULL, '["a. Canlıların sınıflandırılmasında sadece tür, cins, aile, takım, sınıf, şube ve âlem kategorilerinin genel özelliklerine değinilir. b. Carolus Linnaeus’un sınıflandırmayla ilgili çalışmalarına değinilir. c. Hiyerarşik kategoriler dikkate alınarak çevreden seçilecek canlı türleriyle ilgili ikili adlandırma örnekleri verilir. ç. Öğrencilerin canlılar dünyası ile ilgili çektiği/edindiği fotoğraflarlardan video veya bir ürün oluşturmaları sağlanır."]'::jsonb, '{}'::jsonb, 8, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#9', 'yks-2026-biyoloji', 'yks-2026-biyoloji#3', '9.3.2.1', 'Canlıların sınıflandırılmasında kullanılan âlemleri ve bu âlemlerin genel özelliklerini açıklar.', NULL, '["a. Bakteriler, arkeler, protistler, bitkiler, mantarlar, hayvanlar âlemlerinin genel özellikleri açıklanarak örnekler verilir. Hayvanlar âleminin dışında diğer âlemlerin sınıflandırmasına girilmez. b. Hayvanlar âleminin; omurgasız hayvanlar (süngerler, sölentereler, solucanlar, yumuşakçalar, eklembacaklılar, derisidikenliler) ve omurgalı hayvanlar (balıklar, iki yaşamlılar, sürüngenler, kuşlar, memeliler) şubelerinin, sınıflarına ait genel özellikler belirtilerek örnekler verilir, yapı ve sistematiğine girilmez. c. Canlıların sınıflandırması bağlamında, bilimsel bilginin sınandığı, düzeltildiği veya yenilendiği belirtilir."]'::jsonb, '{}'::jsonb, 9, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#10', 'yks-2026-biyoloji', 'yks-2026-biyoloji#3', '9.3.2.2', 'Canlıların biyolojik süreçlere, ekonomiye ve teknolojiye katkılarını örneklerle açıklar.', NULL, '["Canlılardan esinlenilerek geliştirilen teknolojilere örnekler verilir."]'::jsonb, '{}'::jsonb, 10, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#11', 'yks-2026-biyoloji', 'yks-2026-biyoloji#3', '9.3.2.3', 'Virüslerin genel özelliklerini açıklar.', NULL, '["a. Virüslerin biyolojik sınıflandırma kategorileri içine alınmamasının nedenleri üzerinde durulur. b. Virüslerin insan sağlığı üzerine etkilerinin kuduz, hepatit, grip, uçuk ve AIDS hastalıkları üzerinden tartışılması sağlanır. Virütik hastalıklara karşı alınacak önlemler vurgulanır. c. Virüslerin genetik mühendisliği alanında yapılan çalışmalar için yeni imkânlar sunduğu vurgulanır."]'::jsonb, '{}'::jsonb, 11, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#12', 'yks-2026-biyoloji', 'yks-2026-biyoloji#4', '10.1.1.1', 'Canlılarda hücre bölünmesinin gerekliliğini açıklar.', NULL, '["a. Hücre bölünmesinin canlılarda üreme, büyüme ve gelişme ile ilişkilendirilerek açıklanması sağlanır. b. Bölünmenin hücresel gerekçeleri üzerinde durulur."]'::jsonb, '{}'::jsonb, 12, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#13', 'yks-2026-biyoloji', 'yks-2026-biyoloji#4', '10.1.1.2', 'Mitozu açıklar.', NULL, '["a. İnterfaz temel düzeyde işlenir. b. Mitozun evreleri temel düzeyde işlenir. Evreler açıklanırken mikroskop, görsel ögeler (fotoğraflar, resimler, çizimler, karikatürler vb.) ve grafik düzenleyiciler (kavram haritaları, zihin haritaları, şemalar vb.), e-öğrenme nesnesi ve uygulamalarından (animasyon, video, simülasyon, infografik, artırılmış ve sanal gerçeklik uygulamaları vb.) faydalanılır. c. Hücre bölünmesinin kontrolü ve bunun canlılar için önemi üzerinde durulur. Hücre bölünmesini kontrol eden moleküllerin isimleri verilmez. ç. Hücre bölünmesinin kanserle ilişkisi kurulur. d. Öğrencilerin mitozu açıklayan bir ürün veya elektronik sunu (animasyon, video vb.) hazırlamaları ve bu sunuyu paylaşmaları sağlanır."]'::jsonb, '{}'::jsonb, 13, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#14', 'yks-2026-biyoloji', 'yks-2026-biyoloji#4', '10.1.1.3', 'Eşeysiz üremeyi örneklerle açıklar.', NULL, '["a. Eşeysiz üreme bağlamında bölünerek üreme, tomurcuklanma, sporla üreme, rejenerasyon partenogenez ve bitkilerde vejetatif üreme örnekleri verilir. Sporla üremede sadece örnek verilir, döl almaşına girilmez. b. Eşeysiz üreme tekniklerinin bahçecilik ve tarım sektörlerindeki uygulamaları (çelikle ve soğanla üreme şekilleri) örneklendirilir."]'::jsonb, '{}'::jsonb, 14, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#15', 'yks-2026-biyoloji', 'yks-2026-biyoloji#4', '10.1.2.1', 'Mayozu açıklar.', NULL, '["a. Mayozun evreleri temel düzeyde işlenir. Evreler açıklanırken mikroskop, görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından faydalanılır. b. Öğrencilerin mayozu açıklayan bir elektronik sunu (animasyon, video vb.) hazırlamaları ve bu sunuyu paylaşmaları sağlanır."]'::jsonb, '{}'::jsonb, 15, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#16', 'yks-2026-biyoloji', 'yks-2026-biyoloji#4', '10.1.2.2', 'Eşeyli üremeyi örneklerle açıklar.', NULL, '["a. Dış döllenme ve iç döllenme konusu verilmez. b. Eşeyli üremenin temelinin mayoz ve döllenme olduğu açıklanır."]'::jsonb, '{}'::jsonb, 16, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#17', 'yks-2026-biyoloji', 'yks-2026-biyoloji#5', '10.2.1.1', 'Kalıtımın genel esaslarını açıklar.', NULL, '["a. Mendel ilkeleri örneklerle açıklanır. b. Monohibrit, dihibrit ve kontrol çaprazlamaları, eş baskınlık, çok alellilik (Kan gruplarıyla ilişkilendirilir.) örnekler üzerinden işlenir. Eksik baskınlık ve pleiotropizme girilmez. c. Eşeye bağlı kalıtım; hemofili ve kısmi renk körlüğü hastalıkları bağlamında ele alınır. Eşeye bağlı kalıtımın Y kromozomunda da görüldüğü belirtilir. ç. Soyağacı örneklerle açıklanır. d. Kalıtsal hastalıkların ortaya çıkma olasılığının akraba evlilikleri sonucunda arttığı vurgusu yapılır."]'::jsonb, '{}'::jsonb, 17, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#18', 'yks-2026-biyoloji', 'yks-2026-biyoloji#5', '10.2.1.2', 'Genetik varyasyonların biyolojik çeşitliliği açıklamadaki rolünü sorgular.', NULL, '["a. Varyasyonların kaynaklarının (mutasyon, kromozomların bağımsız dağılımı ve krossing over) tartışılması sağlanır. Mutasyon çeşitlerine girilmez. b. Biyolojik çeşitliliğin canlıların genotiplerindeki farklılıklardan kaynaklandığı açıklanır."]'::jsonb, '{}'::jsonb, 18, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#19', 'yks-2026-biyoloji', 'yks-2026-biyoloji#6', '10.3.1.1', 'Ekosistemin canlı ve cansız bileşenleri arasındaki ilişkiyi açıklar.', NULL, '["a. Popülasyon, komünite ve ekosistem arasındaki ilişki örneklerle açıklanır. b. Ekosistemde oluşabilecek herhangi bir değişikliğin sistemdeki olası sonuçları üzerinde durulur. c. Öğrencilerin kendi seçecekleri bir ekosistemi tanıtan bir sunu hazırlamaları sağlanır."]'::jsonb, '{}'::jsonb, 19, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#20', 'yks-2026-biyoloji', 'yks-2026-biyoloji#6', '10.3.1.2', 'Canlılardaki beslenme şekillerini örneklerle açıklar.', NULL, '["Simbiyotik yaşama girilmez."]'::jsonb, '{}'::jsonb, 20, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#21', 'yks-2026-biyoloji', 'yks-2026-biyoloji#6', '10.3.1.3', 'Ekosistemde madde ve enerji akışını analiz eder.', NULL, '["a. Madde ve enerji akışında üretici, tüketici ve ayrıştırıcıların rolünün incelenmesi sağlanır. b. Ekosistemlerde madde ve enerji akışı; besin zinciri, besin ağı ve besin piramidi ile ilişkilendirilerek örneklendirilir. c. Biyolojik birikimin insan sağlığı ve diğer canlılar üzerine olumsuz etkilerinin araştırılması ve tartışılması sağlanır. ç. Öğrencilerin canlılar arasındaki beslenme ilişkilerini gösteren bir besin ağı kurgulaması sağlanır."]'::jsonb, '{}'::jsonb, 21, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#22', 'yks-2026-biyoloji', 'yks-2026-biyoloji#6', '10.3.1.4', 'Madde döngüleri ve hayatın sürdürülebilirliği arasında ilişki kurar.', NULL, '["a. Azot, karbon ve su döngüleri hatırlatılır. b. Azot döngüsünde yer alan mikroorganizmaların tür isimleri verilmez."]'::jsonb, '{}'::jsonb, 22, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#23', 'yks-2026-biyoloji', 'yks-2026-biyoloji#6', '10.3.2.1', 'Güncel çevre sorunlarının sebeplerini ve olası sonuçlarını değerlendirir.', NULL, '["a. Güncel çevre sorunları (biyolojik çeşitliliğin azalması, hava kirliliği, su kirliliği, toprak kirliliği, radyoaktif kirlilik, ses kirliliği, asit yağmurları, küresel iklim değişikliği, erozyon, doğal hayat alanlarının tahribi ve orman yangınları) özetlenerek bu sorunların canlılar üzerindeki olumsuz etkileri belirtilir. b. Çevre sorunları nedeniyle ortaya çıkan hastalıklara vurgu yapılır."]'::jsonb, '{}'::jsonb, 23, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#24', 'yks-2026-biyoloji', 'yks-2026-biyoloji#6', '10.3.2.2', 'Birey olarak çevre sorunlarının ortaya çıkmasındaki rolünü sorgular.', NULL, '["a. Ekolojik ayak izi, su ayak izi ve karbon ayak izi ile ilgili uygulamalar yaptırılır. b. Ekolojik ayak izi, su ayak izi ve karbon ayak izini küçültmek için çözüm önerileri geliştirmesi sağlanır."]'::jsonb, '{}'::jsonb, 24, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#25', 'yks-2026-biyoloji', 'yks-2026-biyoloji#6', '10.3.2.3', 'Yerel ve küresel bağlamda çevre kirliliğinin önlenmesine yönelik çözüm önerilerinde bulunur.', NULL, '["a. Yerel ve küresel bağlamda çevre kirliliğinin önlenmesi için yapılan çalışmalara örnekler verilir. b. Yerel ve küresel boyutta çevreye zarar veren insan faaliyetlerinin tartışılması sağlanır. c. Çevre kirliliğinin önlenmesinde biyolojinin digger disiplinler ile nasıl ilişkilendirildiğine örnekler verir."]'::jsonb, '{}'::jsonb, 25, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#26', 'yks-2026-biyoloji', 'yks-2026-biyoloji#6', '10.3.3.1', 'Doğal kaynakların sürdürülebilirliğinin önemini açıklar.', NULL, '["a. Doğal kaynakların sürdürülebilirliği için Türkiye genelindeki başarılı uygulamalar örneklendirilerek çevre farkındalığının önemi vurgulanır. b. Gelecek nesillere yaşanabilir sağlıklı bir dünya emanet edebilmek için doğal kaynakların israf edilmemesi gerekliliği vurgulanır."]'::jsonb, '{}'::jsonb, 26, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#27', 'yks-2026-biyoloji', 'yks-2026-biyoloji#6', '10.3.3.2', 'Biyolojik çeşitliliğin yaşam için önemini sorgular.', NULL, '["a. Türkiye''nin biyolojik çeşitlilik açısından zengin olmasını sağlayan faktörlerin tartışılması sağlanır. b. Endemik türlerin ülkemizin biyolojik çeşitliliği açısından değeri ve önemi üzerinde durularak sağlık ve ekonomiye katkılarına ilişkin örneklere yer verilir. c. Biyolojik çeşitlilik ve endemik türlerin küresel ve millî bir miras olduğu vurgulanır. ç. Tabiatta her canlının önemli işlevler gördüğü vurgulanarak biyolojik çeşitliliğe ve ekosistemin doğal işleyişine saygı göstermenin ve bunlara müdahaleden kaçınmanın önemi açıklanır. d. Soyu tükenen türlerin biyolojik çeşitlilik açısından yeri doldurulamayacak bir kayıp olduğu vurgulanır."]'::jsonb, '{}'::jsonb, 27, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#28', 'yks-2026-biyoloji', 'yks-2026-biyoloji#6', '10.3.3.3', 'Biyolojik çeşitliliğin korunmasına yönelik çözüm önerilerinde bulunur.', NULL, '["a. Türkiye''de nesli tükenme tehlikesi altında bulunan canlı türleri ile endemik türlerin korunmasına yönelik yapılan çalışmalar örneklendirilir. b. Biyolojik çeşitliliğin korunması ve biyokaçakçılığın önlenmesine yönelik çözüm önerilerinin tartışılması sağlanır. c. Gen bankalarının gerekliliği belirtilir."]'::jsonb, '{}'::jsonb, 28, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#29', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.1.1', 'Sinir sisteminin yapı, görev ve işleyişini açıklar.', NULL, '["a. Sinir doku belirtilir. Yapılarına göre nöron çeşitlerine girilmez. b. İmpuls iletiminin elektriksel ve kimyasal olduğu vurgulanır. c. Sinir Sistemi merkezî ve çevresel sinir sistemi olarak verilir.Merkezî sinir sisteminin bölümlerinden beyin için; ön beyin ( uç ve ara beyin), orta beyin ve arka beynin ( pons, omurilik soğanı, beyincik) görevleri kısaca açıklanarak beynin alt yapı ve görevlerine girilmez. Omuriliğin görevleri ile refleks yayı açıklanır ve refleksin insan yaşamı için önemi vurgulanır. ç. Çevresel sinir sisteminde, somatik ve otonom sinir sisteminin genel özellikleri verilir. Sempatik ve parasempatik sinirler ayrımına girilmez. d. Merkezî ve çevresel sinir sisteminin yapısı işlenirken görsel ögeler (fotoğraflar, resimler, çizimler, karikatürler vb.) ve grafik düzenleyiciler (kavram haritaları, zihin haritaları, şemalar vb.), e-öğrenme nesnesi ve uygulamalarından (animasyon, video, simülasyon, infografik, artırılmış ve sanal gerçeklik uygulamaları vb.) yararlanılır. e. İbn Sina ‘nın insan fizyolojisi ile ilgili yaptığı çalışmalarına ilişkin okuma metni verilir."]'::jsonb, '{}'::jsonb, 29, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#30', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.1.2', 'Endokrin bezleri ve bu bezlerin salgıladıkları hormonları açıklar.', NULL, '["a. Endokrin bezleri ve bu bezlerin salgıladıkları hormonlar işlenirken görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından yararlanılır. b. Hormonların yapısına girilmez. c. Homeostasi örnekleri (vücut sıcaklığının, kandaki kalsiyum ve glikoz oranının düzenlenmesi) açıklanır. ç. Hormonların yaşam kalitesi üzerine etkilerinin örnek bir hastalık üzerinden tartışılması sağlanır."]'::jsonb, '{}'::jsonb, 30, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#31', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.1.3', 'Sinir sistemi rahatsızlıklarına örnekler verir.', NULL, '["a. Multipl skleroz (MS), Parkinson, Alzheimer, epilepsi (sara), depresyon üzerinde durulur. b. Sinir sistemi rahatsızlıklarının tedavisiyle ilgili teknolojik gelişmelerin araştırılması sağlanır. c. Mahmut Gazi Yaşargil’in çalışmalarına değinilir."]'::jsonb, '{}'::jsonb, 31, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#32', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.1.4', 'Sinir sisteminin sağlıklı yapısının korunması için yapılması gerekenlere ilişkin çıkarımlarda bulunur.', NULL, '[]'::jsonb, '{}'::jsonb, 32, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#33', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.1.5', 'Duyu organlarının yapısını ve işleyişini açıklar.', NULL, '["a. Dokunma duyusu olan deri verilirken epitel ve temel bağ doku kısaca açıklanır. b. Duyu organlarının yapısı şema üzerinde gösterilerek açıklanır. c. Duyu organlarının yapısı işlenirken görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından yararlanılır. ç. Göz küresi bölümleri sert tabaka, damar tabaka, ağ tabaka olarak verilir, ayrıntılı yapılarına girilmez. Kulak bölümleri dış kulak, orta kulak ve iç kulak olarak verilip ayrıntılı yapılarına girilmez. d. İbn Heysem’in göz ile ilgili çalışmaları vurgulanır."]'::jsonb, '{}'::jsonb, 33, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#34', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.1.6', 'Duyu organları rahatsızlıklarını açıklar.', NULL, '["a. Renk körlüğü, miyopi, hipermetropi, astigmatizm, işitme kaybı ve denge kaybı gibi rahatsızlıkların araştırılıp sunulması sağlanır. b. Görme ve işitme engelli kişilerin karşılaştığı sorunlara dikkat çekmek ve çevresindeki bireyleri bilinçlendirmek amacıyla sosyal farkındalık etkinlikleri (proje, kamu spotu, broşür vb.) hazırlamaları sağlanır."]'::jsonb, '{}'::jsonb, 34, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#35', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.1.7', 'Duyu organlarının sağlıklı yapısının korunması için yapılması gerekenlere ilişkin çıkarımlarda bulunur.', NULL, '["Duyu organları rahatsızlıklarının tedavisiyle ilgili teknolojik gelişmelerin araştırılması sağlanır."]'::jsonb, '{}'::jsonb, 35, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#36', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.2.1', 'Destek ve hareket sisteminin yapı, görev ve işleyişini açıklar.', NULL, '["a. Kemik, kıkırdak ve kas doku açıklanır. b. Destek ve hareket sisteminin yapısı işlenirken görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından yararlanılır. c. Kemik ve kas çeşitleri açıklanır. ç. Kıkırdak ve eklem çeşitleri ile vücutta bulunduğu yerlere örnekler verilir. Yapılarına girilmez."]'::jsonb, '{}'::jsonb, 36, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#37', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.2.2', 'Destek ve hareket sistemi rahatsızlıklarını açıklar.', NULL, '["Kırık, çıkık, burkulma, menisküs ve eklem rahatsızlıklarının araştırılması ve paylaşılması sağlanır."]'::jsonb, '{}'::jsonb, 37, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#38', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.2.3', 'Destek ve hareket sisteminin sağlıklı yapısının korunması için yapılması gerekenlere ilişkin çıkarımlarda bulunur.', NULL, '["Destek ve hareket sisteminin sağlığı açısından sporun, beslenmenin ve uygun duruşun önemi tartışılır."]'::jsonb, '{}'::jsonb, 38, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#39', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.3.1', 'Sindirim sisteminin yapı, görev ve işleyişini açıklar.', NULL, '["a. Sindirim sisteminin yapısı işlenirken görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından yararlanılır. b. Sindirime yardımcı yapı ve organların (karaciğer, pankreas ve tükürük bezleri) görevleri üzerinde durulur. Yapılarına girilmez."]'::jsonb, '{}'::jsonb, 39, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#40', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.3.2', 'Sindirim sistemi rahatsızlıklarını açıklar.', NULL, '["Reflü, gastrit, ülser, hemoroit , kabızlık, ishal örnekleri verilir."]'::jsonb, '{}'::jsonb, 40, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#41', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.3.3', 'Sindirim sisteminin sağlıklı yapısının korunması için yapılması gerekenlere ilişkin çıkarımlarda bulunur.', NULL, '["a. Fiziksel etkinliklerin sindirim sisteminin sağlığına olumlu etkisi belirtilir. b. Tüketilen besinlerin temizliği, lif açısından zengin gıdalarla doğal beslenmenin önemi vurgulanır. c. Asitli içecekler tüketilmesinin ve fast-food beslenmenin sindirim sistemi üzerindeki etkilerinin tartışılması sağlanır. ç. Antibiyotik kullanımının bağırsak florasına etkileri ve bilinçsiz antibiyotik kullanımının zararları belirtilir."]'::jsonb, '{}'::jsonb, 41, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#42', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.4.1', 'Kalp, kan ve damarların yapı, görev ve işleyişini açıklar.', NULL, '["a. Kan doku açıklanır. b. Dolaşım sistemi işlenirken görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından yararlanılır. c. Kalbin çalışmasına etki eden faktörler (adrenalin, tiroksin, kafein, tein, asetilkolin, vagus siniri) üzerinde durulur. ç. Alyuvar, akyuvar ve kan pulcukları üzerinde durulur. Akyuvar çeşitleri B ve T lenfositleri ile sınırlandırılır. d. Kan grupları üzerinde durulur. Kan nakillerinde kendi grubundan kan alıp vermenin gerekliliği vurgulanır. Kan nakillerinde genel alıcı ve genel verici kavramları kullanılmaz. e. Öğrencilerin kan ve kemik iliği bağışının önemi ile ilgili farkındalık oluşturmaya yönelik çalışma (broşür, kamu spotu, anket vb.) yapmaları sağlanır. f. Konunun işlenişi sırasında model ve analojilerden yararlanılır. g. İbn Nefs’in dolaşımla ilgili görüşleri vurgulanır."]'::jsonb, '{}'::jsonb, 42, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#43', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.4.2', 'Lenf dolaşımını açıklar.', NULL, '["a. Lenf dolaşımı işlenirken görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından yararlanılır. b. Lenf dolaşımı kan dolaşımı ile ilişkilendirilerek ele alınır. c. Ödem oluşumu üzerinde durulur. ç. Lenf dolaşımının bağışıklık ile ilişkisi açıklanır."]'::jsonb, '{}'::jsonb, 43, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#44', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.4.3', 'Dolaşım sistemi rahatsızlıklarını açıklar.', NULL, '["Kalp krizi, damar tıkanıklığı, yüksek tansiyon, varis, kangren, anemi ve lösemi hastalıkları üzerinde durulur."]'::jsonb, '{}'::jsonb, 44, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#45', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.4.4', 'Dolaşım sisteminin sağlıklı yapısının korunması için yapılması gerekenlere ilişkin çıkarımlarda bulunur.', NULL, '["11.1.4.5.Bağışıklık çeşitlerini ve vücudun doğal savunma mekanizmalarını açıklar. a. Hastalık yapan organizmalar ve yabancı maddelere karşı deri, tükürük, mide öz suyu, mukus ve gözyaşının vücut savunmasındaki rolleri örneklendirilir. b. Enfeksiyon ve alerji gibi durumların bağışıklık ile ilişkisi örnekler üzerinden açıklanır. c. İmmünoglobulinler verilmez. ç. Aşılanmanın önemi üzerinde durulur. Bazı aşıların zaman içerisinde değiştirilmesinin nedenleri araştırılır. d. Hastalık yapan organizmaların genetik yapılarının hızlı değişimi nedeniyle insan sağlığına sürekli bir tehdit oluşturduğu vurgulanır."]'::jsonb, '{}'::jsonb, 45, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#46', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.5.1', 'Solunum sisteminin yapı, görev ve işleyişini açıklar.', NULL, '["a. Solunum sisteminin yapısı işlenirken görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından yararlanılır. b. Soluk alıp verme mekanizmasışema üzerinde açıklanır."]'::jsonb, '{}'::jsonb, 46, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#47', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.5.2', 'Alveollerden dokulara ve dokulardan alveollere gaz taşınmasını açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 47, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#48', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.5.3', 'Solunum sistemi hastalıklarına örnekler verir.', NULL, '["KOAH, astım, verem, akciğer ve gırtlak kanseri, zatürre hastalıkları belirtilir."]'::jsonb, '{}'::jsonb, 48, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#49', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.5.4', 'Solunum sisteminin sağlıklı yapısının korunması için yapılması gerekenlere ilişkin çıkarımlarda bulunur.', NULL, '["Yaygın olarak görülen mesleki solunum sistemi hastalıklarından korunmak için iş sağlığı ve güvenliği konusunda alınabilecek önlemlerin araştırılması ve elde edilen bilgilerin paylaşılması sağlanır."]'::jsonb, '{}'::jsonb, 49, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#50', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.6.1', 'Üriner sistemin yapı, görev ve işleyişini açıklar.', NULL, '["a. Üriner sistemin yapısı işlenirken görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından yararlanılır. b. Böbreğin alyuvar üretimine etkisi üzerinde durulur. c. Böbrek diseksiyonu ile böbreğin yapısının incelenmesi sağlanır."]'::jsonb, '{}'::jsonb, 50, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#51', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.6.2', 'Homeostasinin sağlanmasında böbreklerin rolünü belirtir.', NULL, '[]'::jsonb, '{}'::jsonb, 51, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#52', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.6.3', 'Üriner Sistem rahatsızlıklarına örnekler verir.', NULL, '["a. Böbrek taşı, böbrek yetmezliği, idrar yolu enfeksiyonu belirtilir. b. Diyaliz kısaca açıklanarak, diyalize bağımlı hastaların yaşadıkları problemler ve böbrek bağışının önemi vurgulanır."]'::jsonb, '{}'::jsonb, 52, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#53', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.6.4', 'Üriner sistemin sağlıklı yapısının korunması için yapılması gerekenlere ilişkin çıkarımlarda bulunur.', NULL, '[]'::jsonb, '{}'::jsonb, 53, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#54', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.7.1', 'Üreme sisteminin yapı, görev ve işleyişini açıklar.', NULL, '["a. Dişi ve erkek üreme sisteminin yapısı işlenirken görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından yararlanılır. b. Menstrual döngüyü düzenleyen hormonlarla ilgili grafiklere yer verilir. c. In vitro fertilizasyon yöntemleri kısaca açıklanır."]'::jsonb, '{}'::jsonb, 54, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#55', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.7.2', 'Üreme sisteminin sağlıklı yapısının korunması için yapılması gerekenlere ilişkin çıkarımlarda bulunur.', NULL, '[]'::jsonb, '{}'::jsonb, 55, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#56', 'yks-2026-biyoloji', 'yks-2026-biyoloji#7', '11.1.7.3', 'İnsanda embriyonik gelişim sürecini açıklar.', NULL, '["a. Embriyonik tabakalardan meydana gelen organlar verilmez. b. Hamilelikte bebeğin gelişimini olumsuz etkileyen faktörler (antibiyotik dahil erken hamilelik döneminde ilaç kullanımı, yoğun stres, folik asit yetersizliği, X ışınımına maruz kalma) belirtilir. c. Hamileliğin izlenmesinin bebeğin ve annenin sağlığı açısından önemi vurgulanır."]'::jsonb, '{}'::jsonb, 56, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#57', 'yks-2026-biyoloji', 'yks-2026-biyoloji#8', '11.2.1.1', 'Komünitenin yapısına etki eden faktörleri açıklar.', NULL, '["Komünitelerin içerdiği biyolojik çeşitliliğin karasal ekosistemlerde enlem, sucul ekosistemlerde ise suyun derinliği ve suyun kirliliği ile ilişkili olduğu vurgulanır."]'::jsonb, '{}'::jsonb, 57, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#58', 'yks-2026-biyoloji', 'yks-2026-biyoloji#8', '11.2.1.2', 'Komünitede tür içi ve türler arasındaki rekabeti örneklerle açıklar.', NULL, '["Komünitelerde av-avcı ilişkisi vurgulanır."]'::jsonb, '{}'::jsonb, 58, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#59', 'yks-2026-biyoloji', 'yks-2026-biyoloji#8', '11.2.1.3', 'Komünitede türler arasında simbiyotik ilişkileri örneklerle açıklar.', NULL, '["Parazitlik ve mutualizm insan sağlığı ile ilişkilendirilir (bit, pire, kene, tenya, bağırsak florası)."]'::jsonb, '{}'::jsonb, 59, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#60', 'yks-2026-biyoloji', 'yks-2026-biyoloji#8', '11.2.1.4', 'Komünitelerdeki süksesyonu örneklerle açıklar.', NULL, '["Süksesyonun evrelerine girilmez."]'::jsonb, '{}'::jsonb, 60, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#61', 'yks-2026-biyoloji', 'yks-2026-biyoloji#8', '11.2.2.1', 'Popülasyon dinamiğine etki eden faktörleri analiz eder.', NULL, '["a. İnsan yaş piramitleri üzerinde durulur. b. Popülasyon büyümesine ilişkin farklı büyüme eğrileri (S ve J) çizilir. c. Dünyada ve ülkemizde nüfus değişiminin grafikler üzerinden analiz edilmesi ve olası sonuçlarının tartışılması sağlanır."]'::jsonb, '{}'::jsonb, 61, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#62', 'yks-2026-biyoloji', 'yks-2026-biyoloji#9', '12.1.1.1', 'Nükleik asitlerin keşif sürecini özetler.', NULL, '["Rosalind Franklin, James Watson, Francis Crick çalışmaları kısaca açıklanır ancak bu isimlerin ezberlenmesi ve kronolojik sırasının bilinmesi beklenmez."]'::jsonb, '{}'::jsonb, 62, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#63', 'yks-2026-biyoloji', 'yks-2026-biyoloji#9', '12.1.1.2', 'Nükleik asitlerin çeşitlerini ve görevlerini açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 63, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#64', 'yks-2026-biyoloji', 'yks-2026-biyoloji#9', '12.1.1.3', 'Hücredeki genetik materyalin organizasyonunda parça bütün ilişkisi kurar.', NULL, '["a. Nükleotitten DNA ve kromozoma genetik materyal organizasyonunun modellenmesi sağlanır. b. Gen ve DNA ilişkisi üzerinde durulur."]'::jsonb, '{}'::jsonb, 64, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#65', 'yks-2026-biyoloji', 'yks-2026-biyoloji#9', '12.1.1.4', 'DNA'' nın kendini eşlemesini açıklar.', NULL, '["a. Helikaz, DNA polimeraz ve DNA ligaz dışındaki enzimler verilmez. b. Aziz Sancar’ın biyoloji bilimine katkısı, vatanseverliği ve bir bilim insanının genel özellikleri bağlamında şahsına vurgu yapılan bir okuma parçası verilir."]'::jsonb, '{}'::jsonb, 65, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#66', 'yks-2026-biyoloji', 'yks-2026-biyoloji#9', '12.1.2.1', 'Protein sentezinin mekanizmasını açıklar.', NULL, '["a. Genetik şifre ve protein sentezi arasındaki ilişki üzerinde durulur. b. Protein sentezi açıklanırken görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından yararlanılır."]'::jsonb, '{}'::jsonb, 66, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#67', 'yks-2026-biyoloji', 'yks-2026-biyoloji#9', '12.1.2.2', 'Genetik mühendisliği ve biyoteknoloji kavramlarını açıklar.', NULL, '["Genetik mühendisliği ve biyoteknoloji arasındaki farkların tartışılması sağlanır."]'::jsonb, '{}'::jsonb, 67, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#68', 'yks-2026-biyoloji', 'yks-2026-biyoloji#9', '12.1.2.3', 'Genetik mühendisliği ve biyoteknoloji uygulamalarını açıklar.', NULL, '["a. Gen teknolojileri, DNA parmak izi analizi, kök hücre teknolojilerinin ve bunların kullanım alanlarının araştırılması ve sonuçlarının paylaşılması sağlanır. b. Model organizmaların özellikleri tartışılır. c. Model organizmaların genetik ve biyoteknolojik araştırmalarda kullanılmasına ilişkin örnekler verilir."]'::jsonb, '{}'::jsonb, 68, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#69', 'yks-2026-biyoloji', 'yks-2026-biyoloji#9', '12.1.2.4', 'Genetik mühendisliği ve biyoteknoloji uygulamalarının insan hayatına etkisini değerlendirir.', NULL, '["a. Aşı, antibiyotik, insülin, interferon üretimi, kanser tedavisi ve gen terapisi uygulamaları kısaca açıklanır. b. Klonlama çalışmalarının ve organizmaların genetiğinin değiştirilmesinin olası sonuçları belirtilir. Ian Wilmut’un klonlama ile ilgili çalışmasına değinilir. c. Biyogüvenlik ve biyoetik konularının tartışılması sağlanır. ç. Sosyo-ekonomik ve kültürel bağlamın, biyolojinin gelişimini etkilediği vurgulanır."]'::jsonb, '{}'::jsonb, 69, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#70', 'yks-2026-biyoloji', 'yks-2026-biyoloji#10', '12.2.1.1', 'Canlılığın devamı için enerjinin gerekliliğini açıklar.', NULL, '["a. ATP molekülünün yapısı açıklanır. b. Fosforilasyon çeşitleri kısaca belirtilir."]'::jsonb, '{}'::jsonb, 70, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#71', 'yks-2026-biyoloji', 'yks-2026-biyoloji#10', '12.2.2.1', 'Fotosentezin canlılar açısından önemini sorgular.', NULL, '["Fotosentez sürecinin anlaşılmasına katkı sağlayan bilim insanlarına örnekler verilerek kısaca çalışmalarına değinilir."]'::jsonb, '{}'::jsonb, 71, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#72', 'yks-2026-biyoloji', 'yks-2026-biyoloji#10', '12.2.2.2', 'Fotosentez sürecini şema üzerinde açıklar.', NULL, '["a. Klorofil a ve klorofil b’nin yapısı verilmez. b. Suyun fotolizi belirtilir. c. Işığa bağımlı ve ışıktan bağımsız reaksiyonlar, ürün açısından karşılaştırılır. Reaksiyonların basamaklarına girilmez ve matematiksel hesaplamalara yer verilmez. ç. CAM ve C4 bitkileri verilmez. d. Fotosentez süreci görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından faydalanarak açıklanır."]'::jsonb, '{}'::jsonb, 72, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#73', 'yks-2026-biyoloji', 'yks-2026-biyoloji#10', '12.2.2.3', 'Fotosentez hızını etkileyen faktörleri değerlendirir.', NULL, '["a. Fotosentez hızını etkileyen faktörlerden ışık şiddeti, ışığın dalga boyu, sıcaklık, klorofil miktarı ve karbondioksit yoğunluğu verilir. b. Fotosentez hızını etkileyen faktörlerle ilgili kontrollü deney yaparken bilimsel yöntem basamakları kullanılır. c. Tarımsal ürün miktarını artırmada yapay ışıklandırma uygulamalarının araştırılması ve paylaşılması sağlanır."]'::jsonb, '{}'::jsonb, 73, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#74', 'yks-2026-biyoloji', 'yks-2026-biyoloji#10', '12.2.3.1', 'Kemosentez olayını açıklar.', NULL, '["a. Kemosentez yapan canlılara örnekler verilir. b. Kemosentezin madde döngüsüne katkıları ve endüstriyel alanlarda kullanımı özetlenir."]'::jsonb, '{}'::jsonb, 74, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#75', 'yks-2026-biyoloji', 'yks-2026-biyoloji#10', '12.2.4.1', 'Hücresel solunumu açıklar.', NULL, '["a. Oksijenli solunum; glikoliz, krebs döngüsü ve ETS-oksidatif fosforilasyon olarak verilir. b. Tepkimelerdeki NADH, FADH2 , ATP üretim ve tüketimi matematiksel hesaplamalara girilmeden verilir. c. Tüm canlılarda glikozun çeşitli tepkimeler zinciri ile pirüvik asite parçalandığı vurgulanır. Pirüvik asite kadar olan ara basamaklara ve ara ürünlere değinilmez. ç. Etil alkol-laktik asit fermantasyonu açıklanarak günlük hayattan örnekler verilir. d. Oksijensiz solunumda, elektronun oksijen dışında bir moleküle (sülfat, kükürt, nitrat, karbondioksit, demir) aktarıldığı belirtilir. e. Oksijenli solunumda fermantasyona göre enerji verimliliğinin daha fazla olmasının nedenleri üzerinde durulur. f. Hücresel solunum süreçleri görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından faydalanarak açıklanır."]'::jsonb, '{}'::jsonb, 75, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#76', 'yks-2026-biyoloji', 'yks-2026-biyoloji#10', '12.2.4.2', 'Oksijenli solunumda reaksiyona girenler ve reaksiyon sonunda açığa çıkan son ürünlere ilişkin deney yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 76, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#77', 'yks-2026-biyoloji', 'yks-2026-biyoloji#10', '12.2.4.3', 'Fotosentez ve solunum ilişkisi ile ilgili çıkarımlarda bulunur.', NULL, '["a. Fotosentez ve solunumun doğadaki madde ve enerji dengesinin sağlanmasındaki önemi vurgulanır. b. Fotosentez ve solunum olaylarının bir arada gözlemlenebileceği deney deney tasarlanması ve yapılması sağlanır. c. Fotosentez ve oksijenli solunumda enerji üretim mekanizması ile ilgili olarak kemiosmotik görüş şema üzerinde verilerek kısaca tanıtılır."]'::jsonb, '{}'::jsonb, 77, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#78', 'yks-2026-biyoloji', 'yks-2026-biyoloji#11', '12.3.1.1', 'Çiçekli bir bitkinin temel kısımlarının yapı ve görevlerini açıklar.', NULL, '["a. Kök, gövde, yaprak kesitlerinde başlıca dokuların incelenmesi sağlanır ve bunların görevleri açıklanır. b. Uç ve yanal meristemlerin büyümedeki rolü vurgulanarak yaş halkaları ile bağlantı kurulur. c. Prokambiyum, protoderm ve temel meristem konularına girilmez. ç. Kök, gövde ve yapraklarından yararlanılan bitkilere günlük hayattan örnekler verilir. d. Bitki çeşitleriyle ilgili çektikleri/edindikleri fotoğrafları eğitsel sosyal bir ağ üzerinden paylaşmaları sağlanır."]'::jsonb, '{}'::jsonb, 78, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#79', 'yks-2026-biyoloji', 'yks-2026-biyoloji#11', '12.3.1.2', 'Bitki gelişiminde hormonların etkisini örneklerle açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 79, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#80', 'yks-2026-biyoloji', 'yks-2026-biyoloji#11', '12.3.1.3', 'Bitki hareketlerini gözlemleyebileceği kontrollü deney yapar.', NULL, '["a. Nasti ve tropizma hareketleri gözlemlenerek bu hareketlere ilişkin gözlemlerin paylaşılması sağlanır. b. Oksin hormonunun tropizmadaki etkisi vurgulanır."]'::jsonb, '{}'::jsonb, 80, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#81', 'yks-2026-biyoloji', 'yks-2026-biyoloji#11', '12.3.2.1', 'Köklerde su ve mineral emilimini açıklar.', NULL, '["a. Su ve minerallerin bitkiler için önemi vurgulanır. b. Minerallerin topraktan alınması, nodül ve mikoriza oluşumu üzerinde durulur. c. İyonların emilim mekanizmasına girilmez. ç. Bitkilerin büyüme ve gelişmesinde gerekli olan minerallerin isimleri verilir. Ayrı ayrı görevlerine girilmez."]'::jsonb, '{}'::jsonb, 81, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#82', 'yks-2026-biyoloji', 'yks-2026-biyoloji#11', '12.3.2.2', 'Bitkilerde su ve mineral taşınma mekanizmasını açıklar.', NULL, '["a. Suyun taşınmasında kohezyon gerilim teorisi, kök basıncı, adhezyon ve gutasyon olayları açıklanır. b. Suyun taşınmasında stomaların rolüne değinilir."]'::jsonb, '{}'::jsonb, 82, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#83', 'yks-2026-biyoloji', 'yks-2026-biyoloji#11', '12.3.2.3', 'Bitkilerde fotosentez ürünlerinin taşınma mekanizmasını açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 83, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#84', 'yks-2026-biyoloji', 'yks-2026-biyoloji#11', '12.3.2.4', 'Bitkilerde su ve madde taşınması ile ilgili deney tasarlar.', NULL, '[]'::jsonb, '{}'::jsonb, 84, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#85', 'yks-2026-biyoloji', 'yks-2026-biyoloji#11', '12.3.3.1', 'Çiçeğin kısımlarını ve bu kısımların görevlerini açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 85, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#86', 'yks-2026-biyoloji', 'yks-2026-biyoloji#11', '12.3.3.2', 'Çiçekli bitkilerde döllenmeyi, tohum ve meyvenin oluşumunu açıklar.', NULL, '["a. Bitkilerde eşeyli üreme kapalı tohumlu bir bitki örneği üzerinden görsel ögeler, grafik düzenleyiciler, e-öğrenme nesnesi ve uygulamalarından faydalanılarak işlenir. b. Bitkilerin üreme ve yayılmasında tohum ve meyvenin rolü örneklerle ele alınır."]'::jsonb, '{}'::jsonb, 86, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#87', 'yks-2026-biyoloji', 'yks-2026-biyoloji#11', '12.3.3.3', 'Tohum çimlenmesini gözleyebileceği deney tasarlar.', NULL, '["Çimlenmeye etki eden faktörlerin tespit edilmesi sağlanır."]'::jsonb, '{}'::jsonb, 87, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#88', 'yks-2026-biyoloji', 'yks-2026-biyoloji#11', '12.3.3.4', 'Dormansi ve çimlenme arasında ilişki kurar.', NULL, '[]'::jsonb, '{}'::jsonb, 88, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#89', 'yks-2026-biyoloji', 'yks-2026-biyoloji#12', '12.4.1.1', 'Çevre şartlarının genetik değişimlerin sürekliliğine olan etkisini açıklar.', NULL, '["a. Varyasyon, adaptasyon, mutasyon, doğal ve yapay seçilim kavramları vurgulanır. b. Bakterilerin antibiyotiklere karşı direnç geliştirmesinin nedenleri vurgulanır. c. Herbisit ve pestisitlerin zaman içerisinde etkilerini kaybetmelerinin nedenleri üzerinde durulur."]'::jsonb, '{}'::jsonb, 89, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-biyoloji#90', 'yks-2026-biyoloji', 'yks-2026-biyoloji#12', '12.4.1.2', 'Tarım ve hayvancılıkta yapay seçilim uygulamalarına örnekler verir.', NULL, '[]'::jsonb, '{}'::jsonb, 90, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#1', 'yks-2026-cografya', 'yks-2026-cografya#1', '9.1.1', 'Doğa ve insan etkileşimini örneklerle açıklar.', NULL, '["a) Dünyadan ve Türkiye''den örnekler verilir.", "b) Doğa-insan etkileşiminde insanların doğaya karşı göstermesi gereken duyarlılığa yer verilir."]'::jsonb, '{}'::jsonb, 1, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#2', 'yks-2026-cografya', 'yks-2026-cografya#1', '9.1.2', 'Coğrafyanın konularını ve bölümlenmesini açıklar.', NULL, '["Coğrafyanın ilişkili olduğu disiplinlere yer verilir."]'::jsonb, '{}'::jsonb, 2, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#3', 'yks-2026-cografya', 'yks-2026-cografya#1', '9.1.3', 'Coğrafya biliminin gelişimini açıklar.', NULL, '["a) Coğrafya biliminin önemine değinilir.", "b) Coğrafya biliminin gelişimine katkı sağlayan Türk ve Müslüman bilim insanlarının çalışmalarına da yer verilir."]'::jsonb, '{}'::jsonb, 3, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#4', 'yks-2026-cografya', 'yks-2026-cografya#1', '9.1.4', 'Dünya’nın şekli ve hareketlerinin etkilerini değerlendirir.', NULL, '["Dünya’nın Güneş Sistemi içindeki yerine kısaca değinilir."]'::jsonb, '{}'::jsonb, 4, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#5', 'yks-2026-cografya', 'yks-2026-cografya#1', '9.1.5', 'Koordinat sistemini kullanarak zaman ve yere ait özellikler hakkında çıkarımlarda bulunur.', NULL, '["a) Mutlak ve göreceli konum kavramlarına yer verilir.", "b) Türkiye’nin konumuna yer verilir."]'::jsonb, '{}'::jsonb, 5, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#6', 'yks-2026-cografya', 'yks-2026-cografya#1', '9.1.6', 'Haritayı oluşturan unsurlardan yararlanarak harita kullanır.', NULL, '["a) Harita Projeksiyonlarına yer verilir.", "b) Farklı harita türlerine ve kullanım amaçlarına yer verilir.", "c) Ölçek ile uzunluk ve alan ilişkilerinde basit örneklere yer verilir. Alan hesaplamalarında sadece gerçek alan hesaplamalarına yer verilir."]'::jsonb, '{}'::jsonb, 6, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#7', 'yks-2026-cografya', 'yks-2026-cografya#1', '9.1.7', 'Bilgileri haritalara aktarmada kullanılan yöntem ve teknikleri açıklar.', NULL, '["a) Haritacılık tarihinde önemli olan Türk ve Müslüman bilim insanları ve çalışmaları üzerinde durulur.", "b) Coğrafi Bilgi Sistemlerine (CBS) ve uzaktan algılama tekniklerine yer verilir.", "c) Mekânsal verilerin haritaya aktarımında nokta, çizgi ve alansal gösterimlerden yararlanılması sağlanır."]'::jsonb, '{}'::jsonb, 7, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#8', 'yks-2026-cografya', 'yks-2026-cografya#1', '9.1.8', 'Haritalarda yer şekillerinin gösteriminde kullanılan yöntem ve teknikleri açıklar.', NULL, '["a) Eş yükselti eğrilerinin özelliklerine yer verilir.", "b) Eş yükselti eğrileri ile çizilmiş haritalar üzerinde yer şekillerinin ayırt edilmesine yer verilir.", "c) Haritalarda yer şekillerini gösterme yöntemlerinden renklendirme ve kabartma yöntemlerine yer verilir."]'::jsonb, '{}'::jsonb, 8, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#9', 'yks-2026-cografya', 'yks-2026-cografya#1', '9.1.9', 'Atmosferin katmanları ve özellikleri ile hava olaylarını ilişkilendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 9, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#10', 'yks-2026-cografya', 'yks-2026-cografya#1', '9.1.10', 'Örneklerden yararlanarak hava durumu ile iklim özelliklerini etkileri açısından karşılaştırır.', NULL, '[]'::jsonb, '{}'::jsonb, 10, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#11', 'yks-2026-cografya', 'yks-2026-cografya#1', '9.1.11', 'İklim elemanlarının oluşumunu ve dağılışını açıklar.', NULL, '["a) İklim elemanlarına ait temel kavramlara ve iklim elamanlarını etkileyen faktörlere yer verilir.", "b) İklim elemanlarının günlük hayata etkilerine örnekler üzerinden yer verilir.", "c) Yaşanılan yerdeki iklim elemanlarına ait verilerden yararlanılarak tablo ve grafikler çizilir ve günlük hayatla ilişkilendirilir."]'::jsonb, '{}'::jsonb, 11, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#12', 'yks-2026-cografya', 'yks-2026-cografya#1', '9.1.12', 'Yeryüzündeki farklı iklim tiplerinin özellikleri ve dağılışları hakkında çıkarımlarda bulunur.', NULL, '["Gerçek istasyonlara ait klimatolojik verilerin yer aldığı iklim grafiklerine yer verilir."]'::jsonb, '{}'::jsonb, 12, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#13', 'yks-2026-cografya', 'yks-2026-cografya#1', '9.1.13', 'Türkiye’de görülen iklim tiplerinin özellikleri hakkında çıkarımlarda bulunur.', NULL, '["a) Türkiye’nin iklimini etkileyen faktörlere yer verilir.", "b) Türkiye’deki iklim elemanlarının özellikleri üzerinde durulur.", "c) Türkiye’de görülen iklim tipleri ve özelliklerine yer verilir."]'::jsonb, '{}'::jsonb, 13, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#14', 'yks-2026-cografya', 'yks-2026-cografya#2', '9.2.1', 'Yerleşmelerin gelişimini etkileyen faktörleri analiz eder.', NULL, '["Yerleşme yeri seçiminde etkili olan faktörlere yer verilir."]'::jsonb, '{}'::jsonb, 14, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#15', 'yks-2026-cografya', 'yks-2026-cografya#2', '9.2.2', 'Yerleşme doku ve tiplerinin oluşumunda etkili olan faktörleri örneklerle açıklar.', NULL, '["a)", "b) Kır ve şehir yerleşmelerinin oluşumunda etkili olan faktörlere yer verilir."]'::jsonb, '{}'::jsonb, 15, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
