('yks-2026-cografya#17', 'yks-2026-cografya', 'yks-2026-cografya#2', '9.2.4', 'Türkiye’deki yerleşim birimlerini idari fonksiyonlarına göre ayırt eder.', NULL, '["Türkiye’nin idari yapısı verilirken ülkenin mevcut", "a) Şekilsel ve işlevsel bölge ayrımına yer verilir.", "b)"]'::jsonb, '{}'::jsonb, 17, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#18', 'yks-2026-cografya', 'yks-2026-cografya#3', '9.3.1', 'Dünyadaki farklı bölge örneklerini, özellikleri ve bölge belirlemede kullanılan kriterler açısından değerlendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 18, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#19', 'yks-2026-cografya', 'yks-2026-cografya#3', '9.3.2', 'Bölge sınırlarının amaca göre değişebilirliğini örneklerle açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 19, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#20', 'yks-2026-cografya', 'yks-2026-cografya#3', '9.3.3', 'Harita kullanarak çeşitli coğrafi kriterlerle belirlenmiş bölgelerde bulunan ülkeleri sınıflandırır.', NULL, '[]'::jsonb, '{}'::jsonb, 20, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#21', 'yks-2026-cografya', 'yks-2026-cografya#4', '9.4.1', 'İnsanların doğal çevreyi kullanma biçimlerini örneklendirir.', NULL, '["Karadeniz Sahil Yolu, Maltepe Sahil Parkı, Avrasya Tüneli, Osman Gazi Köprüsü, Ordu-Giresun Hava Limanı, Marmaray ve BAE-", "a) Örnek olaylardan hareketle insanın atmosfer, litosfer, hidrosfer ve biyosfer üzerindeki etkilerine yer verilir.", "b) İnsanların doğal ortam üzerinde gerçekleştirdikleri"]'::jsonb, '{}'::jsonb, 21, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#22', 'yks-2026-cografya', 'yks-2026-cografya#4', '9.4.2', 'Doğal ortamda insan etkisiyle meydana gelen değişimleri sonuçları açısından değerlendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 22, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#23', 'yks-2026-cografya', 'yks-2026-cografya#5', '10.1.1', 'Dünya’nın tektonik oluşumunu açıklar.', NULL, '["a) Dünya’nın iç yapısı ile ilgili temel bilgiler verilir.", "b) Levha tektoniği kuramına yer verilir."]'::jsonb, '{}'::jsonb, 23, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
