('yks-2026-cografya#108', 'yks-2026-cografya', 'yks-2026-cografya#14', '12.2.10', 'Dünya ticaret merkezleri ve ağlarını küresel ekonomideki yerleri açısından analiz eder.', NULL, '["Avrupa Birliği, Kuzey Amerika Serbest Ticaret Bölgesi, Güney Ortak Pazarı ve Uzak Doğu Ticaret Bölgesi’ne yer verilir."]'::jsonb, '{}'::jsonb, 108, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#109', 'yks-2026-cografya', 'yks-2026-cografya#14', '12.2.11', 'Türkiye’deki ticaret merkezlerinin ticarete konu olan ürünlere ve akış yönlerine etkilerini açıklar.', NULL, '["Ticaret uygulamalarına yer verilerek e-ticarette siber güvenliğin önemine vurgu yapılır."]'::jsonb, '{}'::jsonb, 109, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#110', 'yks-2026-cografya', 'yks-2026-cografya#14', '12.2.12', 'Tarihî ticaret yollarını Türkiye''nin konumu açısından değerlendirir.', NULL, '["İpek ve baharat yollarına yer verilir."]'::jsonb, '{}'::jsonb, 110, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00')
INSERT INTO public.curriculum_outcomes (id, program_id, unit_id, code, text, topic, limitations, quotas, sort_order, source_id, quota_source_id, text_similarity, source_url, program_version, sha256, fetched_at) VALUES
('yks-2026-cografya#111', 'yks-2026-cografya', 'yks-2026-cografya#14', '12.2.13', 'Türkiye’nin dış ticaretini ve dünya pazarlarındaki yerini ticarete konu olan ürünler açısından analiz eder.', NULL, '["Ticarete konu olan ürünler ve ticaretin Türkiye ekonomisindeki önemi vurgulanır."]'::jsonb, '{}'::jsonb, 111, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#112', 'yks-2026-cografya', 'yks-2026-cografya#14', '12.2.14', 'Türkiye''deki doğal ve kültürel sembollerin mekânla ilişkisini açıklar.', NULL, '["a) Türkiye''deki doğal ve kültürel sembollerin mekân algısına olan etkisine yer verilir.", "b) Türkiye’nin dünya miras listesinde yer alan doğal varlıklar ile şehirleri sembolize eden doğal ve kültürel değerlere yer verilir.", "c) Coğrafi işaret kavramı ve Türkiye’deki örneklerine yer verilir."]'::jsonb, '{}'::jsonb, 112, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#113', 'yks-2026-cografya', 'yks-2026-cografya#14', '12.2.15', 'Türkiye’nin turizm potansiyelini ve varlıklarını açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 113, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#114', 'yks-2026-cografya', 'yks-2026-cografya#14', '12.2.16', 'Türkiye’nin turizm politikalarını çevresel, kültürel ve ekonomik etkileri açısından değerlendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 114, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#115', 'yks-2026-cografya', 'yks-2026-cografya#14', '12.2.17', 'Turizmin Türkiye ekonomisindeki yerini değerlendirir.', NULL, '["Türkiye’nin turizmdeki yeri diğer ülkelerle karşılaştırılarak verilir."]'::jsonb, '{}'::jsonb, 115, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#116', 'yks-2026-cografya', 'yks-2026-cografya#15', '12.3.1', 'Kıtaların ve okyanusların konumsal önemindeki değişimi örneklerle açıklar.', NULL, '["a) Tarihsel süreçte kıtaların ve okyanusların konumsal önemini etkileyen faktörlere ve değişimine yer verilir.", "b) Coğrafi keşiflerle birlikte sömürgeciliğe de yer verilir."]'::jsonb, '{}'::jsonb, 116, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#117', 'yks-2026-cografya', 'yks-2026-cografya#15', '12.3.2', 'Ülkelerin konumunun bölgesel ve küresel etkilerini değerlendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 117, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#118', 'yks-2026-cografya', 'yks-2026-cografya#15', '12.3.3', 'Tarihsel süreçte Türkiye’nin jeopolitik konumunu değerlendirir.', NULL, '["Kıbrıs’ın, Türkiye’nin jeopolitik konumuna olan etkisine yer verilir."]'::jsonb, '{}'::jsonb, 118, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#119', 'yks-2026-cografya', 'yks-2026-cografya#15', '12.3.4', 'Türkiye’nin içinde yer aldığı jeopolitik bölgelerle olan ilişkisini açıklar.', NULL, '["Ülkemizin bölgesel ve küresel bağlantılar açısından önemli bir ulaşım merkezi olduğu vurgulanır."]'::jsonb, '{}'::jsonb, 119, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#120', 'yks-2026-cografya', 'yks-2026-cografya#15', '12.3.5', 'Türk kültür bölgeleri ile ülkemiz arasındaki tarihî ve kültürel bağları açıklar.', NULL, '["Kültür havzamızı oluşturan Türkistan, Kafkasya, Balkanlar, Ortadoğu"]'::jsonb, '{}'::jsonb, 120, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#121', 'yks-2026-cografya', 'yks-2026-cografya#15', '12.3.6', 'Teknolojik gelişmelerin, bölgeler ve ülkeler arası kültürel ve ekonomik etkileşimdeki rolünü açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 121, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#122', 'yks-2026-cografya', 'yks-2026-cografya#15', '12.3.7', 'Ülkelerin gelişmişlik seviyelerinin belirlenmesinde etkili olan faktörleri açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 122, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#123', 'yks-2026-cografya', 'yks-2026-cografya#15', '12.3.8', 'Gelişmiş ve gelişmekte olan ülkelerin ekonomik özelliklerini karşılaştırır.', NULL, '["a) Gelişmiş ve gelişmekte olan ülkelerin farklı gelişmişliklerinin nedenleri üzerinde durulur.", "b) Gayrisafi Millî Hasıla ve İnsani Gelişme Endeksi (İGE) gibi gelişmişlik ölçütlerinden yararlanılır."]'::jsonb, '{}'::jsonb, 123, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#124', 'yks-2026-cografya', 'yks-2026-cografya#15', '12.3.9', 'Ülkelerin bölgesel ve küresel ilişkilerini doğal kaynak potansiyeli açısından değerlendirir.', NULL, '["Doğal kaynaklar üzerinde, küresel güçlerin ekonomik ve siyasi etkilerine de yer verilir."]'::jsonb, '{}'::jsonb, 124, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#125', 'yks-2026-cografya', 'yks-2026-cografya#15', '12.3.10', 'Dünyadaki başlıca enerji nakil hatlarının bölge ve ülkelere etkisini açıklar.', NULL, '["Türkiye’nin"]'::jsonb, '{}'::jsonb, 125, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#126', 'yks-2026-cografya', 'yks-2026-cografya#15', '12.3.11', 'Ülkeler arasında sorun oluşturan mekânsal unsurları günümüz çatışma alanlarıyla ilişkilendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 126, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#127', 'yks-2026-cografya', 'yks-2026-cografya#16', '12.4.1', 'Doğal çevrenin sınırlılığını açıklar.', NULL, '["a) Beslenme halkası ve taşıma kapasitesi kavramları üzerinde durulur.", "b) Sınırlı kaynak, tükenebilirlik, aşırı baskı, çevre sorunu"]'::jsonb, '{}'::jsonb, 127, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#128', 'yks-2026-cografya', 'yks-2026-cografya#16', '12.4.2', 'Farklı gelişmişlik düzeyine sahip ülkelerin çevre sorunlarının önlenmesine yönelik politika ve uygulamalarını karşılaştırır.', NULL, '[]'::jsonb, '{}'::jsonb, 128, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#129', 'yks-2026-cografya', 'yks-2026-cografya#16', '12.4.3', 'Çevresel örgüt ve anlaşmaların çevre yönetimi ve korunmasına etkilerini açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 129, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-cografya#130', 'yks-2026-cografya', 'yks-2026-cografya#16', '12.4.4', 'Ortak doğal ve kültürel mirasa yönelik tehditleri açıklar.', NULL, '["Doğal ve kültürel mirasa yönelik tehditlere karşı duyarlı olmanın önemine vurgu yapılır. Not: Kırmızı renkle gösterilen kazanımlar ve açıklamalar, 11 ve 12. sınıf seviyesinde sadece 4 saatlik öğretim programında yer alan kazanım ve açıklamalardır."]'::jsonb, '{}'::jsonb, 130, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#1', 'yks-2026-dkab', 'yks-2026-dkab#1', '9.1.1', 'İslam’da bilginin kaynaklarını açıklar.', NULL, '[" İslam’ın bilgi kaynaklarında; selim akıl, doğru haber ve salim duyu organlarının yanı sıra bilgi ve düşünme kaynakları hakkında felsefe ve bilim dünyasındaki yapılan değerlendirmeler, İslam kelamının epistemolojik yaklaşımları bağlamında ele alınır. Rüya, keşif ve ilhamın İslam âlimlerince bilgi kaynağı olarak kabul edilmediğine vurgu yapılır. Ayrıca güncel bilgi kaynaklarına (dijital kayıtlar gibi) değinilir.  Bilgiyi sevme, doğru bilgiye ulaşma ve faydalı bilgi ile bilgi ahlakı, bilginin kullanımı ve muhafazası gibi konulara da değinilir."]'::jsonb, '{}'::jsonb, 1, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#2', 'yks-2026-dkab', 'yks-2026-dkab#1', '9.1.2', 'İslam inancında imanın mahiyetini araştırır.', NULL, '[" İman tasdik ilişkisi, iman ikrar ilişkisi, iman bilgi ilişkisi ve iman amel ilişkisi konularına yer verilir.  İslam inancında imanın taklitten kurtarılarak tahkike ulaşmasının önemine de değinilir."]'::jsonb, '{}'::jsonb, 2, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#3', 'yks-2026-dkab', 'yks-2026-dkab#1', '9.1.3', 'İsrâ suresi 36. ayet ile Mülk suresi 23. ayetlerinde verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar İslam, inanç, akide, vahiy. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 3, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#4', 'yks-2026-dkab', 'yks-2026-dkab#2', '9.2.1', 'Kaynağı ve unsurları bakımından din tanımlarını karşılaştırır.', NULL, '[" Kur’an-ı Kerim’de din kavramının farklı anlamları ele alınır ve İslam âlimlerince yapılan din tanımlarına örnekler verilir.  Çeşitli disiplinlere (felsefe, sosyoloji, antropoloji, dinler tarihi) göre din tanımlarına birer örnek verilir."]'::jsonb, '{}'::jsonb, 4, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#5', 'yks-2026-dkab', 'yks-2026-dkab#2', '9.2.2', 'İnsanın doğası ile din arasında ilişki kurar.', NULL, '[" İnsan doğasının maddi ve manevi yönüne değinilir; tarih boyunca insanın inanma ihtiyacının nedenleri Kur’an-ı Kerim’den ilgili ayetlerle ele alınır; dinin insan hayatındaki yeri ve önemi örneklerle açıklanır."]'::jsonb, '{}'::jsonb, 5, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#6', 'yks-2026-dkab', 'yks-2026-dkab#2', '9.2.3', 'İman ve İslam kavramları arasındaki ilişkiyi fark eder.', NULL, '[]'::jsonb, '{}'::jsonb, 6, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#7', 'yks-2026-dkab', 'yks-2026-dkab#2', '9.2.4', 'İslam’ın inanç esaslarının özelliklerini ayet ve hadisler ışığında analiz eder.', NULL, '[" İslam inancının sade ve yalın olması, kul ile Allah arasında hiçbir aracı kişi ve kuruma izin vermemesi, dogmatik olmaması, hür iradeyi esas alması, ebedî kurtuluş için korku ve ümit arasında yaşamayı tavsiye etmesi gibi konulara değinilir.  İslam inancında tevhidin önemi ile tevhid inancının yerleşmesinde Allah’ın isim ve sıfatlarını doğru anlamanın yeri ayetlerle ele alınır; inanç esasları ile ilgili ayrıntılara girilmez.  İslam inanç esasları arasındaki bütünselliğin önemine değinilir; İslam inançlarını parçacı bir yaklaşımla ele almanın sakıncaları örneklerle açıklanır."]'::jsonb, '{}'::jsonb, 7, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#8', 'yks-2026-dkab', 'yks-2026-dkab#2', '9.2.5', 'Nisâ suresi 136. ayette verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir.  Ayet ele alınırken Cibril hadisine de yer verilir. Anahtar Kavramlar din, fıtrat, tevhid, hanif, iman, Esmâ-i Hüsnâ. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 8, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#9', 'yks-2026-dkab', 'yks-2026-dkab#3', '9.3.1', 'İslam’da ibadet kavramını ve ibadetin kapsamını açıklar.', NULL, '[" İslam’da ibadetin kapsamı konusunda Allah’ın rızasına dayanan her davranışın ibadet olduğuna, bazı ibadetlerin (namaz, oruç, hac, zekât gibi) belirli bir vaktinin ve uygulanma şeklinin olduğuna, bazı ibadetlerin ise belirli bir vaktinin olmadığına değinilir."]'::jsonb, '{}'::jsonb, 9, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#10', 'yks-2026-dkab', 'yks-2026-dkab#3', '9.3.2', 'İslam’da ibadetlerin yapılış amacını ve önemini fark eder.', NULL, '[]'::jsonb, '{}'::jsonb, 10, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#11', 'yks-2026-dkab', 'yks-2026-dkab#3', '9.3.3', 'İbadet yükümlülüğü ile ilgili bazı kavramları sınıflandırır.', NULL, '[" Mükellef ve ef’al-i mükellefîne (farz, vacip, sünnet, mendup, mübah, haram ve mekruh) yer verilir."]'::jsonb, '{}'::jsonb, 11, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#12', 'yks-2026-dkab', 'yks-2026-dkab#3', '9.3.4', 'İslam’da ibadetlerin temel ilkelerini değerlendirir.', NULL, '[" İslam’da ibadetlerin temel ilkeleri kapsamında; “Kur’an ve sünnete uygunluk”, “niyet”, “ihlas” konularına yer verilir. Ayrıca ibadetlerde bidatlerden kaçınmanın önemine değinilir."]'::jsonb, '{}'::jsonb, 12, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#13', 'yks-2026-dkab', 'yks-2026-dkab#3', '9.3.5', 'İbadetlerin, bireyin ahlaki gelişimi üzerindeki etkisini yorumlar.', NULL, '[" İbadetlerin teşri hikmeti üzerinde durulur ve ibadetlerin toplumsal yönüne değinilir."]'::jsonb, '{}'::jsonb, 13, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#14', 'yks-2026-dkab', 'yks-2026-dkab#3', '9.3.6', 'Bakara suresi 177. ayette verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar ibadet, mükellef, salih amel, ihlas. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 14, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#15', 'yks-2026-dkab', 'yks-2026-dkab#4', '9.4.1', 'Değerlerin oluşumuna etki eden unsurları analiz eder.', NULL, '[" Değer kavramının analizi yapılır; değerlerin oluşumunda; dinin, örf ve âdetlerin etkisine yer verilir."]'::jsonb, '{}'::jsonb, 15, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#16', 'yks-2026-dkab', 'yks-2026-dkab#4', '9.4.2', 'Gençlerin kişilik gelişiminde dinî ve ahlaki değerler ile örf ve âdetlerin yerini tartışır.', NULL, '[" Gençlerin kişilik gelişimine değerlerin etkisi günlük hayattan örneklerle açıklanır."]'::jsonb, '{}'::jsonb, 16, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#17', 'yks-2026-dkab', 'yks-2026-dkab#4', '9.4.3', 'Temel değerleri ayet ve hadislerle ilişkilendirir.', NULL, '[" İslam düşünce geleneğinde öne çıkan temel “insani erdem ve değerler”den hikmet, adalet, iffet ve şecaat konularına yer verilir. İnsanın düşünme, arzu ve gazap gibi konularda ölçülü olması, itidal üzere hareket etmesi, bedeni ve maddi hazlara aşırı düşkünlükten korunması, gönül tokluğu gibi anlamlara gelen iffet kavramı, ahlaki ve felsefi boyutlarıyla ele alınır."]'::jsonb, '{}'::jsonb, 17, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#18', 'yks-2026-dkab', 'yks-2026-dkab#4', '9.4.4', 'İsrâ suresi 23-29. ayetlerde verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar din, değer, ahlak, örf, âdet. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 18, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#19', 'yks-2026-dkab', 'yks-2026-dkab#5', '9.5.1', 'İslam medeniyeti kavramını izah eder.', NULL, '[" Kültür ve medeniyet kavramları öğrenci seviyesine göre ana hatlarıyla ele alınır; İslam medeniyeti kavramı analiz edilir."]'::jsonb, '{}'::jsonb, 19, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#20', 'yks-2026-dkab', 'yks-2026-dkab#5', '9.5.2', 'İslam medeniyetinin, dünyanın farklı bölgelerindeki etkilerini fark eder.', NULL, '[" Hicaz Bölgesi, Kudüs ve Çevresi, Şam ve Bağdat Bölgesi; İran, Horasan, Türkistan ve Mâverâünnehir Bölgesi; Hint Alt Kıtası; Anadolu ve Balkanlar; Kuzey Afrika (Mısır ve Mağrip Bölgesi) ve Endülüs gibi İslam medeniyetinin tarihî süreçte hayat bulduğu ilim ve kültür havzaları ele alınır.  İslam medeniyetinin bu havzalara İslam’ın taşınmasına öncülük eden âlimler, komutanlar ve tüccarlara kısaca yer verilir.  İslam medeniyetine değer katan ana dillere (Türkçe, Arapça, Farsça) değinilir.  İslam medeniyetinin Anadolu ve Balkanlara taşınmasında Horasan, Anadolu ve Rumeli erenlerinin de rolüne kısaca değinilir.  Öğrencilerin Türkiye ile gönül coğrafyamız arasındaki tarihî ve kültürel bağların güçlenmesine yönelik sözlü ve yazılı önerilerde bulunabilecekleri etkinliklere yer verilir."]'::jsonb, '{}'::jsonb, 20, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#21', 'yks-2026-dkab', 'yks-2026-dkab#5', '9.5.3', 'Hucurât suresi 13. ayette verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar kültür, medeniyet. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 21, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#22', 'yks-2026-dkab', 'yks-2026-dkab#6', '10.1.1', 'Allah inancının insan hayatındaki yeri ve önemini yorumlar.', NULL, '[]'::jsonb, '{}'::jsonb, 22, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#23', 'yks-2026-dkab', 'yks-2026-dkab#6', '10.1.2', 'Allah’ın varlığı ve birliği konusunda akli ve naklî delilleri analiz eder.', NULL, '[" “Gaye ve nizam”, “ekmel varlık” delilleri ile sınırlandırılır."]'::jsonb, '{}'::jsonb, 23, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#24', 'yks-2026-dkab', 'yks-2026-dkab#6', '10.1.3', 'İsim ve sıfatlarının yansımalarıyla Allah''ı tanır.', NULL, '[" Allah’ın isim ve sıfatlarını kavramanın, O’nu tanımadaki önemine değinilir; isim ve sıfatların kâinatta tecellisi üzerinde durulur. İsim ve sıfatlar, Allah insan ilişkisi bağlamında; Bakara suresi 255. ayet, Haşr suresi 22-24. ayetler ve İhlâs suresi kapsamında işlenir."]'::jsonb, '{}'::jsonb, 24, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#25', 'yks-2026-dkab', 'yks-2026-dkab#6', '10.1.4', 'İnsanın özelliklerini ayetlerle açıklar.', NULL, '[" Kazanım kapsamında insanın olumlu özellikleri öne çıkarılır."]'::jsonb, '{}'::jsonb, 25, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#26', 'yks-2026-dkab', 'yks-2026-dkab#6', '10.1.5', 'İnsanın Allah ile irtibat yollarını fark eder.', NULL, '[" Kazanım; dua, ibadet, Kur’an okuma, tövbe ve istiğfar konuları ile sınırlandırılır.  Allah ile insan arasındaki ilişkinin dayandığı temel ilkelere yer verilir; temel ilkeler Yaradan- yaradılan ilişkisi çerçevesinde ele alınır; Allah’ın “ilah” ve “rab” olma vasfının insan üzerindeki etkisine değinilir."]'::jsonb, '{}'::jsonb, 26, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#27', 'yks-2026-dkab', 'yks-2026-dkab#6', '10.1.6', 'Rûm suresi 18-27. ayetlerde verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar Esmâ-i Hüsnâ, tilavet, kıraat, dua, tövbe, istiğfar."]'::jsonb, '{}'::jsonb, 27, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#28', 'yks-2026-dkab', 'yks-2026-dkab#7', '10.2.1', 'Kur’an-ı Kerim’den gençlerle ilgili ayetlere örnekler verir.', NULL, '[]'::jsonb, '{}'::jsonb, 28, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#29', 'yks-2026-dkab', 'yks-2026-dkab#7', '10.2.2', 'Hz. Muhammed''in gençlik yıllarındaki erdemli davranışlarını kendi hayatıyla ilişkilendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 29, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#30', 'yks-2026-dkab', 'yks-2026-dkab#7', '10.2.3', 'Hz. Muhammed ile genç sahabiler arasındaki iletişimi değerlendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 30, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#31', 'yks-2026-dkab', 'yks-2026-dkab#7', '10.2.4', 'Bazı genç sahabilerin öne çıkan özelliklerini örnek alır.', NULL, '[" Öğretmen: Mus''ab b. Umeyr”, “Genç Bir Komutan: Üsame b. Zeyd”, “Genç Bir Yönetici: Muaz b. Cebel”, “Genç Bir Âlim: Hz. Aişe”, “Genç Bir Anne: Hz. Fatıma”, “Sorumluluk Sahibi Bir Genç: Esma binti Ebi Bekir”, “Habeş Kralının Huzurunda Bir Genç: Cafer b. Ebi Talib” konularına yer verilir. “Bilge ve Kahraman Bir Genç: Hz. Ali”, “Genç Bir Davetçi: Erkam b. Ebi’l-Erkam”, “Genç Bir"]'::jsonb, '{}'::jsonb, 31, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#32', 'yks-2026-dkab', 'yks-2026-dkab#7', '10.2.5', 'Âl-i İmrân suresi 159. ayette verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar sahabi, âlim, el-emin, istişare. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 32, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#33', 'yks-2026-dkab', 'yks-2026-dkab#8', '10.3.1', 'İslam dininin aile kurumuna verdiği önemi fark eder.', NULL, '[]'::jsonb, '{}'::jsonb, 33, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#34', 'yks-2026-dkab', 'yks-2026-dkab#8', '10.3.2', 'İslam dininin kültür, sanat ve düşünce üzerindeki etkilerini analiz eder.', NULL, '[" İslam dininin kültürel hayatımızın zenginleşmesindeki katkılarına ve İslam medeniyetinde öne çıkan sanat dallarına kısaca yer verilir. Ayrıca “ Eşyada asıl olan ibahadır.” ilkesinin sanat alanında da geçerli olduğuna değinilir."]'::jsonb, '{}'::jsonb, 34, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#35', 'yks-2026-dkab', 'yks-2026-dkab#8', '10.3.3', 'İslam dininin çevre sorunlarına yaklaşımını ve çözüm önerilerini değerlendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 35, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#36', 'yks-2026-dkab', 'yks-2026-dkab#8', '10.3.4', 'İslam dini ve sosyal değişim arasında ilişki kurar.', NULL, '[" Dinin sabiteleri ve değişkenleri üzerinde durulur; bazı dinî hüküm ve yorumların zamana ve mekâna göre değişebileceğine değinilir."]'::jsonb, '{}'::jsonb, 36, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#37', 'yks-2026-dkab', 'yks-2026-dkab#8', '10.3.5', 'İslam dininin ekonomik hayatla ilgili ilkelerini yorumlar.', NULL, '[]'::jsonb, '{}'::jsonb, 37, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#38', 'yks-2026-dkab', 'yks-2026-dkab#8', '10.3.6', 'İslam dininin sosyal adaletle ilgili ilkelerini açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 38, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#39', 'yks-2026-dkab', 'yks-2026-dkab#8', '10.3.7', 'Âl-i İmrân suresi 103-105. ayetlerdeki mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar din, sanat, iktisat, sosyal değişim. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 39, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#40', 'yks-2026-dkab', 'yks-2026-dkab#9', '10.4.1', 'İslam ahlakının konusu ve gayesini açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 40, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#41', 'yks-2026-dkab', 'yks-2026-dkab#9', '10.4.2', 'Ahlak ile terbiye arasındaki ilişki kurar.', NULL, '[" Duygu yönetimi, düşünce yönetimi, davranış yönetimi, irade yönetimi gibi konular ayet ve hadislerle ilişkilendirilerek ele alınır."]'::jsonb, '{}'::jsonb, 41, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#42', 'yks-2026-dkab', 'yks-2026-dkab#9', '10.4.3', 'İslam ahlakında yerilen bazı davranışları ayet ve hadislerle açıklar.', NULL, '[" Kazanım kapsamında yalan ve iftira, mahremiyetin ihlali (tecessüs), gıybet, haset, suizan, hile ve israf konularına değinilir.  Öğrencilerin İslam ahlakında yerilen bazı davranışların, bireysel ve toplumsal zararlarını değerlendirmelerine yönelik etkinliklere yer verilir. 10.4.4.Tutum ve davranışlarında ölçülü olmaya özen gösterir."]'::jsonb, '{}'::jsonb, 42, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#43', 'yks-2026-dkab', 'yks-2026-dkab#9', '10.4.5', 'Hucurât suresi 11-12. ayetlerde verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar ahlak, seciye, şahsiyet, karakter, terbiye. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 43, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#44', 'yks-2026-dkab', 'yks-2026-dkab#10', '10.5.1', 'Din ve dinin yorumu arasındaki farkı ayırt eder.', NULL, '[" doğan sorunların, dinin kendisinden kaynaklanmadığına değinilir.  girilmeden ele alınır. Dinin farklı yorum biçimleri olabileceğine vurgu yapılır; dinin yanlış yorumlanmasından Din anlayışındaki yorum farklılıklarının sebepleri düzeye uygun bir biçimde ayrıntıya"]'::jsonb, '{}'::jsonb, 44, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#45', 'yks-2026-dkab', 'yks-2026-dkab#10', '10.5.2', 'İslam düşüncesindeki yorum farklılıklarının sebeplerini tartışır.', NULL, '[" yaklaşım ve onları yorumlama farklılıklarından kaynaklanan sebepler ile sınırlandırılır. Yorum farklılıkları; insan unsuru; sosyal, siyasi, kültürel ve coğrafi ortam ile dinî metinlere"]'::jsonb, '{}'::jsonb, 45, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#46', 'yks-2026-dkab', 'yks-2026-dkab#10', '10.5.3', 'Dinî yorumlarla ilgili bazı kavramları değerlendirir.', NULL, '[" İtikad, fıkıh, mezhep ve fırka kavramları öğrencilerin seviyeleri ve kültürel altyapıları göz önünde bulundurularak ele alınır."]'::jsonb, '{}'::jsonb, 46, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#47', 'yks-2026-dkab', 'yks-2026-dkab#10', '10.5.4', 'İslam düşüncesinde itikadi ve siyasi yorumları genel özelliklerine göre sınıflandırır.', NULL, '[" Kazanım Ehl-i sünnet (Eşarilik ve Maturidilik) ve Şia (İmamiye ve Zeydiye) ile sınırlandırılır."]'::jsonb, '{}'::jsonb, 47, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#48', 'yks-2026-dkab', 'yks-2026-dkab#10', '10.5.5', 'İslam düşüncesindeki amelî fıkhi yorumları tanır.', NULL, '[" İslam düşüncesindeki amelî fıkhi yorumlarda; Hanefilik, Malikilik, Şafiilik ve Hanbelilik mezheplerine yer verilir. Ayrıca Caferilik mezhebine de değinilir, bu mezhebin İmamiye Şiası’nın ameli/fıkhi yorumu olduğuna vurgu yapılır."]'::jsonb, '{}'::jsonb, 48, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#49', 'yks-2026-dkab', 'yks-2026-dkab#10', '10.5.6', 'Nisâ suresi 59. ayette verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar itikad, mezhep, fırka, tevil. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 49, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#50', 'yks-2026-dkab', 'yks-2026-dkab#11', '11.1.1', 'Hayatı anlamlandırmada ahiret inancının önemini fark eder.', NULL, '[" Kur’an-ı Kerim’den dünya hayatının amacıyla ilgili örnekler verilmesine özen gösterilir."]'::jsonb, '{}'::jsonb, 50, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#51', 'yks-2026-dkab', 'yks-2026-dkab#11', '11.1.2', 'Dünya hayatı ile ahiret hayatı arasında ilişki kurar.', NULL, '[]'::jsonb, '{}'::jsonb, 51, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#52', 'yks-2026-dkab', 'yks-2026-dkab#11', '11.1.3', 'Ahiret hayatının aşamalarını ayet ve hadislerle temellendirir.', NULL, '[" Ölüm, kabir, berzah âlemi, kıyamet, ba’s, haşir, hesap, cennet ve cehennem kavramlarına yer verilir.  Kıyamet ve yeniden diriliş gibi konular akli ve naklî deliller ışığında ele alınır."]'::jsonb, '{}'::jsonb, 52, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#53', 'yks-2026-dkab', 'yks-2026-dkab#11', '11.1.4', 'Cenaze uğurlama ile ilgili dinî uygulamaları örneklerle açıklar.', NULL, '[" Vefat edenin vasiyet ve borçları; tekfin ve teçhiz, cenaze namazı, taziye ve Kur’an okuma, dua etmek ve hayır yapmak konularına yer verilir.  Cenaze namazına katılmanın ve taziyede bulunmanın, dinî ve insani bir görev olduğuna değinilir.  Kültürümüzde cenaze uğurlama ile ilgili gelenekler tanıtılır; ayrıca Alevi-Bektaşilikte yer alan “Hakk’a Uğurlama Erkânı” gibi cenaze uğurlama geleneklerine de değinilir."]'::jsonb, '{}'::jsonb, 53, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#54', 'yks-2026-dkab', 'yks-2026-dkab#11', '11.1.5', 'Bakara suresi 153-157. ayetlerde verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar ahiret, vefat, cenaze. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 54, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#55', 'yks-2026-dkab', 'yks-2026-dkab#12', '11.2.1', 'Hz. Muhammed’in örnek şahsiyetini tanır.', NULL, '[" Hz. Muhammed’in beşerî yönü ile ilgili ayetlerden örnek verilmesine özen gösterilir.  Hz. Muhammed’in ahlaki özellikleri örneklerle ele alınır.  Öğrencilerin, İslam’ı anlamada Hz. Muhammed’in örnek şahsiyetinin yerini analiz edebileceği etkinliklere yer verilir."]'::jsonb, '{}'::jsonb, 55, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#56', 'yks-2026-dkab', 'yks-2026-dkab#12', '11.2.2', 'Hz. Muhammed’in peygamberlikle ilgili görevlerini açıklar.', NULL, '[" Hz. Muhammed’in tebliğ, tebyin, teşri ve temsil (İslam’ı anlama ve yaşama konusundaki örnekliği) görevlerine değinilir."]'::jsonb, '{}'::jsonb, 56, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#57', 'yks-2026-dkab', 'yks-2026-dkab#12', '11.2.3', 'Hz. Peygamber’e bağlılık ve itaati ayet ve hadislerden hareketle yorumlar.', NULL, '[" Hadis ve sünnet kavramlarına, İslam’ın anlaşılmasında sünnetin önemine ve kültürümüzde Peygamber ve Ehl-İ Beyt sevgisine de değinilir.  Hadis kaynaklarından Kütüb-i tis’a ve müellifleri isim olarak listelenir."]'::jsonb, '{}'::jsonb, 57, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#58', 'yks-2026-dkab', 'yks-2026-dkab#12', '11.2.4', 'Ahzâb suresi 45-46. ayetlerde verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar hadis, sünnet, üsve-i hasene, hatemü’n-nebiyyîn, Kütüb-i sitte, Kütüb-i tis’a. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 58, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#59', 'yks-2026-dkab', 'yks-2026-dkab#13', '11.3.1', 'Kur’an’ı Kerim’de geçen bazı kavramları yorumlar.', NULL, '[" Cihat kavramı; anlam genişliği göz önünde bulundurularak salt savaş ile sınırlandırılmadan tüm boyutlarıyla ve Mekkî ve Medenî ayetlerin bu kavrama yüklediği anlamlar bağlamında ele alınır. Cihadın bir ibadet olarak farzı ayın ve farz-ı kifaye olduğu durumlara değinilir. Bu kapsamda ceht, mücahede, davet, tebliğ, irşat, emr-i bi’l-maruf ve nehy-i ani’l-münker, kıtal/mukatele ve şehadet kavramlarına yer verilir."]'::jsonb, '{}'::jsonb, 59, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#60', 'yks-2026-dkab', 'yks-2026-dkab#13', '11.3.2', 'Kur’an’ı Kerim’de geçen kavramları tanımanın İslam’ı doğru anlamadaki önemini fark eder.', NULL, '[]'::jsonb, '{}'::jsonb, 60, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#61', 'yks-2026-dkab', 'yks-2026-dkab#13', '11.3.3', 'Kehf suresi 107-110. ayetlerde verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar hidayet, ihsan, ihlas, takva, sırat-ı müstakim, cihat, salih amel, şehadet. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 61, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#62', 'yks-2026-dkab', 'yks-2026-dkab#14', '11.4.1', 'İnançla ilgili yaklaşımları tartışır.', NULL, '[" İnançla ilgili yaklaşımlardan teizm, deizm, materyalizm, pozitivizm, sekülarizm, agnostisizm, ateizm ve nihilizme yer verilir. İnançla ilgili yaklaşımlar ele alınırken “kötülük problemi” üzerinde durulur ve problemin inançla ilgili yaklaşımlarla olan ilişkisine değinilir."]'::jsonb, '{}'::jsonb, 62, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#63', 'yks-2026-dkab', 'yks-2026-dkab#14', '11.4.2', 'Yeni dinî akımların özelliklerini değerlendirir.', NULL, '[" “Milenyum Tarikatları”, “Kıyamet Tarikatları” gibi adlarla sınıflandırılan yeni dinî akımların ortak yönlerine, ortaya çıkma ve yaygınlaşma sebeplerine ve ülkemize olan yansımalarına güncel örneklerle yer verilir.  Dinî değerlerin istismarının olumsuz sonuçlarına değinilir; din istismarının siyasi, ekonomik ve sosyal sebepleri üzerinde durulur. Bu kapsamda FETÖ gibi illegal, çıkarcı yapı ve gruplara değinilir.  Batı’da ortaya çıkan “İslamofobi/İslam karşıtlığı” gibi ırkçı akımların gelişmesine sebep olarak gösterilen, hem söylemleri hem de eylemleriyle başta Müslüman halklar olmak üzere dünya üzerinde yaşayan pek çok halka zarar veren, DEAŞ gibi şiddet odaklı, terörist, illegal ve marjinal gruplara değinilir."]'::jsonb, '{}'::jsonb, 63, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#64', 'yks-2026-dkab', 'yks-2026-dkab#14', '11.4.3', 'En’âm suresi 59 ve Lokmân suresi 27. ayetlerde verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar inanç, istismar, İslamofobi. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 64, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#65', 'yks-2026-dkab', 'yks-2026-dkab#15', '11.5.1', 'Yahudiliğin doğuşunu ve gelişim sürecini özetler.', NULL, '[" Yahudiliğin; tarihçesine, inanç esaslarına, ritüellerine, sembollerine ve kutsal mekânlarına; İbrani, İsrail, Yahudi ve Musevi kavramlarına; Yahudilerin kitap ve peygamber anlayışına ve günümüz Yahudi mezheplerine yer verilir. Ayrıca “Siyonizm” konusuna değinilir."]'::jsonb, '{}'::jsonb, 65, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#66', 'yks-2026-dkab', 'yks-2026-dkab#15', '11.5.2', 'Hıristiyanlığın doğuşunu ve gelişim sürecini özetler.', NULL, '[" Hıristiyanlığın; tarihçesine, mekânlarına; Hıristiyanlığın kurumsallaşmasında ve inanç esaslarının oluşmasında Pavlus’un rolüne; Hıristiyanların vahiy ve peygamber anlayışına ve Hıristiyan gruplara (Katoliklik, Ortodoksluk ve Protestanlık) yer verilir. Ayrıca “evanjelik akımlar”dan kısaca bahsedilir. Anahtar Kavramlar Kitab-ı Mukaddes, Ahd-i atik, Ahd-i cedit, sinagog, teslis, haç, kilise, vaftiz, ritüel, sakrament. ●▬▬▬▬๑۩۩๑▬▬▬▬▬● inanç esaslarına, ritüellerine, sembollerine ve kutsal"]'::jsonb, '{}'::jsonb, 66, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#67', 'yks-2026-dkab', 'yks-2026-dkab#16', '12.1.1', 'Din-bilim ilişkisini tartışır.', NULL, '[" İlim öğrenmeyi teşvik eden ayet ve hadislerden örnekler verilir."]'::jsonb, '{}'::jsonb, 67, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#68', 'yks-2026-dkab', 'yks-2026-dkab#16', '12.1.2', 'İslam medeniyetinde bilim ve düşüncenin gelişim sürecini değerlendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 68, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#69', 'yks-2026-dkab', 'yks-2026-dkab#16', '12.1.3', 'İslam medeniyetinde öne çıkan eğitim ve bilim kurumlarını tanır.', NULL, '[" Kurumlar; cami, mescit, mektep, medrese, daru’l-kurra, daru’l-hadis, beytü’l-hikme kütüphane, rasathane ve şifahane ile sınırlandırılır."]'::jsonb, '{}'::jsonb, 69, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#70', 'yks-2026-dkab', 'yks-2026-dkab#16', '12.1.4', 'Müslümanların bilim alanında yaptığı özgün çalışmaları sınıflandırır.', NULL, '[" Geçmişten günümüze Müslümanların bilim alanında yaptığı öncü ve özgün çalışmalara (dil, fıkıh, kelam, tefsir, hadis, tarih, felsefe, coğrafya, tıp, astronomi, matematik, fizik, kimya) ana hatlarıyla yer verilir ve bu çalışmaların diğer medeniyetlerdeki ilmî gelişmelere olan etkisine değinilir."]'::jsonb, '{}'::jsonb, 70, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#71', 'yks-2026-dkab', 'yks-2026-dkab#16', '12.1.5', 'Fâtır suresi 27-28. ayette verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar ilim, bilim, âlim, bilgin. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 71, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#72', 'yks-2026-dkab', 'yks-2026-dkab#17', '12.2.2', 'Dinî anlayış ve kültürümüzün oluşmasında etkili olan bazı şahsiyetleri tanır.', NULL, '[" Dinî anlayış ve kültürümüzün oluşmasında etkili olan şahsiyetlerden; Ebu Hanife, Cafer es- Sadık, Maturidi, Şafii, Eş’ari, Ahmet Yesevi, Mevlana Celaleddin-i Rumi, Ahi Evran, Hacı Bektaş-ı Veli, Yunus Emre, Sarı Saltuk, Hacı Bayram-ı Veli’ye öğrenci seviyesine göre yer verilir.  Dinî anlayış ve kültürümüzün oluşmasında etkili olan şahsiyetlerin ortak değerimiz olduğuna değinilir."]'::jsonb, '{}'::jsonb, 72, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#73', 'yks-2026-dkab', 'yks-2026-dkab#17', '12.2.3', 'Nisâ suresi 69. ayette verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar âlim, fakih, tasavvuf, veli. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 73, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#74', 'yks-2026-dkab', 'yks-2026-dkab#18', '12.3.1', 'İslam düşüncesinde tasavvufi düşüncenin oluşum sürecini değerlendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 74, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#75', 'yks-2026-dkab', 'yks-2026-dkab#18', '12.3.2', 'Tasavvufi düşüncede ahlaki boyutun önemini fark eder.', NULL, '[" Edep ve insan-ı kâmil kavramlarının tasavvufi düşüncedeki yerine de değinilir."]'::jsonb, '{}'::jsonb, 75, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#76', 'yks-2026-dkab', 'yks-2026-dkab#18', '12.3.3', 'Kültürümüzde etkin olan bazı tasavvufi yorumları tanır.', NULL, '[" Yesevilik, Kadirilik, Rifailik, Mevlevilik, Nakşibendilik ve Alevilik-Bektaşilik konularına yer verilir."]'::jsonb, '{}'::jsonb, 76, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#77', 'yks-2026-dkab', 'yks-2026-dkab#18', '12.3.4', 'Alevilik-Bektaşilikteki temel kavram ve erkânları tanır.', NULL, '[" Cem ve cemevi, musahiplik, razılık ve kul hakkının sorulması, cemde on iki hizmet, semah, gülbank, Hızır ve Muharrem orucu konularına yer verilir. Bu kapsamda;  Hacı Bektaş Veli’nin, Bektaşiliğin oluşumu ve Aleviliğin gelişimindeki rolüne, Alevilik- Bektaşilikteki “ocak kültürü”ne, “el ele, el hakka ikrarı”na ve “dört kapı kırk makam”a yer verilir; Bektaşilikte musahipliğe “ikrar ve nasip alma” da denildiğine ve bu kavramın İslam tarihindeki muhacir ensar kardeşliğine dayandırıldığına değinilir.  Cemevi; âyin-i cem erkânının yapıldığı, “yol, âdap ve erkân yeri” olarak nitelendirilir; Bektaşilikte ise cemevi yerine “meydan evi” ifadesinin kullanıldığına da değinilir. “Düşkünlükten kaldırma cemi”, “Dardan indirme cemi” ile “Abdal Musa cemi”nden bahsedilir. Âyin-i cem ve cemevi ile ilgili görsellere yer verilir.  Alevilik-Bektaşilikte duaların başında, “Bismişah”, sonunda ise “Allah Allah” lafzının söylendiğine değinilir. “Gülbank” konusunda ise “Lokma Duasına” da yer verilir."]'::jsonb, '{}'::jsonb, 77, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#78', 'yks-2026-dkab', 'yks-2026-dkab#18', '12.3.5', 'Hucurât Suresi 10. ayette verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar tasavvuf, edep, veli, mürşid, insan-ı kâmil, erkân, semâ. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 78, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#79', 'yks-2026-dkab', 'yks-2026-dkab#19', '12.4.1', 'Dinî meselelerin çözümüyle ilgili temel ilke ve yöntemleri analiz eder.', NULL, '[" Güncel dinî meselelerin çözümü için öne sürülen ilke ve yöntemlerin, İslâm âlimlerinin üzerinde icma ettiği temel esas ve hükümlere ters düşmemesi, bu önerilerin “zarûrât-ı diniye” adı verilen kesin hükümlere aykırı olmaması gibi ilkelere vurgu yapılır.  İslam’ın ortaya koyduğu çözümlerin temel amacının, insanların can, nesil, akıl, mal ve din emniyetini güvence altına almak olduğuna dikkat çekilir.  Çözüm önerilerinin fıtrata, yani Allah''ın koyduğu dengeye ve yaratılışa aykırı olmamasına; temel ahlaki değerleri ihlal etmemesi gerektiğine değinilir.  Sorunların ele alınmasında, farklı uzmanlık alanlarına ve kolektif akla başvurulmasının önemi üzerinde durulur."]'::jsonb, '{}'::jsonb, 79, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#80', 'yks-2026-dkab', 'yks-2026-dkab#19', '12.4.2', 'İslam’ın ekonomik hayatla ilgili ahlaki ölçülerini yorumlar.', NULL, '[" İslam’ın mülkiyet anlayışı, fakirlik problemine bakışı ve fakirliğin çözümü için ortaya koyduğu ilkeler ele alınır.  İslam’da İşçi ve işveren haklarına yer verilir. Ayrıca “İş Sağlığı ve Güvenliği” kapsamında “güvenli yaşam” hususuna da değinilir."]'::jsonb, '{}'::jsonb, 80, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#81', 'yks-2026-dkab', 'yks-2026-dkab#19', '12.4.3', 'Gıda maddeleri ve bağımlılık konusundaki dinî ve ahlaki ilkeleri açıklar.', NULL, '[" Yiyecek ve içecekler konusunda “Eşyada asıl olan ibahadır.” ilkesi kapsamında “yasakların sınırlı, helaller alanının ise geniş olduğu” vurgulanır.  İslam dinine göre yenilmesi ve içilmesi yasaklanmış olan gıdalara örnekler verilir.  Yiyecek ve içeceklerle ilgili yasakların delillerine ve hikmetlerine yer verilir.  Genetiği ve öz niteliği değiştirilmiş yiyecek ve içeceklerin insanın beden ve ruh sağlığı üzerindeki etkilerine değinilir.  Uyuşturucu madde, alkol ve sigara kullanımı ile kumar oynamak gibi bağımlılığa neden olan zararlı alışkanlıklara yer verilir."]'::jsonb, '{}'::jsonb, 81, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#82', 'yks-2026-dkab', 'yks-2026-dkab#19', '12.4.4', 'Sağlık ve tıpla ilgili bazı meseleleri dinî ve ahlaki ölçüler çerçevesinde yorumlar.', NULL, '[" Otopsi, ötenazi, organ nakli, kan bağışı, haram maddelerle tedavi ve intihar konularına ayrıntıya girilmeden öğrenci seviyesi dikkate alınarak yer verilir."]'::jsonb, '{}'::jsonb, 82, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#83', 'yks-2026-dkab', 'yks-2026-dkab#19', '12.4.5', 'En’âm suresi 151-152. ayetlerde verilen mesajları değerlendirir.', NULL, '[" Kazanım; öğrencilerin Kur’an-ı Kerim mealini kullanma, Kur’an-ı Kerim’i anlama ve yorumlama, ayetlerde geçen şahıs, yer, konu ve kavramları belirleme becerilerini geliştirici etkinliklerle desteklenir. Bu kapsamda ayetlerin (nüzul sebebi, ana konuları gibi) kısa açıklamalarına öğrenci seviyesine göre yer verilir. Anahtar Kavramlar icma, helal, haram, mekruh, mübah. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 83, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#84', 'yks-2026-dkab', 'yks-2026-dkab#20', '12.5.1', 'Hinduizm’in doğuşunu ve gelişim sürecini özetler.', NULL, '[" Hinduizm’in; tarihçesine, inanç esaslarına, ritüellerine, sembollerine ve kutsal mekânlarına yer verilir."]'::jsonb, '{}'::jsonb, 84, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#85', 'yks-2026-dkab', 'yks-2026-dkab#20', '12.5.2', 'Budizm’in doğuşunu ve gelişim sürecini özetler.', NULL, '[" Budizm’in; tarihçesine, inanç esaslarına, ritüellerine, sembollerine ve kutsal mekânlarına yer verilir."]'::jsonb, '{}'::jsonb, 85, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#86', 'yks-2026-dkab', 'yks-2026-dkab#20', '12.5.3', 'Konfüçyanizm’in doğuşunu ve gelişim sürecini özetler.', NULL, '[" Konfüçyanizm’in; tarihçesine, mekânlarına yer verilir. inanç esaslarına, ritüellerine, sembollerine ve kutsal"]'::jsonb, '{}'::jsonb, 86, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-dkab#87', 'yks-2026-dkab', 'yks-2026-dkab#20', '12.5.4', 'Taoizm’in doğuşunu ve gelişim sürecini özetler.', NULL, '[" Taoizm’in; tarihçesine, inanç esaslarına, ritüellerine, sembollerine ve kutsal mekânlarına yer verilir. Anahtar Kavramlar karma, tenasüh, reenkarnasyon. ●▬▬▬▬๑۩۩๑▬▬▬▬▬●"]'::jsonb, '{}'::jsonb, 87, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#1', 'yks-2026-felsefe', 'yks-2026-felsefe#1', '10.1.1', 'Felsefenin anlamını açıklar.', NULL, '["a) Çeşitli sorulardan (Bilgi nedir?, Bilinç nedir?, Öz bilinç nedir?) hareketle düşünmenin önemi ve gerekliliğinin tartışılması sağlanır.", "b) Felsefe (philosophia) terimi kapsamında geçen sevgi, arayış, bilgi, hakikat ve hikmet (bilgelik/sophia) kavramlarının felsefeyle ilişkisine değinilir.", "c) Farklı düşünürlerin (Platon, Aristoteles, el-kindî, Fârâbî, İbn Sînâ, I. Kant, K. Jaspers, Hilmi Ziya Ülken ve Takiyettin Mengüşoğlu) felsefe tanımlarına yer verilerek bu tanımların benzer ve farklı noktalarının belirtilmesi sağlanır.", "d) Bilişim teknolojileri kullanılarak “Filozof kimdir?” sorusuna ilişkin bir sunum hazırlanması ve sunumun sınıf ortamında paylaşılması sağlanır."]'::jsonb, '{}'::jsonb, 1, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#2', 'yks-2026-felsefe', 'yks-2026-felsefe#1', '10.1.2', 'Felsefi düşüncenin özelliklerini açıklar.', NULL, '["a) Felsefi düşüncenin ortaya çıkışı üzerinde kısaca durulur.", "b) Felsefenin sorgulama, merak etme, şüphe duyma, hayret etme, yığılımlı ilerleme, eleştirel, refleksif, rasyonel, sistemli, tutarlı ve evrensel olma özellikleri vurgulanır.", "c) N. Uygur’un “Bir Felsefe Sorusu Nedir?” adlı makalesinden alınan veya derlenen bir metinden hareketle felsefi soruların özelliklerinin yorumlanması sağlanır."]'::jsonb, '{}'::jsonb, 2, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#3', 'yks-2026-felsefe', 'yks-2026-felsefe#1', '10.1.3', 'Felsefenin insan ve toplum hayatı üzerindeki rolünü örneklerle açıklar.', NULL, '["a) Felsefenin bireysel ve toplumsal işlevlerine değinilir.", "b) Felsefe hayat ilişkisinin günlük hayattan örneklerle yorumlanması sağlanır. ÜNİTE 2: FELSEFE İLE DÜŞÜNME"]'::jsonb, '{}'::jsonb, 3, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#4', 'yks-2026-felsefe', 'yks-2026-felsefe#2', '10.2.1', 'Düşünme ve akıl yürütmeye ilişkin kavramları açıklar.', NULL, '["a) Görüş, argüman, önerme, tümdengelim, tümevarım, analoji, tutarlılık, çelişiklik, gerçeklik, doğruluk ve temellendirme kavramları üzerinde durulur.", "b) Örnek metinler verilerek bu metinlerdeki akıl yürütme biçimlerinin, tutarlı ve çelişik ifadelerin belirlenmesi sağlanır."]'::jsonb, '{}'::jsonb, 4, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#5', 'yks-2026-felsefe', 'yks-2026-felsefe#2', '10.2.2', 'Düşünme ve akıl yürütmede dili doğru kullanmanın önemini açıklar.', NULL, '["a) Dilin ifade etme ve kavramlaştırma işlevi üzerinde durulur.", "b) Kavramları yanlış kullanmanın, anlamı nasıl değiştirdiğine ilişkin günlük hayattan örnekler verilmesi sağlanır."]'::jsonb, '{}'::jsonb, 5, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#6', 'yks-2026-felsefe', 'yks-2026-felsefe#2', '10.2.3', 'Bir konuyla ilgili felsefi sorular oluşturur.', NULL, '["Seçilen konu örnekleri üzerinden öğrencilere sorular yöneltilerek öğrencilerin konuya ilişkin kendi sorularını yapılandırmaları sağlanır."]'::jsonb, '{}'::jsonb, 6, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#7', 'yks-2026-felsefe', 'yks-2026-felsefe#2', '10.2.4', 'Felsefi bir görüşü veya argümanı sorgular.', NULL, '["a) Bir konuşma veya bir metin seçilerek konuşmacının yahut yazarın ileri sürdüğü görüş ve argümanların tespit edilmesi ve tartışılması sağlanır.", "b) Öğrencilerin gazete, dergi, roman, televizyon haberi, tartışma programı veya filmlerde geçen felsefi bir görüşü tespit etmeleri ve bu görüşü temellendiren argümanları sınıf ortamında tartışmaları sağlanır. ÜNİTE 3: FELSEFENİN TEMEL KONULARI VE PROBLEMLERİ"]'::jsonb, '{}'::jsonb, 7, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#8', 'yks-2026-felsefe', 'yks-2026-felsefe#3', '10.3.1', 'Varlık felsefesinin konusunu ve problemlerini açıklar.', NULL, '["a) “Varlık var mıdır?”, \"Varlığın mahiyeti nedir?\", \"Evrende amaçlılık var mıdır?” problemlerinden hareketle varlık felsefesinin konusu kısaca açıklanır.", "b) Felsefi bir metin üzerinden varlık türlerinin sınıflandırılması sağlanır.", "c) Öğrencilerin hikâye, roman, kısa film veya belgesellerden birinde işlenen konuyu varlık felsefesi açısından değerlendirmeleri ve sınıfta paylaşmaları sağlanır."]'::jsonb, '{}'::jsonb, 8, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#9', 'yks-2026-felsefe', 'yks-2026-felsefe#3', '10.3.2', 'Bilgi felsefesinin konusunu ve problemlerini açıklar.', NULL, '["a) “Doğru bilgi mümkün müdür?\", \"Bilginin kaynağı nedir?\", \"Bilginin sınırları ve doğru bilginin ölçütleri nelerdir?” problemlerinden hareketle bilgi felsefesinin konusu kısaca açıklanır.", "b) Felsefi bir metnin üzerinden doğruluk ve gerçeklik kavramları arasındaki ilişkinin tartışılması sağlanır.", "c) Öğrencilerin dergi ve gazete haberleri, internet, sosyal medya veya TV programlarında paylaşılan bilgileri, bilginin değeri ve güvenilirliği açısından tartışmaları sağlanır."]'::jsonb, '{}'::jsonb, 9, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#10', 'yks-2026-felsefe', 'yks-2026-felsefe#3', '10.3.3', 'Bilim felsefesinin konusunu ve problemlerini açıklar.', NULL, '["a) “Bilim nedir?\", \"Bilimsel yöntem nedir?”, “Bilimin değeri nedir?” problemlerinden hareketle bilim felsefesinin konusu kısaca açıklanır.", "b) Bilim felsefe ilişkisi üzerinde durulur.", "c) B. Russell’ın “Bilgelikle birleştiğinde bilimin sağladığı kudret tüm insanlığa büyük ölçüde refah ve mutluluk getirebilir; tek başına ise yalnız yıkıntıya yol açar.” sözünden hareketle bilimle hayat arasındaki ilişkinin tartışılması sağlanır. 10.3.4 Ahlak felsefesinin konusunu ve problemlerini açıklar.", "a) “İyi ve kötünün ölçütü nedir?\", \"Özgürlük ve sorumluluk arasında nasıl bir ilişki vardır?\", \"Evrensel bir ahlak yasası var mıdır?” problemlerinden hareketle ahlak felsefesinin konusu kısaca açıklanır.", "b) Felsefi bir metnin üzerinden, iyilik ve mutluluk ilişkisinin yorumlanması sağlanır.", "c) Okul ortamında yaşanan durumlardan ve olaylardan hareketle özgürlük, sorumluluk ve kural (norm) ilişkisinin tartışılması sağlanır."]'::jsonb, '{}'::jsonb, 10, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#11', 'yks-2026-felsefe', 'yks-2026-felsefe#3', '10.3.5', 'Din felsefesinin konusunu ve sorularını açıklar.', NULL, '["a) \"Tanrı’nın varlığı ile ilgili görüşler nelerdir?”, “Evren sonlu mudur, sonsuz mudur?”, “Ölümden sonra yaşam var mıdır?” problemlerinden hareketle din felsefesinin konusu kısaca açıklanır.", "b) Teoloji ve din felsefesi farkı üzerinde durulur.", "c) “Ben kimim?” sorusunun felsefe, bilim ve din açısından nasıl ele alındığının tartışılması sağlanır."]'::jsonb, '{}'::jsonb, 11, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#12', 'yks-2026-felsefe', 'yks-2026-felsefe#3', '10.3.6', 'Siyaset felsefesinin konusunu ve problemlerini açıklar.', NULL, '["a) \"Hak, adalet ve özgürlük nedir?\", “ İktidarın kaynağı nedir?\", \"İdeal devlet düzeni olabilir mi?” problemlerinden hareketle siyaset felsefesinin konusu kısaca açıklanır.", "b) Geçmişten günümüze egemenlik sorununun temel hak ve özgürlükler açısından tartışılması sağlanır.", "c) Öğrencilerin ülkemizde yaşanan sorunlardan birini araştırarak birey, toplum ve devlet ilişkileri bağlamında tartışmaları sağlanır."]'::jsonb, '{}'::jsonb, 12, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#13', 'yks-2026-felsefe', 'yks-2026-felsefe#3', '10.3.7', 'Sanat felsefesinin konusunu ve problemlerini açıklar.', NULL, '["a) “Güzel nedir?\", \"Sanat nedir?\", \"Sanat eserinin özellikleri nelerdir?” problemlerinden hareketle sanat felsefesinin konusu kısaca açıklanır.", "b) Felsefi bir metin üzerinden sanat ve duyarlılık ilişkisinin yorumlanması sağlanır.", "c) Öğrencilerin yaşadığı şehrin mimari yapısını estetik açıdan tartışmaları sağlanır. ÜNİTE 4: FELSEFİ OKUMA VE YAZMA"]'::jsonb, '{}'::jsonb, 13, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#14', 'yks-2026-felsefe', 'yks-2026-felsefe#4', '10.4.1', 'Felsefi bir metni analiz eder.', NULL, '["Felsefi bir metin örneğinde; “ Metinde hangi felsefi kavramlar geçmektedir?”, “ Metinde hangi felsefi problem veya problemler ele alınmaktadır?”, “ Felsefi probleme veya problemlere filozofun bakış açısı nasıldır?”, “ Kullanılan kavramlar ve savunulan görüşler, güncel sorunların anlaşılması ve çözümlenmesi için nasıl bir katkı sunabilir?” soruları yoluyla analiz ve değerlendirme yapılması sağlanır."]'::jsonb, '{}'::jsonb, 14, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#15', 'yks-2026-felsefe', 'yks-2026-felsefe#4', '10.4.2', 'Verilen konu hakkında alternatif görüşler geliştirir.', NULL, '["Metin alıntılarına yer verilerek öğrencilerin bu alıntılardaki konu veya durumla ilgili öne sürülen görüşleri belirlemeleri ve “Bu konuya farklı bir açıdan bakılabilir mi?”, “Bu konuyla ilgili sizden görüş öne sürmeniz istenseydi görüşünüz ne olurdu?” gibi sorulardan hareketle aynı konuyla ilgili özgün görüşler geliştirmeleri sağlanır."]'::jsonb, '{}'::jsonb, 15, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#16', 'yks-2026-felsefe', 'yks-2026-felsefe#4', '10.4.3', 'Bir konu hakkında felsefi bir deneme yazar.', NULL, '["a) Felsefi denemenin ne olduğu ve nasıl yazıldığı açıklanır.", "b) Tutarlı, sistematik ve temellendirilmiş bir felsefi denemenin yazılması sağlanır."]'::jsonb, '{}'::jsonb, 16, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#17', 'yks-2026-felsefe', 'yks-2026-felsefe#4', '10.4.4', 'Felsefi akıl yürütme becerilerini diğer alanlarda kullanır.', NULL, '["Felsefeden farklı bir konuda yazılmış bir metni, felsefenin varlık, bilgi ve değer alanları üzerinden yorumlanması sağlanır."]'::jsonb, '{}'::jsonb, 17, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#18', 'yks-2026-felsefe', 'yks-2026-felsefe#5', '11.1.1', 'Felsefenin ortaya çıkışını hazırlayan düşünce ortamını açıklar.', NULL, '["a) Sümer, Mezopotamya, Mısır, Çin, Hint ve İran medeniyetlerinde varlık, bilgi ve değer anlayışlarının felsefenin doğuşundaki etkilerine değinilir.", "b) Anadolu’da yaşamış filozofların (Thales, Anaksimandros, Anaksimenes, Anaksagoras, Herakleitos, Epiktetos, Diogenes, Lukianos, Ksenofanes ve Aristoteles) doğduğu ve yaşadığı yer vurgulanarak haklarında kısaca biyografik bilgi verilir."]'::jsonb, '{}'::jsonb, 18, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#19', 'yks-2026-felsefe', 'yks-2026-felsefe#5', '11.1.2', 'MÖ 6. yüzyıl-MS 2. yüzyıl felsefesinin karakteristik özelliklerini açıklar.', NULL, '["a) Filozofların ilk neden hakkındaki Empedokles ve Demokritos) ve değişim düşüncesi (Lao Tse, Herakleitos ve Parmenides) ele alınır.", "b) Sokrates ve Sofistlerin (Protagoras ve Gorgias) bilgi ve ahlak anlayışları ele alınır.", "c) Platon ve Aristoteles’in varlık, bilgi ve değer anlayışları ele alınır. düşünceleri (Thales, Anaksimandros, Anaksimenes,"]'::jsonb, '{}'::jsonb, 19, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#20', 'yks-2026-felsefe', 'yks-2026-felsefe#5', '11.1.3', 'Örnek felsefi metinlerden hareketle MÖ 6. yüzyıl-MS 2. yüzyıl filozoflarının felsefi görüşlerini analiz eder.', NULL, '["a) Konfüçyüs’ün “İdeal Bir İnsan ve Topluma Dair Konuşmalar” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun ahlak görüşünün irdelenmesi sağlanır.", "b) Platon’un “Sokrates’in Savunması” adlı eserinden alınan veya derlenen bir metinden hareketle Sokrates’in “bilgelik ve erdem” anlayışının irdelenmesi sağlanır.", "c) Platon’un “Devlet” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun varlık, bilgi ve siyaset görüşlerinin irdelenmesi sağlanır.", "d) Aristoteles’in “Nikomakhos’a Etik” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun “altın orta” düşüncesinin irdelenmesi sağlanır."]'::jsonb, '{}'::jsonb, 20, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#21', 'yks-2026-felsefe', 'yks-2026-felsefe#5', '11.1.4', 'MÖ 6. yüzyıl-MS 2. yüzyıl felsefesindeki örnek düşünce ve argümanları felsefi açıdan değerlendirir.', NULL, '["a) Protagoras’ın “İnsan her şeyin ölçüsüdür.” sözünün dayandığı argümanların tartışılması sağlanır.", "b) Öğrencilerin, “bilgi erdem ilişkisini” günlük hayatla ilişkilendiren özgün bir metin yazmaları sağlanır. ÜNİTE 2: MS 2. YÜZYIL-MS 15. YÜZYIL FELSEFESİ"]'::jsonb, '{}'::jsonb, 21, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#22', 'yks-2026-felsefe', 'yks-2026-felsefe#6', '11.2.1', 'MS 2. yüzyıl-MS 15. yüzyıl felsefesini hazırlayan düşünce ortamını açıklar.', NULL, '["MÖ 6. yüzyıl-MS 2. yüzyıl felsefesinin MS 2. yüzyıl-MS 15. yüzyıl felsefesi üzerindeki etkilerine değinilir."]'::jsonb, '{}'::jsonb, 22, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#23', 'yks-2026-felsefe', 'yks-2026-felsefe#6', '11.2.2', 'MS 2. yüzyıl-MS 15. yüzyıl felsefesinin karakteristik özelliklerini açıklar.', NULL, '["a) MS 2. yüzyıl-MS 15. yüzyıl Hristiyan felsefesinin temel özellikleri ve problemleri üzerinde durulur.", "b) MS 2. yüzyıl-MS 15. yüzyıl İslam felsefesinin temel özellikleri ve problemleri üzerinde durulur.", "c) MS 2. yüzyıl-MS 15. yüzyıl felsefesinin temel problemlerinden “inanç akıl ilişkisi” konusunda Hristiyan ve İslam felsefesinin yaklaşımları arasındaki farklar vurgulanır.", "d) 8-12. yüzyıl arasındaki çeviri faaliyetlerinin İslam felsefesine ve Batı felsefesine etkileri üzerinde durulur."]'::jsonb, '{}'::jsonb, 23, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#24', 'yks-2026-felsefe', 'yks-2026-felsefe#6', '11.2.3', 'Örnek felsefi metinlerden hareketle MS 2. yüzyıl-MS 15. yüzyıl filozoflarının felsefi görüşlerini analiz eder.', NULL, '["a) St. Augustinus’un “İtiraflar” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun “Tanrı ve evren” ile ilgili görüşlerinin irdelenmesi sağlanır.", "b) Fârâbî’nin “el-medînetü’l fâzıla” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun ahlak ve siyaset görüşlerinin irdelenmesi sağlanır.", "c) İbn Sînâ’nın “Salâmân ve absâl” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun varlık görüşünün irdelenmesi sağlanır.", "d) Gazâlî’nin “el-münkız mine''d-dalâl” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun bilgi görüşünün irdelenmesi sağlanır.", "e) İbn Rüşd’ün “Tehâfut et-tehâfut el-felâsife” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun “din felsefe ilişkisi” ile ilgili görüşlerinin irdelenmesi sağlanır."]'::jsonb, '{}'::jsonb, 24, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#25', 'yks-2026-felsefe', 'yks-2026-felsefe#6', '11.2.4', 'MS 2. yüzyıl-MS 15. yüzyıl felsefesindeki örnek düşünce ve argümanları felsefi açıdan değerlendirir.', NULL, '["a) Mevlânâ, Yûnus Emre ve Hacı Bektâş Velî‘nin eserlerinden alınan veya derlenen bir metinden hareketle tasavvuf düşüncesindeki insan anlayışının tartışılması sağlanır.", "b) “Anlamak için inanıyorum” düşüncesinden hareketle “inanç akıl ilişkisini” ele alan özgün bir metin yazılması sağlanır. ÜNİTE 3: 15. YÜZYIL-17. YÜZYIL FELSEFESİ"]'::jsonb, '{}'::jsonb, 25, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#26', 'yks-2026-felsefe', 'yks-2026-felsefe#7', '11.3.1', '15. yüzyıl-17. yüzyıl felsefesini hazırlayan düşünce ortamını açıklar.', NULL, '["a) 12. yüzyıldaki çeviri faaliyetlerinin 15. Yüzyıl-17. yüzyıl felsefesi üzerindeki etkilerine değinilir.", "b) MÖ 6. yüzyıl- MS 2. yüzyıl ve MS 2. yüzyıl-MS 15. yüzyıl felsefesinin 15. yüzyıl-17. yüzyıl felsefesi üzerindeki etkilerine değinilir."]'::jsonb, '{}'::jsonb, 26, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#27', 'yks-2026-felsefe', 'yks-2026-felsefe#7', '11.3.2', '15. yüzyıl-17. yüzyıl felsefesinin karakteristik özelliklerini açıklar.', NULL, '["a) Skolastik düşünce ile modern düşüncenin temel farkları üzerinde durulur.", "b) Hümanizm, bilimsel yöntem, kartezyen felsefe ve hukuk felsefesi üzerinde durulur.", "c) N. Kopernik, G. Galileo, F. Bacon ve I. Newton’un bilimsel çalışmalarının 15. yüzyıl-17. yüzyıl felsefesi üzerindeki etkilerine değinilir."]'::jsonb, '{}'::jsonb, 27, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#28', 'yks-2026-felsefe', 'yks-2026-felsefe#7', '11.3.3', 'Örnek felsefi metinlerden hareketle 15. yüzyıl-17. yüzyıl filozoflarının felsefi görüşlerini analiz eder.', NULL, '["a) R. Descartes’ın “Felsefenin İlkeleri” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun bilgi ve varlık görüşlerinin irdelenmesi sağlanır.", "b) B. Spinoza’nın “Ethica” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun ahlak görüşünün irdelenmesi sağlanır.", "c) T. Hobbes’un “Leviathan” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun siyaset görüşlerinin irdelenmesi sağlanır."]'::jsonb, '{}'::jsonb, 28, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#29', 'yks-2026-felsefe', 'yks-2026-felsefe#7', '11.3.4', '15. yüzyıl-17. yüzyıl felsefesindeki örnek düşünce ve argümanları felsefi açıdan değerlendirir.', NULL, '["a) F. Bacon’ın “Bilgi güçtür.” sözünün olumlu ve olumsuz yönlerinin günlük hayattan örneklerle tartışılması sağlanır.", "b) Ütopya kavramı ve türleri üzerinde durularak özgün bir ütopya yazılması sağlanır. ÜNİTE 4: 18. YÜZYIL-19. YÜZYIL FELSEFESİ"]'::jsonb, '{}'::jsonb, 29, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#30', 'yks-2026-felsefe', 'yks-2026-felsefe#8', '11.4.1', '18. yüzyıl -19. yüzyıl felsefesini hazırlayan düşünce ortamını açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 30, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#31', 'yks-2026-felsefe', 'yks-2026-felsefe#8', '11.4.2', '18. yüzyıl -19. yüzyıl felsefesinin karakteristik özelliklerini açıklar.', NULL, '["a) 18. yüzyıl -19. yüzyıl felsefesinin temel özellikleri ve problemleri üzerinde durulur.", "b) 18. yüzyıl -19. yüzyıl felsefesinin, dönemin dil ve edebiyatla ilişkisine değinilir."]'::jsonb, '{}'::jsonb, 31, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#32', 'yks-2026-felsefe', 'yks-2026-felsefe#8', '11.4.3', 'Örnek felsefi metinlerinden hareketle 18. yüzyıl -19. yüzyıl filozoflarının felsefi görüşlerini analiz eder.', NULL, '["a) J. Locke’un “İnsan Zihni Üzerine Bir Deneme” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun bilginin kaynağı konusundaki görüşlerinin irdelenmesi sağlanır.", "b) I. Kant’ın ”Ahlak Metafiziğinin Temellendirilmesi” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun “ödev ahlakı” anlayışının irdelenmesi sağlanır.", "c) F. Hegel’in “Tinin Fenomenolojisi” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun “diyalektik idealizm” anlayışının irdelenmesi sağlanır."]'::jsonb, '{}'::jsonb, 32, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#33', 'yks-2026-felsefe', 'yks-2026-felsefe#8', '11.4.4', '18. yüzyıl -19. yüzyıl felsefesindeki örnek düşünce ve argümanları felsefi açıdan değerlendirir.', NULL, '["a) J. J. Rousseau’nun “İnsan özgür doğar oysa her yerde zincire vurulmuştur.” sözünden hareketle özgürlük probleminin tartışılması sağlanır.", "b) Günlük hayatta kullanılan bilgilerde aklın ve deneyin rolüne ilişkin özgün bir metin yazılması sağlanır. ÜNİTE 5: 20. YÜZYIL FELSEFESİ"]'::jsonb, '{}'::jsonb, 33, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#34', 'yks-2026-felsefe', 'yks-2026-felsefe#9', '11.5.1', '20. yüzyıl felsefesini hazırlayan düşünce ortamını açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 34, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#35', 'yks-2026-felsefe', 'yks-2026-felsefe#9', '11.5.2', '20. yüzyıl felsefesinin karakteristik özelliklerini açıklar.', NULL, '["a) 20. yüzyıl felsefesinin temel özellikleri, problemleri ve bazı ana akımları (fenomenoloji, hermeneutik, varoluşçuluk, diyalektik materyalizm, mantıksal pozitivizm, yeni ontoloji) üzerinde durulur.", "b) Türkiye’de felsefi düşünceye katkıda bulunan felsefeciler üzerinde durulur."]'::jsonb, '{}'::jsonb, 35, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#36', 'yks-2026-felsefe', 'yks-2026-felsefe#9', '11.5.3', 'Örnek felsefi metinlerden hareketle 20. yüzyıl filozoflarının felsefi görüşlerini analiz eder.', NULL, '["a) F. Nietzsche’nin “Böyle Buyurdu Zerdüşt” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun “yeni değerler inşası ve güç istenci” görüşlerinin irdelenmesi sağlanır.", "b) H. Bergson’un “Bilincin Dolaysız Verileri Üzerine Deneme” derlenen bir metinden hareketle filozofun bilginin kaynağı konusundaki düşüncelerinin irdelenmesi sağlanır.", "c) J. P. Sartre’ın “Varoluşçuluk” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun “varoluş” görüşlerinin irdelenmesi sağlanır.", "d) T. Kuhn’un “Bilimsel Devrimlerin Yapısı” adlı eserinden alınan veya derlenen bir metinden hareketle filozofun bilim anlayışının irdelenmesi sağlanır. adlı eserinden alınan veya"]'::jsonb, '{}'::jsonb, 36, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#37', 'yks-2026-felsefe', 'yks-2026-felsefe#9', '11.5.4', '20. yüzyıl felsefesi örnek düşünce ve argümanları felsefi açıdan değerlendirir.', NULL, '["a) N. Topçu’nun “İsyan Ahlakı” adlı eserinden alınan veya derlenen bir metinden hareketle düşünürün ahlak hakkındaki görüşlerinin tartışılması sağlanır.", "b) T. Mengüşoğlu’nun “İnsan Felsefesi” adlı eserinden alınan ve derlenen bir metinden hareketle filozofun “insanı bir bütün olarak gören” düşüncelerinin tartışılması sağlanır.", "c) K. Popper’ın “Ben yanılmış olabilirim ve sen haklı olabilirsin ve ortak çaba sonucunda belki doğruluğa biraz daha yaklaşabiliriz.” sözünden hareketle bilginin doğruluğu ile ilgili özgün bir metin yazılması sağlanır."]'::jsonb, '{}'::jsonb, 37, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-felsefe#38', 'yks-2026-felsefe', 'yks-2026-felsefe#9', '11.5.5', 'Harita üzerinde 20 ve 21. yüzyıl felsefecilerinin isimlerini ve yaşadıkları coğrafyayı gösterir.', NULL, '["a) Felsefeciler ve yaşadıkları yerler, Türkiye ve Dünya haritası üzerinde gösterilir.", "b) Felsefecilerin, isimleri ve yaşadıkları coğrafyanın ezberletilmesi yoluna gidilmez."]'::jsonb, '{}'::jsonb, 38, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#1', 'yks-2026-fizik', 'yks-2026-fizik#1', '9.1.1.1', 'Evrendeki olayların anlaşılmasında fizik biliminin önemini açıklar.', NULL, '["Fiziğin evren ve evrendeki olayların anlaşılması ve açıklanmasındaki rolü üzerinde durulur."]'::jsonb, '{}'::jsonb, 1, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#2', 'yks-2026-fizik', 'yks-2026-fizik#1', '9.1.2.1', 'Fiziğin uygulama alanlarını, alt dalları ve diğer disiplinlerle ilişkilendirir.', NULL, '["a) Fiziğin mekanik, termodinamik, elektromanyetizma, optik, katıhal fiziği, atom fiziği, nükleer fizik, yüksek enerji ve plazma fiziği alt dalları, uygulama alanlarından örneklerle açıklanır. Alt dallar ile ilgili mesleklere örnekler verilir.", "b) Fiziğin felsefe, biyoloji, kimya, teknoloji, mühendislik, sanat, spor ve matematik alanları ile olan ilişkisine günlük hayattan örnekler verilir."]'::jsonb, '{}'::jsonb, 2, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#3', 'yks-2026-fizik', 'yks-2026-fizik#1', '9.1.3.1', 'Fiziksel nicelikleri sınıflandırır.', NULL, '["a) Niceliklerin temel ve türetilmiş olarak tanımlanması ve sınıflandırılması sağlanır.", "b) Temel büyüklüklerin birimleri SI birim sisteminde tanıtılır. Türetilmiş büyüklükler için fen bilimleri dersinde geçmiş konulardan örnekler verilir.", "c) Niceliklerin skaler ve vektörel olarak tanımlanması ve sınıflandırılması sağlanır.", "ç) Vektörlerde toplama işlemlerinin tek boyutta yapılması sağlanır. Skaler ve vektörel niceliklerde toplama işlemlerine (tek boyutta) günlük hayattan örnekler verilerek, karşılaştırma yapılması sağlanır."]'::jsonb, '{}'::jsonb, 3, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#4', 'yks-2026-fizik', 'yks-2026-fizik#1', '9.1.4.1', 'Bilim araştırma merkezlerinin fizik bilimi için önemini açıklar.', NULL, '["a) Bilim araştırma merkezleri TÜBİTAK, TAEK, ASELSAN, CERN, NASA ve ESA ile sınırlandırılır.", "b) Bilimsel araştırmalarda etik ilkelere uymanın önemi vurgulanır."]'::jsonb, '{}'::jsonb, 4, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#5', 'yks-2026-fizik', 'yks-2026-fizik#2', '9.2.1.1', 'Özkütleyi, kütle ve hacimle ilişkilendirerek açıklar.', NULL, '["a) Kütle ve hacim kavramlarına değinilir. Kütle (mg, g, kg ve ton) ve hacim (mL, L, cm3, dm3, m3) için anlamlı birim dönüşümleri yapılır. Dönüşümler yapılırken bilişim teknolojilerinden faydalanılabileceği belirtilir.", "b) Düzgün geometrik şekilli cisimlerden küp, dikdörtgenler prizması, silindir, küre ve şekli düzgün olmayan cisimler için hacim hesaplamaları yapılır. Kum-su problemlerine girilmez.", "c) Sabit sıcaklık ve basınçta ölçüm yapılarak kütle-hacim grafiğinin çizilmesi; kütle, hacim ve özkütle kavramları arasındaki matematiksel modelin çıkarılması sağlanır. Matematiksel hesaplamalar yapılır.", "ç) Kütle-özkütle, hacim-özkütle grafiklerinin çizilmesi ve yorumlanması sağlanır.", "d) Eşit kollu terazi ile ilgili matematiksel hesaplamalara girilmez.", "e) Karışımların özkütlelerine değinilir. Matematiksel hesaplamalara girilmez.", "f) Archimedes ve el-Hazini’nin özkütle ile ilgili yaptığı çalışmalar hakkında kısaca bilgi verilir."]'::jsonb, '{}'::jsonb, 5, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#6', 'yks-2026-fizik', 'yks-2026-fizik#2', '9.2.1.2', 'Günlük hayatta saf maddelerin ve karışımların özkütlelerinden faydalanılan durumlara örnekler verir.', NULL, '["Kuyumculuk, porselen yapımı, ebru yapımı gibi özkütleden faydalanılan çalışma alanlarına değinilir."]'::jsonb, '{}'::jsonb, 6, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#7', 'yks-2026-fizik', 'yks-2026-fizik#2', '9.2.2.1', 'Dayanıklılık kavramını açıklar.', NULL, '["Düzgün geometrik şekilli cisimlerden küp, dikdörtgenler prizması, silindir ve kürenin kesit alanının hacme oranı dışında dayanıklılık kavramı ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 7, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#8', 'yks-2026-fizik', 'yks-2026-fizik#2', '9.2.3.1', 'Yapışma (adezyon) ve birbirini tutma (kohezyon) olaylarını örneklerle açıklar.', NULL, '["a) Yüzey gerilimi ve kılcallık olayının yapışma ve birbirini tutma olayları ile açıklanması ve günlük hayattan örnekler verilmesi sağlanır.", "b) Yüzey gerilimini etkileyen faktörlerin, günlük hayattaki örnekler ile açıklanması sağlanır.", "c) Adezyon, kohezyon, yüzey gerilimi ve kılcallık ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 8, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#9', 'yks-2026-fizik', 'yks-2026-fizik#3', '9.3.1.1', 'Cisimlerin hareketlerini sınıflandırır.', NULL, '["Deney veya simülasyonlardan yararlanarak öteleme, dönme ve titreşim hareketlerine örnekler verilmesi sağlanır."]'::jsonb, '{}'::jsonb, 9, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#10', 'yks-2026-fizik', 'yks-2026-fizik#3', '9.3.1.2', 'Konum, alınan yol, yer değiştirme, sürat ve hız kavramlarını birbirleri ile ilişkilendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 10, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#11', 'yks-2026-fizik', 'yks-2026-fizik#3', '9.3.1.3', 'Düzgün doğrusal hareket için konum, hız ve zaman kavramlarını ilişkilendirir.', NULL, '["a) Öğrencilerin deney yaparak veya simülasyonlarla veriler toplamaları, konum-zaman ve hız-zaman grafiklerini çizmeleri, bunları yorumlamaları ve çizilen grafikler arasında dönüşümler yapmaları sağlanır.", "b) Öğrencilerin grafiklerden yararlanarak hareket ile ilgili matematiksel modelleri çıkarmaları ve yorumlamaları sağlanır."]'::jsonb, '{}'::jsonb, 11, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#12', 'yks-2026-fizik', 'yks-2026-fizik#3', '9.3.1.4', 'Ortalama hız kavramını açıklar.', NULL, '["Trafikte yeşil dalga sisteminin çalışma ilkesi üzerinde durulur."]'::jsonb, '{}'::jsonb, 12, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#13', 'yks-2026-fizik', 'yks-2026-fizik#3', '9.3.1.5', 'İvme kavramını hızlanma ve yavaşlama olayları ile ilişkilendirir.', NULL, '["a) Sabit ivmeli hareket ile sınırlı kalınır.", "b) İvmenin matematiksel modelinin çıkarılması sağlanır. Matematiksel hesaplamalara girilmez.", "c) Sabit ivmeli hareket için hız-zaman ve ivme- zaman grafiklerini çizmeleri, yorumlamaları sağlanır. Grafikler arasında dönüşümlere girilmez. Konum-zaman grafiği çizdirilmez.", "ç) Anlık hız kavramına değinilir."]'::jsonb, '{}'::jsonb, 13, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#14', 'yks-2026-fizik', 'yks-2026-fizik#3', '9.3.1.6', 'Bir cismin hareketini farklı referans noktalarına göre açıklar.', NULL, '["Gözlemlerle hareketin göreceli olduğu çıkarımının yapılması sağlanır."]'::jsonb, '{}'::jsonb, 14, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#15', 'yks-2026-fizik', 'yks-2026-fizik#3', '9.3.2.1', 'Kuvvet kavramını örneklerle açıklar.', NULL, '["a) Temas gerektiren ve gerektirmeyen kuvvetlere örnek verilmesi sağlanır.", "b) Dört temel kuvvetin hangi kuvvetler olduğu belirtilir.", "c) Kütle çekim kuvvetinin bağlı olduğu değişkenler verilir. Matematiksel hesaplamalara girilmez.", "ç) Dengelenmiş ve dengelenmemiş kuvvetler vurgulanır."]'::jsonb, '{}'::jsonb, 15, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#16', 'yks-2026-fizik', 'yks-2026-fizik#3', '9.3.3.1', 'Dengelenmiş kuvvetlerin etkisindeki cisimlerin hareket durumlarını örneklerle açıklar.', NULL, '["İbn-i Sina’nın hareket konusunda yaptığı çalışmalar hakkında kısaca bilgi verilir."]'::jsonb, '{}'::jsonb, 16, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#17', 'yks-2026-fizik', 'yks-2026-fizik#3', '9.3.3.2', 'Kuvvet, ivme ve kütle kavramları arasındaki ilişkiyi açıklar.', NULL, '["a) Net kuvvet, ivme ve kütle arasındaki matematiksel model verilir.", "b) Serbest cisim diyagramı üzerinde cisme etki eden kuvvetler gösterilir. Net kuvvetin büyüklüğü hesaplanarak yönü gösterilir.", "c) Hesaplamalarda yatay düzlemde tek kütle ile sınırlı kalınır. Bileşenlere ayırma hesaplamalarına girilmez.", "ç) Yer çekimi ivmesi açıklanarak ağırlık hesaplamaları yapılır."]'::jsonb, '{}'::jsonb, 17, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#18', 'yks-2026-fizik', 'yks-2026-fizik#3', '9.3.3.3', 'Etki-tepki kuvvetlerini örneklerle açıklar.', NULL, '["a) Yatay ve düşey düzlemlerde etki-tepki kuvvetlerinin gösterilmesi sağlanır.", "b) Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 18, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#19', 'yks-2026-fizik', 'yks-2026-fizik#3', '9.3.4.1', 'Sürtünme kuvvetinin bağlı olduğu değişkenleri analiz eder.', NULL, '["a) Öğrencilerin deney yaparak veya simülasyonlardan elde ettiği verilerden çıkarım yapmaları ve değişkenler arasındaki ilişkiyi belirlemeleri sağlanır. Yatay düzlemle sınırlı kalınır.", "b) Statik ve kinetik sürtünme kuvvetlerinin karşılaştırılması sağlanır.", "c) Serbest cisim diyagramları üzerinde sürtünme kuvvetinin gösterilmesi sağlanır.", "ç) Sürtünme kuvvetinin matematiksel modeli verilir. Matematiksel hesaplamalara girilmez.", "d) Sürtünme kuvvetinin günlük hayattaki avantaj ve dezavantajlarına örnekler verilmesi sağlanır.", "e) Kayarak ve dönerek ilerleyen cisimlerde sürtünme kuvvetinin yönü, örnekler üzerinden açıklanır."]'::jsonb, '{}'::jsonb, 19, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#20', 'yks-2026-fizik', 'yks-2026-fizik#4', '9.4.1.1', 'İş, enerji ve güç kavramlarını birbirleriyle ilişkilendirir.', NULL, '["a) İş ile enerji arasındaki ilişki kavramsal olarak verilir. b)Öğrencilerin iş ve güç kavramlarının matematiksel modellerini incelemeleri sağlanır.", "c) Fiziksel anlamda iş ve güç ile günlük hayatta kullanılan iş ve güç kavramlarının farklı olduğu vurgulanır."]'::jsonb, '{}'::jsonb, 20, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#21', 'yks-2026-fizik', 'yks-2026-fizik#4', '9.4.1.2', 'Mekanik iş ve mekanik güç ile ilgili hesaplamalar yapar.', NULL, '["Hareket ile aynı doğrultudaki kuvvetlerle sınırlı kalınır."]'::jsonb, '{}'::jsonb, 21, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#22', 'yks-2026-fizik', 'yks-2026-fizik#4', '9.4.2.1', 'Öteleme kinetik enerjisi, yer çekimi potansiyel enerjisi ve esneklik potansiyel enerjisinin bağlı olduğu değişkenleri analiz eder.', NULL, '["a) Öteleme kinetik enerjisi, yer çekimi potansiyel enerjisi ve esneklik potansiyel enerjisinin matematiksel modelleri verilir. Deney veya simülasyonlar yardımıyla değişkenlerin analiz edilmesi sağlanır. Matematiksel hesaplamalara girilmez.", "b) Esneklik potansiyel enerjisinde tek yaylı sistemler dikkate alınmalıdır.", "c) Mekanik enerjinin kinetik enerji ve potansiyel enerjinin toplamına eşit olduğu vurgulanır."]'::jsonb, '{}'::jsonb, 22, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#23', 'yks-2026-fizik', 'yks-2026-fizik#4', '9.4.3.1', 'Enerjinin bir biçimden diğer bir biçime (mekanik, ısı, ışık, ses gibi) dönüşümünde toplam enerjinin korunduğu çıkarımını yapar.', NULL, '["a) Sürtünmeden dolayı enerjinin tamamının hedeflenen enerji biçimine dönüştürülemeyeceği vurgulanır.", "b) Enerji dönüşüm hesaplamalarına girilmez."]'::jsonb, '{}'::jsonb, 23, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#24', 'yks-2026-fizik', 'yks-2026-fizik#4', '9.4.3.2', 'Canlıların besinlerden kazandıkları enerji ile günlük aktiviteler için harcadıkları enerjiyi karşılaştırır.', NULL, '["Canlıların fiziksel anlamda iş yapmadan da enerji harcayabildikleri vurgulanır."]'::jsonb, '{}'::jsonb, 24, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#25', 'yks-2026-fizik', 'yks-2026-fizik#4', '9.4.4.1', 'Verim kavramını açıklar.', NULL, '["Enerji tasarrufu ve enerji verimliliği arasındaki ilişki enerji kimlik belgeleri üzerinden açıklanır."]'::jsonb, '{}'::jsonb, 25, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#26', 'yks-2026-fizik', 'yks-2026-fizik#4', '9.4.4.2', 'Örnek bir sistem veya tasarımın verimini artıracak öneriler geliştirir.', NULL, '["Tarihsel süreçte tasarlanmış olan çeşitli verim artırıcı sistemlerin çalışma prensibine değinilir."]'::jsonb, '{}'::jsonb, 26, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#27', 'yks-2026-fizik', 'yks-2026-fizik#4', '9.4.5.1', 'Yenilenebilir ve yenilenemez enerji kaynaklarını avantaj ve dezavantajları açısından değerlendirir.', NULL, '["a) Enerji kaynaklarının maliyeti, erişilebilirliği, üretim kolaylığı, toplum, teknoloji ve çevresel etkileri göz önünde bulundurulur.", "b) Enerji kaynaklarını tasarruflu kullanmanın gerekliliği vurgulanır."]'::jsonb, '{}'::jsonb, 27, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#28', 'yks-2026-fizik', 'yks-2026-fizik#5', '9.5.1.1', 'Isı, sıcaklık ve iç enerji kavramlarını açıklar.', NULL, '["a) Entalpi ve entropi kavramlarına girilmez.", "b) Isı ve sıcaklık kavramlarının birimleri ve ölçüm aletlerinin adları verilir."]'::jsonb, '{}'::jsonb, 28, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#29', 'yks-2026-fizik', 'yks-2026-fizik#5', '9.5.1.2', 'Termometre çeşitlerini kullanım amaçları açısından karşılaştırır.', NULL, '[]'::jsonb, '{}'::jsonb, 29, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#30', 'yks-2026-fizik', 'yks-2026-fizik#5', '9.5.1.3', 'Sıcaklık birimleri ile ilgili hesaplamalar yapar.', NULL, '["C, 0F, K için birim dönüşümleri yapılması sağlanır."]'::jsonb, '{}'::jsonb, 30, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#31', 'yks-2026-fizik', 'yks-2026-fizik#5', '9.5.1.4', 'Öz ısı ve ısı sığası kavramlarını birbiriyle ilişkilendirir.', NULL, '["Günlük hayattan örnekler (denizlerin karalardan geç ısınıp geç soğuması gibi) verilir."]'::jsonb, '{}'::jsonb, 31, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#32', 'yks-2026-fizik', 'yks-2026-fizik#5', '9.5.1.5', 'Isı alan veya ısı veren saf maddelerin sıcaklığında meydana gelen değişimin bağlı olduğu değişkenleri analiz eder.', NULL, '["Deney veya simülasyonlardan yararlanılarak değişkenler arasındaki ilişkiyi belirlemeleri sağlanır. Matematiksel model verilir. Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 32, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#33', 'yks-2026-fizik', 'yks-2026-fizik#5', '9.5.2.1', 'Saf maddelerde hâl değişimi için gerekli olan ısı miktarının bağlı olduğu değişkenleri analiz eder.', NULL, '["Deney veya simülasyonlardan yararlanarak değişkenler arasındaki ilişkiyi belirlemeleri sağlanır. Matematiksel model verilir. Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 33, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#34', 'yks-2026-fizik', 'yks-2026-fizik#5', '9.5.3.1', 'Isıl denge kavramının sıcaklık farkı ve ısı kavramı ile olan ilişkisini analiz eder.', NULL, '["a) Deney veya simülasyonlardan yararlanılarak ısıl dengenin sıcaklık değişimi ve ısı ile ilişkisinin belirlenmesi sağlanır.", "b) Isıl denge ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 34, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#35', 'yks-2026-fizik', 'yks-2026-fizik#5', '9.5.4.1', 'Enerji iletim yollarını örneklerle açıklar.', NULL, '["9.5.4.2.Katı maddedeki enerji iletim hızını etkileyen değişkenleri analiz eder.", "a) Deney veya simülasyonlardan yararlanılarak değişkenler arasındaki ilişkiyi belirlemeleri sağlanır.", "b) Günlük hayattan örnekler (ısı yalıtımında izolasyon malzemelerinin kullanılması, soğuk bölgelerde pencerelerin küçük, duvarların daha kalın olması gibi) verilir.", "c) Enerji iletim hızı ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 35, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#36', 'yks-2026-fizik', 'yks-2026-fizik#5', '9.5.4.3', 'Enerji tasarrufu için yaşam alanlarının yalıtımına yönelik tasarım yapar.', NULL, '["a) Enerji tasarrufu için ısı yalıtım sisteminin aile bütçesine ve ülke ekonomisine olan katkısının önemi vurgulanır.", "b) Öğrencilerin ısı yalıtımı ile ilgili günlük hayattan bir problem belirlemeleri ve bu problem için çözümler üretmeleri sağlanır.", "c) Yapılacak tasarımlarda finans bilincinin geliştirilmesi için bütçe hesaplaması yapılmasının gerekliliği vurgulanmalıdır."]'::jsonb, '{}'::jsonb, 36, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#37', 'yks-2026-fizik', 'yks-2026-fizik#5', '9.5.4.4', 'Hissedilen ve gerçek sıcaklık arasındaki farkın sebeplerini yorumlar.', NULL, '[]'::jsonb, '{}'::jsonb, 37, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#38', 'yks-2026-fizik', 'yks-2026-fizik#5', '9.5.4.5', 'Küresel ısınmaya karşı alınacak tedbirlere yönelik proje geliştirir.', NULL, '["a) Öğrencilerin projelerini poster, broşür veya elektronik sunu ile tanıtmaları sağlanır.", "b) Küresel ısınmanın sebeplerine dikkat çekilir.", "c) Çevreye karşı duyarlı olmanın gerekliliği ve bireysel olarak yapılabilecek katkılar hakkında tartışılması sağlanır."]'::jsonb, '{}'::jsonb, 38, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#39', 'yks-2026-fizik', 'yks-2026-fizik#5', '9.5.5.1', 'Katı ve sıvılarda genleşme ve büzülme olaylarının günlük hayattaki etkilerini yorumlar.', NULL, '["a) Katı ve sıvıların genleşmesi ve büzülmesinin günlük hayatta oluşturduğu avantaj ve dezavantajların tartışılması sağlanır.", "b) Su ve buzun özkütle, öz ısıları karşılaştırılarak günlük hayata etkileri üzerinde durulur.", "c) Genleşme ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 39, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#40', 'yks-2026-fizik', 'yks-2026-fizik#6', '9.6.1.1', 'Elektrikle yüklenme çeşitlerini örneklerle açıklar.', NULL, '["a) Yük, birim yük ve elektrikle yüklenme kavramları verilir.", "b) Elektrikle yüklenmede yüklerin korunumlu olduğu vurgulanmalıdır.", "c) Elektroskopun yük cinsinin tayininde kullanılmasına örnekler verilir."]'::jsonb, '{}'::jsonb, 40, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#41', 'yks-2026-fizik', 'yks-2026-fizik#6', '9.6.1.2', 'Elektriklenen iletken ve yalıtkan maddelerde yük dağılımlarını karşılaştırır.', NULL, '["a) Öğrencilerin karşılaştırmayı deneyler yaparak veya simülasyonlar kullanarak yapmaları sağlanır.", "b) Faraday kafesi, kullanım alanları ve önemi açıklanır.", "c) Topraklama olayı açıklanarak günlük hayattaki önemi vurgulanır."]'::jsonb, '{}'::jsonb, 41, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#42', 'yks-2026-fizik', 'yks-2026-fizik#6', '9.6.1.3', 'Elektrik yüklü cisimler arasındaki etkileşimi açıklar.', NULL, '["a) Deney veya simülasyonlardan yararlanılarak elektrik yüklü cisimler arasındaki etkileşimin (Coulomb Kuvveti) bağlı olduğu değişkenler arasındaki ilişkiyi belirlemeleri sağlanır. Matematiksel model verilir.", "b) Yüklerin etkileşimi ile ilgili noktasal yüklerle ve tek boyutta matematiksel hesaplamalar yapılması sağlanır."]'::jsonb, '{}'::jsonb, 42, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#43', 'yks-2026-fizik', 'yks-2026-fizik#6', '9.6.1.4', 'Elektrik alan kavramını açıklar.', NULL, '["Deney veya simülasyonlardan yararlanılarak elektrik alan kavramı ile elektriksel kuvvet arasındaki ilişki açıklanır. Matematiksel model verilir. Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 43, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#44', 'yks-2026-fizik', 'yks-2026-fizik#7', '10.1.1.1', 'Elektrik akımı, direnç ve potansiyel farkı kavramlarını açıklar.', NULL, '["a) Elektrik yükünün hareketi üzerinden elektrik akımı kavramının açıklanması sağlanır.", "b) Katı, sıvı, gaz ve plazmalarda elektrik iletimine değinilir."]'::jsonb, '{}'::jsonb, 44, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#45', 'yks-2026-fizik', 'yks-2026-fizik#7', '10.1.1.2', 'Katı bir iletkenin direncinin bağlı olduğu değişkenleri analiz eder.', NULL, '["a) Deney veya simülasyonlardan yararlanarak değişkenler arasındaki ilişkiyi belirlemeleri ve matematiksel modeli çıkarmaları sağlanır. Matematiksel hesaplamalara girilmez.", "b) İletken direncinin sıcaklığa bağlı değişimine ve renk kodlarıyla direnç okuma işlemlerine girilmez."]'::jsonb, '{}'::jsonb, 45, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#46', 'yks-2026-fizik', 'yks-2026-fizik#7', '10.1.2.1', 'Elektrik Akımı, direnç ve potansiyel farkı arasındaki ilişkiyi analiz eder.', NULL, '["a) Voltmetre ve ampermetrenin direnç özellikleri ile devredeki görevleri açıklanır.", "b) Öğrencilerin basit devreler üzerinden deney yaparak elektrik akımı, direnç ve potansiyel farkı arasındaki ilişkinin (Ohm Yasası) matematiksel modelini çıkarmaları sağlanır.", "c) Elektrik devrelerinde eşdeğer direnç, direnç, potansiyel farkı ve elektrik akımı ile ilgili matematiksel hesaplamalar yapılması sağlanır."]'::jsonb, '{}'::jsonb, 46, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#47', 'yks-2026-fizik', 'yks-2026-fizik#7', '10.1.2.2', 'Üreteçlerin seri ve paralel bağlanma gerekçelerini açıklar.', NULL, '["a) Öğrencilerin deney veya simülasyonlarla üreteçlerin bağlanma şekillerini incelemeleri ve tükenme sürelerini karşılaştırmaları sağlanır. Üreteçlerin ters bağlanması da dikkate alınır.", "b) Elektromotor kuvvetleri farklı üreteçlerin paralele bağlanmasına girilmez.", "c) Üreteçlerin iç dirençleri örneklerle açıklanır, iç dirençler ile ilgili matematiksel hesaplamalara girilmez.", "ç) Öğrencilerin üretecin keşfi üzerine deneyler yapan bilim insanları Galvani ve Volta’nın bakış açıları arasındaki farkı tartışmaları sağlanır.", "d) Kirchhoff Kanunlarına girilmez."]'::jsonb, '{}'::jsonb, 47, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#48', 'yks-2026-fizik', 'yks-2026-fizik#7', '10.1.2.3', 'Elektrik enerjisi ve elektriksel güç kavramlarını ilişkilendirir.', NULL, '["a) Elektrik enerjisi ve elektriksel güç ilişkisi ile mekanik enerji ve mekanik güç ilişkisi arasındaki benzerliğe değinilir.", "b) Bir direncin birim zamanda harcadığı elektrik enerjisi ile ilgili hesaplamalar dışında matematiksel hesaplamalara girilmez.", "c) Öğrencilerin ısı, iş, mekanik enerji ve elektrik enerjisinin birbirine dönüşümünü açıklamaları sağlanır.", "ç) Lamba parlaklıklarının karşılaştırılması sağlanır."]'::jsonb, '{}'::jsonb, 48, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#49', 'yks-2026-fizik', 'yks-2026-fizik#7', '10.1.2.4', 'Elektrik akımının oluşturabileceği tehlikelere karşı alınması gereken sağlık ve güvenlik önlemlerini açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 49, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#50', 'yks-2026-fizik', 'yks-2026-fizik#7', '10.1.3.1', 'Mıknatısların oluşturduğu manyetik alanı ve özelliklerini açıklar.', NULL, '["a) Öğrencilerin deneyler yaparak veya simülasyonlar kullanarak manyetik alanı incelemeleri sağlanır.", "b) Mıknatısların manyetik alanının manyetik alan çizgileri ile temsil edildiği vurgulanır.", "c) Mıknatısların itme-çekme kuvvetleri ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 50, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#51', 'yks-2026-fizik', 'yks-2026-fizik#7', '10.1.4.1', 'Üzerinden akım geçen düz bir iletken telin oluşturduğu manyetik alanı etkileyen değişkenleri analiz eder.', NULL, '["a) Öğrencilerin deneyler yaparak veya simülasyonlar kullanarak manyetik alanı etkileyen değişkenleri belirlemeleri sağlanır.", "b) Sağ el kuralı verilir. Manyetik alanın yönü ve şiddeti ile ilgili matematiksel hesaplamalara girilmez.", "c) Yüksek gerilim hatlarının geçtiği alanlarda oluşan manyetik alanın canlılar üzerindeki etkilerine değinilir.", "ç) Elektromıknatıs tanıtılarak kullanım alanlarına örnekler verilir."]'::jsonb, '{}'::jsonb, 51, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#52', 'yks-2026-fizik', 'yks-2026-fizik#7', '10.1.4.2', 'Dünya’nın manyetik alanının sonuçlarını açıklar.', NULL, '["a) Öğrencilerin pusula ile yön bulmaları sağlanır.", "b) Arılar, göçmen kuşlar, bazı büyükbaş hayvanlar gibi canlıların yerin manyetik alanından yararlanarak yön buldukları belirtilir."]'::jsonb, '{}'::jsonb, 52, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#53', 'yks-2026-fizik', 'yks-2026-fizik#8', '10.2.1.1', 'Basınç ve basınç kuvveti kavramlarının katı, durgun sıvı ve gazlarda bağlı olduğu değişkenleri açıklar.', NULL, '["a) Öğrencilerin, günlük hayattan basıncın hayatımıza etkilerine örnekler vermeleri sağlanır. Basıncın hâl değişimine etkileri vurgulanır.", "b) Katı ve durgun sıvı basıncı ve basınç kuvveti ile ilgili matematiksel modeller verilir. Bileşenlerine ayırma ve matematiksel hesaplamalara girilmez.", "c) Torricelli deneyi açıklanır ve kılcallık ile farkı belirtilir.", "ç) Basınç etkisiyle çalışan ölçüm aletlerinden barometre, altimetre, manometre ve batimetre hakkında bilgi verilir.", "d) Pascal Prensibi’ne değinilir. Gaz basıncı ve Pascal Prensibi ile ilgili matematiksel modeller verilmez."]'::jsonb, '{}'::jsonb, 53, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#54', 'yks-2026-fizik', 'yks-2026-fizik#8', '10.2.1.2', 'Akışkanlarda akış sürati ile akışkan basıncı arasında ilişki kurar.', NULL, '["a) Deney veya simülasyonlardan yararlanılarak kesit alanı, basınç ve akışkan sürati arasında bağlantı kurulması sağlanır.", "b) Bernoulli İlkesi’nin günlük hayattaki örnekler (çatıların uçması, şemsiyenin ters çevrilmesi, rüzgârlı havalarda kapıların sert kapanması gibi) üzerinden açıklanması sağlanır.", "c) Bernoulli İlkesi’yle ilgili matematiksel hesaplamalara girilmez.", "ç) Günlük hayatta akışkan basıncının sağlayabileceği kolaylıklar (uçakların uçması gibi) ve olumsuz etkilerine karşı alınması gereken sağlık ve güvenlik tedbirleri (yüksek süratle hareket eden araçlara yaklaşılmaması gibi) vurgulanır.", "d) Tansiyonun damarlardaki kan basıncı olduğu vurgulanarak öğrencilerin tansiyon aletinin çalışma prensibini araştırmaları sağlanır."]'::jsonb, '{}'::jsonb, 54, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#55', 'yks-2026-fizik', 'yks-2026-fizik#8', '10.2.2.1', 'Durgun akışkanlarda cisimlere etki eden kaldırma kuvvetinin basınç kuvveti farkından kaynaklandığını açıklar.', NULL, '["a) Archimedes İlkesi açıklanır. Yüzme, askıda kalma ve batma durumlarında kaldırma kuvveti ile cismin ağırlığının büyüklükleri karşılaştırılır.", "b) Kaldırma kuvveti ile ilgili matematiksel model verilir. Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 55, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00')
INSERT INTO public.curriculum_outcomes (id, program_id, unit_id, code, text, topic, limitations, quotas, sort_order, source_id, quota_source_id, text_similarity, source_url, program_version, sha256, fetched_at) VALUES
('yks-2026-fizik#56', 'yks-2026-fizik', 'yks-2026-fizik#8', '10.2.2.2', 'Kaldırma kuvvetiyle ilgili belirlediği günlük hayattaki problemlere kaldırma kuvveti ve/veya Bernoulli İlkesi’ni kullanarak çözüm önerisi üretir.', NULL, '[]'::jsonb, '{}'::jsonb, 56, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#57', 'yks-2026-fizik', 'yks-2026-fizik#9', '10.3.1.1', 'Titreşim, dalga hareketi, dalga boyu, periyot, frekans, hız ve genlik kavramlarını açıklar.', NULL, '["a) Deney, gözlem veya simülasyonlarla kavramların açıklanması sağlanır.", "b) Periyot ve frekans kavramlarının birbiriyle ilişkilendirilmesi ve matematiksel model oluşturulması sağlanır. Matematiksel hesaplamalara girilmez.", "c) Dalganın ilerleme hızı, dalga boyu ve frekans kavramları arasındaki matematiksel model verilir. Matematiksel hesaplamalara girilmez.", "ç) Dalganın ilerleme hızının ortama, frekansın kaynağa bağlı olduğu vurgulanır."]'::jsonb, '{}'::jsonb, 57, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#58', 'yks-2026-fizik', 'yks-2026-fizik#9', '10.3.1.2', 'Dalgaları taşıdığı enerjiye ve titreşim doğrultusuna göre sınıflandırır.', NULL, '["Öğrencilerin dalga çeşitlerine örnekler vermeleri sağlanır."]'::jsonb, '{}'::jsonb, 58, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#59', 'yks-2026-fizik', 'yks-2026-fizik#9', '10.3.2.1', 'Atma ve periyodik dalga oluşturarak aralarındaki farkı açıklar.', NULL, '["a) Atmanın dalgaların özelliklerini incelemek için oluşturulduğu vurgulanır.", "b) Öğrencilerin deney yaparak veya simülasyonlar kullanarak atma ve periyodik dalgayı incelemeleri sağlanır."]'::jsonb, '{}'::jsonb, 59, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#60', 'yks-2026-fizik', 'yks-2026-fizik#9', '10.3.2.2', 'Yaylarda atmanın yansımasını ve iletilmesini analiz eder.', NULL, '["a) Öğrencilerin gergin bir yayda oluşturulan atmanın ilerleme hızının bağlı olduğu değişkenleri açıklaması sağlanır. Atmanın ilerleme hızı ile ilgili matematiksel hesaplamalara girilmez.", "b) Öğrencilerin deney yaparak veya simülasyonlar kullanarak atmaların sabit ve serbest uçtan yansıma durumlarını incelemeleri sağlanır.", "c) Bir ortamdan başka bir ortama geçerken yansıyan ve iletilen atmaların özellikleri üzerinde durulur.", "ç) Öğrencilerin deney ya da simülasyonlarla iki atmanın karşılaşması durumunda meydana gelebilecek olayları gözlemlemesi sağlanır."]'::jsonb, '{}'::jsonb, 60, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#61', 'yks-2026-fizik', 'yks-2026-fizik#9', '10.3.3.1', 'Dalgaların ilerleme yönü, dalga tepesi ve dalga çukuru kavramlarını açıklar.', NULL, '["Kavramlar doğrusal ve dairesel su dalgaları bağlamında ele alınır."]'::jsonb, '{}'::jsonb, 61, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#62', 'yks-2026-fizik', 'yks-2026-fizik#9', '10.3.3.2', 'Doğrusal ve dairesel su dalgalarının yansıma hareketlerini analiz eder.', NULL, '["a) Öğrencilerin deney yaparak veya simülasyonlar kullanarak su dalgalarının yansıma hareketlerini çizmeleri sağlanır.", "b) Doğrusal su dalgalarının doğrusal ve parabolik engellerden yansıması dikkate alınır.", "c) Dairesel su dalgalarının doğrusal engelden yansıması dikkate alınır, parabolik engelden yansımasında ise sadece odak noktası ve merkezden gönderilen dalgalar dikkate alınır.", "ç) Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 62, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#63', 'yks-2026-fizik', 'yks-2026-fizik#9', '10.3.3.3', 'Ortam derinliği ile su dalgalarının yayılma hızını ilişkilendirir.', NULL, '["a) Öğrencilerin deney yaparak veya simülasyonlarla ortam derinliğinin dalganın hızına etkisini incelemeleri ve dalga boyundaki değişimi gözlemlemeleri sağlanır.", "b) Ortam değiştiren su dalgalarının dalga boyu ve hız değişimi ile ilgili matematiksel hesaplamalara girilmez.", "c) Stroboskopun dalga boyu ölçümünde kullanıldığından bahsedilir, matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 63, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#64', 'yks-2026-fizik', 'yks-2026-fizik#9', '10.3.3.4', 'Doğrusal su dalgalarının kırılma hareketini analiz eder.', NULL, '["a) Öğrencilerin deney yaparak veya simülasyonlar kullanarak su dalgalarının kırılma hareketlerini çizmeleri sağlanır. Su dalgalarının mercek şeklindeki su ortamından geçişi ile ilgili kırılma hareketlerine girilmez.", "b) Dairesel su dalgalarının kırılması konusuna girilmez.", "c) Su dalgalarının kırılma hareketi ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 64, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#65', 'yks-2026-fizik', 'yks-2026-fizik#9', '10.3.4.1', 'Ses dalgaları ile ilgili temel kavramları örneklerle açıklar.', NULL, '["a) Yükseklik, şiddet, tını, rezonans ve yankı kavramları ile sınırlı kalınır.", "b) Uğultu, gürültü ve ses kirliliği kavramlarına değinilir.", "c) Farabi''nin ses dalgaları ile ilgili yaptığı çalışmalar hakkında kısaca bilgi verilir."]'::jsonb, '{}'::jsonb, 65, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#66', 'yks-2026-fizik', 'yks-2026-fizik#9', '10.3.4.2', 'Ses dalgalarının tıp, denizcilik, sanat ve coğrafya alanlarında kullanımına örnekler verir.', NULL, '[]'::jsonb, '{}'::jsonb, 66, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#67', 'yks-2026-fizik', 'yks-2026-fizik#9', '10.3.5.1', 'Deprem dalgasını tanımlar.', NULL, '["a) Depremin büyüklüğü ve şiddeti ile ilgili bilgi verilir.", "b) Depremlerde dalga çeşitlerine girilmez."]'::jsonb, '{}'::jsonb, 67, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#68', 'yks-2026-fizik', 'yks-2026-fizik#9', '10.3.5.2', 'Deprem kaynaklı can ve mal kayıplarını önlemeye yönelik çözüm önerileri geliştirir.', NULL, '[]'::jsonb, '{}'::jsonb, 68, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#69', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.1.1', 'Işığın davranış modellerini açıklar.', NULL, '["Modeller açıklanırken ayrıntılara girilmez."]'::jsonb, '{}'::jsonb, 69, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#70', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.1.2', 'Işık şiddeti, ışık akısı ve aydınlanma şiddeti kavramları arasında ilişki kurar.', NULL, '["a) Deney yaparak veya simülasyonlarla aydınlanma şiddeti, ışık şiddeti, ışık akısı kavramları arasında ilişki kurulur.", "b) Işık şiddeti, ışık akısı ve aydınlanma şiddeti kavramları ile ilgili matematiksel modeller verilir. Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 70, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#71', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.2.1', 'Saydam, yarı saydam ve saydam olmayan maddelerin ışık geçirme özelliklerini açıklar.', NULL, '["a) Öğrencilerin gölge ve yarı gölge alanlarını çizmeleri ve açıklamaları sağlanır.", "b) Gölge ve yarı gölge ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 71, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#72', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.3.1', 'Işığın yansımasını, su dalgalarında yansıma olayıyla ilişkilendirir.', NULL, '["a) Yansıma Kanunları üzerinde durulur.", "b) Işığın düzgün ve dağınık yansımasının çizilerek gösterilmesi sağlanır.", "c) Görme olayında yansımanın rolü vurgulanır."]'::jsonb, '{}'::jsonb, 72, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#73', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.4.1', 'Düzlem aynada görüntü oluşumunu açıklar.', NULL, '["a) Düzlem aynada görüntü özellikleri yapılan çizimler üzerinden açıklanır.", "b) Kesişen ayna, aynanın döndürülmesi, hareketli ayna ve hareketli cisim konularına girilmez.", "c) Deney veya simülasyonlarla görüş alanına etki eden değişkenler ile ilgili çıkarım yapılması sağlanır. Çıkarım yapılırken saydam ve saydam olmayan engeller de dikkate alınır. Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 73, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#74', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.5.1', 'Küresel aynalarda odak noktası, merkez, tepe noktası ve asal eksen kavramlarını açıklar.', NULL, '["Küresel aynalarda özel ışınların yansımasının çizilmesi sağlanır."]'::jsonb, '{}'::jsonb, 74, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#75', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.5.2', 'Küresel aynalarda görüntü oluşumunu ve özelliklerini açıklar.', NULL, '["a) Deney veya simülasyonlarla görüntü oluşumunun ve oluşan görüntü özelliklerinin yorumlanması sağlanır.", "b) Öğrencilerin günlük hayatta karşılaştıkları küresel ayna gibi davranan cisimlere örnekler vermeleri sağlanır.", "c) Küresel aynalarla ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 75, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#76', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.6.1', 'Işığın kırılmasını, su dalgalarında kırılma olayı ile ilişkilendirir.', NULL, '["a) Deney veya simülasyonlar kullanılarak ortam değiştiren ışığın ilerleme doğrultusundan sapma miktarının bağlı olduğu değişkenleri belirlemeleri sağlanır. Snell Yasası’nın matematiksel modeli verilir.", "b) Kırılma indisinin, ışığın ortamdaki ortalama hızı ve boşluktaki hızı ile ilişkili bir bağıl değişken olduğu vurgulanır.", "c) Snell Yasası ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 76, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#77', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.6.2', 'Işığın tam yansıma olayını ve sınır açısını analiz eder.', NULL, '["a) Öğrencilerin deney veya simülasyonlarla oluşturulan tam yansıma olayını ve sınır açısını yorumlamaları sağlanır.", "b) Tam yansımanın gerçekleştiği fiber optik teknolojisi, serap olayı, havuz ışıklandırması örneklerine yer verilir.", "c) Tam yansıma ve sınır açısı ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 77, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#78', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.6.3', 'Farklı ortamda bulunan bir cismin görünür uzaklığını etkileyen sebepleri açıklar.', NULL, '["a) Öğrencilerin deney yaparak ışığın izlediği yolu çizmeleri ve günlük hayatta gözlemlenen olaylarla ilişki kurmaları sağlanır.", "b) Görünür uzaklıkla ilgili matematiksel model verilmez. Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 78, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#79', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.7.1', 'Merceklerin özelliklerini ve mercek çeşitlerini açıklar.', NULL, '["a) Merceklerin odak uzaklığının bağlı olduğu faktörlere değinilir. Matematiksel model verilmez.", "b) Cam şişelerin ve cam kırıklarının mercek gibi davranarak orman yangınlarına sebep olduğu açıklanır. Çevre temizliği ve doğal hayatı korumanın önemi vurgulanır."]'::jsonb, '{}'::jsonb, 79, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#80', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.7.2', 'Merceklerin oluşturduğu görüntünün özelliklerini açıklar.', NULL, '["a) Merceklerdeki özel ışınlar verilir. Görüntü oluşumlarına dair çizimler yaptırılmaz.", "b) Deney veya simülasyonlar yardımıyla merceklerin oluşturduğu görüntü özelliklerinin incelenmesi sağlanır.", "c) Öğrencilerin merceklerin nerelerde ve ne tür amaçlar için kullanıldığına örnekler vermeleri sağlanır.", "ç) Mercekler ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 80, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#81', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.8.1', 'Işık prizmalarının özelliklerini açıklar.', NULL, '["a) Öğrencilerin deney veya simülasyonlar yardımıyla prizmalarda tek renkli ışığın izlediği yolu çizmeleri sağlanır.", "b) Öğrencilerin deney veya simülasyonlarla beyaz ışığın prizmada renklerine ayrılması olayını gözlemlemeleri sağlanır.", "c) Işık prizmalarının kullanım alanlarına örnekler verilir.", "ç) Prizmalar ile ilgili matematiksel modeller verilmez."]'::jsonb, '{}'::jsonb, 81, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#82', 'yks-2026-fizik', 'yks-2026-fizik#10', '10.4.9.1', 'Cisimlerin renkli görülmesinin sebeplerini açıklar.', NULL, '["a) Öğrencilerin ışık ve boya renkleri arasındaki farkları karşılaştırmaları sağlanır.", "b) Işık ve boya renklerini ana, ara ve tamamlayıcı olarak sınıflandırmaları sağlanır. Işıkta ana renklerin boyada ara renk, ışıkta ara renklerin boyada ana renk olduğu vurgulanır.", "c) Işık renklerinden saf sarı ile karışım sarı arasındaki fark vurgulanır.", "ç) Öğrencilerin beyaz ışığın ve farklı renklerdeki ışığın filtreden geçişine ve soğurulmasına ilişkin örnekler vermeleri sağlanır."]'::jsonb, '{}'::jsonb, 82, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#83', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.1.1', 'Vektörlerin özelliklerini açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 83, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#84', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.1.2', 'İki ve üç boyutlu kartezyen koordinat sisteminde vektörleri çizer.', NULL, '["Birim vektör sistemi (i, j,", "k) işlemlerine girilmez."]'::jsonb, '{}'::jsonb, 84, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#85', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.1.3', 'Vektörlerin bileşkelerini farklı yöntemleri kullanarak hesaplar.', NULL, '["a) Uç uca ekleme ve paralel kenar yöntemleri kullanılmalıdır.", "b) Kosinüs teoremi verilerek bileşke vektörün büyüklüğünün bulunması sağlanır.", "c) Eşit büyüklükteki vektörlerin bileşkesi hesaplanırken açılara göre özel durumlar verilir."]'::jsonb, '{}'::jsonb, 85, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#86', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.1.4', 'Bir vektörün iki boyutlu kartezyen koordinat sisteminde bileşenlerini çizerek büyüklüklerini hesaplar.', NULL, '[]'::jsonb, '{}'::jsonb, 86, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#87', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.2.1', 'Sabit hızlı iki cismin hareketini birbirine göre yorumlar.', NULL, '[]'::jsonb, '{}'::jsonb, 87, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#88', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.2.2', 'Hareketli bir ortamdaki sabit hızlı cisimlerin hareketini farklı gözlem çerçevelerine göre yorumlar.', NULL, '[]'::jsonb, '{}'::jsonb, 88, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#89', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.2.3', 'Bağıl hareket ile ilgili hesaplamalar yapar.', NULL, '["Hesaplamalarla ilgili problemlerin günlük hayattan seçilmesine özen gösterilir."]'::jsonb, '{}'::jsonb, 89, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#90', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.3.1', 'Net kuvvetin yönünü belirleyerek büyüklüğünü hesaplar.', NULL, '["a) Yatay, düşey ve eğik düzlemde sürtünme kuvvetinin yönü belirlenerek büyüklüğünün hesaplanması sağlanır.", "b) Sürtünmeli ve sürtünmesiz yüzeylerde serbest cisim diyagramları üzerinde cisme etki eden kuvvetlerin gösterilmesi sağlanır."]'::jsonb, '{}'::jsonb, 90, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#91', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.3.2', 'Net kuvvet etkisindeki cismin hareketi ile ilgili hesaplamalar yapar.', NULL, '["a) Hesaplamaların günlük hayat örnekleri üzerinden yapılmasına özen gösterilir.", "b) Sürtünmeli ve sürtünmesiz yüzeyler dikkate alınmalıdır."]'::jsonb, '{}'::jsonb, 91, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#92', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.4.1', 'Bir boyutta sabit ivmeli hareketi analiz eder.', NULL, '["a) Hareket denklemleri verilir.", "b) Öğrencilerin sabit ivmeli hareket ile ilgili konum-zaman, hız-zaman ve ivme-zaman grafiklerini çizmeleri, yorumlamaları ve grafikler arasında dönüşüm yapmaları sağlanır."]'::jsonb, '{}'::jsonb, 92, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#93', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.4.2', 'Bir boyutta sabit ivmeli hareket ile ilgili hesaplamalar yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 93, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#94', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.4.3', 'Hava direncinin ihmal edildiği ortamda düşen cisimlerin hareketlerini analiz eder.', NULL, '["İlk hızsız bırakılan cisimler için hareket denklemleri, konum-zaman, hız-zaman ve ivme-zaman grafikleri verilerek matematiksel hesaplamalar yapılması sağlanır."]'::jsonb, '{}'::jsonb, 94, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#95', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.4.4', 'Düşen cisimlere etki eden hava direnç kuvvetinin bağlı olduğu değişkenleri analiz eder.', NULL, '["Öğrencilerin değişkenleri deney yaparak veya simülasyonlar kullanarak belirlemeleri sağlanır."]'::jsonb, '{}'::jsonb, 95, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#96', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.4.5', 'Limit hız kavramını açıklar.', NULL, '["a) Limit hız kavramı günlük hayattan örneklerle (yağmur damlalarının canımızı acıtmaması vb.) açıklanır.", "b) Limit hızın matematiksel modeli verilir. Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 96, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#97', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.4.6', 'Düşey doğrultuda ilk hızı olan ve sabit ivmeli hareket yapan cisimlerin hareketlerini analiz eder.', NULL, '["Düşey doğrultuda (yukarıdan aşağıya ve aşağıdan yukarıya) atış hareket denklemleri, konum-zaman, hız-zaman ve ivme-zaman grafikleri verilerek matematiksel hesaplamalar yapılması sağlanır."]'::jsonb, '{}'::jsonb, 97, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#98', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.5.1', 'Atış hareketlerini yatay ve düşey boyutta analiz eder.', NULL, '["Öğrencilerin deney yaparak veya simülasyonlarla atış hareketlerini incelemeleri ve yorumlamaları sağlanır."]'::jsonb, '{}'::jsonb, 98, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#99', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.5.2', 'İki boyutta sabit ivmeli hareket ile ilgili hesaplamalar yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 99, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#100', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.6.1', 'Yapılan iş ile enerji arasındaki ilişkiyi analiz eder.', NULL, '["a) Kuvvet-yol grafiğinden faydalanılarak iş hesaplamaları yapılır.", "b) Hooke Yasası verilir.", "c) Grafiklerden faydalanılarak kinetik, yer çekimi potansiyel ve esneklik potansiyel enerji türlerinin matematiksel modellerine ulaşılması sağlanır.", "ç) Matematiksel hesaplamalar yapılması sağlanır."]'::jsonb, '{}'::jsonb, 100, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#101', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.6.2', 'Cisimlerin hareketini mekanik enerjinin korunumunu kullanarak analiz eder.', NULL, '["a) Öğrencilerin serbest düşme, atış hareketleri ve esnek yay içeren olayları incelemeleri ve mekanik enerjinin korunumunu kullanarak matematiksel hesaplamalar yapmaları sağlanır.", "b) Canan Dağdeviren’in yaptığı çalışmalar hakkında bilgi verilir."]'::jsonb, '{}'::jsonb, 101, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#102', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.6.3', 'Sürtünmeli yüzeylerde enerji korunumunu ve dönüşümlerini analiz eder.', NULL, '["Sürtünmeli yüzeylerde hareket eden cisimlerle ilgili enerji korunumu ve dönüşümü ile ilgili matematiksel hesaplamalar yapılması sağlanır."]'::jsonb, '{}'::jsonb, 102, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#103', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.7.1', 'İtme ve çizgisel momentum kavramlarını açıklar.', NULL, '["a) Çizgisel momentumla ilgili günlük hayattan örnekler verilir.", "b) İtme ve çizgisel momentum kavramlarının matematiksel modeli verilir."]'::jsonb, '{}'::jsonb, 103, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#104', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.7.2', 'İtme ile çizgisel momentum değişimi arasında ilişki kurar.', NULL, '["a) Öğrencilerin Newton’ın ikinci hareket yasasından faydalanarak itme ve momentum arasındaki matematiksel modeli elde etmeleri sağlanır.", "b) Öğrencilerin kuvvet-zaman grafiğinden alan hesaplamaları yapmaları ve cismin momentum değişikliği ile ilişkilendirmeleri sağlanır.", "c) İtme ve çizgisel momentum değişimi ile ilgili matematiksel hesaplamalar yapılması sağlanır."]'::jsonb, '{}'::jsonb, 104, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#105', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.7.3', 'Çizgisel momentumun korunumunu analiz eder.', NULL, '["a) Öğrencilerin deney yaparak veya simülasyonlar kullanarak çizgisel momentum korunumu ile ilgili çıkarımda bulunmaları sağlanır.", "b) Çizgisel momentumun korunumu bir ve iki boyutlu hareketle sınırlandırılır."]'::jsonb, '{}'::jsonb, 105, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#106', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.7.4', 'Çizgisel momentumun korunumu ile ilgili hesaplamalar yapar.', NULL, '["Enerjinin korunduğu ve korunmadığı durumlar göz önüne alınarak bir ve iki boyutta çizgisel momentumun korunumu, çarpışmalar ve patlamalarla ilgili matematiksel hesaplamalar yapılması sağlanır."]'::jsonb, '{}'::jsonb, 106, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#107', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.8.1', 'Tork kavramını açıklar.', NULL, '["Torkun yönünü belirlemek için sağ el kuralı verilir."]'::jsonb, '{}'::jsonb, 107, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#108', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.8.2', 'Torkun bağlı olduğu değişkenleri analiz eder.', NULL, '["a) Öğrencilerin deney yaparak veya simülasyonlar kullanarak torkun bağlı olduğu değişkenler ile ilgili sonuçlar çıkarmaları sağlanır.", "b) Öğrencilerin tork ile ilgili günlük hayattan problem durumları bulmaları ve bunlar için çözüm yolları üretmeleri sağlanır."]'::jsonb, '{}'::jsonb, 108, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#109', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.8.3', 'Tork ile ilgili hesaplamalar yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 109, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#110', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.9.1', 'Cisimlerin denge şartlarını açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 110, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#111', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.9.2', 'Kütle merkezi ve ağırlık merkezi kavramlarını açıklar.', NULL, '["Kütle ve ağırlık merkezi kavramlarının farklı olduğu durumlara değinilir."]'::jsonb, '{}'::jsonb, 111, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#112', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.9.3', 'Kütle merkezi ve ağırlık merkezi ile ilgili hesaplamalar yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 112, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#113', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.10.1', 'Günlük hayatta kullanılan basit makinelerin işlevlerini açıklar.', NULL, '["Kaldıraç, sabit ve hareketli makara, palanga, eğik düzlem, vida, çıkrık, çark ve kasnak ile sınırlı kalınır."]'::jsonb, '{}'::jsonb, 113, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#114', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.10.2', 'Basit makineler ile ilgili hesaplamalar yapar.', NULL, '["a) İkiden fazla basit makinenin bir arada olduğu sistemlerle ilgili matematiksel hesaplamalara girilmez.", "b) Hesaplamaların günlük hayatta kullanılan basit makine örnekleri (anahtar gibi) üzerinden yapılması sağlanır.", "c) Basit makinelerde verim ile ilgili matematiksel hesaplamalar yapılması sağlanır."]'::jsonb, '{}'::jsonb, 114, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#115', 'yks-2026-fizik', 'yks-2026-fizik#11', '11.1.10.3', 'Hayatı kolaylaştırmak amacıyla basit makinelerden oluşan güvenli bir sistem tasarlar.', NULL, '["a) Atık malzeme ve bilişim teknolojilerinden yararlanmaları için teşvik edilmelidir.", "b) Basit makine sistemlerinin kullanıldığı alanlarda iş sağlığı ve güvenliğini arttırıcı tedbirlere yönelik araştırma yapılması sağlanır.", "c) Yapılan özgün tasarımlara patent alınabileceği vurgulanarak öğrenciler, proje yarışmalarına katılmaları konusunda teşvik edilmelidir."]'::jsonb, '{}'::jsonb, 115, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#116', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.1.1', 'Yüklü cisimler arasındaki elektriksel kuvveti etkileyen değişkenleri belirler.', NULL, '["a) Öğrencilerin deney veya simülasyonlardan yararlanmaları sağlanır.", "b) Coulomb sabitinin (k), ortamın elektriksel geçirgenliği ile ilişkisi vurgulanır."]'::jsonb, '{}'::jsonb, 116, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#117', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.1.2', 'Noktasal yük için elektrik alanı açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 117, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#118', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.1.3', 'Noktasal yüklerde elektriksel kuvvet ve elektrik alanı ile ilgili hesaplamalar yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 118, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#119', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.2.1', 'Noktasal yükler için elektriksel potansiyel enerji, elektriksel potansiyel, elektriksel potansiyel farkı ve elektriksel iş kavramlarını açıklar.', NULL, '["a) Kavramların günlük hayat örnekleri ile açıklanması sağlanır.", "b) Öğrencilerin, noktasal yüklerin bir noktada oluşturduğu elektrik potansiyeli ve eş potansiyel yüzeylerini tanımlamaları sağlanır."]'::jsonb, '{}'::jsonb, 119, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#120', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.2.2', 'Düzgün bir elektrik alan içinde iki nokta arasındaki potansiyel farkını hesaplar.', NULL, '[]'::jsonb, '{}'::jsonb, 120, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#121', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.2.3', 'Noktasal yükler için elektriksel potansiyel enerji, elektriksel potansiyel, elektriksel potansiyel farkı ve elektriksel iş ile ilgili hesaplamalar yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 121, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#122', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.3.1', 'Yüklü, iletken ve paralel levhalar arasında oluşan elektrik alanı, alan çizgilerini çizerek açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 122, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#123', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.3.2', 'Yüklü, iletken ve paralel levhalar arasında oluşan elektrik alanının bağlı olduğu değişkenleri analiz eder.', NULL, '["Değişkenlerin deney veya simülasyonlarla belirlenmesi sağlanır."]'::jsonb, '{}'::jsonb, 123, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#124', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.3.3', 'Yüklü parçacıkların düzgün elektrik alandaki davranışını açıklar.', NULL, '["a) Alana dik giren parçacıkların sapma yönleri üzerinde durulur. Matematiksel hesaplamalara girilmez.", "b) Öğrencilerin yüklü parçacıkların elektrik alandaki davranışının teknolojideki kullanım yerlerini araştırmaları ve sunum yapmaları sağlanır."]'::jsonb, '{}'::jsonb, 124, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#125', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.3.4', 'Sığa (kapasite) kavramını açıklar.', NULL, '["Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 125, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#126', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.3.5', 'Sığanın bağlı olduğu değişkenleri analiz eder.', NULL, '["a) Değişkenlerin deney veya simülasyonlarla belirlenmesi sağlanır.", "b) Öğrencilerin matematiksel modeli elde etmeleri sağlanır. Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 126, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#127', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.3.6', 'Yüklü levhaların özelliklerinden faydalanarak sığacın (kondansatör) işlevini açıklar.', NULL, '["a) Sığaçların kullanım alanlarına yönelik araştırma yapılması sağlanır.", "b) Öğrencilerin elektrik yüklerinin nasıl depolanıp kullanılabileceğini tartışmaları ve elektrik enerjisi ile ilişkilendirmeleri sağlanır."]'::jsonb, '{}'::jsonb, 127, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#128', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.4.1', 'Üzerinden akım geçen iletken düz bir telin çevresinde, halkanın merkezinde ve akım makarasının (bobin) merkez ekseninde oluşan manyetik alanın şiddetini etkileyen değişkenleri analiz eder.', NULL, '["Manyetik alan yönünün sağ el kuralıyla gösterilmesi sağlanır."]'::jsonb, '{}'::jsonb, 128, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#129', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.4.2', 'Üzerinden akım geçen iletken düz bir telin çevresinde, halkanın merkezinde ve akım makarasının merkez ekseninde oluşan manyetik alan ile ilgili hesaplamalar yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 129, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#130', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.4.3', 'Üzerinden akım geçen iletken düz bir tele manyetik alanda etki eden kuvvetin yönünün ve şiddetinin bağlı olduğu değişkenleri analiz eder.', NULL, '["Manyetik kuvvetin büyüklüğünün matematiksel modeli verilir, sağ el kuralının uygulanması sağlanır. Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 130, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#131', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.4.4', 'Manyetik alan içerisinde akım taşıyan dikdörtgen tel çerçeveye etki eden kuvvetlerin döndürme etkisini açıklar.', NULL, '["Dönen çerçeveye etki eden manyetik kuvvetlerin yönünün gösterilmesi sağlanır."]'::jsonb, '{}'::jsonb, 131, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#132', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.4.5', 'Yüklü parçacıkların manyetik alan içindeki hareketini analiz eder.', NULL, '["a) Öğrencilerin, sağ el kuralını kullanarak yüklü parçacıklara etki eden manyetik kuvvetin yönünü bulmaları ve bu kuvvetin etkisiyle yükün manyetik alandaki yörüngesini çizmeleri sağlanır.", "b) Yüklü parçacıkların manyetik alan içindeki hareketi ile ilgili matematiksel modeller verilmez. Matematiksel hesaplamalara girilmez.", "c) Öğrencilerin, manyetik kuvvetin teknolojide kullanım alanlarıyla ilgili araştırma yapmaları ve paylaşması sağlanır."]'::jsonb, '{}'::jsonb, 132, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#133', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.4.6', 'Manyetik akı kavramını açıklar.', NULL, '["Manyetik akının matematiksel modeli verilir."]'::jsonb, '{}'::jsonb, 133, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#134', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.4.7', 'İndüksiyon akımını oluşturan sebeplere ilişkin çıkarım yapar.', NULL, '["Çıkarımların deney veya simülasyonlardan yararlanılarak yapılması ve indüksiyon akımının matematiksel modelinin çıkarılması sağlanır."]'::jsonb, '{}'::jsonb, 134, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#135', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.4.8', 'Manyetik akı ve indüksiyon akımı ile ilgili hesaplamalar yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 135, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#136', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.4.9', 'Öz-indüksiyon akımının oluşum sebebini açıklar.', NULL, '["Öz-indüksiyon akımı ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 136, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#137', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.4.10', 'Yüklü parçacıkların manyetik alan ve elektrik alandaki davranışını açıklar.', NULL, '["a) Lorentz kuvvetinin matematiksel modeli verilir. Matematiksel hesaplamalara girilmez.", "b) Lorentz kuvvetinin günlük hayattaki uygulamalarına örnekler verilir."]'::jsonb, '{}'::jsonb, 137, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#138', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.4.11', 'Elektromotor kuvveti oluşturan sebeplere ilişkin çıkarım yapar.', NULL, '["a) Deney veya simülasyonlar yardımıyla çıkarımın yapılması sağlanır.", "b) Öğrencilerin elektrik motoru ve dinamonun çalışma ilkelerini karşılaştırmaları sağlanır."]'::jsonb, '{}'::jsonb, 138, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#139', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.5.1', 'Alternatif akımı açıklar.', NULL, '["Öğrencilerin farklı ülkelerin elektrik şebekelerinde kullanılan gerilim değerleri ile ilgili araştırma yapmaları ve araştırma bulgularına dayanarak bu değerlerin kullanılmasının sebeplerini tartışmaları sağlanır."]'::jsonb, '{}'::jsonb, 139, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#140', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.5.2', 'Alternatif ve doğru akımı karşılaştırır.', NULL, '["a) Alternatif ve doğru akımın kullanıldığı yerler açıklanarak bu akımların karşılaştırılması sağlanır.", "b) Edison ve Tesla’nın alternatif akım ve doğru akım ile ilgili görüşlerinin karşılaştırılması sağlanır.", "c) Alternatif akımın etkin ve maksimum değerleri vurgulanır."]'::jsonb, '{}'::jsonb, 140, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#141', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.5.3', 'Alternatif ve doğru akım devrelerinde direncin, bobinin ve sığacın davranışını açıklar.', NULL, '["Öğrencilerin simülasyonlar yardımıyla alternatif ve doğru akım devrelerinde direnç, bobin ve kondansatör davranışlarını ayrı ayrı incelemeleri, değerleri kontrol ederek gerçekleşen değişiklikleri gözlemlemeleri ve yorumlamaları sağlanır."]'::jsonb, '{}'::jsonb, 141, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#142', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.5.4', 'İndüktans, kapasitans, rezonans ve empedans kavramlarını açıklar.', NULL, '["a) Vektörel gösterim yapılmaz. Akım ve gerilimin zamana bağlı değişim grafiklerine girilmez.", "b) Her devre elemanının kendine has bir ohmik direnci olduğu vurgulanır.", "c) Alternatif akım devreleri ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 142, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#143', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.6.1', 'Transformatörlerin çalışma prensibini açıklar.', NULL, '["a) Primer ve sekonder gerilimi, primer ve sekonder akım şiddeti, primer ve sekonder güç kavramları açıklanır. Matematiksel hesaplamalara girilmez.", "b) İdeal ve ideal olmayan transformatörlerin çalışma ilkesi üzerinde durulur."]'::jsonb, '{}'::jsonb, 143, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#144', 'yks-2026-fizik', 'yks-2026-fizik#12', '11.2.6.2', 'Transformatörlerin kullanım amaçlarını açıklar.', NULL, '["a) Öğrencilerin transformatörlerin kullanıldığı yerleri araştırmaları sağlanır.", "b) Elektrik enerjisinin taşınma sürecinde transformatörlerin rolü vurgulanır."]'::jsonb, '{}'::jsonb, 144, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#145', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.1.1', 'Düzgün çembersel hareketi açıklar.', NULL, '["a) Periyot, frekans, çizgisel hız ve açısal hız, merkezcil ivme kavramları verilir.", "b) Öğrencilerin düzgün çembersel harekette çizgisel hız vektörünü çember üzerinde iki farklı noktada çizerek merkezcil ivmenin şiddetini bulmaları ve yönünü göstermeleri sağlanır. Çizgisel ivme kavramına girilmez."]'::jsonb, '{}'::jsonb, 145, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#146', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.1.2', 'Düzgün çembersel harekette merkezcil kuvvetin bağlı olduğu değişkenleri analiz eder.', NULL, '["Deney yaparak veya simülasyonlarla merkezcil kuvvetin bağlı olduğu değişkenler arasındaki ilişkinin belirlenmesi sağlanır. Matematiksel model verilir. Matematiksel hesaplamalar yapılır."]'::jsonb, '{}'::jsonb, 146, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#147', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.1.3', 'Düzgün çembersel hareket yapan cisimlerin hareketini analiz eder.', NULL, '["a) Yatay ve düşey düzlemde düzgün çembersel hareket yapan cisimlere ait serbest cisim diyagramlarının çizilmesi sağlanır.", "b) Düzgün çembersel harekette konum, hız ve ivme hesaplamaları yapılır. Hesaplamalarda trigonometrik fonksiyonlara girilmez."]'::jsonb, '{}'::jsonb, 147, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#148', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.1.4', 'Yatay, düşey, eğimli zeminlerde araçların emniyetli dönüş şartları ile ilgili hesaplamalar yapar.', NULL, '["Virajlarda emniyetli dönüş için hız sınırına uymanın önemi vurgulanır."]'::jsonb, '{}'::jsonb, 148, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#149', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.2.1', 'Öteleme ve dönme hareketini karşılaştırır.', NULL, '[]'::jsonb, '{}'::jsonb, 149, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#150', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.2.2', 'Eylemsizlik momenti kavramını açıklar.', NULL, '["Eylemsizlik momenti ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 150, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#151', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.2.3', 'Dönme ve dönerek öteleme hareketi yapan cismin kinetik enerjisinin bağlı olduğu değişkenleri açıklar.', NULL, '["Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 151, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#152', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.3.1', 'Açısal momentumun fiziksel bir nicelik olduğunu açıklar.', NULL, '["Açısal momentumun atomik boyutta da fiziksel bir nicelik olduğu belirtilir."]'::jsonb, '{}'::jsonb, 152, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#153', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.3.2', 'Açısal momentumu çizgisel momentum ile ilişkilendirerek açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 153, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#154', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.3.3', 'Açısal momentumu torkla ilişkilendirir.', NULL, '["a) Öğrencilerin, açısal momentumu, eylemsizlik momenti ve açısal hız kavramlarını kullanarak elde etmeleri sağlanır.", "b) Öğrencilerin torku, eylemsizlik momenti ve açısal ivme kavramlarını kullanarak elde etmeleri sağlanır."]'::jsonb, '{}'::jsonb, 154, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#155', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.3.4', 'Açısal momentumun korunumunu günlük hayattan örneklerle açıklar.', NULL, '["Açısal momentumun korunumu ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 155, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#156', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.4.1', 'Kütle çekim kuvvetini açıklar.', NULL, '["a) Kütle çekim kuvvetine değinilir. Matematiksel model verilir. Matematiksel hesaplamalara girilmez.", "b) Yapay uydular, ay ve gezegenlerin hareketleri açıklanır. Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 156, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#157', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.4.2', 'Newton’ın Hareket Kanunları’nı kullanarak kütle çekim ivmesinin bağlı olduğu değişkenleri belirler.', NULL, '["a) Öğrencilerin yerçekimi ivmesini; dünyanın yarıçapı ve kütlesi cinsinden ifade etmeleri sağlanır.", "b) Öğrencilerin homojen bir kürenin içinde, yüzeyinde ve dışındaki çekim alanını gösteren kuvvet çizgilerini çizmeleri sağlanır.", "c) Her kütlenin bir kütle çekim alanı oluşturduğu vurgulanır."]'::jsonb, '{}'::jsonb, 157, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#158', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.4.3', 'Kütle çekim potansiyel enerjisini açıklar.', NULL, '["Bağlanma ve kurtulma enerjisi kavramları üzerinde durulur."]'::jsonb, '{}'::jsonb, 158, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#159', 'yks-2026-fizik', 'yks-2026-fizik#13', '12.1.5.1', 'Kepler Kanunları’nı açıklar.', NULL, '["a) Matematiksel hesaplamalara girilmez.", "b) Galileo Galilei, Ali Kuşçu ve Uluğ Bey’in gök cisimleri ve gök cisimlerinin hareketleri ile ilgili çalışmalarına yer verilir."]'::jsonb, '{}'::jsonb, 159, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#160', 'yks-2026-fizik', 'yks-2026-fizik#14', '12.2.1.1', 'Basit harmonik hareketi düzgün çembersel hareketi kullanarak açıklar.', NULL, '["a) Basit harmonik harekete günlük hayattan örnekler verilir.", "b) Yay sarkacı ve basit sarkaç için uzanım, genlik, periyot, frekans, geri çağırıcı kuvvet ve denge noktası kavramları harmonik hareket örnekleri ile açıklanır.", "c) Uzanım, genlik, periyot, frekans ilişkisi ile ilgili matematiksel hesaplamalar yapılır.", "ç) Basit harmonik hareket ile ilgili fonksiyonların türevlerine ve işlemlerine girilmez."]'::jsonb, '{}'::jsonb, 160, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#161', 'yks-2026-fizik', 'yks-2026-fizik#14', '12.2.1.2', 'Basit harmonik harekette konumun zamana göre değişimini analiz eder.', NULL, '["Öğrencilerin deney yaparak veya simülasyonlar kullanarak konum-zaman grafiğini çizmeleri ve yorumlamaları sağlanır."]'::jsonb, '{}'::jsonb, 161, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#162', 'yks-2026-fizik', 'yks-2026-fizik#14', '12.2.1.3', 'Basit harmonik harekette kuvvet, hız ve ivmenin konuma göre değişimi ile ilgili hesaplamalar yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 162, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#163', 'yks-2026-fizik', 'yks-2026-fizik#14', '12.2.1.4', 'Yay sarkacı ve basit sarkaçta periyodun bağlı olduğu değişkenleri belirler.', NULL, '["Öğrencilerin deney yaparak veya simülasyonlarla periyoda etki eden değişkenleri belirlemeleri sağlanır. Periyodun matematiksel modeli verilir."]'::jsonb, '{}'::jsonb, 163, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#164', 'yks-2026-fizik', 'yks-2026-fizik#14', '12.2.1.5', 'Yay sarkacı ve basit sarkacın periyodu ile ilgili hesaplamalar yapar.', NULL, '["a) Paralel ve seri bağlı yaylarda eş değer yay sabiti hesaplamalarının yapılması sağlanır.", "b) Esnek yayların hareketi tek boyut ile sınırlandırılır."]'::jsonb, '{}'::jsonb, 164, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#165', 'yks-2026-fizik', 'yks-2026-fizik#15', '12.3.1.1', 'Su dalgalarında kırınım olayının dalga boyu ve yarık genişliği ile ilişkisini belirler.', NULL, '["Öğrencilerin deney yaparak veya simülasyonlar kullanarak elde ettikleri verilerden yararlanarak yorum yapmaları sağlanır."]'::jsonb, '{}'::jsonb, 165, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#166', 'yks-2026-fizik', 'yks-2026-fizik#15', '12.3.1.2', 'Su dalgalarında girişim olayını açıklar.', NULL, '["a) Öğrencilerin girişim desenini deney yaparak veya simülasyonlar kullanarak çizmeleri sağlanır.", "b) Girişimle ilgili matematiksel hesaplamalara girilmez.", "c) Faz farkı kavramına girilmez."]'::jsonb, '{}'::jsonb, 166, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#167', 'yks-2026-fizik', 'yks-2026-fizik#15', '12.3.1.3', 'Işığın çift yarıkta girişimine etki eden değişkenleri açıklar.', NULL, '["a) Öğrencilerin girişim desenini deney yaparak veya simülasyonlar kullanarak çizmeleri sağlanır.", "b) Çift yarıkta girişimle ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 167, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#168', 'yks-2026-fizik', 'yks-2026-fizik#15', '12.3.1.4', 'Işığın tek yarıkta kırınımına etki eden değişkenleri açıklar.', NULL, '["a) Öğrencilerin kırınım desenini deney yaparak veya simülasyonlar kullanarak çizmeleri sağlanır.", "b) Tek yarıkta kırınımla ilgili matematiksel hesaplamalara girilmez.", "c) İnce zarlarda girişim, hava kaması ve çözme gücü konularına girilmez."]'::jsonb, '{}'::jsonb, 168, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#169', 'yks-2026-fizik', 'yks-2026-fizik#15', '12.3.1.5', 'Kırınım ve girişim olaylarını inceleyerek ışığın dalga doğası hakkında çıkarım yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 169, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#170', 'yks-2026-fizik', 'yks-2026-fizik#15', '12.3.1.6', 'Doppler olayının etkilerini ışık ve ses dalgalarından örneklerle açıklar.', NULL, '["Örneklerin günlük hayattan seçilmesine özen gösterilir. Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 170, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#171', 'yks-2026-fizik', 'yks-2026-fizik#15', '12.3.2.1', 'Elektromanyetik dalgaların ortak özelliklerini açıklar.', NULL, '["Maxwell’in elektromanyetik teorinin kurucusu olduğu vurgulanır."]'::jsonb, '{}'::jsonb, 171, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#172', 'yks-2026-fizik', 'yks-2026-fizik#15', '12.3.2.2', 'Elektromanyetik spektrumu günlük hayattan örneklerle ilişkilendirerek açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 172, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#173', 'yks-2026-fizik', 'yks-2026-fizik#16', '12.4.1.1', 'Atom kavramını açıklar.', NULL, '["a) Bohr atom teorisi haricindeki diğer teoriler, ayrıntılara girilmeden tarihsel gelişim süreci içinde verilir.", "b) Atom teorilerinin birbirleriyle ilişkili olarak geliştirildiği vurgulanmalıdır.", "c) Bohr atom teorisinde; atom yarıçapı, enerji seviyeleri, uyarılma, iyonlaşma ve ışıma kavramları vurgulanır. Matematiksel hesaplamalara girilmez.", "ç) Milikan yağ damlası, Thomson’ın e/m tayini, Rutherford saçılması deneyleri ile sınırlı kalınır. Bu deneylerle ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 173, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#174', 'yks-2026-fizik', 'yks-2026-fizik#16', '12.4.1.2', 'Atomun uyarılma yollarını açıklar.', NULL, '["Atomların birbirleriyle, elektronla, fotonla ve ısıyla uyarılma şartlarının tartışılması sağlanır."]'::jsonb, '{}'::jsonb, 174, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#175', 'yks-2026-fizik', 'yks-2026-fizik#16', '12.4.1.3', 'Modern atom teorisinin önemini açıklar.', NULL, '["a) Heisenberg Belirsizlik İlkesi, kuantum sayıları, olasılık dalgası ve Schrödinger dalga denklemine değinilir.", "b) Matematiksel hesaplamalara girilmez.", "c) Feza Gürsey, Asım Orhan Barut ve Behram N. Kurşunoğlu''nun atom fiziği konusunda çalışmalar yaptığı vurgulanır."]'::jsonb, '{}'::jsonb, 175, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#176', 'yks-2026-fizik', 'yks-2026-fizik#16', '12.4.2.1', 'Büyük patlama teorisini açıklar.', NULL, '["a) Evrenin oluşumu ve geleceğiyle ilgili farklı teorilerin de olduğu vurgulanır.", "b) Öğrencilerin büyük patlama teorisini destekleyen bilimsel çalışmaları araştırmaları ve araştırma sonuçlarını rapor olarak sunmaları sağlanır.", "c) Hubble Yasası’na değinilir. Matematiksel modeli verilmez."]'::jsonb, '{}'::jsonb, 176, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#177', 'yks-2026-fizik', 'yks-2026-fizik#16', '12.4.2.2', 'Atom altı parçacıkların özelliklerini temel düzeyde açıklar.', NULL, '["a) Öğrencilerin atom altı parçacıkları standart model çerçevesinde tanımlamaları sağlanır.", "b) Korunum yasaları ile ilgili matematiksel hesaplamalara girilmez.", "c) Dört temel kuvvetin açıklanması sağlanır.", "ç) Abdus Salam, Sheldon Lee Glashow ve Steven Weinberg’in Nobel ödülünü elektromanyetik ve zayıf kuvvetin birleşik bir kuvvet görünümünde olduğunu keşfetmeleri üzerine aldıkları vurgulanır."]'::jsonb, '{}'::jsonb, 177, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#178', 'yks-2026-fizik', 'yks-2026-fizik#16', '12.4.2.3', 'Madde oluşum sürecini açıklar.', NULL, '["a) Atom altı parçacıklardan başlayarak madde oluşumunun modelle açıklanması sağlanır.", "b) Higgs bozonuna kısaca değinilir."]'::jsonb, '{}'::jsonb, 178, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#179', 'yks-2026-fizik', 'yks-2026-fizik#16', '12.4.2.4', 'Madde ve antimadde kavramlarını açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 179, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#180', 'yks-2026-fizik', 'yks-2026-fizik#16', '12.4.3.1', 'Kararlı ve kararsız durumdaki atomların özelliklerini karşılaştırır.', NULL, '["a) Radyoaktif madde, radyoaktivite, radyoaktif ışıma kavramları üzerinde durulur.", "b) Bazı atom çekirdeklerinin çeşitli yollarla ışıma yapabileceği vurgulanır.", "c) Marie Curie ve Wilhelm Conrad Röntgen’in radyoaktivite konusunda yaptığı çalışmalara yer verilir."]'::jsonb, '{}'::jsonb, 180, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#181', 'yks-2026-fizik', 'yks-2026-fizik#16', '12.4.3.2', 'Radyoaktif bozunma sonucu atomun kütle numarası, atom numarası ve enerjisindeki değişimi açıklar.', NULL, '["a) Alfa, beta, gama ışınımları dışındaki bozunma türlerine girilmez.", "b) Enerjideki değişim açıklanırken matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 181, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#182', 'yks-2026-fizik', 'yks-2026-fizik#16', '12.4.3.3', 'Nükleer fisyon ve füzyon olaylarını açıklar.', NULL, '["a) Nükleer enerji ile çalışan sistemler hakkında araştırma yapılması sağlanır.", "b) Nükleer reaktörlerin bilime, teknolojiye, ülke ekonomisine ve çevreye etkileri üzerinde durulur.", "c) Atom bombasının yıkıcı etkileri tarihî gerçekler üzerinden açıklanarak nükleer silahsızlanmanın dünya barışı açısından önemi üzerinde durulur."]'::jsonb, '{}'::jsonb, 182, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#183', 'yks-2026-fizik', 'yks-2026-fizik#16', '12.4.3.4', 'Radyasyonun canlılar üzerindeki etkilerini açıklar.', NULL, '["a) Yaşam alanlarında var olan radyasyon kaynakları, radyasyondan korunma yolları ve radyasyon güvenliğinin araştırılması ve bilgilerin paylaşılması sağlanır.", "b) İyonlaştırıcı radyasyona değinilerek kullanıldığı alanlardan ve biyolojik etkilerinden bahsedilir."]'::jsonb, '{}'::jsonb, 183, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#184', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.1.1', 'Michelson–Morley deneyinin amacını ve sonuçlarını açıklar.', NULL, '["a) Deneyin yapılış aşamaları üzerinde durulur.", "b) Deneyin farklı bilim insanları tarafından farklı koşullarda çok kez tekrarlanmış olmasının nedeni üzerinde durulur. Bilimsel çalışmalarda sabırlı ve kararlı olmanın önemi vurgulanır.", "c) Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 184, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#185', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.1.2', 'Einstein’ın özel görelilik teorisinin temel postülalarını ifade eder.', NULL, '[]'::jsonb, '{}'::jsonb, 185, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#186', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.1.3', 'Göreli zaman ve göreli uzunluk kavramlarını açıklar.', NULL, '["Özel görelilikte matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 186, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#187', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.1.4', 'Kütle-enerji eşdeğerliğini açıklar.', NULL, '["Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 187, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#188', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.2.1', 'Siyah cisim ışımasını açıklar.', NULL, '["a) Planck hipotezi açıklanır.", "b) Dalga boyu-ışıma şiddeti grafiğinden hareketle klasik yaklaşımla modern yaklaşımın çelişkisi ve bu çelişkinin kuantum fiziğinin doğuşuna etkisi vurgulanır.", "c) Siyah cisim ışıması ile ilgili matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 188, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#189', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.3.1', 'Foton kavramını açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 189, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#190', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.3.2', 'Fotoelektrik olayını açıklar.', NULL, '["a) Hertz’in çalışmaları üzerinde durulur.", "b) Einstein’ın fotoelektrik denklemi üzerinde durulur.", "c) Öğrencilerin simülasyonlar yardımıyla fotoelektrik olaya etki eden değişkenleri gözlemlemeleri ve yorumlamaları sağlanır."]'::jsonb, '{}'::jsonb, 190, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#191', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.3.3', 'Farklı metaller için maksimum kinetik enerji-frekans grafiğini çizer.', NULL, '[]'::jsonb, '{}'::jsonb, 191, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#192', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.3.4', 'Fotoelektronların sahip olduğu maksimum kinetik enerji, durdurma gerilimi ve metalin eşik enerjisi arasındaki matematiksel ilişkiyi açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 192, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#193', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.3.5', 'Fotoelektrik olayın günlük hayattaki uygulamalarına örnekler verir.', NULL, '["Fotoelektrik olayın günlük hayattaki olumlu (musluklarda hijyenin sağlanması gibi) ve olumsuz (sahte güneş gözlüklerinin kullanımı gibi) etkileri üzerinde durulur."]'::jsonb, '{}'::jsonb, 193, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#194', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.3.6', 'Fotoelektrik olayla ilgili hesaplamalar yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 194, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#195', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.4.1', 'Compton olayında foton ve elektron etkileşimini açıklar.', NULL, '["Öğrencilerin model veya simülasyonlar kullanarak Compton saçılmasını açıklamaları sağlanır. Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 195, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#196', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.4.2', 'Compton ve fotoelektrik olaylarının benzer yönlerini belirterek ışığın tanecik doğası hakkında çıkarım yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 196, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#197', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.4.3', 'Işığın ikili doğasını açıklar.', NULL, '["Işığın tanecik, dalga, hem tanecik hem de dalga doğası ile açıklanan olaylar vurgulanır."]'::jsonb, '{}'::jsonb, 197, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#198', 'yks-2026-fizik', 'yks-2026-fizik#17', '12.5.4.4', 'Madde ve dalga arasındaki ilişkiyi açıklar.', NULL, '["a) De Broglie bağıntısı verilir.", "b) Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 198, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#199', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.1.1', 'Görüntüleme cihazlarının çalışma prensiplerini açıklar.', NULL, '["a) Öğrencilerin röntgen, MR, PET, tomografi, ultrason, radarlar, sonar, termal kameralar ile ilgili araştırmalar yaparak bu teknolojilerin oluşturulmasında fiziğin rolünü sorgulamaları sağlanır.", "b) Görüntüleme cihazlarının (röntgen, MR, PET, tomografi, ultrason, radarlar, sonar, termal kameralar) çalışma ilkelerine kısaca değinilir."]'::jsonb, '{}'::jsonb, 199, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#200', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.1.2', 'LCD ve plazma teknolojilerinde fizik biliminin yerini açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 200, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#201', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.2.1', 'Yarı iletken maddelerin genel özelliklerini açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 201, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#202', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.2.2', 'Yarı iletken malzemelerin teknolojideki önemini açıklar.', NULL, '["a) Diyot ve transistörlerin işlevi verilir, çeşitlerine girilmez.", "b) Öğrencilerin kumun bir elektronik devre elemanı hâline gelme sürecini araştırmaları ve paylaşmaları sağlanır."]'::jsonb, '{}'::jsonb, 202, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#203', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.2.3', 'LED teknolojisinin kullanıldığı yerlere örnekler verir.', NULL, '[]'::jsonb, '{}'::jsonb, 203, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#204', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.2.4', 'Güneş pillerinin çalışma şeklini açıklar.', NULL, '["a) Yapı elemanlarının özelliklerinin detaylarına girilmez.", "b) Güneş pillerinin günümüzdeki ve gelecekteki yerinin tartışılması sağlanır."]'::jsonb, '{}'::jsonb, 204, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#205', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.2.5', 'Günlük hayatı kolaylaştıran, güneş pillerinin kullanıldığı sistem tasarlar.', NULL, '["Öğrencilerin yapmış oldukları tasarımın ülke ekonomisine ve çevreye sağlayacağı katkıları açıklamaları sağlanır."]'::jsonb, '{}'::jsonb, 205, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#206', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.3.1', 'Süper iletken maddenin temel özelliklerini açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 206, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#207', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.3.2', 'Süper iletkenlerin teknolojideki kullanım alanlarına örnekler verir.', NULL, '["Hızlı trenlerin ve parçacık hızlandırıcılarının çalışma ilkeleri üzerinde durulur."]'::jsonb, '{}'::jsonb, 207, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#208', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.4.1', 'Nanobilimin temellerini açıklar.', NULL, '["a) Fizik bilimi ile nanobilim ve nanoteknolojinin ilişkisi üzerinde durulur.", "b) Fonksiyonel ve doğal nanoyapılara sahip sistemlere örnekler verilir."]'::jsonb, '{}'::jsonb, 208, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#209', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.4.2', 'Nanomalzemelerin temel özelliklerini açıklar.', NULL, '["Malzemelerin nano boyutlara indirilmesi durumunda yeni özellikler kazandıkları vurgulanır."]'::jsonb, '{}'::jsonb, 209, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#210', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.4.3', 'Nanomalzemelerin teknolojideki kullanım alanlarına örnekler verir.', NULL, '["Nanomalzemelerin bilim ve teknolojinin gelişimine etkisi vurgulanır."]'::jsonb, '{}'::jsonb, 210, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#211', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.5.1', 'LASER ışınlarının elde edilişini açıklar.', NULL, '["a) Simülasyonlar ve videolar yardımıyla LASER ışınının oluşumunun incelenmesi sağlanır.", "b) Matematiksel hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 211, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-fizik#212', 'yks-2026-fizik', 'yks-2026-fizik#18', '12.6.5.2', 'LASER ışınlarının teknolojideki kullanım alanlarına örnekler verir.', NULL, '[]'::jsonb, '{}'::jsonb, 212, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#1', 'yks-2026-kimya', 'yks-2026-kimya#1', '9.1.1.1', 'Kimyanın bilim olma sürecini açıklar.', NULL, '["a. Simya ile kimya bilimi arasındaki fark vurgulanır. b. Kimya biliminin gelişim süreci ele alınırken Mezopotamya, Çin, Hint, Mısır, Yunan, Orta Asya ve İslam uygarlıklarının kimya bilimine yaptığı katkılara ilişkin okuma parçası verilir. c. Simyadan kimyaya geçiş sürecine katkı sağlayan bilim insanlarından bazılarının (Empedokles, Democritus, Aristo, Cabir bin Hayyan, Ebubekir er-Razi, Robert Boyle, Antoine Lavoisier) kimya bilimine ilişkin çalışmaları kısaca tanıtılır."]'::jsonb, '{}'::jsonb, 1, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#2', 'yks-2026-kimya', 'yks-2026-kimya#1', '9.1.2.1', 'Kimyanın ve kimyacıların başlıca çalışma alanlarını açıklar.', NULL, '["a. Biyokimya, analitik kimya, organik kimya, anorganik kimya, fizikokimya, polimer kimyası ve endüstriyel kimya disiplinleri kısaca tanıtılır. b. İlaç, gübre, petrokimya, arıtım, boya-tekstil alanlarının kimya ile ilişkisi belirtilir. c. Kimya alanı ile ilgili kimya mühendisliği, metalurji mühendisliği, eczacı, kimyager, kimya öğretmenliği meslekleri tanıtılır."]'::jsonb, '{}'::jsonb, 2, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#3', 'yks-2026-kimya', 'yks-2026-kimya#1', '9.1.3.1', 'Günlük hayatta sıklıkla etkileşimde bulunulan elementlerin adlarını sembolleriyle eşleştirir.', NULL, '["a. Element tanımı yapılır. b. Periyodik sistemdeki ilk 20 element ve günlük hayatta sıkça kullanılan krom, mangan, demir, kobalt, nikel, bakır, çinko, brom, gümüş, kalay, iyot, baryum, platin, altın, cıva, kurşun elementlerinin sembolleri tanıtılır."]'::jsonb, '{}'::jsonb, 3, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#4', 'yks-2026-kimya', 'yks-2026-kimya#1', '9.1.3.2', 'Bileşiklerin formüllerini adlarıyla eşleştirir.', NULL, '["a. Bileşik tanımı yapılır. b. H2O, HCl, H2SO4, HNO3, CH3COOH, CaCO3, NaHCO3 , NH3, Ca(OH)2, NaOH, KOH, CaO ve NaCl bileşiklerinin yaygın adları tanıtılır."]'::jsonb, '{}'::jsonb, 4, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#5', 'yks-2026-kimya', 'yks-2026-kimya#1', '9.1.4.1', 'Kimya laboratuvarlarında uyulması gereken iş sağlığı ve güvenliği kurallarını açıklar.', NULL, '["a. Kimyada kullanılan sağlık ve güvenlik amaçlı temel uyarı işaretleri [yanıcı, yakıcı, korozif, patlayıcı, tahriş edici, zehirli (toksik), radyoaktif ve çevreye zararlı anlamına gelen işaretler] tanıtılır. b. İş sağlığı ve güvenliği için temel uyarı işaretlerin bilinmesinin gerekliliği ve önemi vurgulanır."]'::jsonb, '{}'::jsonb, 5, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#6', 'yks-2026-kimya', 'yks-2026-kimya#1', '9.1.4.2', 'Kimyasal maddelerin insan sağlığı ve çevre üzerindeki etkilerini açıklar.', NULL, '["a. Na, K, Fe, Ca, Mg, H2O maddelerinin insan sağlığı ve çevre için önemine değinilir. b. Hg, Pb, CO2, NO2, SO3, CO, Cl2 maddelerinin insan sağlığı ve çevre üzerindeki zararlı etkileri vurgulanır."]'::jsonb, '{}'::jsonb, 6, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#7', 'yks-2026-kimya', 'yks-2026-kimya#1', '9.1.4.3', 'Kimya laboratuvarında kullanılan bazı temel malzemeleri tanır.', NULL, '["Beherglas, erlenmayer, dereceli silindir (mezür), pipet, cam balon, balon joje, büret ve ayırma hunisi gibi laboratuvarda bulunan temel araç gereçler tanıtılır."]'::jsonb, '{}'::jsonb, 7, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#8', 'yks-2026-kimya', 'yks-2026-kimya#2', '9.2.1.1', 'Dalton, Thomson, Rutherford ve Bohr atom modellerini açıklar.', NULL, '["a. Bohr atom modeli, atomların soğurduğu/yaydığı ışınlar ile ilişkilendirilir. Hesaplamalara girilmeden sadece ışın soğurma/yayma üzerinde durulur. b. Bohr atom modelinin sınırlılıkları belirtilerek modern atom teorisinin (bulut modelinin) önemi vurgulanır. Orbital kavramına girilmez. c. Atom modellerinin açıklanmasında bilişim teknolojilerinden (animasyon, simülasyon, video vb.) yararlanılır."]'::jsonb, '{}'::jsonb, 8, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#9', 'yks-2026-kimya', 'yks-2026-kimya#2', '9.2.2.1', 'Elektron, proton ve nötronun yüklerini, kütlelerini ve atomda bulundukları yerleri karşılaştırır.', NULL, '["a. Elektron, proton, nötron, atom numarası, kütle numarası, izotop, izoton, izobar ve izoelektronik kavramları tanıtılır. b. Elektron, proton ve nötronun yük ve kütlelerinin nasıl bulunduğu sürecine ve izotop atomlarda ortalama atom kütlesi hesabına girilmez."]'::jsonb, '{}'::jsonb, 9, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#10', 'yks-2026-kimya', 'yks-2026-kimya#2', '9.2.3.1', 'Elementlerin periyodik sistemdeki yerleşim esaslarını açıklar.', NULL, '["a. Mendeleyev’in periyodik sistem üzerine yaptığı çalışmalar ve Moseley’in katkıları üzerinde durulur. b. Atomların katman-elektron dağılımlarıyla periyodik sistemdeki yerleri arasındaki ilişki açıklanır. İlk 20 element esas olup diğer elementlerin katman elektron dağılımlarına girilmez."]'::jsonb, '{}'::jsonb, 10, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#11', 'yks-2026-kimya', 'yks-2026-kimya#2', '9.2.3.2', 'Elementleri periyodik sistemdeki yerlerine göre sınıflandırır.', NULL, '["Elementlerin sınıflandırılması metal, ametal, yarı metal ve asal (soy) gazlar olarak yapılır."]'::jsonb, '{}'::jsonb, 11, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#12', 'yks-2026-kimya', 'yks-2026-kimya#2', '9.2.3.3', 'Periyodik özelliklerin değişme eğilimlerini açıklar.', NULL, '["a. Periyodik özelliklerden metalik-ametalik, atom yarıçapı, iyonlaşma enerjisi, elektron ilgisi ve elektronegatiflik kavramları açıklanır; bunların nasıl ölçüldüğü konusuna girilmez. b. Kovalent, iyonik, metalik, van der Waals yarıçap tanımlarına girilmez. c. Periyodik özelliklerin açıklanmasında bilişim teknolojilerinden (animasyon, simülasyon, video vb.) yararlanılır."]'::jsonb, '{}'::jsonb, 12, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#13', 'yks-2026-kimya', 'yks-2026-kimya#3', '9.3.1.1', 'Kimyasal türleri açıklar.', NULL, '["Radikal kavramına girilmez."]'::jsonb, '{}'::jsonb, 13, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#14', 'yks-2026-kimya', 'yks-2026-kimya#3', '9.3.2.1', 'Kimyasal türler arasındaki etkileşimleri sınıflandırır.', NULL, '["a. Bağlanan türler arası sınıflandırma, atomlar arası ve moleküller arası şeklinde yapılır; bu sınıflandırmanın getirdiği güçlüklere değinilir. b. Güçlü etkileşimlere örnek olarak iyonik, kovalent ve metalik bağ; zayıf etkileşimlere örnek olarak da hidrojen bağı ve van der Waals kuvvetleri verilir."]'::jsonb, '{}'::jsonb, 14, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#15', 'yks-2026-kimya', 'yks-2026-kimya#3', '9.3.3.1', 'İyonik bağın oluşumunu iyonlar arası etkileşimler ile ilişkilendirir.', NULL, '["a. Nötr atomların ve tek atomlu iyonların Lewis sembolleri verilir. Örnekler periyodik sistemde ilk 20 element arasından seçilir. b. İyonik bileşiklerin yapısal birimleri ile molekül kavramının karıştırılmamasına vurgu yapılır. c. İyonik bağların açıklanmasında bilişim teknolojilerinden (animasyon, simülasyon, video vb.) yararlanılır."]'::jsonb, '{}'::jsonb, 15, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#16', 'yks-2026-kimya', 'yks-2026-kimya#3', '9.3.3.2', 'İyonik bağlı bileşiklerin sistematik adlandırmasını yapar.', NULL, '["a. Tek atomlu ve çok atomlu iyonların (NH4+, OH-, NO3-, SO42-, CO32-, PO43-, CN-, CH3COO-) oluşturduğu bileşiklerin adlandırılması yapılır. b. Değişken değerlikli metallerin (Cu, Fe, Hg, Sn, Pb) oluşturduğu bileşiklerin adlandırılması yapılır. c. Hidrat bileşiklerinin adlandırılmasına girilmez."]'::jsonb, '{}'::jsonb, 16, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#17', 'yks-2026-kimya', 'yks-2026-kimya#3', '9.3.3.3', 'Kovalent bağın oluşumunu atomlar arası elektron ortaklaşması temelinde açıklar.', NULL, '["a. Kovalent bağlar sınıflandırılırken polar ve apolar kovalent bağlar verilir; koordine kovalent bağa girilmez. b. Basit moleküllerin (H2, Cl2, O2, N2, HCl, H2O, BH3, NH3, CH4, CO2) Lewis elektron nokta formülleri üzerinden bağın ve moleküllerin polarlık-apolarlık durumları üzerinde durulur. c. Kovalent bağların açıklanmasında bilişim teknolojilerinden (animasyon, simülasyon, video vb.) yararlanılır."]'::jsonb, '{}'::jsonb, 17, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#18', 'yks-2026-kimya', 'yks-2026-kimya#3', '9.3.3.4', 'Kovalent bağlı bileşiklerin sistematik adlandırmasını yapar.', NULL, '["H2O, HCl, H2SO4, HNO3, NH3 bileşik örneklerinin sistematik adları verilir."]'::jsonb, '{}'::jsonb, 18, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#19', 'yks-2026-kimya', 'yks-2026-kimya#3', '9.3.3.5', 'Metalik bağın oluşumunu açıklar.', NULL, '["Metalik bağın açıklanmasında elektron denizi modeli kullanılır."]'::jsonb, '{}'::jsonb, 19, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#20', 'yks-2026-kimya', 'yks-2026-kimya#3', '9.3.4.1', 'Zayıf ve güçlü etkileşimleri bağ enerjisi esasına göre ayırt eder.', NULL, '[]'::jsonb, '{}'::jsonb, 20, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#21', 'yks-2026-kimya', 'yks-2026-kimya#3', '9.3.4.2', 'Kimyasal türler arasındaki zayıf etkileşimleri sınıflandırır.', NULL, '["a. Van der Waals kuvvetleri (dipol-dipol etkileşimleri, iyon-dipol etkileşimleri, dipol- indüklenmiş dipol etkileşimleri, iyon-indüklenmiş dipol etkileşimleri ve London kuvvetleri) açıklanır. b. Dipol-dipol etkileşimleri, iyon-dipol etkileşimleri ve London kuvvetlerinin genel etkileşme güçleri karşılaştırılır."]'::jsonb, '{}'::jsonb, 21, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#22', 'yks-2026-kimya', 'yks-2026-kimya#3', '9.3.4.3', 'Hidrojen bağları ile maddelerin fiziksel özellikleri arasında ilişki kurar.', NULL, '["a. Hidrojen bağının oluşumu açıklanır. b. Uygun bileşik serilerinin kaynama noktası değişimleri grafik üzerinde, hidrojen bağları ve diğer etkileşimler kullanılarak açıklanır. c. Aziz Sancar’ın DNA’nın onarımı ile ilgili çalışmalarına ve kısa biyografisine okuma parçası olarak yer verilir. Sabırlı, azimli ve kararlı olmanın bilimsel çalışmalarda başarıya ulaşmadaki önemi vurgulanır."]'::jsonb, '{}'::jsonb, 22, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#23', 'yks-2026-kimya', 'yks-2026-kimya#3', '9.3.5.1', 'Fiziksel ve kimyasal değişimi, kopan ve oluşan bağ enerjilerinin büyüklüğü temelinde ayırt eder.', NULL, '["Türler arasında fiziksel ve kimyasal değişimlerin açıklanmasında bilişim teknolojilerinden (animasyon, simülasyon, video vb.) yararlanılır."]'::jsonb, '{}'::jsonb, 23, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#24', 'yks-2026-kimya', 'yks-2026-kimya#4', '9.4.1', 'Maddenin Fiziksel Hâlleri 9.4.1.1.Maddenin farklı hâllerde olmasının canlılar ve çevre için önemini açıklar.', NULL, '["a. Suyun fiziksel hâllerinin (katı, sıvı, gaz) farklı işlevler sağladığı vurgulanır. b. LPG (sıvılaştırılmış petrol gazı), deodorantlardaki itici gazlar, LNG (sıvılaştırılmış doğal gaz), soğutucularda kullanılan gazların davranışları üzerinden hâl değişimlerinin önemi vurgulanır. c. Havadan azot ve oksijen eldesi üzerinde durulur."]'::jsonb, '{}'::jsonb, 24, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#25', 'yks-2026-kimya', 'yks-2026-kimya#4', '9.4.2.1', 'Katıların özellikleri ile bağların gücü arasında ilişki kurar.', NULL, '["Katılar sınıflandırılarak günlük hayatta sıkça karşılaşılan tuz, iyot, elmas ve çinko katılarının taneciklerini bir arada tutan kuvvetler üzerinde durulur."]'::jsonb, '{}'::jsonb, 25, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#26', 'yks-2026-kimya', 'yks-2026-kimya#4', '9.4.3.2', 'Sıvılarda viskoziteyi etkileyen faktörleri açıklar.', NULL, '["a. Viskozitenin moleküller arası etkileşim ile ilişkilendirilmesi sağlanır. b. Farklı sıvıların viskoziteleri sıcaklıkla ilişkilendirilir. c. Farklı sıcaklıklarda su, gliserin ve zeytinyağının viskozite deneyleri yaptırılarak elde edilen sonuçların karşılaştırılması sağlanır."]'::jsonb, '{}'::jsonb, 26, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#27', 'yks-2026-kimya', 'yks-2026-kimya#4', '9.4.3.3', 'Kapalı kaplarda gerçekleşen buharlaşma-yoğuşma süreçleri üzerinden denge buhar basıncı kavramını açıklar.', NULL, '["a. Kaynama olayı dış basınca bağlı olarak açıklanır. b. Faz diyagramlarına girilmeden kaynama ile buharlaşma olayının birbirinden farklı olduğu belirtilir."]'::jsonb, '{}'::jsonb, 27, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#28', 'yks-2026-kimya', 'yks-2026-kimya#4', '9.4.3.4', 'Doğal olayları açıklamada sıvılar ve özellikleri ile ilgili kavramları kullanır.', NULL, '["a. Atmosferdeki su buharının varlığının nem kavramıyla ifade edildiği belirtilir. b. Meteoroloji haberlerinde verilen gerçek ve hissedilen sıcaklık kavramlarının bağıl nem kavramıyla ifade edildiği belirtilir. Bağıl nem hesaplamalarına girilmez."]'::jsonb, '{}'::jsonb, 28, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#29', 'yks-2026-kimya', 'yks-2026-kimya#4', '9.4.4.1', 'Gazların genel özelliklerini açıklar.', NULL, '["Gaz yasaları ve kinetik-moleküler teoriye girilmez."]'::jsonb, '{}'::jsonb, 29, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#30', 'yks-2026-kimya', 'yks-2026-kimya#4', '9.4.4.2', 'Gazların basınç, sıcaklık, hacim ve miktar özelliklerini birimleriyle ifade eder.', NULL, '["Basınç birimleri olarak (atm ve mmHg); hacim birimi olarak litre (L); sıcaklık birimleri olarak Celcius (oC) ve Kelvin (K); miktar birimi olarak da mol verilir. Birim dönüşümlerine ve hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 30, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#31', 'yks-2026-kimya', 'yks-2026-kimya#4', '9.4.4.3', 'Saf maddelerin hâl değişim grafiklerini yorumlar.', NULL, '["a. Hâl değişim grafikleri üzerinden erime-donma, buharlaşma-yoğuşma ve kaynama süreçleri incelenir. b. Gizli erime ve buharlaşma ısılarıyla ısınma-soğuma süreçlerine ilişkin hesaplamalara girilmez. c. Saf suyun hâl değişim deneyi yaptırılarak grafiğinin çizdirilmesi sağlanır."]'::jsonb, '{}'::jsonb, 31, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#32', 'yks-2026-kimya', 'yks-2026-kimya#4', '9.4.5.1', 'Plazma hâlini açıklar.', NULL, '["Sıcak ve soğuk plazma sınıflandırmasına girilmez."]'::jsonb, '{}'::jsonb, 32, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#33', 'yks-2026-kimya', 'yks-2026-kimya#5', '9.5.1.1', 'Suyun varlıklar için önemini açıklar.', NULL, '["Su kaynaklarının ve korunmasının önemi açıklanır."]'::jsonb, '{}'::jsonb, 33, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#34', 'yks-2026-kimya', 'yks-2026-kimya#5', '9.5.1.2', 'Su tasarrufuna ve su kaynaklarının korunmasına yönelik çözüm önerileri geliştirir.', NULL, '["Suyu tasarruflu kullanmanın her vatandaşın ülkesine ve dünyaya karşı sorumluluğu/görevi olduğu vurgulanır."]'::jsonb, '{}'::jsonb, 34, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#35', 'yks-2026-kimya', 'yks-2026-kimya#5', '9.5.1.3', 'Suyun sertlik ve yumuşaklık özelliklerini açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 35, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#36', 'yks-2026-kimya', 'yks-2026-kimya#5', '9.5.2.1', 'Hava, su ve toprak kirliliğine sebep olan kimyasal kirleticileri açıklar.', NULL, '["a. Hava kirleticiler olarak azot oksitler, karbon dioksit ve kükürt oksitleri üzerinde durulur. b. Su ve toprak kirleticiler olarak plastikler, deterjanlar, organik sıvılar, ağır metaller, piller, ve endüstriyel atıklar üzerinde durulur."]'::jsonb, '{}'::jsonb, 36, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#37', 'yks-2026-kimya', 'yks-2026-kimya#5', '9.5.2.2', 'Çevreye zarar veren kimyasal kirleticilerin etkilerinin azaltılması konusunda çözüm önerilerinde bulunur.', NULL, '["a. Atmosferin, canlılar için taşıdığı hayati önem vurgulanarak tüketim maddelerini seçerken ve kullanırken canlılara ve çevreye karşı duyarlı olmanın gerekliliği vurgulanır. b. Öğrencilerin, kimyasal kirleticilerin çevreye zararlarının azaltılması konusunda yapılan araştırmalar, çalışmalar ve sonuçları hakkında bilişim teknolojilerini kullanarak bilgi toplamaları ve sınıfta paylaşmaları sağlanır. Literatür araştırmalarında elde edilen bilgi ve bilgi kaynaklarının geçerliliği ve güvenilirliğinin sorgulanmasının gerekliliği hatırlatılır. c. Çevre temizliği konusunda farkındalık oluşturmak amacıyla öğrencilerin, grup arkadaşlarıyla birlikte kampanya veya etkinlik önerileri geliştirmeleri sağlanır. Görev dağılımı yapmanın ve herkesin üzerine düşen sorumluluğu yerine getirmesinin grup çalışmalarının başarıya ulaşmasındaki önemi hatırlatılır."]'::jsonb, '{}'::jsonb, 37, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#38', 'yks-2026-kimya', 'yks-2026-kimya#6', '10.1.1.1', 'Kimyanın temel kanunlarını açıklar.', NULL, '["a. Kütlenin korunumu, sabit oranlar ve katlı oranlar kanunları ile ilgili hesaplamalar yapılır. b. Demir(II) sülfür bileşiğinin elde edilmesi deneyi yaptırılır."]'::jsonb, '{}'::jsonb, 38, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#39', 'yks-2026-kimya', 'yks-2026-kimya#6', '10.1.2.1', 'Mol kavramını açıklar.', NULL, '["a. Mol kavramının tarihsel süreç içerisindeki değişimi üzerinde durulur. b. Bağıl atom kütlesi tanımlanır. c. İzotop kavramı ve bazı elementlerin mol kütlelerinin tam sayı çıkmayışının nedeni örneklerle açıklanır. ç. Mol hesaplamaları yapılır."]'::jsonb, '{}'::jsonb, 39, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#40', 'yks-2026-kimya', 'yks-2026-kimya#6', '10.1.3.1', 'Kimyasal tepkimeleri açıklar.', NULL, '["a. Kimyasal tepkime denklemlerinin denkleştirilmesi sağlanır. Redoks tepkimelerine girilmez. b. Yanma, sentez (oluşum), analiz (ayrışma), asit-baz, çözünme-çökelme tepkimeleri örneklerle açıklanır. c. Kurşun(II) iyodürün çökmesi deneyi yaptırılır. ç. Kimyasal tepkimelerin açıklanmasında bilişim teknolojilerinden (animasyon, simülasyon, video vb.) yararlanılır."]'::jsonb, '{}'::jsonb, 40, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#41', 'yks-2026-kimya', 'yks-2026-kimya#6', '10.1.4.1', 'Kütle, mol sayısı, molekül sayısı, atom sayısı ve gazlar için normal şartlarda hacim kavramlarını birbirleriyle ilişkilendirerek hesaplamalar yapar.', NULL, '["a. Sınırlayıcı bileşen hesapları üzerinde durulur. b. Tepkime denklemleri temelinde % verim hesapları yapılır."]'::jsonb, '{}'::jsonb, 41, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#42', 'yks-2026-kimya', 'yks-2026-kimya#7', '10.2.1.1', 'Karışımları niteliklerine göre sınıflandırır.', NULL, '["a. Homojen ve heterojen karışımların ayırt edilmesinde belirleyici olan özellikler açıklanır. b. Homojen karışımların çözelti olarak adlandırıldığı vurgulanır ve günlük hayattan çözelti örnekleri verilir. c. Heterojen karışımlar, dağılan maddenin ve dağılma ortamının fiziksel hâline göre sınıflandırılır. ç. Karışımlar çözünenin ve/veya dağılanın tanecik boyutu esas alınarak sınıflandırılır."]'::jsonb, '{}'::jsonb, 42, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#43', 'yks-2026-kimya', 'yks-2026-kimya#7', '10.2.1.2', 'Çözünme sürecini moleküler düzeyde açıklar.', NULL, '["a. Tanecikler arası etkileşimlerden faydalanılarak çözünme açıklanır. b. Çözünme ile polarlık, hidrojen bağı ve çözücü-çözünen benzerliği ilişkilendirilir. c. Farklı maddelerin (sodyum klorür, etil alkol, karbon tetraklorür) suda çözünme deneyleri yaptırılır. ç. Farklı fiziksel hâldeki maddelerin suda çözünme süreçlerinin açıklanmasında bilişim teknolojilerinden (animasyon, simülasyon, video vb.) yararlanılır."]'::jsonb, '{}'::jsonb, 43, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00')
INSERT INTO public.curriculum_outcomes (id, program_id, unit_id, code, text, topic, limitations, quotas, sort_order, source_id, quota_source_id, text_similarity, source_url, program_version, sha256, fetched_at) VALUES
('yks-2026-kimya#44', 'yks-2026-kimya', 'yks-2026-kimya#7', '10.2.1.3', 'Çözünmüş madde oranını belirten ifadeleri yorumlar.', NULL, '["a. Çözünen madde oranının yüksek (derişik) ve düşük (seyreltik) olduğu çözeltilere örnekler verilir. b. Kütlece yüzde, hacimce yüzde ve ppm derişimleri tanıtılır; ppm ile ilgili hesaplamalara girilmez. c. Yaygın sulu çözeltilerde (çeşme suyu, deniz suyu, serum, kolonya, şekerli su) çözünenin kütlece ve/veya hacimce yüzde derişimlerine örnekler verilir. ç. Kütlece yüzde ve hacimce yüzde derişimleri farklı çözeltiler hazırlatılır. d. Günlük tüketim maddelerinin etiketlerindeki derişime ilişkin verilere dikkat çekilir. e. Örnek çözelti hazırlanmasında bilişim teknolojilerinden (animasyon, simülasyon, video vb.) yararlanılır."]'::jsonb, '{}'::jsonb, 44, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#45', 'yks-2026-kimya', 'yks-2026-kimya#7', '10.2.1.4', 'Çözeltilerin özelliklerini günlük hayattan örneklerle açıklar.', NULL, '["a. Çözeltilerin donma ve kaynama noktasının çözücülerinkinden farklı olduğu ve derişime bağlı olarak değişimi açıklanır. Hesaplamalara girilmez. b. Karayollarında ve taşıtlarda buzlanmaya karşı alınan önlemlere değinilir; bu önlemlerin olumlu ve olumsuz etkilerinin tartışılması sağlanır. Sınıf içi tartışmalarda karşısındakini dinlemenin ve görgü kurallarına uygun davranmanın tartışmanın verimliliği üzerindeki etkisi hatırlatılır."]'::jsonb, '{}'::jsonb, 45, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#46', 'yks-2026-kimya', 'yks-2026-kimya#7', '10.2.2.1', 'Endüstri ve sağlık alanlarında kullanılan karışım ayırma tekniklerini açıklar.', NULL, '["a. Mıknatıs ile ayırma bunun yanı sıra tanecik boyutu (eleme, süzme, diyaliz), yoğunluk (ayırma hunisi, yüzdürme), erime noktası, kaynama noktası (basit damıtma, ayrımsal damıtma) ve çözünürlük (özütleme, kristallendirme, ayrımsal kristallendirme) farkından yararlanılarak uygulanan ayırma teknikleri üzerinde durulur. b. Karışımları ayırma deneyleri yaptırılır."]'::jsonb, '{}'::jsonb, 46, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#47', 'yks-2026-kimya', 'yks-2026-kimya#8', '10.3.1.1', 'Asitleri ve bazları bilinen özellikleri yardımıyla ayırt eder.', NULL, '["a. Limon suyu, sirke gibi maddelerin ekşilik ve aşındırma özellikleri, asitlikleriyle ilişkilendirilir. b. Kirecin, sabunun ve deterjanların ciltte oluşturduğu kayganlık hissi baziklikle ilişkilendirilir. c. Asitler ve bazların bazı renkli maddelerin (çay, üzüm suyu, kırmızı lahana) rengini değiştirmesi deneyleri yapılarak indikatör kavramı ve pH kâğıdı tanıtılır. ç. Sirke, limon suyu, çamaşır suyu, sodyum hidroksit, hidroklorik asit ve sodyum klorür çözeltilerinin asitlik veya bazlık değerlerinin pH kâğıdı kullanılarak yorumlanması sağlanır. d. pH kavramı asitlik ve bazlık ile ilişkilendirilerek açıklanır. Logaritmik tanıma girilmez. e. Günlük hayatta kullanılan tüketim maddelerinin ambalajlarında yer alan pH değerlerinin asitlik- bazlıkla ilişkilendirilmesi sağlanır."]'::jsonb, '{}'::jsonb, 47, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#48', 'yks-2026-kimya', 'yks-2026-kimya#8', '10.3.1.2', 'Maddelerin asitlik ve bazlık özelliklerini moleküler düzeyde açıklar.', NULL, '["a. Asitler su ortamında H3O+ iyonu oluşturma, bazlar ise OH- iyonu oluşturma özellikleriyle tanıtılarak basit örnekler verilir. b. Su ile etkileşerek asit/baz oluşturan CO2 , SO2 ve N2O5 maddelerinin çözeltilerinin neden asit gibi davrandığı; NH3 ve CaO maddelerinin çözeltilerinin de neden baz gibi davrandığı bu tepkimeler üzerinden açıklanır. Lewis asit-baz tanımına girilmez."]'::jsonb, '{}'::jsonb, 48, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#49', 'yks-2026-kimya', 'yks-2026-kimya#8', '10.3.2.1', 'Asitler ve bazlar arasındaki tepkimeleri açıklar.', NULL, '["a. Nötralleşme tepkimeleri, asidin ve bazın mol sayıları üzerinden açıklanır. b. Sodyum hidroksit ile sülfürik asidin etkileşiminden sodyum sülfat oluşumu deneyi yaptırılarak asit, baz ve tuz kavramları ilişkilendirilir."]'::jsonb, '{}'::jsonb, 49, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#50', 'yks-2026-kimya', 'yks-2026-kimya#8', '10.3.2.2', 'Asitlerin ve bazların günlük hayat açısından önemli tepkimelerini açıklar.', NULL, '["a. Asitlerin ve bazların metallerle etkileşerek hidrojen gazı oluşturması reaksiyonlarına örnekler verilir; aktif metal, yarı soy metal, soy metal ve amfoter metal kavramları üzerinde durulur. b. Alüminyum metalinin amfoterlik özelliğini gösteren deney yaptırılır. c. Nitrik asit, sülfürik asit ve hidroflorik asidin soy metal ve cam/porselen aşındırma özelliklerine değinilir. Tepkime denklemlerine girilmez. ç. Derişik sülfürik asit, fosforik asit ve asetik asidin nem çekme ve çözünürken ısı açığa çıkarma özellikleri nedeniyle yol açtıkları tehlikeler vurgulanır."]'::jsonb, '{}'::jsonb, 50, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#51', 'yks-2026-kimya', 'yks-2026-kimya#8', '10.3.3.1', 'Asitlerin ve bazların fayda ve zararlarını açıklar.', NULL, '["a. Asit yağmurlarının oluşumuna, çevreye ve tarihi eserlere etkilerine değinilir. b. Kirecin ve kostiğin yağ, saç ve deriye etkisi deney yapılarak açıklanır. c. Öğrencilerin asit ve bazların fayda ve zararları hakkında bilişim teknolojileri kullanarak araştırma yapmaları, elde ettikleri bilgileri kaynak belirterek özetlemeleri ve yazılı olarak sunmaları sağlanır. Bilişim teknolojilerini kullanırken siber güvenlik kurallarına uymanın gerekliliği hatırlatılır."]'::jsonb, '{}'::jsonb, 51, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#52', 'yks-2026-kimya', 'yks-2026-kimya#8', '10.3.3.2', 'Asit ve bazlarla çalışırken alınması gereken sağlık ve güvenlik önlemlerini açıklar.', NULL, '["a. Birbiriyle karıştırılması sakıncalı evsel kimyasallara (çamaşır suyu ile tuz ruhu) örnekler verilir. b. Asit ve baz ambalajlarındaki güvenlik uyarılarına dikkat çekilir. c. Aşırı temizlik malzemesi ve lavabo açıcı kullanmanın sağlık, çevre ve tesisat açısından sakıncaları üzerinde durulur. ç. Mutfak gereçlerinde oluşan kireçlenmeyi ve metal eşyaların paslarını gidermek için yöntem ve malzeme seçiminde dikkat edilmesi gereken hususlar üzerinde durulur."]'::jsonb, '{}'::jsonb, 52, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#53', 'yks-2026-kimya', 'yks-2026-kimya#8', '10.3.4.1', 'Tuzların özelliklerini ve kullanım alanlarını açıklar.', NULL, '["Sodyum klorür, sodyum karbonat, sodyum bikarbonat, kalsiyum karbonat ve amonyum klorür tuzları üzerinde durulur."]'::jsonb, '{}'::jsonb, 53, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#54', 'yks-2026-kimya', 'yks-2026-kimya#9', '10.4.1.1', 'Temizlik maddelerinin özelliklerini açıklar.', NULL, '["a. Yapısal ayrıntılara girmeden sabun ve deterjan aktif maddelerinin kirleri nasıl temizlediği belirtilir. b. Kişisel temizlikte kullanılan temizlik maddelerinin (şampuan, diş macunu, katı sabun, sıvı sabun) fayda ve zararları vurgulanır. c. Hijyen amacıyla kullanılan temizlik maddeleri (çamaşır suyu, kireç kaymağı) tanıtılır."]'::jsonb, '{}'::jsonb, 54, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#55', 'yks-2026-kimya', 'yks-2026-kimya#9', '10.4.1.2', 'Yaygın polimerlerin kullanım alanlarına örnekler verir.', NULL, '["a. Polimerleşme olayı açıklanarak -mer, monomer ve polimer kavramları üzerinde durulur. b. Kauçuk, polietilen (PE), polietilen teraftalat (PET), kevlar, polivinil klorür (PVC), politetraflor eten (TEFLON) ve polistirenin (PS) yapısal ayrıntılarına girilmeden başlıca kullanım alanlarına değinilir. c. Polimerlerin farklı alanlarda kullanımlarına ilişkin olumlu ve olumsuz özellikleri vurgulanır. ç. İçerisinde polimer malzeme kullanılan oyuncak ve tekstil ürünlerinin zararlarına değinilir."]'::jsonb, '{}'::jsonb, 55, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#56', 'yks-2026-kimya', 'yks-2026-kimya#9', '10.4.1.3', 'Polimer, kâğıt, cam ve metal malzemelerin geri dönüşümünün ülke ekonomisine katkısını açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 56, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#57', 'yks-2026-kimya', 'yks-2026-kimya#9', '10.4.1.4', 'Kozmetik malzemelerin içerebileceği zararlı kimyasalları açıklar.', NULL, '["Kişisel bakım ve estetik amacıyla kullanılan parfüm, saç boyası, kalıcı dövme boyası ve jöle üzerinde durulur."]'::jsonb, '{}'::jsonb, 57, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#58', 'yks-2026-kimya', 'yks-2026-kimya#9', '10.4.1.5', 'İlaçların farklı formlarda kullanılmasının nedenlerini açıklar.', NULL, '["a. Piyasadaki ilaç formlarının (hap, şurup, iğne, merhem) temel özelliklerine değinilir. b. Yanlış ve gereksiz ilaç kullanımının insan sağlığına, ülke ekonomisine ve çevreye verdiği zararlar vurgulanır."]'::jsonb, '{}'::jsonb, 58, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#59', 'yks-2026-kimya', 'yks-2026-kimya#9', '10.4.2.1', 'Hazır gıdaları seçerken ve tüketirken dikkat edilmesi gereken hususları açıklar.', NULL, '["a. Hazır gıdaların doğal gıdalardan başlıca farklarına (koruyucular, renklendiriciler, emülsiyonlaştırıcılar, tatlandırıcılar, pastörizasyon, UHT sütün işlenmesi) değinilir. b. Hazır gıda etiketlerindeki üretim ve son kullanım tarihlerinin önemi vurgulanır. c. Koruyucular, renklendiriciler ve yapay tatlandırıcıların kullanılmasının sağlık üzerindeki etkilerine değinilir. ç. Günlük tüketim maddelerindeki katkı maddesi içeriği ve katkı maddesi kodlarına ilişkin okuma parçası verilir."]'::jsonb, '{}'::jsonb, 59, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#60', 'yks-2026-kimya', 'yks-2026-kimya#9', '10.4.2.2', 'Yenilebilir yağ türlerini sınıflandırır.', NULL, '["a. Yağ türlerinden katı (tereyağı, margarin) ve sıvı (zeytin yağı, ayçiçek yağı, mısır özü yağı, fındık yağı) yağlara değinilir. b. Yağ endüstrisinde kullanılan sızma, rafine, riviera ve vinterize kavramları açıklanır. c. Yenilebilir yağların yanlış kullanımının sağlık üzerindeki etkileri vurgulanır."]'::jsonb, '{}'::jsonb, 60, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#61', 'yks-2026-kimya', 'yks-2026-kimya#10', '11.1.1.1', 'Atomu kuantum modeliyle açıklar.', NULL, '["a. Bohr atom modelinin deney ve gözlemlerden elde edilen bulguları açıklamadaki sınırlılıkları vurgulanarak modern atom teorisinin (bulut modelinin) önemi üzerinde durulur. b. Tek elektronlu atomlar/iyonlar için orbital kavramı elektronların bulunma olasılığı ile ilişkilendirilir. c. Yörünge ve orbital kavramları karşılaştırılır. ç. Kuantum sayıları orbitallerle ilişkilendirilir. d. Çok elektronlu atomlarda orbitallerin enerji seviyeleri açıklanır."]'::jsonb, '{}'::jsonb, 61, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#62', 'yks-2026-kimya', 'yks-2026-kimya#10', '11.1.2.1', 'Nötr atomların elektron dizilimleriyle periyodik sistemdeki yerleri arasında ilişki kurar.', NULL, '["a. Hund Kuralı, Pauli İlkesi ve Aufbau Prensibi açıklanır. b. Atomların ve iyonların elektron dizilimlerine örnekler verilir. Atom numarası 36 ve daha küçük türlerin elektron dizilimleri esas alınır. c. Değerlik orbital ve değerlik elektronu kavramları açıklanır. ç. Elektron dizilimleriyle elementin ait olduğu blok ilişkilendirilerek grup ve periyot belirlenir."]'::jsonb, '{}'::jsonb, 62, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#63', 'yks-2026-kimya', 'yks-2026-kimya#10', '11.1.3.1', 'Periyodik özelliklerdeki değişim eğilimlerini sebepleriyle açıklar.', NULL, '["a. Kovalent yarıçap, van der Waals yarıçapı ve iyonik yarıçapın farkları üzerinde durulur. b. Periyodik özellikler arasında metallik/ametallik, atom/iyon yarıçapı, iyonlaşma enerjisi, elektron ilgisi, elektronegatiflik ve oksit/hidroksit bileşiklerinin asitlik/bazlık eğilimleri üzerinde durulur. Periyodik özelliklerin nasıl ölçüldüğüne girilmez. c. Ardışık iyonlaşma enerjilerinin grup numarasıyla ilişkisi örneklerle gösterilir."]'::jsonb, '{}'::jsonb, 63, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#64', 'yks-2026-kimya', 'yks-2026-kimya#10', '11.1.4.1', 'Elementlerin periyodik sistemdeki konumu ile özellikleri arasındaki ilişkileri açıklar.', NULL, '["a. s, p, d bloku elementlerinin metal/ametal karakteri, iyon yükleri, aktiflikleri ve yaptıkları kimyasal bağ tipi elektron dizilimiyle ilişkilendirilir. b. f blok elementlerinin periyodik sistemdeki konumlarıyla ilgili özel durumları vurgulanır. c. Asal gaz özellikleri elektron dizilimleriyle ilişkilendirilir."]'::jsonb, '{}'::jsonb, 64, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#65', 'yks-2026-kimya', 'yks-2026-kimya#10', '11.1.5.1', 'Yükseltgenme basamakları ile elektron dizilimleri arasındaki ilişkiyi açıklar.', NULL, '["a. Ametallerin anyon hâlindeki yükleriyle yükseltgenme basamakları arasındaki fark örneklendirilir. b. d bloku elementlerinin birden çok yükseltgenme basamağında bulunabilmeleri, elektron dizilimleriyle ilişkilendirilir."]'::jsonb, '{}'::jsonb, 65, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#66', 'yks-2026-kimya', 'yks-2026-kimya#11', '11.2.1.1', 'Gazların betimlenmesinde kullanılan özellikleri açıklar.', NULL, '["a. Basınç birimleri (atm, Torr, mmHg ) ve hacim birimleri (L, m³) ile bunların ondalık ast ve üst katları kısaca açıklanır. b. Gazların özelliklerinin ölçme yöntemleri üzerinde durulur. Manometrelerle ilgili hesaplamalara girilmez."]'::jsonb, '{}'::jsonb, 66, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#67', 'yks-2026-kimya', 'yks-2026-kimya#11', '11.2.1.2', 'Gaz yasalarını açıklar.', NULL, '["a. Gazların özelliklerine ilişkin yasalar (Boyle, Charles, Gay Lussac ve Avogadro) üzerinde durulur. b. Öğrencilerin hazır veriler kullanılarak gaz yasaları ile ilgili grafikler çizmeleri ve yorumlamaları sağlanır."]'::jsonb, '{}'::jsonb, 67, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#68', 'yks-2026-kimya', 'yks-2026-kimya#11', '11.2.2.1', 'Deneysel yoldan türetilmiş gaz yasaları ile ideal gaz yasası arasındaki ilişkiyi açıklar.', NULL, '["a. Boyle, Charles ve Avogadro yasalarından yola çıkılarak ideal gaz denklemi türetilir. b. İdeal gaz denklemi kullanılarak örnek hesaplamalar yapılır. c. Normal şartlarda gaz hacimleri kütle ve mol sayısıyla ilişkilendirilir."]'::jsonb, '{}'::jsonb, 68, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#69', 'yks-2026-kimya', 'yks-2026-kimya#11', '11.2.3.1', 'Gaz davranışlarını kinetik teori ile açıklar.', NULL, '["a. Kinetik teorinin temel varsayımları üzerinde durulur. b. Kinetik teorinin temel varsayımları kullanılarak Graham Difüzyon ve Efüzyon Yasası türetilir. c. Difüzyon deneyi yaptırılır; bilişim teknolojilerinden (animasyon, simülasyon, video vb.) yararlanılarak da açıklanır. Deney yapılırken güvenlik uyarılarına dikkat edilmesi gerektiği hatırlatılır."]'::jsonb, '{}'::jsonb, 69, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#70', 'yks-2026-kimya', 'yks-2026-kimya#11', '11.2.4.1', 'Gaz karışımlarının kısmi basınçlarını günlük hayattan örneklerle açıklar.', NULL, '["Sıvıların doygun buhar basınçları kısmi basınç kavramıyla ilişkilendirilerek su üzerinde toplanan gazlarla ilgili hesaplamalar yapılır."]'::jsonb, '{}'::jsonb, 70, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#71', 'yks-2026-kimya', 'yks-2026-kimya#11', '11.2.5.1', 'Gazların sıkışma/genleşme sürecinde gerçek gaz ve ideal gaz kavramlarını karşılaştırır.', NULL, '["a. Gerçek gazların hangi durumlarda ideallikten saptığı belirtilir. b. Karbon dioksitin ve suyun faz diyagramı açıklanarak buhar ve gaz kavramları arasındaki fark vurgulanır. c. Suyun farklı kristal yapılarını gösteren faz diyagramlarına girilmez. ç. Günlük hayatta yaygın kullanılan ve gerçek gazların hâl değişimlerinin uygulamaları olan soğutma sistemleri (Joule-Thomson olayı) örnekleriyle açıklanır."]'::jsonb, '{}'::jsonb, 71, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#72', 'yks-2026-kimya', 'yks-2026-kimya#12', '11.3.1.1', 'Kimyasal türler arası etkileşimleri kullanarak sıvı ortamda çözünme olayını açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 72, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#73', 'yks-2026-kimya', 'yks-2026-kimya#12', '11.3.2.1', 'Çözünen madde miktarı ile farklı derişim birimlerini ilişkilendirir.', NULL, '["a. Derişim birimleri olarak molarite ve molalite tanıtılır. b. Normalite ve formalite tanımlarına girilmez."]'::jsonb, '{}'::jsonb, 73, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#74', 'yks-2026-kimya', 'yks-2026-kimya#12', '11.3.2.2', 'Farklı derişimlerde çözeltiler hazırlar.', NULL, '["Derişimle ilgili hesaplamalar yapılarak hesaplamalarda molarite ve molalite yanında kütlece yüzde, hacimce yüzde, mol kesri ve ppm kavramları da kullanılır."]'::jsonb, '{}'::jsonb, 74, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#75', 'yks-2026-kimya', 'yks-2026-kimya#12', '11.3.3.1', 'Çözeltilerin koligatif özellikleri ile derişimleri arasında ilişki kurar.', NULL, '["a. Koligatif özelliklerden buhar basıncı alçalması, donma noktası alçalması (kriyoskopi), kaynama noktası yükselmesi (ebülyoskopi) ve osmotik basınç üzerinde durulur. b. Osmotik basınç ile ilgili hesaplamalara girilmez. c. Ters osmoz yöntemiyle su arıtımı hakkında kısaca bilgi verilir. ç. Saf suyun ve farklı derişimlerdeki sulu çözeltilerin kaynama noktası tayini deneyleri yaptırılır."]'::jsonb, '{}'::jsonb, 75, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#76', 'yks-2026-kimya', 'yks-2026-kimya#12', '11.3.4.1', 'Çözeltileri çözünürlük kavramı temelinde sınıflandırır.', NULL, '["a. Seyreltik, derişik, doygun, aşırı doygun ve doymamış çözelti kavramları üzerinde durulur. b. Çözünürlükler g/100 g su birimi cinsinden verilir. c. Çözünürlükle ilgili hesaplamalar yapılır."]'::jsonb, '{}'::jsonb, 76, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#77', 'yks-2026-kimya', 'yks-2026-kimya#12', '11.3.5.1', 'Çözünürlüğün sıcaklık ve basınçla ilişkisini açıklar.', NULL, '["a. Farklı tuzların sıcaklığa bağlı çözünürlük eğrilerinin yorumlanması sağlanır. b. Tuzların farklı sıcaklıklardaki çözünürlüklerinden faydalanılarak deriştirme ve kristallendirme ile ilgili hesaplamalar yapılır. c. Gazların çözünürlüklerinin basınç ve sıcaklıkla değişimi üzerinde durulur; çözünürlük eğrilerinin yorumlanması sağlanır. ç. Öğrencilerin çözünürlüğün sıcaklık ve basınçla ilişkisini elektronik tablolama programı kullanarak kurgulamaları, değerleri değiştirerek gerçekleşen değişiklikleri gözlemlemeleri ve yorumlamaları sağlanır."]'::jsonb, '{}'::jsonb, 77, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#78', 'yks-2026-kimya', 'yks-2026-kimya#13', '11.4.1.1', 'Tepkimelerde meydana gelen enerji değişimlerini açıklar.', NULL, '["a. Tepkimelerin ekzotermik ve endotermik olması ısı alışverişiyle ilişkilendirilir. b. Ekzotermik ve endotermik tepkimelerin açıklanmasında bilişim teknolojilerinden (animasyon, simülasyon, video vb.) yararlanılır."]'::jsonb, '{}'::jsonb, 78, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#79', 'yks-2026-kimya', 'yks-2026-kimya#13', '11.4.2.1', 'Standart oluşum entalpileri üzerinden tepkime entalpilerini hesaplar.', NULL, '["a. Standart oluşum entalpileri tanımlanır. b. Tepkime entalpisi potansiyel enerji-tepkime koordinatı grafiği üzerinden açıklanır. c. Öğrencilerin tepkime entalpilerine ilişkin elektronik tablolama programı kullanarak grafik oluşturmaları, yorumlamaları sağlanır. değerleri değiştirerek gerçekleşen değişimleri gözlemlemeleri ve"]'::jsonb, '{}'::jsonb, 79, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#80', 'yks-2026-kimya', 'yks-2026-kimya#13', '11.4.3.1', 'Bağ enerjileri ile tepkime entalpisi arasındaki ilişkiyi açıklar.', NULL, '["Oluşan ve kırılan bağ enerjileri üzerinden tepkime entalpisi hesaplamaları yapılır."]'::jsonb, '{}'::jsonb, 80, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#81', 'yks-2026-kimya', 'yks-2026-kimya#13', '11.4.4.1', 'Hess Yasasını açıklar.', NULL, '["Hess Yasası ile ilgili hesaplamalar yapılır."]'::jsonb, '{}'::jsonb, 81, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#82', 'yks-2026-kimya', 'yks-2026-kimya#14', '11.5.1.1', 'Kimyasal tepkimeler ile tanecik çarpışmaları arasındaki ilişkiyi açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 82, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#83', 'yks-2026-kimya', 'yks-2026-kimya#14', '11.5.1.2', 'Kimyasal tepkimelerin hızlarını açıklar.', NULL, '["a. Madde miktarı (derişim, mol, kütle, gaz maddeler için normal şartlarda hacim) ile tepkime hızı ilişkilendirilir. b. Ortalama tepkime hızı kavramı açıklanır. c. Homojen ve heterojen faz tepkimelerine örnekler verilir."]'::jsonb, '{}'::jsonb, 83, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#84', 'yks-2026-kimya', 'yks-2026-kimya#14', '11.5.2.1', 'Tepkime hızına etki eden faktörleri açıklar.', NULL, '["a. Tek basamaklı tepkimelerde, her iki yöndeki tepkime hızının derişime bağlı ifadeleri verilir. b. Çok basamaklı tepkimeler için hız belirleyici basamağın üzerinde durulur. c. Madde cinsi, derişim, sıcaklık, katalizör (enzimlere girilmez) ve temas yüzeyinin tepkime hızına etkisi üzerinde durulur. Arrhenius bağıntısına girilmez. ç. Oktay Sinanoğlu’nun kısa biyografisini ve tepkime mekanizmaları üzerine yaptığı çalışmaları tanıtan okuma parçasına yer verilir."]'::jsonb, '{}'::jsonb, 84, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#85', 'yks-2026-kimya', 'yks-2026-kimya#15', '11.6.1.1', 'Fiziksel ve kimyasal değişimlerde dengeyi açıklar.', NULL, '["a. Maksimum düzensizlik ve minimum enerji eğilimleri üzerinden denge açıklanır. b. İleri ve geri tepkime hızları üzerinden denge açıklanır. c. Tersinir reaksiyonlar için derişim ve basınç cinsinden denge ifadeleri türetilerek hesaplamalar yapılır. ç. Farklı denge sabitleri arasındaki ilişki incelenir."]'::jsonb, '{}'::jsonb, 85, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#86', 'yks-2026-kimya', 'yks-2026-kimya#15', '11.6.2.1', 'Dengeyi etkileyen faktörleri açıklar.', NULL, '["a. Sıcaklığın, derişimin, hacmin, kısmi basınçların ve toplam basıncın dengeye etkisi denge ifadesi üzerinden açıklanır. b. Le Chatelier İlkesi örnekler üzerinden irdelenir. c. Katalizör-denge ilişkisi vurgulanır."]'::jsonb, '{}'::jsonb, 86, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#87', 'yks-2026-kimya', 'yks-2026-kimya#15', '11.6.3.1', 'pH ve pOH kavramlarını suyun oto-iyonizasyonu üzerinden açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 87, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#88', 'yks-2026-kimya', 'yks-2026-kimya#15', '11.6.3.2', 'Brönsted-Lowry asitlerini/bazlarını karşılaştırır.', NULL, '[]'::jsonb, '{}'::jsonb, 88, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#89', 'yks-2026-kimya', 'yks-2026-kimya#15', '11.6.3.3', 'Katyonların asitliğini ve anyonların bazlığını su ile etkileşimleri temelinde açıklar.', NULL, '["a. Kuvvetli/zayıf asitler ve bazlar tanıtılır; konjuge asit-baz çiftlerine örnekler verilir. b. Asit gibi davranan katyonların ve baz gibi davranan anyonların su ile etkileşimleri üzerinde durulur."]'::jsonb, '{}'::jsonb, 89, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#90', 'yks-2026-kimya', 'yks-2026-kimya#15', '11.6.3.4', 'Asitlik/bazlık gücü ile ayrışma denge sabitleri arasında ilişki kurar.', NULL, '["Asitlerin/bazların iyonlaşma oranlarının denge sabitleriyle ilişkilendirilmesi sağlanır."]'::jsonb, '{}'::jsonb, 90, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#91', 'yks-2026-kimya', 'yks-2026-kimya#15', '11.6.3.5', 'Kuvvetli ve zayıf monoprotik asit/baz çözeltilerinin pH değerlerini hesaplar.', NULL, '["a. Çok derişik ve çok seyreltik asit/baz çözeltilerinin pH değerlerine girilmez. b. Zayıf asitler/bazlar için [H+] = (Ka.Ca)1/2 ve [OH-] = (Kb.Cb)1/2 eşitlikleri esas alınır. c. Poliprotik asitlere girilmez."]'::jsonb, '{}'::jsonb, 91, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#92', 'yks-2026-kimya', 'yks-2026-kimya#15', '11.6.3.6', 'Tampon çözeltilerin özellikleri ile günlük kullanım alanlarını ilişkilendirir.', NULL, '["a. Tampon çözeltilerin pH değerlerinin seyrelme ve asit/baz ilavesi ile fazla değişmemesi ortamdaki dengeler üzerinden açıklanır. Henderson formülü ve tampon kapasitesine girilmez. b. Tampon çözeltilerin canlı organizmalar açısından önemine değinilir."]'::jsonb, '{}'::jsonb, 92, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#93', 'yks-2026-kimya', 'yks-2026-kimya#15', '11.6.3.7', 'Tuz çözeltilerinin asitlik/bazlık özelliklerini açıklar.', NULL, '["a. Asidik, bazik ve nötr tuz kavramları açıklanır. b. Anyonu zayıf baz olan tuzlara örnekler verilir. c. Katyonu NH4+ veya anyonu HSO4– olan tuzların asitliği üzerinde durulur. ç. Hidroliz hesaplamalarına girilmez."]'::jsonb, '{}'::jsonb, 93, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#94', 'yks-2026-kimya', 'yks-2026-kimya#15', '11.6.3.8', 'Kuvvetli asit/baz derişimlerini titrasyon yöntemiyle belirler.', NULL, '["a. Titrasyon deneyi yaptırılıp sonuçların grafik üzerinden gösterilerek yorumlanması sağlanır. b. Titrasyonla ilgili hesaplama örnekleri verilir. c. Öğrencilerin titrasyon yöntemine yönelik hesaplamaları elektronik tablolama programı yardımıyla kurgulamaları, değerleri değiştirerek gerçekleşen değişiklikleri gözlemlemeleri ve yorumlamaları sağlanır."]'::jsonb, '{}'::jsonb, 94, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#95', 'yks-2026-kimya', 'yks-2026-kimya#15', '11.6.3.9', 'Sulu ortamlarda çözünme-çökelme dengelerini açıklar.', NULL, '["a. Çözünme-çökelme denge örneklerine yer verilir; çözünürlük çarpımı (Kçç ) ve çözünürlük (s) kavramları ilişkilendirilir. b. Tuzların çözünürlüğüne etki eden faktörlerden, sıcaklık ve ortak iyon etkisi üzerinde durulur. c. Ortak iyon etkisi hesaplamaları yapılır."]'::jsonb, '{}'::jsonb, 95, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#96', 'yks-2026-kimya', 'yks-2026-kimya#16', '12.1.1.1', 'Redoks tepkimelerini tanır.', NULL, '["a. Yükseltgenme ve indirgenme kavramları üzerinde durulur. b. Redoks tepkimeleri denkleştirilerek yaygın yükseltgenler (O2, KMnO4, H2SO4, HNO3, H2O2) ve indirgenler (H2, SO2) tanıtılır. c. İyonik redoks tepkimelerinin denkleştirilmesine girilmez."]'::jsonb, '{}'::jsonb, 96, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#97', 'yks-2026-kimya', 'yks-2026-kimya#16', '12.1.1.2', 'Redoks tepkimeleriyle elektrik enerjisi arasındaki ilişkiyi açıklar.', NULL, '["a. İndirgen-yükseltgen arasındaki elektron alışverişinin doğrudan temas dışında bir yolla mümkün olup olmayacağının üzerinde durulur. b. Elektrik enerjisi ile redoks tepkimesinin istemlilik/istemsizlik durumu ilişkilendirilir."]'::jsonb, '{}'::jsonb, 97, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#98', 'yks-2026-kimya', 'yks-2026-kimya#16', '12.1.2.1', 'Elektrot ve elektrokimyasal hücre kavramlarını açıklar.', NULL, '["a. Katot ve anot kavramları, indirgenme-yükseltgenme ile ilişkilendirilerek ele alınır. b. Elektrot, yarı-hücre ve hücre kavramları üzerinde durulur. c. İnert elektrotların hangi durumlarda gerekli olduğu belirtilir. ç. Pillerde tuz köprüsünün işlevi açıklanır. d. Zn/Cu elektrokimyasal pili deneyi yaptırılır; bilişim teknolojilerinden (animasyon, simülasyon, video vb.) yararlanılarak da açıklanır."]'::jsonb, '{}'::jsonb, 98, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#99', 'yks-2026-kimya', 'yks-2026-kimya#16', '12.1.3.1', 'Redoks tepkimelerinin istemliliğini standart elektrot potansiyellerini kullanarak açıklar.', NULL, '["a. Standart yarı hücre indirgenme potansiyelleri, standart hidrojen yarı hücresi ile ilişkilendirilir. b. Metallerin aktiflik sırası üzerinde durulur. c. İki ayrı yarı hücre arasındaki istemli redoks tepkimesinin, standart indirgenme potansiyelleri ile ilişkilendirilmesi sağlanır. ç. Standart olmayan koşullarda elektrot potansiyellerinin hesaplanmasına yönelik çalışmalara yer verilir."]'::jsonb, '{}'::jsonb, 99, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#100', 'yks-2026-kimya', 'yks-2026-kimya#16', '12.1.4.1', 'Standart koşullarda galvanik pillerin voltajını ve kullanım ömrünü örnekler vererek açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 100, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#101', 'yks-2026-kimya', 'yks-2026-kimya#16', '12.1.4.2', 'Lityum iyon pillerinin önemini kullanım alanlarıyla ilişkilendirerek açıklar.', NULL, '["Öğrencilerin lityum iyon pilleri ve güncel kullanım alanlarını açıklayan bir poster hazırlamaları ve sınıfta sunmaları sağlanır."]'::jsonb, '{}'::jsonb, 101, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#102', 'yks-2026-kimya', 'yks-2026-kimya#16', '12.1.5.1', 'Elektroliz olayını elektrik akımı, zaman ve değişime uğrayan madde kütlesi açısından açıklar.', NULL, '["a. 1 mol elektronun toplam yükü üzerinden elektrik yükü-kütle ilişkisi kurulması sağlanır. b. Yük birimi Coulomb (C) tanımlanır. c. Faraday bağıntısı açıklanarak bu bağıntının kullanıldığı hesaplamalar yapılır. ç. Öğrencilerin Faraday bağıntısını elektronik tablolama programı kullanarak kurgulamaları, değerleri değiştirerek gerçekleşen değişiklikleri gözlemlemeleri ve yorumlamaları sağlanır. d. Kaplama deneyi yaptırılır."]'::jsonb, '{}'::jsonb, 102, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#103', 'yks-2026-kimya', 'yks-2026-kimya#16', '12.1.5.2', 'Kimyasal maddelerin elektroliz yöntemiyle elde ediliş sürecini açıklar.', NULL, '["Suyun elektrolizi ile hidrojen ve oksijen eldesi deneyi yaptırılır."]'::jsonb, '{}'::jsonb, 103, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#104', 'yks-2026-kimya', 'yks-2026-kimya#16', '12.1.6.1', 'Korozyon önleme yöntemlerinin elektrokimyasal temellerini açıklar.', NULL, '["a. Korozyon kavramı açıklanır. b. Korozyondan koruma süreci metallerin aktiflik sırası ile ilişkilendirilir; kurban elektrot kavramı üzerinde durulur. c. Kurban elektrotun kullanım alanlarına örnekler verilir."]'::jsonb, '{}'::jsonb, 104, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#105', 'yks-2026-kimya', 'yks-2026-kimya#17', '12.2.1.1', 'Anorganik ve organik bileşikleri ayırt eder.', NULL, '["a. Organik bileşik kavramının tarihsel gelişimi açıklanır. b. Anorganik ve organik bileşiklerin özellikleri vurgulanır."]'::jsonb, '{}'::jsonb, 105, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#106', 'yks-2026-kimya', 'yks-2026-kimya#17', '12.2.2.1', 'Organik bileşiklerin basit ve molekül formüllerinin bulunması ile ilgili hesaplamalar yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 106, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#107', 'yks-2026-kimya', 'yks-2026-kimya#17', '12.2.3.1', 'Karbon allotroplarının özelliklerini yapılarıyla ilişkilendirir.', NULL, '["a. Karbon elementinin çok sayıda bileşik oluşturma özelliği ile bağ yapma özelliği arasında ilişki kurulur. b. Elmas ve grafitin incelenmesi sağlanarak fulleren, nanotüp ve grafenin yapıları ve önemleri üzerinde durulur."]'::jsonb, '{}'::jsonb, 107, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#108', 'yks-2026-kimya', 'yks-2026-kimya#17', '12.2.4.1', 'Kovalent bağlı kimyasal türlerin Lewis formüllerini yazar.', NULL, '["Oktetin aşıldığı moleküller kapsam dışıdır."]'::jsonb, '{}'::jsonb, 108, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#109', 'yks-2026-kimya', 'yks-2026-kimya#17', '12.2.5.1', 'Tek, çift ve üçlü bağların oluşumunu hibrit ve atom orbitalleri temelinde açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 109, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#110', 'yks-2026-kimya', 'yks-2026-kimya#17', '12.2.5.2', 'Moleküllerin geometrilerini merkez atomu orbitallerinin hibritleşmesi esasına göre belirler.', NULL, '["a. Hibritleşme ve VSEPR (Değerlik Katmanı Elektron Çifti İtmesi) yaklaşımı üzerinde durulur."]'::jsonb, '{}'::jsonb, 110, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#111', 'yks-2026-kimya', 'yks-2026-kimya#18', '12.3.1.1', 'Hidrokarbon türlerini ayırt eder.', NULL, '[]'::jsonb, '{}'::jsonb, 111, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#112', 'yks-2026-kimya', 'yks-2026-kimya#18', '12.3.1.2', 'Basit alkanların adlarını, formüllerini, özelliklerini ve kullanım alanlarını açıklar.', NULL, '["a. Yanma ve halojenlerle yer değiştirme özellikleri üzerinde durulur. b. Yapısal izomerlik ve çeşitleri üzerinde durulur. c. Alkanların yakıtlarda [LPG, benzin, motorin (dizel), fueloil, katran ve asfalt ürünlerinin bileşenleri] kullanıldığı, hekzanın ise çözücü olarak kullanıldığı vurgulanır. ç. Benzinlerde oktan sayısı hakkında okuma parçası verilir."]'::jsonb, '{}'::jsonb, 112, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#113', 'yks-2026-kimya', 'yks-2026-kimya#18', '12.3.1.3', 'Basit alkenlerin adlarını, formüllerini, özelliklerini ve kullanım alanlarını açıklar.', NULL, '["a. Cis-trans izomerlik üzerinde durulur. b. Alkenlerin kullanım alanı olarak alkil halojenür ve alkoller için ham madde oldukları vurgulanır. c. Alkenlerin gıda endüstrisindeki kullanımları ve polimerleşme özellikleri hakkında bilgi verilir."]'::jsonb, '{}'::jsonb, 113, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#114', 'yks-2026-kimya', 'yks-2026-kimya#18', '12.3.1.4', 'Basit alkinlerin adlarını, formüllerini, özelliklerini ve kullanım alanlarını açıklar.', NULL, '["Asetilenin üretimi, kullanım alanları, katılma özellikleri ve birincil patlayıcı tuzları üzerinde durulur. Diğer alkin örneklerine girilmez."]'::jsonb, '{}'::jsonb, 114, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#115', 'yks-2026-kimya', 'yks-2026-kimya#18', '12.3.1.5', 'Basit aromatik bileşiklerin adlarını, formüllerini ve kullanım alanlarını açıklar.', NULL, '["Benzen, naftalin, anilin, toluen ve fenol bileşikleri tanıtılarak yapıları ve kullanım alanlarına değinilir."]'::jsonb, '{}'::jsonb, 115, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#116', 'yks-2026-kimya', 'yks-2026-kimya#18', '12.3.2.1', 'Organik bileşikleri fonksiyonel gruplarına göre sınıflandırır.', NULL, '["Alkil-gruplarına, hidroksi-, alkoksi-, halo-, karbonil-, karboksil-, amino-, nitro-, fenil- grupları bağlanınca oluşan bileşikler genel olarak tanıtılır."]'::jsonb, '{}'::jsonb, 116, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#117', 'yks-2026-kimya', 'yks-2026-kimya#18', '12.3.3.1', 'Alkolleri sınıflandırarak adlarını, formüllerini, özelliklerini ve kullanım alanlarını açıklar.', NULL, '["a. Etanolün fermantasyon yöntemi ile elde edilişi açıklanır. b. Etanolün alkil halojenürlerden ve alkenlerden elde edilişi üzerinde durulur. c. Alkollerin hidroksil sayısına ve alfa karbonundaki alkil sayısına göre sınıflandırılması sağlanır. ç. 1-4 karbonlu mono alkoller, etandiol (glikol) ve propantriol (gliserin) üzerinde durulur. d. Metanolün zehirli özellikleri vurgulanır. e. Etanolün sağlık alanında kullanımına vurgu yapılır. f. Etanolün biyoyakıt işlevi gördüğü ve çözücü olarak kullanıldığı vurgulanır."]'::jsonb, '{}'::jsonb, 117, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#118', 'yks-2026-kimya', 'yks-2026-kimya#18', '12.3.4.1', 'Eterleri sınıflandırarak adlarını, formüllerini, özelliklerini ve kullanım alanlarını açıklar.', NULL, '["a. Asimetrik-simetrik eter ayrımı yapılır. b. Eterlerin çözücü özelliklerine vurgu yapılır. c. Fonksiyonel grup izomerliği açıklanarak eterlerin alkollerle izomerliğine değinilir."]'::jsonb, '{}'::jsonb, 118, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#119', 'yks-2026-kimya', 'yks-2026-kimya#18', '12.3.5.1', 'Karbonil bileşiklerini sınıflandırarak adlarını, formüllerini, özelliklerini ve kullanım alanlarını açıklar.', NULL, '["a. Aldehit ve ketonları ayırt edecek düzeyde yapısal ilişki kurularak indirgenme- yükseltgenme özelliklerinin karşılaştırılması sağlanır. b. Aldehitlere örnek olarak formaldehit, asetaldehit ve benzaldehit; ketonlara örnek olarak aseton verilir. c. Aldehit ve ketonların fonksiyonel grup izomerliklerine değinilir. ç. Aldehit ve ketonların gıda ve kozmetik sanayinde nasıl kullanıldıkları üzerinde durulur."]'::jsonb, '{}'::jsonb, 119, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#120', 'yks-2026-kimya', 'yks-2026-kimya#18', '12.3.6.1', 'Karboksilik asitleri sınıflandırarak adlarını, formüllerini ve kullanım alanlarını açıklar.', NULL, '["a. Formik asit, asetik asit, salisilik asit, ftalik asit, sitrik asit, malik asit, folik asit ve benzoik asit tanıtılır. Düz zincirli monokarboksilli asitlerin dışındakilerin formüllerine girilmez. b. Doymuş ve doymamış yağ asitleri tanıtılır. c. Yağ asidi tuzlarının sabun olarak kullanıldığı vurgulanır. ç. Benzoik asidin ve benzoatların gıda koruyucu maddesi olarak kullanıldığı vurgulanır."]'::jsonb, '{}'::jsonb, 120, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#121', 'yks-2026-kimya', 'yks-2026-kimya#18', '12.3.7.1', 'Esterlerin adlarını, formüllerini ve kullanım alanlarını açıklar.', NULL, '["a. Esterleşme tepkimesine örnek verilir. b. Esterlerin yer aldığı doğal maddelere örnek olarak lanolin, balmumu ve balsam verilir. c. Esterlerin çözücü olarak kullanımlarına ilişkin örnekler verilir. ç. Karboksilik asit ve esterlerin fonksiyonel grup izomerliklerine değinilir. d. Sabun eldesi deneyi yaptırılır."]'::jsonb, '{}'::jsonb, 121, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#122', 'yks-2026-kimya', 'yks-2026-kimya#19', '12.4.1.1', 'Fosil yakıtların çevreye zararlı etkilerini azaltmak için çözüm önerilerinde bulunur.', NULL, '["a. Fosil yakıtlar ve bu yakıtların oluşumu bilişim teknolojilerinden (animasyon, simülasyon, video vb.) yararlanılarak açıklanır. b. Fosil yakıtları bilinçsizce tüketmenin ve israf etmenin bireye, topluma ve çevreye verdiği zararlara değinilir. c. Öğrencilerin, fosil yakıtların çevreye zararlı etkilerini araştırmaları ve elde ettikleri bilgilerden yararlanarak bunların çevreye zararlı etkilerini azaltmaya yönelik çözüm önerileri hakkında tartışmaları sağlanır."]'::jsonb, '{}'::jsonb, 122, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#123', 'yks-2026-kimya', 'yks-2026-kimya#19', '12.4.2.1', 'Alternatif enerji kaynaklarını tanır.', NULL, '["a. Güneş, rüzgâr, hidrojen, jeotermal ve biyokütle enerji kaynaklarına değinilir. b. Bor mineralinden hidrojen eldesinin ülkemizin kalkınması için önemi vurgulanır. c. Turhan Nejat Veziroğlu’nun kısa özgeçmişi ve hidrojenin yakıt olarak kullanılması üzerine yaptığı çalışmalara okuma parçası olarak yer verilir."]'::jsonb, '{}'::jsonb, 123, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#124', 'yks-2026-kimya', 'yks-2026-kimya#19', '12.4.2.2', 'Nükleer enerji kullanımını bilim, toplum, teknoloji, çevre ve ekonomi açısından değerlendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 124, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#125', 'yks-2026-kimya', 'yks-2026-kimya#19', '12.4.3.1', 'Sürdürülebilir hayat ve kalkınmanın toplum ve çevre için önemini kimya bilimi ile ilişkilendirerek açıklar.', NULL, '["Enerji, polimer, kâğıt ve metal sektörlerinin sürdürülebilir hayat üzerindeki etkilerine değinilir."]'::jsonb, '{}'::jsonb, 125, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-kimya#126', 'yks-2026-kimya', 'yks-2026-kimya#19', '12.4.4.1', 'Nanoteknoloji alanındaki gelişmeleri bilim, toplum, teknoloji, çevre ve ekonomiye etkileri açısından değerlendirir.', NULL, '["Nanoteknoloji kavramı örnekler üzerinden açıklanır."]'::jsonb, '{}'::jsonb, 126, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#1', 'yks-2026-matematik', 'yks-2026-matematik#1', '9.1.1.1', 'Önermeyi, önermenin doğruluk değerini, iki önermenin denkliğini ve önermenin değilini açıklar.', NULL, '["Boole ve Leibniz’in çalışmalarına yer verilir."]'::jsonb, '{}'::jsonb, 1, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#2', 'yks-2026-matematik', 'yks-2026-matematik#1', '9.1.1.2', 'Bileşik önermeyi örneklerle açıklar, ‘‘ve, veya, ya da’’ bağlaçları ile kurulan bileşik önermelerin özelliklerini ve De Morgan kurallarını doğruluk tablosu kullanarak gösterir.', NULL, '[]'::jsonb, '{}'::jsonb, 2, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#3', 'yks-2026-matematik', 'yks-2026-matematik#1', '9.1.1.3', 'Koşullu önermeyi ve iki yönlü koşullu önermeyi açıklar.', NULL, '["a) Koşullu önermenin karşıtı, tersi, karşıt tersi verilir.", "b) 𝑝𝑝 ⇒ 𝑞𝑞 ≡ 𝑝𝑝′ ∨ 𝑞𝑞 olduğu doğruluk tablosu yardımıyla gösterilir.", "c) ‘‘ ve, veya, ya da, ise’’ bağlaçları kullanılarak verilen, en fazla üç önerme içeren ve en fazla dört bileşenli bileşik önermelere denk basit önermeler buldurulur.", "ç) 𝑝𝑝 ⇔ 𝑞𝑞 ≡ (𝑝𝑝 ⇒ 𝑞𝑞) ∧ (𝑞𝑞 ⇒ 𝑝𝑝) olduğu doğruluk tablosu ile gösterilir."]'::jsonb, '{}'::jsonb, 3, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#4', 'yks-2026-matematik', 'yks-2026-matematik#1', '9.1.1.4', 'Her (∀) ve bazı (∃) niceleyicilerini örneklerle açıklar.', NULL, '["Sözel olarak verilen ve niceleyici içeren açık önermeler, sembolik mantık diliyle; sembolik mantık diliyle verilen ve niceleyici içeren açık önermeler de sözel olarak ifade edilir."]'::jsonb, '{}'::jsonb, 4, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#5', 'yks-2026-matematik', 'yks-2026-matematik#1', '9.1.1.5', 'Tanım, aksiyom, teorem ve ispat kavramlarını açıklar.', NULL, '["Bir teoremin hipotezi ve hükmü belirtilir."]'::jsonb, '{}'::jsonb, 5, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#6', 'yks-2026-matematik', 'yks-2026-matematik#2', '9.2.1.1', 'Kümeler ile ilgili temel kavramlar hatırlatılır.', NULL, '["a) Kümelerle ilgili gerçek hayattan örneklere yer verilir.", "b) Kümelerin farklı gösterimlerine yer verilir.", "c) Cantor’un çalışmalarına yer verilir."]'::jsonb, '{}'::jsonb, 6, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#7', 'yks-2026-matematik', 'yks-2026-matematik#2', '9.2.1.2', 'Alt kümeyi kullanarak işlemler yapar.', NULL, '["a) Alt küme kavramı ve özellikleri ele alınır.", "b) Alt küme kavramıyla ilgili gerçek hayattan örneklere yer verilir.", "c) Kombinasyon gerektiren problemlere girilmez."]'::jsonb, '{}'::jsonb, 7, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#8', 'yks-2026-matematik', 'yks-2026-matematik#2', '9.2.1.3', 'İki kümenin eşitliğini kullanarak işlemler yapar.', NULL, '["a) İki kümenin eşitliği kavramı alt küme ile ilişkilendirilir.", "b) Denk küme kavramı verilmez."]'::jsonb, '{}'::jsonb, 8, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#9', 'yks-2026-matematik', 'yks-2026-matematik#2', '9.2.2.1', 'Kümelerde birleşim, kesişim, fark, tümleme işlemleri yardımıyla problemler çözer.', NULL, '["a) Kümelerin birleşim, kesişim, fark ve tümleme işlemlerinin özellikleri verilir.", "b) Ayrık küme kavramına yer verilir.", "c) En fazla üç kümenin birleşiminin eleman sayısını veren ilişkiler üzerinde durulur.", "ç) Kümelerle yapılan işlemler ve sembolik mantıkta kullanılan sembol, gösterim ve bunlarla ifade edilen işlemler arasında aşağıdaki ilişkilendirmeler yapılır. Sembolik Mantık Kümeler Sembolik Mantık 𝑝𝑝 ∨ 𝑝𝑝′ ≡ 1 𝑝𝑝 ∧ 𝑝𝑝′ ≡ 0 𝑝𝑝 ∧ (𝑞𝑞 ∨ 𝑟𝑟) ≡ (𝑝𝑝 ∧ 𝑞𝑞) ∨ (𝑝𝑝 ∧ 𝑟𝑟) (𝑝𝑝 ∧ 𝑞𝑞)′ ≡ 𝑝𝑝′ ∨ 𝑞𝑞′", "d) Gerçek hayat problemlerine yer verilir. 0 1 ∨ ∧ ′ ≡ ∅ 𝐸𝐸 ∪ ∩ ′ = Kümeler 𝐴𝐴 ∪ 𝐴𝐴′ = 𝐸𝐸 𝐴𝐴 ∩ 𝐴𝐴′ = ∅ 𝐴𝐴 ∩ (𝐵𝐵 ∪ 𝐶𝐶) = (𝐴𝐴 ∩ 𝐵𝐵) ∪ (𝐴𝐴 ∩ 𝐶𝐶) (𝐴𝐴 ∩ 𝐵𝐵)′ = 𝐴𝐴′ ∪ 𝐵𝐵′"]'::jsonb, '{}'::jsonb, 9, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#10', 'yks-2026-matematik', 'yks-2026-matematik#2', '9.2.2.2', 'İki kümenin kartezyen çarpımıyla ilgili işlemler yapar.', NULL, '["a) Sıralı ikili ve sıralı ikililerin eşitliği örneklerle açıklanır.", "b) Kartezyen çarpımın eleman sayısı buldurulur.", "c) Sadece sonlu sayıda elemanı olan kümelerin kartezyen çarpımlarının grafik çizimi yapılır."]'::jsonb, '{}'::jsonb, 10, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#11', 'yks-2026-matematik', 'yks-2026-matematik#3', '9.3.1.1', 'Sayı kümelerini birbiriyle ilişkilendirir.', NULL, '["a) Doğal sayı, tam sayı, rasyonel sayı, irrasyonel sayı ve gerçek sayı kümelerinin sembolleri tanıtılarak bu sayı kümeleri arasındaki ilişki üzerinde durulur.", "b) √2, √3, √5 gibi sayıların sayı doğrusundaki yeri belirlenir.", "c) Gerçek sayılar kümesinde toplama ve çarpma işlemlerinin özellikleri üzerinde durulur.", "ç) ℝ nin geometrik temsilinin sayı doğrusu, ℝ×ℝ nin geometrik temsilinin de kartezyen koordinat sistemi olduğu vurgulanır."]'::jsonb, '{}'::jsonb, 11, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#12', 'yks-2026-matematik', 'yks-2026-matematik#3', '9.3.2.1', 'Tam sayılarda bölünebilme kurallarıyla ilgili problemler çözer.', NULL, '["2, 3, 4, 5, 8, 9, 10, 11 ile bu sayılardan elde edilen 6, 12, 15 gibi sayıların bölünebilme kuralları ele alınır."]'::jsonb, '{}'::jsonb, 12, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#13', 'yks-2026-matematik', 'yks-2026-matematik#3', '9.3.2.2', 'Tam sayılarda EBOB ve EKOK ile ilgili uygulamalar yapar.', NULL, '["a) Gerçek hayat problemlerine yer verilir.", "b) Elektronik tablolarda bulunan EBOB ve EKOK fonksiyonlarından yararlanılır."]'::jsonb, '{}'::jsonb, 13, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#14', 'yks-2026-matematik', 'yks-2026-matematik#3', '9.3.2.3', 'Gerçek hayatta periyodik olarak tekrar eden durumları içeren problemleri çözer.', NULL, '["Modüler aritmetiğe girilmeden periyodik durum içeren problemlere yer verilir. 9.3.3.Birinci Dereceden Denklemler ve Eşitsizlikler Terimler ve Kavramlar: bilinmeyen, değişken, denklem, denklemin derecesi, eşitsizlik, gerçek sayı aralıkları, çözüm kümesi, mutlak değer Sembol ve Gösterimler: <, ≤, >, ≥, [𝑎𝑎, 𝑏𝑏], (𝑎𝑎, 𝑏𝑏], [𝑎𝑎, 𝑏𝑏), (𝑎𝑎, 𝑏𝑏), (−∞, ∞), |𝑥𝑥|"]'::jsonb, '{}'::jsonb, 14, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#15', 'yks-2026-matematik', 'yks-2026-matematik#3', '9.3.3.1', 'Gerçek sayılar kümesinde aralık kavramını açıklar.', NULL, '["a) Açık, kapalı ve yarı açık aralık kavramları ile bunların gösterimleri üzerinde durulur.", "b) Aralıkların kartezyen çarpımlarına yer verilmez."]'::jsonb, '{}'::jsonb, 15, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#16', 'yks-2026-matematik', 'yks-2026-matematik#3', '9.3.3.2', 'Birinci dereceden bir bilinmeyenli denklem ve eşitsizliklerin çözüm kümelerini bulur.', NULL, '["a) Birinci dereceden bir bilinmeyenli denklem ve eşitsizliklerin çözümü hatırlatılır.", "b) Harezmî’nin denklemler konusundaki çalışmalarına yer verilir."]'::jsonb, '{}'::jsonb, 16, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#17', 'yks-2026-matematik', 'yks-2026-matematik#3', '9.3.3.3', 'Mutlak değer içeren birinci dereceden bir bilinmeyenli denklem ve eşitsizliklerin çözüm kümelerini bulur.', NULL, '["a) Bir gerçek sayının mutlak değeri hatırlatılarak mutlak değer özellikleri verilir. (𝑥𝑥, 𝑦𝑦 ∈ ℝ, 𝑛𝑛 ∈ ℤ ve 𝑎𝑎, 𝑏𝑏 ∈ ℝ+) |𝑥𝑥| ≤ 𝑎𝑎 ⇔ −𝑎𝑎 ≤ 𝑥𝑥 ≤ 𝑎𝑎 |𝑥𝑥| ≥ 𝑎𝑎 ⇔ (𝑥𝑥 ≥ 𝑎𝑎 ∨ 𝑥𝑥 ≤ −𝑎𝑎) � �= 𝑎𝑎 ≤ |𝑥𝑥| ≤ 𝑏𝑏 ⇔ (𝑎𝑎 ≤ 𝑥𝑥 ≤ 𝑏𝑏 ∨ −𝑏𝑏 ≤ 𝑥𝑥 ≤ −𝑎𝑎)", "b) İkiden çok mutlak değer içeren denklem ve eşitsizliklere girilmez. |𝑥𝑥. 𝑦𝑦| = |𝑥𝑥|. |𝑦𝑦| |𝑥𝑥| = |−𝑥𝑥| 𝑥𝑥 |𝑥𝑥| |𝑥𝑥 𝑛𝑛 | = |𝑥𝑥|𝑛𝑛 , (𝑦𝑦 ≠ 0) 𝑦𝑦 |𝑦𝑦| |𝑥𝑥 + 𝑦𝑦| ≤ |𝑥𝑥| + |𝑦𝑦|"]'::jsonb, '{}'::jsonb, 17, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#18', 'yks-2026-matematik', 'yks-2026-matematik#3', '9.3.3.4', 'Birinci dereceden iki bilinmeyenli denklem ve eşitsizlik sistemlerinin çözüm kümelerini bulur.', NULL, '["a) Birinci dereceden iki bilinmeyenli denklem sistemlerinin çözüm kümeleri bulunurken yerine koyma, yok etme veya grafikle çözüm yöntemlerinden faydalanılır.", "b) Birinci dereceden iki bilinmeyenli denklem ve eşitsizlik sistemlerinin çözümü, analitik düzlemde gösterilir."]'::jsonb, '{}'::jsonb, 18, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#19', 'yks-2026-matematik', 'yks-2026-matematik#3', '9.3.4.1', 'Üslü ifadeleri içeren denklemleri çözer.', NULL, '["a) Üslü ifade kavramı hatırlatılır.", "b) Bir gerçek sayının tam sayı kuvveti ile ilgili uygulamalar yapılır.", "c) Üslü ifadelerin özellikleri üzerinde durulur."]'::jsonb, '{}'::jsonb, 19, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#20', 'yks-2026-matematik', 'yks-2026-matematik#3', '9.3.4.2', 'Köklü ifadeleri içeren denklemleri çözer.', NULL, '["a) Köklü ifadelerin özellikleri üzerinde durulur. 𝑚𝑚 𝑛𝑛", "b) 𝑥𝑥 ∈ ℝ+ ve 𝑚𝑚, 𝑛𝑛 ∈ ℤ+ için 𝑛𝑛 > 1 𝑜𝑜𝑜𝑜𝑜𝑜𝑜𝑜𝑜𝑜 ü𝑧𝑧𝑧𝑧𝑧𝑧𝑧𝑧 √𝑥𝑥 𝑚𝑚 = 𝑥𝑥 𝑛𝑛 olduğu vurgulanarak köklü ifadeler ve üslü ifadeler arasındaki ilişkiler üzerinde durulur.", "c) En çok iki terimli köklü ifadelerin eşleniklerine yer verilir.", "ç) Köklü ifadelerde sonsuza giden iç içe köklerle yapılan işlemlere yer verilmez."]'::jsonb, '{}'::jsonb, 20, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#21', 'yks-2026-matematik', 'yks-2026-matematik#3', '9.3.5.1', 'Oran ve orantı kavramlarını kullanarak problemler çözer.', NULL, '["a) Oran, orantı, doğru orantı, ters orantı kavramları ile oran ve orantıya ait özellikler hatırlatılır.", "b) Altın oran tanıtılarak gerçek hayattan örnekler verilir ancak hesaplama yöntemlerine yer verilmez."]'::jsonb, '{}'::jsonb, 21, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#22', 'yks-2026-matematik', 'yks-2026-matematik#3', '9.3.5.2', 'Denklemler ve eşitsizlikler ile ilgili problemler çözer.', NULL, '["a) Gerçek hayat durumlarını temsil eden sözel ifadelerdeki ilişkilerin cebirsel, grafiksel ve sayısal temsilleri ile ilgili uygulamalar yapılır.", "b) Farklı problem çözme stratejilerinin uygulanmasını gerektiren oran, orantı kavramlarının kullanıldığı problemlere (örneğin elektrik, su vb. fatura ve ödemeler; sayı, kesir, yaş, işçi, alım-satım, kâr-zarar, yüzde ve karışım problemleri; hız ve hareket (hız kavramı, sabit hız, ortalama hız, birimler arası dönüşüm (km/sa., m/sn.)) yer verilir; faiz, havuz, saat problemlerine girilmez.", "c) Rutin olmayan problem türlerine de yer verilerek farklı problem çözme stratejilerinin uygulanmasına imkân verilir. GEOMETRİ"]'::jsonb, '{}'::jsonb, 22, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#23', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.1.1', 'Üçgende açı özellikleri ile ilgili işlemler yapar.', NULL, '["a) Kültür ve medeniyetimizden geometrinin tarihsel gelişim sürecine katkı sağlamış bilim insanları ve bilim insanlarının yaptığı çalışmalar tanıtılır. Mustafa Kemal Atatürk’ün geometri üzerine yaptığı çalışmalardan bahsedilir.", "b) Açı çeşitleri ve paralel iki doğrunun bir kesenle yaptığı açılar hatırlatılır.", "c) Üçgende sadece iç ve dış açı özelliklerinin kullanıldığı sorulara yer verilir. İkizkenar ve eşkenar üçgenin açı özellikleri üzerinde durulur."]'::jsonb, '{}'::jsonb, 23, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#24', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.1.2', 'Üçgenin kenar uzunlukları ile bu kenarların karşılarındaki açıların ölçülerini ilişkilendirir.', NULL, '["a) Bir üçgende en uzun kenarın karşısındaki açının ölçüsünün en büyük olduğu ve bunun tersinin de doğru olduğu gösterilir.", "b) Dinamik matematik yazılımları kullanılarak oluşturulan üçgenlerin kenar ve açıları arasındaki ilişkinin gözlemlenmesi sağlanır."]'::jsonb, '{}'::jsonb, 24, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#25', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.1.3', 'Uzunlukları verilen üç doğru parçasının hangi durumlarda üçgen oluşturduğunu değerlendirir.', NULL, '["a) İki kenar uzunluğu verilen bir üçgenin üçüncü kenar uzunluğunun hangi aralıkta değerler alabileceğine ilişkin uygulamalar yapılır.", "b) Dinamik matematik yazılımlarından yararlanılarak hangi durumlarda üçgen oluşacağının test edilmesi sağlanır."]'::jsonb, '{}'::jsonb, 25, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#26', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.2.1', 'İki üçgenin eş olması için gerekli olan asgari koşulları değerlendirir.', NULL, '["a) İki üçgenin eşliği hatırlatılır.", "b) Kenar-Açı-Kenar (K.A.K.), Açı-Kenar-Açı (A.K.A.), Kenar-Kenar-Kenar (K.K.K.) eşlik kuralları, ölçümler yapılarak oluşturulur.", "c) Eş üçgenlerin karşılıklı yardımcı elemanlarının da eş olduğu gösterilir."]'::jsonb, '{}'::jsonb, 26, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#27', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.2.2', 'İki üçgenin benzer olması için gerekli olan asgari koşulları değerlendirir.', NULL, '["a) Kenar-Açı-Kenar (K.A.K.), Kenar-Kenar-Kenar (K.K.K.) ve Açı-Açı (A.A.) benzerlik kuralları, ölçümler yapılarak oluşturulur.", "b) Eşlik ile benzerlik arasındaki ilişki incelenir.", "c) Benzer üçgenlerin karşılıklı yardımcı elemanlarının da aynı benzerlik oranına sahip olduğu gösterilir.", "ç) Bilgi ve iletişim teknolojilerinden yararlanılır."]'::jsonb, '{}'::jsonb, 27, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#28', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.2.3', 'Üçgenin bir kenarına paralel ve diğer iki kenarı kesecek şekilde çizilen doğrunun ayırdığı doğru parçaları arasındaki ilişkiyi kurar.', NULL, '["Thales’ in çalışmalarına yer verilir."]'::jsonb, '{}'::jsonb, 28, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#29', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.2.4', 'Üçgenlerin benzerliği ile ilgili problemler çözer.', NULL, '["Gerçek hayat problemlerine yer verilir."]'::jsonb, '{}'::jsonb, 29, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#30', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.3.1', 'Üçgenin iç ve dış açıortaylarının özelliklerini elde eder.', NULL, '["a) Açıortay üzerinde alınan bir noktadan açının kollarına indirilen dikmelerin uzunluklarının eşit olduğu gösterilir.", "b) İç ve dış açıortay uzunlukları formülle hesaplatılmaz.", "c) Açıortay özelliklerinin gösteriminde pergel-cetvelden yararlanılır.", "ç) Bilgi ve iletişim teknolojilerinden yararlanılır."]'::jsonb, '{}'::jsonb, 30, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#31', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.3.2', 'Üçgenin kenarortaylarının özelliklerini elde eder.', NULL, '["a) Kenarortayların kesiştiği nokta ile bu noktanın kenarortay üzerinde ayırdığı parçalar arasındaki ilişki üzerinde durulur.", "b) Kenarortayların kesiştiği noktanın, üçgenin ağırlık merkezi olduğuna ve üçgenin ağırlık merkeziyle ilgili özelliklerine yer verilir.", "c) Dik üçgende, hipotenüse ait kenarortay uzunluğunun hipotenüs uzunluğunun yarısı olduğu gösterilir.", "ç) Kenarortay uzunluğu formülle hesaplatılmaz.", "d) Pergel-cetvel kullanarak veya bilgi ve iletişim teknolojileri yardımıyla üçgen üzerinde değişiklikler yapılarak ve üçgen çeşitlerine bağlı olarak değişikliklerin kenarortaylar üzerindeki etkisi gözlemlenir."]'::jsonb, '{}'::jsonb, 31, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#32', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.3.3', 'Üçgenin kenar orta dikmelerinin bir noktada kesiştiğini gösterir.', NULL, '["a) Bir doğru parçasının orta dikmesi üzerinde alınan her noktanın, doğru parçasının uç noktalarına eşit uzaklıkta olduğu ve bunun karşıtının da doğru olduğu gösterilir.", "b) Pergel-cetvel veya bilgi ve iletişim teknolojilerinden yararlanılır."]'::jsonb, '{}'::jsonb, 32, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#33', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.3.4', 'Üçgenin çeşidine göre yüksekliklerinin kesiştiği noktanın konumunu belirler.', NULL, '["a) Pergel-cetvel kullanarak veya bilgi ve iletişim teknolojileri yardımıyla bir üçgenin yükseklikleri çizilerek kesişimleri üzerinde durulur. Farklı üçgen çeşitleri üzerinde örnekler yapılır.", "b) İkizkenar üçgenin tabanında alınan bir noktadan kenarlara çizilen dikmelerin uzunlukları toplamı ile üçgenin eş olan kenarlarına ait yükseklik arasındaki ilişki bulunur.", "c) Eşkenar üçgen içerisinde alınan bir noktadan kenarlara indirilen dikmelerin uzunlukları toplamı ile üçgenin yüksekliği arasındaki ilişki bulunur."]'::jsonb, '{}'::jsonb, 33, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#34', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.4.1', 'Dik üçgende Pisagor teoremini elde ederek problemler çözer.', NULL, '["a) Teorem elde edilirken model çeşitliliğine yer verilir.", "b) Gerçek hayat problemlerine yer verilir.", "c) Pythagoras’ın çalışmalarına yer verilir."]'::jsonb, '{}'::jsonb, 34, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#35', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.4.2', 'Öklid teoremini elde ederek problemler çözer.', NULL, '["a) Gerçek hayat problemlerine yer verilir.", "b) Euclid’in çalışmalarına yer verilir."]'::jsonb, '{}'::jsonb, 35, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#36', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.4.3', 'Dik üçgende dar açıların trigonometrik oranlarını hesaplar.', NULL, '["a) Bir açının sinüs, kosinüs, tanjant ve kotanjant değerleri dik üçgen üzerinde tanımlanır.", "b) Dik üçgende; 30°, 45° ve 60° nin trigonometrik değerleri özel üçgenler yardımıyla hesaplanır.", "c) Gerçek hayat problemlerine yer verilir.", "ç) Bilgi ve iletişim teknolojilerinden yararlanılır."]'::jsonb, '{}'::jsonb, 36, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#37', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.4.4', 'Birim çemberi tanımlar ve trigonometrik oranları birim çemberin üzerindeki noktanın koordinatlarıyla ilişkilendirir.', NULL, '["a) Sadece 0° ve 180° arasındaki açıların trigonometrik oranları birim çember yardımıyla hesaplatılır.", "b) Ebu’l Vefa ve Gıyaseddin Cemşid’in trigonometrik oranlarla ilgili çalışmalarından bahsedilir."]'::jsonb, '{}'::jsonb, 37, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#38', 'yks-2026-matematik', 'yks-2026-matematik#4', '9.4.5.1', 'Üçgenin alanı ile ilgili problemler çözer.', NULL, '["a) Üçgenin alanı, bir kenarı ile bu kenara ait yükseklik kullanılarak hesaplatılır.", "b) İki kenarının uzunluğu ve bu kenarlar arasındaki açının ölçüsü verilen üçgenin alanını hesaplar.", "c) Aynı yüksekliğe sahip üçgenlerin alanlarıyla tabanları; aynı tabana sahip üçgenlerin alanlarıyla yükseklikleri arasındaki ilişki vurgulanır.", "ç) Benzer üçgenlerin alanları ile benzerlik oranları arasındaki ilişki belirtilir.", "d) Bilgi ve iletişim teknolojileri yardımıyla alan, taban ve yüksekliği değiştirilen bir üçgenin alanının nasıl değiştiği gözlemlenir. VERİ, SAYMA VE OLASILIK"]'::jsonb, '{}'::jsonb, 38, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#39', 'yks-2026-matematik', 'yks-2026-matematik#5', '9.5.1.1', 'Verileri merkezî eğilim ve yayılım ölçülerini hesaplayarak yorumlar.', NULL, '["a) Veri kavramı, kesikli ve sürekli veri çeşitleri verilir.", "b) Aritmetik ortalama, ortanca, tepe değer, en büyük değer, en küçük değer ve açıklık kavramları verilir.", "c) Alt çeyrek, üst çeyrek ve çeyrekler açıklığına yer verilmez.", "ç) Veri sayısı en fazla beş olan veri grupları için standart sapma hesaplanır.", "d) Gerçek hayat durumlarında aritmetik ortalama, ortanca, tepe değer kavramları birlikte yorumlanır."]'::jsonb, '{}'::jsonb, 39, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#40', 'yks-2026-matematik', 'yks-2026-matematik#5', '9.5.2.1', 'Bir veri grubuna ilişkin histogram oluşturur.', NULL, '["a) Histogram oluşturulurken veri grubunun açıklığı seçilen grup sayısına bölünür ve aşağıdaki eşitsizliği sağlayan en küçük doğal sayı değeri grup genişliği olarak belirlenir. 𝐴𝐴ç𝚤𝚤𝑘𝑘𝑘𝑘𝚤𝚤𝑘𝑘 < 𝐺𝐺𝐺𝐺𝐺𝐺𝐺𝐺 𝑔𝑔𝑔𝑔𝑔𝑔𝑔𝑔ş𝑙𝑙𝑙𝑙ğ𝑖𝑖 𝐺𝐺𝐺𝐺𝐺𝐺𝐺𝐺 𝑠𝑠𝑠𝑠𝑠𝑠𝑠𝑠𝑠𝑠𝑠𝑠", "b) Veri gruplarının histogramı çizilir."]'::jsonb, '{}'::jsonb, 40, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#41', 'yks-2026-matematik', 'yks-2026-matematik#5', '9.5.2.2', 'Gerçek hayat durumunu yansıtan veri gruplarını uygun grafik türleriyle temsil ederek yorumlar.', NULL, '["a) İkiden fazla veri grubunun karşılaştırıldığı durumlara da yer verilir.", "b) Serpme ve kutu grafiklerine yer verilmez.", "c) Grafik türleri bilgi ve iletişim teknolojileri kullanılarak çizilir.", "ç) Tasarruf bilinci kazandırmak amacıyla ekmek israfı, su israfı gibi konulara ilişkin veriler kullanılarak grafik oluşturulması sağlanır."]'::jsonb, '{}'::jsonb, 41, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#42', 'yks-2026-matematik', 'yks-2026-matematik#6', '10.1.1.1', 'Olayların gerçekleşme sayısını toplama ve çarpma yöntemlerini kullanarak hesaplar.', NULL, '["a) Sayma konusunun tarihsel gelişim sürecinden söz edilir ve bu süreçte rol alan Sâbit İbn Kurrâ‘nın çalışmalarına yer verilir.", "b) Faktöriyel kavramı verilerek saymanın temel ilkesi ile ilişkilendirilir."]'::jsonb, '{}'::jsonb, 42, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#43', 'yks-2026-matematik', 'yks-2026-matematik#6', '10.1.1.2', 'n çeşit nesne ile oluşturulabilecek r li dizilişlerin (permütasyonların) kaç farklı şekilde yapılabileceğini hesaplar.', NULL, '[]'::jsonb, '{}'::jsonb, 43, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#44', 'yks-2026-matematik', 'yks-2026-matematik#6', '10.1.1.3', 'Sınırlı sayıda tekrarlayan nesnelerin dizilişlerini (permütasyonlarını) açıklayarak problemler çözer.', NULL, '["a) En az iki tanesi özdeş olan nesnelerin tüm farklı dizilişlerinin sayısı örnekler/problemler bağlamında ele alınır.", "b) Gerçek hayat problemlerine yer verilir."]'::jsonb, '{}'::jsonb, 44, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#45', 'yks-2026-matematik', 'yks-2026-matematik#6', '10.1.1.4', 'n elemanlı bir kümenin r tane elemanının kaç farklı şekilde seçilebileceğini hesaplar.', NULL, '["a) Kombinasyon kavramı alt küme sayısı ile ilişkilendirilir.", "b) Kombinasyon kavramının aşağıdaki temel özellikleri incelenir: • 𝐶𝐶(𝑛𝑛, 𝑟𝑟) = 𝐶𝐶(𝑛𝑛, 𝑛𝑛 − 𝑟𝑟) • 𝐶𝐶(𝑛𝑛, 0) + 𝐶𝐶(𝑛𝑛, 1) + ⋯ + 𝐶𝐶(𝑛𝑛, 𝑛𝑛) = 2𝑛𝑛"]'::jsonb, '{}'::jsonb, 45, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#46', 'yks-2026-matematik', 'yks-2026-matematik#6', '10.1.1.5', 'Pascal üçgenini açıklar.', NULL, '["Pascal üçgeninin, aralarında Ömer Hayyam’ın da bulunduğu Hint, Çin, İslam medeniyetlerindeki matematikçi ve düşünürler tarafından Pascal’dan çok önceleri ele alındığı; bu çerçevede matematiksel bilginin oluşumunda farklı kültür ve bilim insanlarının rolü vurgulanır."]'::jsonb, '{}'::jsonb, 46, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#47', 'yks-2026-matematik', 'yks-2026-matematik#6', '10.1.1.6', 'Binom açılımını yapar.', NULL, '["a) Binom açılımı Pascal üçgeni ile ilişkilendirilir.", "b) Sadece iki terimli ifadelerin açılımı ele alınır.", "c) Binom formülü ile ilgili örnekler yapılır ancak (𝑎𝑎𝑎𝑎 + 𝑏𝑏𝑏𝑏)𝑛𝑛 açılımında 𝑛𝑛 ∈ ℕ, 𝑎𝑎, 𝑏𝑏 ∈ ℚ′ şeklindeki örneklere yer verilmez."]'::jsonb, '{}'::jsonb, 47, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#48', 'yks-2026-matematik', 'yks-2026-matematik#6', '10.1.2.1', 'Örnek uzay, deney, çıktı, bir olayın tümleyeni, kesin olay, imkânsız olay, ayrık olay ve ayrık olmayan olay kavramlarını açıklar.', NULL, '["a) Örnek uzay, deney, çıktı kavramları eş olası durumlardan yola çıkılarak eş olası olmayan durumlar için de örneklendirilir ve tanımlanır.", "b) Ayrık olay ve ayrık olmayan olay üzerinde durulur.", "c) El Kindî ve Laplace''ın çalışmalarına yer verilir."]'::jsonb, '{}'::jsonb, 48, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#49', 'yks-2026-matematik', 'yks-2026-matematik#6', '10.1.2.2', 'Olasılık kavramı ile ilgili uygulamalar yapar.', NULL, '["a) Eş olası olan ve olmayan olayların olasılıkları hesaplanır.", "b) Tümleyen, ayrık olay ve ayrık olmayan olay ile ilgili olasılıklar hesaplanır.", "c) Gerçek hayat problemlerine yer verilir. SAYILAR VE CEBİR"]'::jsonb, '{}'::jsonb, 49, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#50', 'yks-2026-matematik', 'yks-2026-matematik#7', '10.2.1.1', 'Fonksiyonlarla ilgili problemler çözer.', NULL, '["a) Fonksiyon kavramı açıklanır.", "b) Sadece gerçek sayılar üzerinde tanımlanmış fonksiyonlar ele alınır.", "c) İçine fonksiyon, örten fonksiyon, bire bir fonksiyon, eşit fonksiyon, birim (özdeşlik) fonksiyon, sabit fonksiyon, doğrusal fonksiyon, tek fonksiyon, çift fonksiyon ve parçalı tanımlı fonksiyon açıklanır.", "ç) İki fonksiyonun eşitliği örneklerle açıklanır. 𝑓𝑓", "d) f ve g fonksiyonları kullanılarak 𝑓𝑓 + 𝑔𝑔, 𝑓𝑓 − 𝑔𝑔, 𝑓𝑓. 𝑔𝑔, 𝑔𝑔 fonksiyonlarda bu işlemlere girilmez.", "e) Gerçek hayat problemlerine ve tablo-grafik kullanımına yer verilir. işlemleri yapılır, ancak parçalı tanımlı"]'::jsonb, '{}'::jsonb, 50, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#51', 'yks-2026-matematik', 'yks-2026-matematik#7', '10.2.1.2', 'Fonksiyonların grafiklerini çizer.', NULL, '["a) f(x) = ax + b şeklindeki fonksiyonların grafikleri ile ilgili uygulamalar yapılır.", "b) Parçalı tanımlı şekilde verilen fonksiyonların grafikleri çizilir.", "c) f(x) = ax + b tipindeki fonksiyonların grafiği bilgi ve iletişim teknolojileri yardımıyla çizilerek a ve b katsayıları ile fonksiyon grafiği arasındaki ilişki ele alınır."]'::jsonb, '{}'::jsonb, 51, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#52', 'yks-2026-matematik', 'yks-2026-matematik#7', '10.2.1.3', 'Fonksiyonların grafiklerini yorumlar.', NULL, '["a) Grafiği verilen fonksiyonların tanım ve görüntü kümeleri gösterilir.", "b) Bir fonksiyon grafiğinde, fonksiyonun x ekseni üzerinde tanımlı olduğu her bir noktadan y eksenine paralel çizilen doğruların, grafiği yalnızca bir noktada kestiğine (düşey/dikey doğru testi) işaret edilir.", "c) Bir f fonksiyonunun grafiğinin y = f(x) denkleminin grafiği olduğu ve grafiğin (varsa), x eksenini kestiği noktaların f(x) = 0 denkleminin gerçek sayılardaki çözüm kümesi olduğu vurgulanır."]'::jsonb, '{}'::jsonb, 52, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#53', 'yks-2026-matematik', 'yks-2026-matematik#7', '10.2.1.4', 'Gerçek hayat durumlarından doğrusal fonksiyonlarla ifade edilebilenlerin grafik gösterimlerini yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 53, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#54', 'yks-2026-matematik', 'yks-2026-matematik#7', '10.2.2.1', 'Bire bir ve örten fonksiyonlar ile ilgili uygulamalar yapar.', NULL, '["a) Bir fonksiyonun bire bir ve örtenliği grafik üzerinde yatay doğru testiyle incelenir ve cebirsel olarak ilişkilendirilir.", "b) Bilgi ve iletişim teknolojileri yardımıyla bir fonksiyonun bire bir ve örten olup olmadığı belirlenir."]'::jsonb, '{}'::jsonb, 54, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#55', 'yks-2026-matematik', 'yks-2026-matematik#7', '10.2.2.2', 'Fonksiyonlarda bileşke işlemiyle ilgili işlemler yapar.', NULL, '["a) Bileşke işlemi, fonksiyonların cebirsel ve grafik gösterimleri ile ilişkilendirilerek ele alınır.", "b) Fonksiyonlarda bileşke işleminin birleşme özelliğinin olduğu belirtilir, değişme özelliğinin olmadığı örneklerle gösterilir.", "c) Parçalı tanımlı fonksiyonların bileşkesine girilmez."]'::jsonb, '{}'::jsonb, 55, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#56', 'yks-2026-matematik', 'yks-2026-matematik#7', '10.2.2.3', 'Verilen bir fonksiyonun tersini bulur.', NULL, '["a) Bir fonksiyonun tersinin de fonksiyon olması için gerekli şartlar belirtilir.", "b) Sadece bire bir ve örten doğrusal fonksiyonun tersinin grafiği çizilir; fonksiyonun grafiği ile tersinin grafiğinin y=x doğrusuna göre simetrik olduğu gösterilir.", "c) Parçalı tanımlı fonksiyonların tersi verilmez."]'::jsonb, '{}'::jsonb, 56, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#57', 'yks-2026-matematik', 'yks-2026-matematik#8', '10.3.1.1', 'Bir değişkenli polinom kavramını açıklar.', NULL, '["a) Polinomun derecesi, katsayıları ve sabit terimi belirtilir.", "b) Sabit polinom, sıfır polinomu ve iki polinomun eşitliği örneklerle açıklanır."]'::jsonb, '{}'::jsonb, 57, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#58', 'yks-2026-matematik', 'yks-2026-matematik#8', '10.3.1.2', 'Polinomlarla toplama, çıkarma, çarpma ve bölme işlemlerini yapar.', NULL, '["a) Bir P(x) polinomunun x – a ile bölümünden kalan P(a) dır. 𝑃𝑃(𝑎𝑎) = 0 ⇔ 𝑥𝑥 – 𝑎𝑎, 𝑃𝑃(𝑥𝑥) in bir çarpanı olduğu vurgulanır.", "b) Polinomun sıfırı kavramı bölme işlemiyle ilişkilendirilir."]'::jsonb, '{}'::jsonb, 58, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#59', 'yks-2026-matematik', 'yks-2026-matematik#8', '10.3.2.1', 'Bir polinomu çarpanlarına ayırır.', NULL, '["a) Ortak çarpan parantezine alma ve değişken değiştirme yöntemleri kullanılarak çarpanlara ayırma uygulamaları yapılır.", "b) Tam kare, iki kare farkı, iki terimin toplamının ve farkının küpü, iki terimin küplerinin toplamı ve farkına ait özdeşlikler kullanılarak çarpanlara ayırma uygulamaları yapılır.", "c) 𝑎𝑎𝑥𝑥 2 + 𝑏𝑏𝑏𝑏 + 𝑐𝑐 biçimindeki ifadeler çarpanlarına ayrılır."]'::jsonb, '{}'::jsonb, 59, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#60', 'yks-2026-matematik', 'yks-2026-matematik#8', '10.3.2.2', 'Rasyonel ifadelerin sadeleştirilmesi ile ilgili işlemler yapar.', NULL, '["a) Rasyonel ifade kavramı tanıtılır.", "b) Çarpanları polinom olmayan ifadelerde çarpanlara ayırma uygulamalarına yer verilmez."]'::jsonb, '{}'::jsonb, 60, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#61', 'yks-2026-matematik', 'yks-2026-matematik#9', '10.4.1.1', 'İkinci dereceden bir bilinmeyenli denklem kavramını açıklar.', NULL, '["İkinci dereceden bir bilinmeyenli denklemlerin tarihsel gelişim sürecine ve bu süreçte rol alan Brahmagupta, Harezmî ve Abdulhamid İbn Türk’ün çalışmalarına yer verilir."]'::jsonb, '{}'::jsonb, 61, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#62', 'yks-2026-matematik', 'yks-2026-matematik#9', '10.4.1.2', 'İkinci dereceden bir bilinmeyenli denklemleri çözer.', NULL, '["a) ax2 + bx + c biçimindeki cebirsel ifadelerin; tam kare ve iki kare farkına ait özdeşlikler kullanılarak çarpanlara ayrılmasıyla ilgili uygulamalar yapılır.", "b) Denklemlerin çözümünde farklı yöntemlerden (çarpanlara ayırma, tam kareye tamamlama, değişken değiştirme, iki kare farkı, diskriminant) yararlanılır.", "c) Gerçek hayat problemlerine yer verilir."]'::jsonb, '{}'::jsonb, 62, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#63', 'yks-2026-matematik', 'yks-2026-matematik#9', '10.4.1.3', 'Bir karmaşık sayının a+ib (a,b ∈ ℝ) biçiminde ifade edildiğini açıklar.', NULL, '["a)Diskriminantın sıfırdan küçük olduğu durumlarda ikinci dereceden bir bilinmeyenli denklemlerin köklerinin bulunabilmesi için gerçek sayılar kümesini kapsayan yeni bir sayı kümesi tanımlama gereği örneklerle açıklanır.", "b) 𝑖𝑖 2= −1 olmak üzere bir karmaşık sayı 𝑎𝑎 + 𝑖𝑖𝑖𝑖 (𝑎𝑎, 𝑏𝑏 ∈ ℝ) biçiminde gösterilir.", "c) Köklerin birbirinin eşleniği olduğu belirtilir.", "ç) Karmaşık sayının eşleniği dışındaki özelliklere ve işlemlere girilmez."]'::jsonb, '{}'::jsonb, 63, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#64', 'yks-2026-matematik', 'yks-2026-matematik#9', '10.4.1.4', 'İkinci dereceden bir bilinmeyenli denklemin kökleri ile katsayıları arasındaki ilişkileri kullanarak işlemler yapar.', NULL, '["a) Sadece kökler toplamı ve çarpımı ile denklemin katsayıları arasındaki ilişkiler üzerinde durulur.", "b) Kökleri verilen ikinci dereceden denklemi elde etme ile ilgili uygulamalara yer verilir. GEOMETRİ"]'::jsonb, '{}'::jsonb, 64, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#65', 'yks-2026-matematik', 'yks-2026-matematik#10', '10.5.1.1', 'Çokgen kavramını açıklayarak işlemler yapar.', NULL, '["a) İçbükey çokgenlere girilmez.", "b) Düzgün çokgenler hatırlatılır, iç ve dış açılarının ölçüleri bulunur.", "c) Çokgenlerin köşegenleri ile ilgili özelliklere ve alan problemlerine yer verilmez."]'::jsonb, '{}'::jsonb, 65, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#66', 'yks-2026-matematik', 'yks-2026-matematik#10', '10.5.2.1', 'Dörtgenin temel elemanlarını ve özelliklerini açıklayarak problemler çözer.', NULL, '["a) Dışbükey ve içbükey dörtgen kavramları açıklanır. (Bundan sonra dörtgen denildiğinde dış bükey dörtgen anlaşılmalıdır.)", "b) Dörtgenin iç ve dış açılarının ölçüleri toplamı bulunur.", "c) Dörtgenin çevresi üzerinde durulur."]'::jsonb, '{}'::jsonb, 66, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#67', 'yks-2026-matematik', 'yks-2026-matematik#10', '10.5.3.1', 'Özel dörtgenlerin açı, kenar, köşegen ve alan özelliklerini açıklayarak problemler çözer.', NULL, '["a) Yamuk, paralelkenar, eşkenar dörtgen, dikdörtgen, kare ve deltoid arasındaki hiyerarşik ilişkilere yer verilir.", "b) Hiyerarşik ilişkiye göre her bir özel dörtgen kendi içerisinde; açı, kenar, köşegen ve alan özellikleri bağlamında ele alınır.", "c) Origami, tangram kullanılarak uygulamalar yapılır.", "ç) Geleneksel mimaride kullanılan motif örneklerinde yer alan çokgen örneklerine yer verilir.", "d) Bilgi ve iletişim teknolojilerinden yararlanılır."]'::jsonb, '{}'::jsonb, 67, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#68', 'yks-2026-matematik', 'yks-2026-matematik#11', '10.6.1.1', 'Dik prizmalar ve dik piramitlerin uzunluk, alan ve hacim bağıntılarını oluşturur.', NULL, '["a) Üçgen, dörtgen ve altıgen dik prizma/piramit ile sınırlandırılır.", "b) Gerçek hayat problemlerine yer verilir.", "c) Bilgi ve iletişim teknolojilerinden yararlanılır."]'::jsonb, '{}'::jsonb, 68, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#69', 'yks-2026-matematik', 'yks-2026-matematik#12', '11.1.1.1', 'Yönlü açıyı açıklar.', NULL, '[]'::jsonb, '{}'::jsonb, 69, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#70', 'yks-2026-matematik', 'yks-2026-matematik#12', '11.1.1.2', 'Açı ölçü birimlerini açıklayarak birbiri ile ilişkilendirir.', NULL, '["a) Derecenin alt birimleri olan dakika ve saniyeden bahsedilir.", "b) Derece ile radyan ilişkilendirilir, grada girilmez.", "c) Açının esas ölçüsü bulunur."]'::jsonb, '{}'::jsonb, 70, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#71', 'yks-2026-matematik', 'yks-2026-matematik#12', '11.1.2.1', 'Trigonometrik fonksiyonları birim çember yardımıyla açıklar.', NULL, '["a) Trigonometrik fonksiyonlar arasındaki temel özdeşlikler, oluşturulan benzer üçgenler yardımıyla incelenir.", "b) Trigonometrik fonksiyonların bölgelere göre işaretleri incelenir. c)Trigonometrik fonksiyonların açı değerlerine göre sıralanmasına yer verilir. 𝑘𝑘𝑘𝑘", "ç) 𝑘𝑘 ∈ ℤ+ olmak üzere yararlanarak hesaplanır. ± 𝜃𝜃 açılarının trigonometrik değerleri θ dar açısının trigonometrik değerlerinden"]'::jsonb, '{}'::jsonb, 71, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#72', 'yks-2026-matematik', 'yks-2026-matematik#12', '11.1.2.2', 'Kosinüs teoremiyle ilgili problemler çözer.', NULL, '["a) Kosinüs teoremi, Pisagor teoreminden yararlanılarak elde edilir.", "b) Gerçek hayat problemlerine yer verilir."]'::jsonb, '{}'::jsonb, 72, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#73', 'yks-2026-matematik', 'yks-2026-matematik#12', '11.1.2.3', 'Sinüs teoremiyle ilgili problemler çözer.', NULL, '["a) Sinüs teoremi, iki kenarının uzunluğu ve bu kenarlar arasındaki açının ölçüsü verilen üçgenin alanından yararlanılarak elde edilir.", "b) Sinüs teoremi çevrel çemberle ilişkilendirilmez.", "c) Gerçek hayat problemlerine yer verilir."]'::jsonb, '{}'::jsonb, 73, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#74', 'yks-2026-matematik', 'yks-2026-matematik#12', '11.1.2.4', 'Trigonometrik fonksiyon grafiklerini çizer.', NULL, '["a) y=sinx ve y=cosx fonksiyonları dışındaki fonksiyonların grafik çizimlerinde sadece bilgi ve iletişim teknolojileri kullanılır.", "b) Periyodik fonksiyon tanımı verilir, trigonometrik fonksiyonların periyodik oldukları gösterilir.", "c) 𝑓𝑓(𝑥𝑥) = 𝑎𝑎. 𝑠𝑠𝑠𝑠𝑠𝑠(𝑏𝑏𝑏𝑏 + 𝑐𝑐) + 𝑘𝑘 türündeki fonksiyonların grafikleri ve katsayılarının grafik üzerindeki etkileri ele alınır.", "ç) Grafikleri yardımıyla trigonometrik fonksiyonların tek ya da çift fonksiyon olup olmadıkları belirlenir.", "d) Sekant ve kosekant fonksiyonlarının grafiklerine yer verilmez."]'::jsonb, '{}'::jsonb, 74, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#75', 'yks-2026-matematik', 'yks-2026-matematik#12', '11.1.2.5', 'Sinüs, kosinüs, tanjant fonksiyonlarının ters fonksiyonlarını açıklar.', NULL, '["Ters trigonometrik fonksiyonların grafiklerine yer verilmez."]'::jsonb, '{}'::jsonb, 75, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#76', 'yks-2026-matematik', 'yks-2026-matematik#13', '11.2.1.1', 'Analitik düzlemde iki nokta arasındaki uzaklığı veren bağıntıyı elde ederek problemler çözer.', NULL, '[]'::jsonb, '{}'::jsonb, 76, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#77', 'yks-2026-matematik', 'yks-2026-matematik#13', '11.2.1.2', 'Bir doğru parçasını belli bir oranda (içten veya dıştan) bölen noktanın koordinatlarını hesaplar.', NULL, '["a) Bir doğru parçasının orta noktasının koordinatları buldurulur.", "b) Bir üçgenin ağırlık merkezinin koordinatları buldurulur."]'::jsonb, '{}'::jsonb, 77, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#78', 'yks-2026-matematik', 'yks-2026-matematik#13', '11.2.1.3', 'Analitik düzlemde doğruları inceleyerek işlemler yapar.', NULL, '["a) Bir doğrunun eğim açısı ve eğimi tanımlanır.", "b) Analitik düzlemde bir doğrunun denklemi oluşturulur.", "c) Eksenlere paralel ve orijinden geçen doğruların denklemleri bulunur ve bulunan denklemlerin grafikleri yorumlanır.", "ç) İki doğrunun birbirine göre durumları incelenir ve kesişen iki doğrunun kesişim noktası bulunur.", "d) Bilgi ve iletişim teknolojilerinden yararlanılır."]'::jsonb, '{}'::jsonb, 78, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#79', 'yks-2026-matematik', 'yks-2026-matematik#13', '11.2.1.4', 'Bir noktanın bir doğruya uzaklığını hesaplar.', NULL, '["Bir noktanın bir doğruya uzaklığı ve paralel iki doğru arasındaki uzaklık ile ilgili uygulamalar yapılır. SAYILAR VE CEBİR"]'::jsonb, '{}'::jsonb, 79, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#80', 'yks-2026-matematik', 'yks-2026-matematik#14', '11.3.1.1', 'Fonksiyonun grafik ve tablo temsilini kullanarak problem çözer.', NULL, '["a) Grafiğin x ve y eksenlerini kestiği noktalar; fonksiyonun pozitif, negatif, artan ve azalan olduğu aralıklar; fonksiyonun maksimum ve minimum değerleri ve bunların (verilen durum bağlamında) anlamları grafik üzerinden açıklanır.", "b) Cebirsel ifade, grafik veya tablo ile verilen bir fonksiyonun belli bir aralıktaki ortalama değişim hızı 𝑓𝑓(𝑏𝑏)−𝑓𝑓(𝑎𝑎) (kesenin eğimi , 𝑏𝑏−𝑎𝑎", "c) Fonksiyonun grafiği bilgi ve iletişim teknolojileri yardımıyla çizilir ve yorumlanır. ) hesaplanır."]'::jsonb, '{}'::jsonb, 80, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#81', 'yks-2026-matematik', 'yks-2026-matematik#14', '11.3.2.1', 'İkinci dereceden bir değişkenli fonksiyonun grafiğini çizerek yorumlar.', NULL, '["a) Fonksiyonun grafiğinin tepe noktası, eksenleri kestiği noktalar ve simetri ekseni buldurulur.", "b) Fonksiyonun grafiğinin tepe noktası ile fonksiyonun en küçük ya da en büyük değeri ilişkilendirilir.", "c) Fonksiyonun katsayılarındaki değişimin, fonksiyonun grafiği üzerine etkisi bilgi ve iletişim teknolojilerinden yararlanılarak yorumlanır.", "ç) Biri tepe noktası olmak üzere iki noktası verilen veya biri y ekseni üzerinde olmak üzere üç noktası verilen ikinci dereceden fonksiyon oluşturulur.", "d) Bir doğru ile bir parabolün birbirine göre durumları incelenir."]'::jsonb, '{}'::jsonb, 81, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#82', 'yks-2026-matematik', 'yks-2026-matematik#14', '11.3.2.2', 'İkinci dereceden fonksiyonlarla modellenebilen problemleri çözer.', NULL, '[]'::jsonb, '{}'::jsonb, 82, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#83', 'yks-2026-matematik', 'yks-2026-matematik#14', '11.3.3.1', 'Bir fonksiyonun grafiğinden, dönüşümler yardımı ile yeni fonksiyon grafikleri çizer.', NULL, '["a) Tek ve çift fonksiyonların grafiğinin simetri özellikleri üzerinde durulur.", "b) grafikleri bilgi ve iletişim teknolojilerinden yararlanılarak verilir. 𝑦𝑦 = 𝑓𝑓(𝑥𝑥) + 𝑏𝑏, 𝑦𝑦 = 𝑓𝑓(𝑥𝑥 − 𝑎𝑎), 𝑦𝑦 = 𝑘𝑘 𝑓𝑓(𝑥𝑥), 𝑦𝑦 = 𝑓𝑓(𝑘𝑘𝑘𝑘), 𝑦𝑦 = −𝑓𝑓(𝑥𝑥), 𝑦𝑦 = 𝑓𝑓(−𝑥𝑥) dönüşümlerinin"]'::jsonb, '{}'::jsonb, 83, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#84', 'yks-2026-matematik', 'yks-2026-matematik#15', '11.4.1.1', 'İkinci dereceden İki bilinmeyenli denklem sistemlerinin çözüm kümesini bulur.', NULL, '["Bilgi ve iletişim teknolojilerinden yararlanılarak çizilen grafikler yardımıyla çözüm yorumlatılır."]'::jsonb, '{}'::jsonb, 84, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#85', 'yks-2026-matematik', 'yks-2026-matematik#15', '11.4.2.1', 'İkinci dereceden bir bilinmeyenli eşitsizliklerin çözüm kümesini bulur.', NULL, '["a) ax + b veya 𝑎𝑎𝑥𝑥 2 + 𝑏𝑏𝑏𝑏 + 𝑐𝑐 şeklindeki ifadelerin çarpımı veya bölümü biçiminde verilen eşitsizliklerin çözüm kümesi buldurulur.", "b) Bilgi ve iletişim teknolojilerinden yararlanılarak çizilen grafikler yardımıyla çözüm yorumlatılır."]'::jsonb, '{}'::jsonb, 85, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#86', 'yks-2026-matematik', 'yks-2026-matematik#15', '11.4.2.2', 'İkinci dereceden bir bilinmeyenli eşitsizlik sistemlerinin çözüm kümesini bulur.', NULL, '["GEOMETRİ"]'::jsonb, '{}'::jsonb, 86, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#87', 'yks-2026-matematik', 'yks-2026-matematik#16', '11.5.1.1', 'Çemberde teğet, kiriş, çap, yay ve kesen kavramlarını açıklar.', NULL, '["Bir çember ile bir doğrunun birbirlerine göre durumları ele alınır."]'::jsonb, '{}'::jsonb, 87, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#88', 'yks-2026-matematik', 'yks-2026-matematik#16', '11.5.1.2', 'Çemberde kirişin özelliklerini göstererek işlemler yapar.', NULL, '["a) Bir çemberde, kirişin orta dikmesinin çemberin merkezinden geçtiği ve bir kirişin orta noktasını çemberin merkezine birleştiren doğrunun da kirişe dik olduğu gösterilir.", "b) Bir çemberde kirişlerin uzunlukları ile merkeze olan uzaklıkları arasındaki ilişki üzerinde durulur."]'::jsonb, '{}'::jsonb, 88, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#89', 'yks-2026-matematik', 'yks-2026-matematik#16', '11.5.2.1', 'Bir çemberde merkez, çevre, iç, dış ve teğet-kiriş açıların özelliklerini kullanarak işlemler yapar.', NULL, '["a) Üçgenin çevrel çemberi çizdirilir.", "b) Sinüs teoreminin çevrel çemberin yarıçapı ile ilişkisi üzerinde durulur.", "c) Pergel-cetvelden veya bilgi ve iletişim teknolojilerinden yararlanılır."]'::jsonb, '{}'::jsonb, 89, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#90', 'yks-2026-matematik', 'yks-2026-matematik#16', '11.5.3.1', 'Çemberde teğetin özelliklerini göstererek işlemler yapar.', NULL, '["a) Çemberin dışındaki bir noktadan çizilen teğet parçalarının uzunluklarının eşit olduğu gösterilir.", "b) Üçgenin iç teğet ve dış teğet çemberleri çizilir.", "c) İki çemberin ortak teğetine girilmez.", "ç) Bilgi ve iletişim teknolojileri yardımıyla bir çember ve bu çembere dışındaki bir noktadan iki teğet çizilerek dışarıda alınan noktanın sürüklenmesi suretiyle ortaya çıkan durum ele alınır."]'::jsonb, '{}'::jsonb, 90, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#91', 'yks-2026-matematik', 'yks-2026-matematik#16', '11.5.4.1', 'Dairenin çevre ve alan bağıntılarını oluşturur.', NULL, '["a) Dairenin çevresi ve alanı ile ilgili uygulamalar yapılır.", "b) Daire diliminin alanı ve yay uzunluğu bağıntıları buldurularak uygulamalar yapılır.", "c) Archimedes’in çalışmalarına yer verilir.", "ç) Gerçek hayat problemlerine yer verilir."]'::jsonb, '{}'::jsonb, 91, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#92', 'yks-2026-matematik', 'yks-2026-matematik#17', '11.6.1.1', 'Küre, dik dairesel silindir ve dik dairesel koninin alan ve hacim bağıntılarını oluşturarak işlemler yapar.', NULL, '["a) Gerçek hayat problemlerine yer verilir.", "b) Bilgi ve iletişim teknolojilerinden yararlanılır. VERİ, SAYMA VE OLASILIK"]'::jsonb, '{}'::jsonb, 92, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#93', 'yks-2026-matematik', 'yks-2026-matematik#18', '11.7.1.1', 'Koşullu olasılığı açıklayarak problemler çözer.', NULL, '["a) Olasılık konusunun tarihsel gelişim sürecinden bahsedilir.", "b) Gerçek hayat problemlerine yer verilir."]'::jsonb, '{}'::jsonb, 93, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#94', 'yks-2026-matematik', 'yks-2026-matematik#18', '11.7.1.2', 'Bağımlı ve bağımsız olayları açıklayarak gerçekleşme olasılıklarını hesaplar.', NULL, '["Gerçek hayat problemlerine yer verilir."]'::jsonb, '{}'::jsonb, 94, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#95', 'yks-2026-matematik', 'yks-2026-matematik#18', '11.7.1.3', 'Bileşik olayı açıklayarak gerçekleşme olasılığını hesaplar.', NULL, '["a) Ağaç şemasından yararlanılır.", "b) En fazla üç aşamalı olaylardan seçim yapılır.", "c) “ve, veya” bağlaçları ile oluşturulan olayların olasılıkları hesaplatılır.", "ç) Gerçek hayat problemlerine yer verilir."]'::jsonb, '{}'::jsonb, 95, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#96', 'yks-2026-matematik', 'yks-2026-matematik#18', '11.7.2.1', 'Deneysel olasılık ile teorik olasılığı ilişkilendirir.', NULL, '["Bilgi ve iletişim teknolojilerinden yararlanılır."]'::jsonb, '{}'::jsonb, 96, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#97', 'yks-2026-matematik', 'yks-2026-matematik#19', '12.1.1.1', 'Üstel fonksiyonu açıklar.', NULL, '["a) Üstel fonksiyonlara neden ihtiyaç duyulduğu vurgulanmalıdır.", "b) Üslü ifadeler ve bunlarla yapılan işlemlerin özellikleri hatırlatılır.", "c) Üstel fonksiyonların bire bir ve örten olduğu grafik yardımıyla gösterilir.", "ç) a nın aldığı değerlere göre f(x) = ax fonksiyonunun grafiğinin değişimini incelemek için bilgi ve iletişim teknolojilerinden de yararlanılır."]'::jsonb, '{}'::jsonb, 97, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#98', 'yks-2026-matematik', 'yks-2026-matematik#19', '12.1.2.1', 'Logaritma fonksiyonu ile üstel fonksiyonu ilişkilendirerek problemler çözer.', NULL, '["a) 𝑎𝑎 ∈ ℝ+ −{1} olmak üzere logaritma fonksiyonunun grafiği üstel fonksiyonun grafiğinden yararlanarak çizilir. 𝑦𝑦 = 𝑎𝑎 𝑥𝑥 ve 𝑦𝑦 = 𝑙𝑙𝑙𝑙𝑙𝑙𝑎𝑎 𝑥𝑥 fonksiyonlarının grafiklerinin y=x doğrusuna göre simetrik olduğu belirtilir.", "b) 𝑎𝑎 ∈ ℝ+ −{1} olmak üzere 𝑓𝑓: ℝ+ → ℝ , 𝑓𝑓(𝑥𝑥) = 𝑙𝑙𝑙𝑙𝑙𝑙𝑎𝑎 𝑥𝑥 logaritma fonksiyonunun 𝑎𝑎 > 1 için artan fonksiyon, 0 < 𝑎𝑎 < 1 için azalan fonksiyon olduğu verilir. a nın aldığı değerlere göre logaritma fonksiyonunun grafiğinin değişimini incelemek için bilgi ve iletişim teknolojilerinden yararlanılır.", "c) Gelenbevi İsmail Efendi ve John Napier’in çalışmalarına yer verilir."]'::jsonb, '{}'::jsonb, 98, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#99', 'yks-2026-matematik', 'yks-2026-matematik#19', '12.1.2.2', '10 ve e tabanında logaritma fonksiyonunu tanımlayarak problemler çözer.', NULL, '["e sayısının irrasyonel olduğu vurgulanarak matematikte ve diğer bilim dallarında kullanımından bahsedilir."]'::jsonb, '{}'::jsonb, 99, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#100', 'yks-2026-matematik', 'yks-2026-matematik#19', '12.1.2.3', 'Logaritma fonksiyonunun özelliklerini kullanarak işlemler yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 100, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#101', 'yks-2026-matematik', 'yks-2026-matematik#19', '12.1.3.1', 'Üstel, logaritmik denklemlerin ve eşitsizliklerin çözüm kümelerini bulur.', NULL, '[]'::jsonb, '{}'::jsonb, 101, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#102', 'yks-2026-matematik', 'yks-2026-matematik#19', '12.1.3.2', 'Üstel ve logaritmik fonksiyonları gerçek hayat durumlarını modellemede kullanır.', NULL, '["a) Gerçek hayat durumlarından nüfus artışı, bakteri popülasyonu, radyoaktif maddelerin bozunumu (yarı ömür), fosil yaşlarının tayini, deprem şiddeti (Richter ölçeği), pH değeri, ses şiddeti (desibel) gibi örneklere yer verilir.", "b) İsraf ve tasarruf kavramları hakkında farkındalık oluşturacak örneklere yer verilir.", "c) Bilgi ve iletişim teknolojilerinden yararlanılır."]'::jsonb, '{}'::jsonb, 102, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#103', 'yks-2026-matematik', 'yks-2026-matematik#20', '12.2.1.1', 'Dizi kavramını fonksiyon kavramıyla ilişkilendirerek açıklar.', NULL, '["Sonlu dizi, sabit dizi ve dizilerin eşitliği verilir."]'::jsonb, '{}'::jsonb, 103, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#104', 'yks-2026-matematik', 'yks-2026-matematik#20', '12.2.1.2', 'Genel terimi veya indirgeme bağıntısı verilen bir sayı dizisinin terimlerini bulur.', NULL, '[]'::jsonb, '{}'::jsonb, 104, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#105', 'yks-2026-matematik', 'yks-2026-matematik#20', '12.2.1.3', 'Aritmetik ve geometrik dizilerin özelliklerini kullanarak işlemler yapar.', NULL, '["a) İlk n terim toplamı bulunur.", "b) Toplam sembolü tanıtılır ancak özellikleri verilmez."]'::jsonb, '{}'::jsonb, 105, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#106', 'yks-2026-matematik', 'yks-2026-matematik#20', '12.2.1.4', 'Diziler yardımıyla gerçek hayat durumları ile ilgili problemler çözer.', NULL, '["Aritmetik, geometrik ve Fibonacci dizilerine doğadan, çeşitli sanat dallarından örnekler verilir. GEOMETRİ"]'::jsonb, '{}'::jsonb, 106, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#107', 'yks-2026-matematik', 'yks-2026-matematik#21', '12.3.1.1', 'İki açının ölçüleri toplamının ve farkının trigonometrik değerlerine ait formülleri oluşturarak işlemler yapar.', NULL, '["Dönüşüm ve ters dönüşüm formülleri verilmez."]'::jsonb, '{}'::jsonb, 107, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#108', 'yks-2026-matematik', 'yks-2026-matematik#21', '12.3.1.2', 'İki kat açı formüllerini oluşturarak işlemler yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 108, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#109', 'yks-2026-matematik', 'yks-2026-matematik#21', '12.3.2.1', 'Trigonometrik denklemlerin çözüm kümelerini bulur.', NULL, '["a) 𝑎𝑎, 𝑏𝑏, 𝑐𝑐 ∈ ℝ olmak üzere 𝑎𝑎 𝑠𝑠𝑠𝑠𝑠𝑠𝑠𝑠(𝑥𝑥) + 𝑏𝑏 𝑐𝑐𝑐𝑐𝑐𝑐 𝑔𝑔(𝑥𝑥) = 𝑐𝑐 biçimindeki trigonometrik denklemlerin kökleri buldurulur; a, b ve c katsayıları ile çözüm ilişkilendirilir.", "b) Gerçek hayat problemlerine yer verilir.", "c) El Battani’nin çalışmalarına yer verilir."]'::jsonb, '{}'::jsonb, 109, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#110', 'yks-2026-matematik', 'yks-2026-matematik#22', '12.4.1.1', 'Analitik düzlemde koordinatları verilen bir noktanın öteleme, dönme ve simetri dönüşümleri altındaki görüntüsünün koordinatlarını bulur.', NULL, '["a) Öteleme, simetri ve dönme kavramları hatırlatılır.", "b) Noktanın; noktaya, eksenlere, y=x doğrusuna, bir doğruya göre simetrileri ve doğrunun noktaya göre simetrileri vurgulanır. Doğrunun doğruya göre simetrilerine yer verilmez.", "c) Bilgi ve iletişim teknolojileri yardımıyla öteleme, simetri ve dönme ele alınır."]'::jsonb, '{}'::jsonb, 110, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#111', 'yks-2026-matematik', 'yks-2026-matematik#22', '12.4.1.2', 'Temel dönüşümler ve bileşkeleriyle ilgili problem çözer.', NULL, '["a) Modelleme çalışmalarına yer verilir.", "b) Doğadan ve mimari eserlerden örneklendirme yapılır. SAYILAR VE CEBİR"]'::jsonb, '{}'::jsonb, 111, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#112', 'yks-2026-matematik', 'yks-2026-matematik#23', '12.5.1.1', 'Bir fonksiyonun bir noktadaki limiti, soldan limit ve sağdan limit kavramlarını açıklar.', NULL, '["a) Limit kavramı bir bağımsız değişkenin verilen bir sayıya yaklaşmasından hareketle, tablo ve grafikler yardımıyla açıklanır.", "b) Bilgi ve iletişim teknolojilerinden yararlanılır.", "c) Cauchy’nin çalışmalarına yer verilir."]'::jsonb, '{}'::jsonb, 112, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#113', 'yks-2026-matematik', 'yks-2026-matematik#23', '12.5.1.2', 'Limit ile ilgili özellikleri belirterek uygulamalar yapar.', NULL, '["a) Polinom, köklü, üstel, logaritmik ve trigonometrik fonksiyonlar içeren limit uygulamaları yapılır ancak sonucu ± ∞ olan limit durumlarına girilmez.", "b) Sadece pay ve paydası çarpanlarına ayrılarak belirsizliğin kaldırılabileceği limit örneklerine yer verilir."]'::jsonb, '{}'::jsonb, 113, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#114', 'yks-2026-matematik', 'yks-2026-matematik#23', '12.5.1.3', 'Bir fonksiyonun bir noktadaki sürekliliğini açıklar.', NULL, '["a) Fonksiyonun grafiği üzerinde sürekli ve süreksiz olduğu noktalar buldurulur.", "b) Limitin tarihsel gelişiminden ve Salih Zeki’nin bu alana katkılarından bahsedilir.", "c) Bilgi ve iletişim teknolojileri yardımıyla süreklilik uygulamaları yaptırılır."]'::jsonb, '{}'::jsonb, 114, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#115', 'yks-2026-matematik', 'yks-2026-matematik#23', '12.5.2.1', 'Türev kavramını açıklayarak işlemler yapar.', NULL, '["a) Anlık değişim oranı fizik ve geometri modellerinden yararlanılarak açıklanır.", "b) Verilen bir fonksiyonun bir noktadaki türev değeri ile o noktadaki teğetinin eğimi arasındaki ilişki üzerinde durulur.", "c) Bir fonksiyonun bir noktadaki soldan türevi ve sağdan türevi ile türev arasındaki ilişki açıklanır.", "ç) f(x) = c, 𝑓𝑓(𝑥𝑥) = 𝑎𝑎𝑎𝑎 𝑛𝑛 (𝑎𝑎, 𝑐𝑐 ∈ ℝ, 𝑛𝑛 ∈ ℚ) şeklindeki fonksiyonlar için türev kuralları verilir. Bunun dışındaki fonksiyonların (kapalı ve parametrik fonksiyonlar dâhil) türev kurallarına yer verilmez.", "d) Rolle’nin çalışmalarına yer verilir."]'::jsonb, '{}'::jsonb, 115, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#116', 'yks-2026-matematik', 'yks-2026-matematik#23', '12.5.2.2', 'Bir fonksiyonun bir noktada ve bir aralıkta türevlenebilirliğini değerlendirir.', NULL, '["a) Bir fonksiyonun bir noktada türevli olması için gerek ve yeter şartları inceler.", "b) Fonksiyonun türevli olmadığı noktalarla grafiği arasında ilişki kurulur."]'::jsonb, '{}'::jsonb, 116, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#117', 'yks-2026-matematik', 'yks-2026-matematik#23', '12.5.2.3', 'Türevlenebilen iki fonksiyonun toplamı, farkı, çarpımı ve bölümünün türevine ait kurallar yardımıyla işlemler yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 117, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00')
INSERT INTO public.curriculum_outcomes (id, program_id, unit_id, code, text, topic, limitations, quotas, sort_order, source_id, quota_source_id, text_similarity, source_url, program_version, sha256, fetched_at) VALUES
('yks-2026-matematik#118', 'yks-2026-matematik', 'yks-2026-matematik#23', '12.5.2.4', 'İki fonksiyonun bileşkesinin türevine ait kuralı (zincir kuralı) oluşturularak türev hesabı yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 118, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#119', 'yks-2026-matematik', 'yks-2026-matematik#23', '12.5.3.1', 'Bir fonksiyonun artan veya azalan olduğu aralıkları türev yardımıyla belirler.', NULL, '[]'::jsonb, '{}'::jsonb, 119, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#120', 'yks-2026-matematik', 'yks-2026-matematik#23', '12.5.3.2', 'Bir fonksiyonun mutlak maksimum ve mutlak minimum, yerel maksimum, yerel minimum noktalarını belirler.', NULL, '["Bilgi ve iletişim teknolojilerinden yararlanılarak grafik çizimine yer verilir ve yorumlanır."]'::jsonb, '{}'::jsonb, 120, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#121', 'yks-2026-matematik', 'yks-2026-matematik#23', '12.5.3.3', 'Türevi yardımıyla bir fonksiyonun grafiğini çizer.', NULL, '["a)Grafik çizimleri polinom fonksiyonlarla sınırlandırılır.", "b) Bilgi ve iletişim teknolojilerinden yararlanılır."]'::jsonb, '{}'::jsonb, 121, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#122', 'yks-2026-matematik', 'yks-2026-matematik#23', '12.5.3.4', 'Maksimum ve minimum problemlerini türev yardımıyla çözer.', NULL, '["Gerçek hayat problemlerine yer verilir."]'::jsonb, '{}'::jsonb, 122, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#123', 'yks-2026-matematik', 'yks-2026-matematik#24', '12.6.1.1', 'Bir fonksiyonun belirsiz integralini açıklayarak integral alma kurallarını oluşturur.', NULL, '["a) Belirsiz integral alma kuralları n≠ -1 olmak üzere 𝑓𝑓(𝑥𝑥) = 𝑎𝑎𝑎𝑎 𝑛𝑛 (𝑎𝑎, 𝑐𝑐 ∈ ℝ, 𝑛𝑛 ∈ ℚ) şeklindeki fonksiyonlarla sınırlandırılır.", "b) Bir fonksiyonun bir sabitle çarpımının, iki fonksiyonun toplamının ve farkının integral alma kuralları verilerek uygulamalar yaptırılır."]'::jsonb, '{}'::jsonb, 123, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#124', 'yks-2026-matematik', 'yks-2026-matematik#24', '12.6.1.2', 'Değişken değiştirme yoluyla integral alma işlemleri yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 124, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#125', 'yks-2026-matematik', 'yks-2026-matematik#24', '12.6.2.1', 'Bir fonksiyonun grafiği ile x ekseni arasında kalan sınırlı bölgenin alanını Riemann toplamı yardımıyla yaklaşık olarak hesaplar.', NULL, '["a) Gerçek hayatta karşılaşılan ve değeri alan formülleriyle hesaplanamayan alanların, uygun toplamların limiti olarak ifade edilebileceği açıklanır.", "b) Polinom fonksiyonlarla sınırlandırılır.", "c) Bilgi ve iletişim teknolojilerinden yararlanılır."]'::jsonb, '{}'::jsonb, 125, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#126', 'yks-2026-matematik', 'yks-2026-matematik#24', '12.6.2.2', 'Bir fonksiyonun belirli ve belirsiz integralleri arasındaki ilişkiyi açıklayarak işlemler yapar.', NULL, '[]'::jsonb, '{}'::jsonb, 126, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#127', 'yks-2026-matematik', 'yks-2026-matematik#24', '12.6.2.3', 'Belirli integralin özelliklerini kullanarak işlemler yapar.', NULL, '["Parçalı fonksiyonların belirli integraline yer verilir."]'::jsonb, '{}'::jsonb, 127, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#128', 'yks-2026-matematik', 'yks-2026-matematik#24', '12.6.2.4', 'Belirli integral ile alan hesabı yapar.', NULL, '["a) İki fonksiyonun grafikleri arasında kalan sınırlı bölgenin alanı hesaplanır.", "b) Gerçek hayat problemlerine yer verilir.", "c) Bilgi ve iletişim teknolojilerinden yararlanılır. GEOMETRİ"]'::jsonb, '{}'::jsonb, 128, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#129', 'yks-2026-matematik', 'yks-2026-matematik#25', '12.7.1.1', 'Merkezi ve yarıçapı verilen çemberin denklemini oluşturur.', NULL, '["a) 𝑀𝑀(𝑎𝑎, 𝑏𝑏) merkezli ve 𝑟𝑟 yarıçaplı çemberin standart denklemi (𝑥𝑥 − 𝑎𝑎)2 + (𝑦𝑦 − 𝑏𝑏)2 = 𝑟𝑟 2 yardımıyla çemberin genel denklemi 𝑥𝑥 2 + 𝑦𝑦 2 + 𝐷𝐷𝐷𝐷 + 𝐸𝐸𝐸𝐸 + 𝐹𝐹 = 0 şeklinde elde edilir.", "b) 𝐴𝐴𝑥𝑥 2 + 𝐵𝐵𝑦𝑦 2 + 𝐷𝐷𝐷𝐷 + 𝐸𝐸𝐸𝐸 + 𝐹𝐹 = 0 denkleminin hangi durumlarda çember oluşturduğu gösterilir.", "c) Bilgi ve iletişim teknolojilerinden yararlanılır."]'::jsonb, '{}'::jsonb, 129, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-matematik#130', 'yks-2026-matematik', 'yks-2026-matematik#25', '12.7.1.2', 'Denklemleri verilen doğru ile çemberin birbirine göre durumlarını belirleyerek işlemler yapar.', NULL, '["a) Doğru ile çemberin varsa kesişim noktaları bulunur.", "b) Bilgi ve iletişim teknolojilerinden yararlanılır. ORTAÖĞRETİM 11 VE 12. SINIFLAR TEMEL DÜZEY MATEMATİK DERSİ ÖĞRETİM PROGRAMI"]'::jsonb, '{}'::jsonb, 130, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#1', 'yks-2026-tarih', 'yks-2026-tarih#1', '9.1.1', 'Bir araştırma alanı ve bilim dalı olarak tarihin konusunu, kapsamını ve diğer bilim dallarıyla ilişkisini açıklar.', NULL, '["ortaya çıkan eserler ve değişimler olduğu belirtilir.", "b) Tarih biliminin diğer beşerî ve sosyal bilimler ile fen bilimlerinden farklılıklarına değinilir.", "a) Ortak hafızanın kimlik oluşturma ve toplumsallaşmadaki rolü üzerinde durulur.", "b) Mensubu olduğumuz toplum ve ülke ile içinde yaşadığımız dünyayı anlamak için geçmişi bilmemiz gerektiği üzerinde durulur.", "c) Günümüzde olup bitenleri anlayabilmek ve gelecek hakkında gerçekçi ve akılcı"]'::jsonb, '{}'::jsonb, 1, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#2', 'yks-2026-tarih', 'yks-2026-tarih#1', '9.1.2', 'Tarih öğrenmenin amaç ve yararlarını kavrar.', NULL, '["planlamalar yapabilmek için geçmişte meydana gelenlerin farkındalığına dayanan bir tarih bilincine sahip olmak gerektiği vurgulanır.", "ç) Tarihî olayların, bugünün bakış açısı ve değer yargılarıyla ele alınmasının tarihî gerçeklerin yorumlanmasına etkileri örnek olay ve metinler üzerinden ele alınır.", "a) Farklı toplum ve kültürlerin geçmişin dönemlendirilmesinde kendi tarihlerindeki önemli olayları dikkate aldıklarına değinilir.", "b) Zaman içerisinde kullanılan farklı takvim sistemlerine (güneş yılı ve ay yılı esaslı"]'::jsonb, '{}'::jsonb, 2, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#3', 'yks-2026-tarih', 'yks-2026-tarih#1', '9.1.3', 'Zamanı anlama ve anlamlandırmaya yönelik farklı yaklaşımları analiz eder.', NULL, '["takvimler) ve Türklerin kullandığı takvimlere (On İki Hayvanlı Türk Takvimi, miladi takvim, hicrî takvim, Celâli Takvimi, Rûmî Takvim) değinilir.", "c) Miladi takvim ile hicrî takvim arasındaki temel farklar vurgulanır.", "ç) Yüzyıl hesaplamalarının nasıl yapıldığı açıklanır."]'::jsonb, '{}'::jsonb, 3, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#4', 'yks-2026-tarih', 'yks-2026-tarih#1', '9.2.1', 'Kanıtlardan yola çıkarak yazının icadından önceki zamanlarda yaşayan insanların hayatı hakkında çıkarımlarda bulunur.', NULL, '["hayatta kalma mücadelesi (yeme-içme, giyinme ve barınma) ele alınır.", "b) Yazının icadından önceki dönemde hâkim olan sözlü kültür örneklerine (mitler, kuruluş efsaneleri) kısaca değinilir.", "c) Yazının icadından önceki zamana dair dönemlendirmeye kısaca değinilir."]'::jsonb, '{}'::jsonb, 4, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#5', 'yks-2026-tarih', 'yks-2026-tarih#1', '9.2.2', 'Yazının icadının insanlık tarihinde meydana getirdiği değişimi fark eder.', NULL, '["a) Yazının kullanılmasının yönetim işleri ile vergi ve muhasebe kayıtları üzerindeki etkilerine değinilir.", "b) Kadîm tıp, astronomi ve coğrafya bilimlerinin amaç, konu ve yöntem açılarından modern zamanlardaki bilimlerden ne tür farklılıklara sahip olduğuna değinilir.", "a) İlk Çağ medeniyetleriyle ilgili başlıca olay ve olgular tarih şeridi üzerinde gösterilir. Başlıca gelişmeler olarak Sümerler’in yazıyı bulması (MÖ 3200), Urkagina Yasaları’nın çıkarılması (MÖ 2375), Anadolu’da yazının kullanılmaya başlanması (MÖ 1900), Hammurabi Kanunları (MÖ 1700), Kadeş Savaşı (MÖ 1296), Kadeş Antlaşması (MÖ 1280), Truva Savaşları (MÖ 1260-1250), Ege Göçleri (MÖ 1230), İlk Olimpiyatlar (MÖ 776), Roma’nın kurulması (MÖ 753), Lidyalıların parayı kullanmaya başlamaları (MÖ 680), Pers İmparatorluğu’nun kurulması (MÖ 550), İskender İmparatorluğu’nun kurulması (MÖ 359), Pers İmparatorluğu’nun yıkılması (MÖ 330), İskender"]'::jsonb, '{}'::jsonb, 5, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#6', 'yks-2026-tarih', 'yks-2026-tarih#1', '9.2.3', 'İlk Çağ’da yeryüzündeki belli başlı medeniyet havzalarını tanır.', NULL, '["İmparatorluğu’nun yıkılması (MÖ 323), Hz. İsa’nın doğumu (0), Milano Fermanı (313), Roma İmparatorluğu’nda Hristiyanlığın resmi din haline gelmesi (330), İznik Konsülü (325), Kavimler Göçü (375), Roma İmparatorluğu’nun ikiye ayrılması (395) ve Batı Roma’nın yıkılışı (476) verilir. Burada verilen kronolojik sıralama, öğrencilerin kronolojik düşünme becerilerini desteklemeye yöneliktir. Sıralanan olay ve olgulara ilişkin bir konu anlatımı yapılmamalı ve bunların ezberletilmesi yoluna gidilmemelidir.", "b) İlk Çağ’ın önemli medeniyet havzaları (Çin, Hint, İran, Anadolu, Mezopotamya, Mısır, Doğu Akdeniz, Ege Yunan), bu havzalardaki medeniyet teşekkülleri ve bunların insanlığa en önemli katkıları harita/haritalar üzerinde gösterilir.", "a) Konar-göçer ve yerleşik hayat tarzlarının İlk Çağ’dan itibaren birbirlerini tamamlayan ve coğrafi şartlara bağlı olarak tercih edilen hayat tarzları olduğu vurgulanır.", "b) İlk Çağ’da insan topluluklarının kitlesel göçlerinin sebepleri (geçim imkânını"]'::jsonb, '{}'::jsonb, 6, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#7', 'yks-2026-tarih', 'yks-2026-tarih#1', '9.2.4', 'İlk Çağ’da coğrafya ve iklimin, insanların hayat ve geçim tarzları üzerindeki belirleyici etkisini analiz eder.', NULL, '["kaybetme, iklim değişikliği, politik değişiklikler, inanç nedeniyle baskı altına alınma), belli başlı tarihî örneklerle (Ege Göçleri, Filistin’den Yahudi sürgünleri, ilk Hıristiyanların Roma baskısından kaçmaları) ele alınır.", "c) İlk Çağ’daki başlıca tüccar kavimler (Asurlular, Fenikeliler, Lidyalılar ve Soğdlar) ve faaliyet bölgeleri harita üzerinde tanıtılır. Bu toplulukların siyasi tarihlerine ayrıntılı şekilde girilmez."]'::jsonb, '{}'::jsonb, 7, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#8', 'yks-2026-tarih', 'yks-2026-tarih#1', '9.2.5', 'İlk Çağ’da siyasi gücün kaynaklarını siyasi organizasyon türleriyle ilişkilendirir.', NULL, '["a) İlk Çağ’da Asya ve Avrupa’da varlığını sürdüren siyasi organizasyon türleri olarak tiranlık, aristokrasi, monarşi, demokrasi, cumhuriyet ve imparatorluğa değinilir.", "b) Siyasi gücün meşruiyet kaynakları ve siyasi gücün maddi kaynakları (coğrafi yapı, hayat ve geçim tarzı, soy dayanışması, silahlı güç) üzerinde durulur."]'::jsonb, '{}'::jsonb, 8, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#9', 'yks-2026-tarih', 'yks-2026-tarih#1', '9.2.6', 'İlk Çağ’da hukuk sistemlerinin oluşturulmasında etkili olan dinî ve beşerî kaynakları kavrar.', NULL, '["Sözlü ve yazılı hukuk kaynaklarına (akıl, gelenek ve kutsal kitaplar) ilişkin tarihî örnekler (Urkagina ve Hammurabi Kanunları, Hitit Hukuku ve Tevrat) ele alınır."]'::jsonb, '{}'::jsonb, 9, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#10', 'yks-2026-tarih', 'yks-2026-tarih#1', '9.3.1', 'Orta Çağ’da yeryüzünün çeşitli bölgelerinde kurulan siyasi ve sosyal yapıları tanır.', NULL, '["becerilerini desteklemeye yöneliktir. Sıralanan olay ve olgulara ilişkin bir konu anlatımı yapılmamalı ve bunların ezberletilmesi yoluna gidilmemelidir.", "b) Orta Çağ’ın çeşitli dönemlerinde ortaya çıkmış/kurulmuş olan belli başlı siyasi yapılar haritalar üzerinde gösterilir.", "c) Orta Çağ’daki siyasi yapılar; aralarındaki farklılıklar vurgulanarak gücün meşruiyet kaynağı, gücün maddi kaynakları (coğrafi yapı, hayat ve geçim tarzı, soy dayanışması ve silahlı güç), güç paylaşımı ve yönetim organizasyonu temaları çerçevesinde ele alınır.", "a) Tarıma dayalı ekonomilerde artı ürünün bölüşümü ile toprak mülkiyeti ve vergilendirmenin siyasi ve sosyal organizasyonların (monarşi, feodalite, tabakalı toplum, kast sistemi) oluşmasındaki işlevleri ele alınır.", "b) Orta Çağ’da Asya ve Avrupa arasındaki ticarete konu olan mallara, nakliye"]'::jsonb, '{}'::jsonb, 10, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#11', 'yks-2026-tarih', 'yks-2026-tarih#1', '9.3.2', 'Orta Çağ’da tarım ve ticaretin yaygın ekonomik faaliyetler olduklarını kavrar.', NULL, '["araçlarına, ticaret mekânlarına (arasta, bedesten, han, kapan, ribat, kervansaray, pazar, liman, panayır) ve madeni paralara değinilir.", "c) Kral Yolu, İpek Yolu, Kürk Yolu ve Baharat Yolu’nun dünya ticaretindeki rollerine ve bu yollara hâkim olma mücadelelerinin gerekçelerine vurgu yapılır. Söz konusu ticaret güzergâhları harita/haritalar üzerinde gösterilir.", "a) Asya ve Avrupa’da var olan askerî organizasyon türlerine değinilirken bağımsız ya"]'::jsonb, '{}'::jsonb, 11, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#12', 'yks-2026-tarih', 'yks-2026-tarih#1', '9.3.3', 'Orta Çağ’da Asya ve Avrupa’da askerî organizasyon biçimleri ile toplumların yaşam tarzları (konar-göçer ve yerleşik) arasındaki bağlantıları analiz eder.', NULL, '["da ücretli savaşçı toplulukların düzenli ve disiplinli ordulara dönüşmesine de değinilir.", "b) Yerleşik ve konar-göçer toplulukların sosyoekonomik yapıları kazanım bağlamında kısaca ele alınır."]'::jsonb, '{}'::jsonb, 12, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#13', 'yks-2026-tarih', 'yks-2026-tarih#1', '9.3.4', 'İlk Çağ’ın sonlarından itibaren gerçekleştirilen hukuki düzenlemelerin günümüzün evrensel hukuk ilkelerine temel teşkil ettiğini kavrar.', NULL, '["a) Bu dönemin başlıca kanun metinleri (Roma Hukuku, Justinianus Kanunları, Cengiz Yasası) kısaca ele alınır.", "b) Seçme örnek ve uygulamalardan hareketle (hukuki metinler, aile ve iş akitleri, ceza infaz yöntemleri) insan topluluklarının kültür ve gelişmişlik düzeyleri ile sosyal yapılarının hukuk kurallarını ve bu kuralların uygulanmasını farklılaştırdığı vurgulanır."]'::jsonb, '{}'::jsonb, 13, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#14', 'yks-2026-tarih', 'yks-2026-tarih#2', '9.4.1', 'Türklerin Asya’da tarih sahnesine çıktıkları ve yaşadıkları alanlar ile başlıca kültür çevrelerini tanır.', NULL, '["(375), Avrupa Hun Devleti’nin yıkılması (496), I. Kök Türk Devleti’nin kurulması (552), I. Kök Türk Devleti’nin yıkılması (630), II. Kök Türk Devleti’nin kurulması (682), II. Kök Türk Devleti’nin yıkılması (742), Uygur Devleti’nin kurulması (744) ve Uygur Devleti’nin yıkılması (840) verilir. Burada verilen kronolojik sıralama, öğrencilerin kronolojik düşünme becerilerini desteklemeye yöneliktir. Sıralanan olay ve olgulara ilişkin bir konu anlatımı yapılmamalı ve bunların ezberletilmesi yoluna gidilmemelidir.", "a) Asya Hun, Kök Türk ve Uygur Devletleri, gücün meşruiyet kaynağı (Gök Tengri ve Kut inançları); gücün maddi kaynakları (coğrafi yapı, konargöçer hayat tarzı, soy"]'::jsonb, '{}'::jsonb, 14, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#15', 'yks-2026-tarih', 'yks-2026-tarih#2', '9.4.2', 'İlk ve Orta Çağlarda İç Asya’daki Türk siyasi teşekküllerinin güç ve yönetim yapısını kavrar.', NULL, '["dayanışması ve silahlı güç); güç paylaşımı ve yönetim organizasyonu (kurultay, ikili teşkilat yapısı ve ülüş ilkesi) temaları çerçevesinde ele alınır.", "b) “Töre”nin Türk toplum yapısı ve hukuk sistemindeki yeri ve önemi vurgulanır.", "c) Kazanım kapsamındaki konular işlenirken Orhun Kitabelerinden örnekler verilir.", "a) Tarıma uygun olmayan bozkır coğrafyasının Türk topluluklarını konar-göçer hayat tarzına yönelttiği vurgulanır.", "b) Türk topluluklarının çeşitli dönemlerde Asya içlerine ve Asya dışına yaptıkları"]'::jsonb, '{}'::jsonb, 15, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#16', 'yks-2026-tarih', 'yks-2026-tarih#2', '9.4.3', 'İslamiyet öncesi dönemde Türklerin yaşadığı coğrafyalar ile hayat tarzları arasındaki ilişkiyi analiz eder.', NULL, '["kitlesel göçlerin onların hayat tarzlarına etkisi açıklanır.", "c) Askerî kültürün Türk hayat tarzındaki yeri ve öneminden hareketle Türk topluluklarının geliştirdiği ve dünya askerî tarihine mal olmuş teşkilat, teçhizat ve taktikler (süvarilik, onlu teşkilat, ok ve yay, üzengi, Turan taktiği) vurgulanır.", "a) Kavimler Göçü ile Asya ve Avrupa’daki siyasi yapılarda meydana gelen değişim"]'::jsonb, '{}'::jsonb, 16, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#17', 'yks-2026-tarih', 'yks-2026-tarih#2', '9.4.4', 'Kavimler Göçü’nün sebep ve sonuçlarını siyasi ve sosyal açılardan analiz eder.', NULL, '["harita üzerinde gösterilir.", "b) Avrupa Hun Devleti’nin kuruluşuna ve bu devletin Avrupa’ya etkilerine değinilir.", "c) Türk topluluklarına kısaca değinilir."]'::jsonb, '{}'::jsonb, 17, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#18', 'yks-2026-tarih', 'yks-2026-tarih#2', '9.4.5', 'Asya merkezli Türk Devletlerinin çevrelerindeki devletlerle ilişkilerinin çok boyutlu yapısını analiz eder.', NULL, '["a) Hun, Kök Türk, Uygur ve Hazar Devletlerinin Çin, Sasani ve Bizans Devletleri ile ilişkilerinden hareketle konar-göçer ve yerleşik topluluklar arasındaki ilişkilerin çatışma ve uzlaşma eksenli olarak askerî ve ekonomik boyutlarda gerçekleştiği vurgulanır.", "b) Hun, Kök Türk, Uygur ve Hazar siyasi teşekküllerinin hâkimiyetleri altındaki topraklarda ticareti canlandırmaya yönelik politikaları ile bu politikaların gerekçeleri üzerinde durulur."]'::jsonb, '{}'::jsonb, 18, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#19', 'yks-2026-tarih', 'yks-2026-tarih#3', '9.5.1', 'İslamiyet’in doğuşu sırasında Arap Yarımadası, Asya, Avrupa ve Afrika’nın genel durumunu açıklar.', NULL, '["Taif Seferi (630), Tebük Seferi (631), Veda Haccı ve Hz. Muhammed’in vefatı (632) verilir. Burada verilen kronolojik sıralama, öğrencilerin kronolojik düşünme becerilerini desteklemeye yöneliktir. Sıralanan olay ve olgulara ilişkin bir konu anlatımı yapılmamalı ve bunların ezberletilmesi yoluna gidilmemelidir.", "b) Hz. Muhammed’in peygamberliğinin öncesinde Mekke''deki ve Arap Yarımadası’nın geri kalan kısmındaki siyasi durum ve toplumsal düzen ana hatlarıyla ele alınır.", "c) \"Cahiliye Dönemi\" kavramı toplum düzeni açısından açıklanır.", "a) Hz. Muhammed Dönemi’nde Müslümanların kendilerini korumak ve İslam’ı yaymak üzere gerçekleştirdikleri muharebelere değinilir. Muharebelerin sadece önem ve amaçları vurgulanarak diğer ayrıntılara girilmez."]'::jsonb, '{}'::jsonb, 19, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#20', 'yks-2026-tarih', 'yks-2026-tarih#3', '9.5.2', 'Hz. Muhammed ve Dört Halife Dönemi’nde Müslümanların Arap Yarımadası ve çevresinde siyasi hâkimiyet kurmaya yönelik faaliyetlerini kavrar.', NULL, '["b) Medine Sözleşmesi’nin öngördüğü toplum düzeni ve ilk kurumsal yapılanmalar (eğitim, idare, güvenlik ve yargı) ele alınır.", "c) Dört Halife Dönemi’nde İslam toplumunun idaresi, sınırların genişlemesi ve ihtidalar üzerinde durulur.", "ç) Dört Halife Dönemi’nde İslam toplumunda yaşanan siyasi mücadeleler ile sosyal karışıklıkların sebep ve sonuçlarına ana hatlarıyla değinilir.", "a) Emeviler Dönemi’nde hilafetin saltanata dönüştüğü ve Arap olmayan unsurların"]'::jsonb, '{}'::jsonb, 20, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#21', 'yks-2026-tarih', 'yks-2026-tarih#3', '9.5.3', 'Emeviler ile birlikte İslam Devleti’nin yapısında meydana gelen değişimi analiz eder.', NULL, '["(mevali) zaman zaman devlet idaresi ve sosyal yaşamda bazı haklardan mahrum bırakıldıkları vurgulanır.", "b) Emeviler Dönemi’nde inanç ve siyaset ilişkisi ile keskinleşmeye başlayan mezhebi yönelimler ele alınır.", "c) Emeviler Dönemi’nde İslamiyet’in Kuzey Afrika ve Avrupa’daki yayılışına ve İslam kültürünün Avrupa’ya etkilerine değinilir. Endülüs’teki düşünce ve kültür dünyası; önemli şahsiyetler ve tercüme faaliyetleri ekseninde özellikle vurgulanır.", "a) Abbasiler Dönemi’ndeki başlıca siyasi ve sosyal gelişmelere kısaca değinilir.", "b) Halife Me’mun ve Mu’tasım Dönemlerinde Türk asker ve devlet görevlilerinin"]'::jsonb, '{}'::jsonb, 21, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#22', 'yks-2026-tarih', 'yks-2026-tarih#3', '9.5.4', 'Türklerin Abbasi Devleti’ndeki askerî ve siyasi gelişmelerde oynadıkları rolleri kavrar.', NULL, '["Abbasi devlet yönetiminde artan etkisi ve bu durumun sonuçları açıklanır.", "c) İslam hâkimiyetinin Afrika’daki genişlemesinden hareketle Tolunoğulları (868-905), İhşîdîler (935-969), Eyyubiler (1174-1250) ve Memlûk Devleti (1250-1517) öne çıkan özellikleriyle kısaca ele alınır.", "a) İslam medeniyetinin ilim ve eğitim kurumları (Beytü’l-hikme, medreseler, camiler ve kütüphaneler) kısaca tanıtılır.", "b) İslam medeniyetinde kabul görmüş dinî (naklî) ve aklî ilimler ayrımı üzerinde durulur.", "c) İslam âlimlerinin nazari (teorik) ve bütüncül bir perspektifle kişinin kendini, âlemi ve Allah’ı tanıması maksadı güden bir ilim anlayışına sahip oldukları vurgulanır."]'::jsonb, '{}'::jsonb, 22, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#23', 'yks-2026-tarih', 'yks-2026-tarih#3', '9.5.5', 'Sekizinci ve on ikinci yüzyıllar arasında İslam medeniyeti çerçevesindeki ilmî faaliyetleri değerlendirir.', NULL, '["ç) İslam medeniyetine mensup olup farklı bilim alanlarındaki çalışmaları ile düşünce ve bilim tarihine geçmiş önemli âlimleri (Farabi, İbn-i Sina, İmam Gazali, İbn-i Rüşd) öne çıkan çalışmaları, fikir ve eserleri yönüyle ele alınır. İslam kültür ve medeniyetinde farklı ilmî havzalara önemli ekollere ve şahıslara harita ve infografiklerle değinilir.", "d) İslam dünyasında ortaya çıkan bilimsel gelişmelere ve bu gelişmelerin Avrupa’ya etkilerine kısaca değinilir.", "e) İslam medeniyetinde sanata verilen önem ve öne çıkan sanat dallarına değinilir."]'::jsonb, '{}'::jsonb, 23, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#24', 'yks-2026-tarih', 'yks-2026-tarih#4', '9.6.1', 'Türklerin İslamiyet’i kabul etmeye başlamaları ile Türkiye Selçuklu Devleti’nin kuruluşu arasındaki süreçte meydana gelen başlıca siyasi gelişmeleri tarih şeridi ve haritalar üzerinde gösterir.', NULL, '["(840), Gazneli Devleti’nin kurulması (963), Büyük Selçuklu Devleti’nin kurulması (1040), Dandakan Savaşı (1040), Pasinler Muharebesi (1048), Malazgirt Muharebesi (1071) ve Türkiye Selçuklu Devleti’nin kurulması (1077), Harzemşahlar Devleti’nin kurulması (1097), Büyük Selçuklu Devleti’nin yıkılması (1157), Gazneli Devleti’nin yıkılması (1187), Karahanlı Devleti’nin yıkılması (1212), Harzemşahlar Devleti’nin yıkılması (1230) verilir. Burada verilen kronolojik sıralama, öğrencilerin kronolojik düşünme becerilerini desteklemeye yöneliktir. Sıralanan olay ve olgulara ilişkin bir konu anlatımı yapılmamalı ve bunların ezberletilmesi yoluna gidilmemelidir.", "a) Türk topluluklarının İslamiyet’i kabullerinin bir anda ve toplu olarak değil aşamalı"]'::jsonb, '{}'::jsonb, 24, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#25', 'yks-2026-tarih', 'yks-2026-tarih#4', '9.6.2', 'Türklerin İslamiyet’i kabul etme sürecine etki eden faktörleri açıklar.', NULL, '["olarak ve farklı tarihlerde gerçekleştiği vurgulanır.", "b) Acemler, Berberiler ve Kürtlerin İslam dinini kabul etme süreçlerine kısaca değinilir."]'::jsonb, '{}'::jsonb, 25, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#26', 'yks-2026-tarih', 'yks-2026-tarih#4', '9.6.3', 'Karahanlı ve Gazneli örneklerinden hareketle İslamiyet’in kabulünün Türk devlet yapısında ve toplumsal hayatta meydana getirdiği değişimleri analiz eder.', NULL, '["Dönemin yazılı eserleri “Kutadgu Bilig”, “Divânü Lûgati’t-Türk”, “Atabetü’l-Hakayık” ve “Divân-ı Hikmet”e kısaca değinilir.", "a) Oğuz Türklerinin İslamiyet’i kabul etmelerinin Türk ve İslam tarihinde meydana getirdiği siyasi, sosyal ve kültürel etkilere değinilir.", "b) Dandanakan, Pasinler ve Malazgirt Muharebelerinin sebep ve sonuçları kısaca ele"]'::jsonb, '{}'::jsonb, 26, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#27', 'yks-2026-tarih', 'yks-2026-tarih#4', '9.6.4', 'Büyük Selçuklu Devleti Dönemi’ndeki başlıca siyasi gelişmeleri Türk tarihi içerisindeki önemi bağlamında açıklar.', NULL, '["alınır.", "c) Büyük Selçuklu Devleti’nin Tuğrul Bey Dönemi’nde İslam dünyasında koruyucu rol üstlendiğine değinilir.", "ç) Büyük Selçuklu Devleti’nin yıkılış sürecine değinilir.", "a) Büyük Selçuklu Devleti’nin güç ve yönetim yapısı; gücün meşruiyet kaynağı, gücün maddi kaynakları, güç paylaşımı ve yönetim organizasyonu temaları çerçevesinde ele alınır.", "b) İran ve Türk devlet geleneklerine ait unsurların Büyük Selçuklu devlet teşkilatında birlikte yer aldığı vurgulanır."]'::jsonb, '{}'::jsonb, 27, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#28', 'yks-2026-tarih', 'yks-2026-tarih#4', '9.6.5', 'Büyük Selçuklu Devleti’nin yönetim ve toplum yapısını kavrar.', NULL, '["c) Nizâmülmülk’ün “Siyasetnâme” adlı eseri devlet yöneticilerinde aranan özellikler açısından incelenir. Ayrıca Nizamiye Medreseleri yapılanması ve Gazalî’nin bu medereselere etkisine değinilir.", "ç) Selçuklu kültür ve medeniyetinin ana unsurları (bilimsel ve düşünsel gelişim, mimari, sanat ve edebiyat alanlarındaki faaliyetler) işlenir. TARİH DERSİ (10. SINIF) ÖĞRETİM PROGRAMI"]'::jsonb, '{}'::jsonb, 28, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#29', 'yks-2026-tarih', 'yks-2026-tarih#5', '10.1.1', 'Türklerin Anadolu’ya yerleşmeye başlaması ile Türkiye Selçuklu Devleti’nin yıkılışı arasındaki süreçte meydana gelen başlıca siyasi gelişmeleri tarih şeridi ve haritalar üzerinde gösterir.', NULL, '["(1174), Miryokefalon Muharebesi (1176), III. Haçlı Seferi (1189-1192), Moğol İmparatorluğu’nun kurulması (1196), IV. Haçlı Seferi (1202-1204), Bâbailer Ayaklanması (1240), Kösedağ Muharebesi (1243), Memlûklular Devleti’nin kurulması (1250), Ayn-ı Calut Muharebesi (1260), Karamanoğlu Mehmet Bey’in Türkçeyi resmî dil ilan etmesi (1277) ve Türkiye Selçuklu Devleti’nin yıkılması (1308) verilir. Burada verilen kronolojik sıralama, öğrencilerin kronolojik düşünme becerilerini desteklemeye yöneliktir. Sıralanan olay ve olgulara ilişkin bir konu anlatımı yapılmamalı ve bunların ezberletilmesi yoluna gidilmemelidir.", "a) Oğuz göçleri sırasında Türklerin Anadolu’da yerleşmesini kolaylaştıran nedenler kısaca açıklanır.", "b) Türkiye isminin doğuşu açıklanır. Öğrencilerin, Anadolu’nun Türkiye olarak adlandırılmasının"]'::jsonb, '{}'::jsonb, 29, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#30', 'yks-2026-tarih', 'yks-2026-tarih#5', '10.1.2', 'Anadolu’ya yapılan Türk göçlerinin sosyokültürel etkilerini analiz eder.', NULL, '["nedenleri ile ilgili çıkarımda bulunmaları sağlanır.", "c) Öğrencilerin, Anadolu ile birlikte Irak ve Suriye bölgesine yapılan göçlerin, bu bölgelerde günümüze kadar devam eden Türkmen varlığına etkilerini analiz etmeleri sağlanır.", "ç) İç Asya’nın batısında kurulan Türk Devleti’nin devamlılığı Büyük Selçuklu, Türkiye Selçuklu, Osmanlı ve Türkiye Cumhuriyeti devletleri üzerinden vurgulanır."]'::jsonb, '{}'::jsonb, 30, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#31', 'yks-2026-tarih', 'yks-2026-tarih#5', '10.1.3', 'Anadolu’daki ilk Türk siyasi teşekküllerinin birbirleriyle ve çevre devletlerle olan ilişkilerini uzlaşma ve çatışma bağlamında değerlendirir.', NULL, '["a) Anadolu’da kurulan ilk Türk beyliklerinin birbirleriyle ve çevre devletlerle olan ilişkilerine değinilerek öğrencilerin, bu beyliklerin Anadolu’nun Türkleşmesindeki etkisini yorumlamaları sağlanır.", "b) Türkiye Selçuklu Devleti’nin teşkilat yapısı ile sosyokültürel özelliklerine ana hatlarıyla değinilir.", "c) Türkiye Selçuklu Devleti’nin Bizans ile mücadeleleri çerçevesinde Miryokefalon Muharebesi’ne değinilir.", "a) Haçlı Seferleri’nin güzergâhı harita/haritalar üzerinde gösterilir.", "b) Haçlı Seferleri’nin sebeplerine, taraflarına, katılanlarına (çocuk haçlı seferi vurgulanmak üzere),"]'::jsonb, '{}'::jsonb, 31, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#32', 'yks-2026-tarih', 'yks-2026-tarih#5', '10.1.4', 'İslam dünyasının korunması bağlamında Türkiye Selçuklu Devleti ve Eyyubi Devleti’nin Haçlılarla yaptıkları mücadelelerin sosyokültürel etkilerini analiz eder.', NULL, '["Haçlılar tarafından Hristiyanlara, Müslümanlara ve Yahudilere yapılan katliamlara ve Haçlılara karşı mücadele eden komutanlara (I. Kılıç Arslan, Nureddin Zengi ve Selahaddin Eyyubi vurgulanmak üzere) değinilir.", "c) Öğrencilerin, Haçlı Seferleri’nin Avrupa’daki siyasi, sosyal ve ekonomik açıdan dönüştürücü etkisini analiz etmeleri sağlanır.", "ç) Haçlılarla yapılan mücadelenin Anadolu’nun Türk yurdu haline gelmesindeki pekiştirici rolüne değinilir."]'::jsonb, '{}'::jsonb, 32, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#33', 'yks-2026-tarih', 'yks-2026-tarih#5', '10.1.5', 'Moğol İstilası’nın Anadolu’da meydana getirdiği Babailer siyasi ve sosyal değişimi analiz eder.', NULL, '["sonra Anadolu’da İkinci Beylikler Dönemi’nin ortaya çıkması kısaca açıklanır. İsyanı’na Moğol İstilası’nın önünü açması bağlamında değinilerek Kösedağ Muharebesi’nden"]'::jsonb, '{}'::jsonb, 33, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#34', 'yks-2026-tarih', 'yks-2026-tarih#6', '10.2.1', '1302-1453 yılları arasındaki süreçte meydana gelen başlıca siyasi gelişmeleri tarih şeridi ve haritalar üzerinde gösterir.', NULL, '["(1329), İznik’in Fethi (1331), İzmit’in Fethi (1337), Karesi Beyliği’nin alınması (1345), Çimpe Kalesi’nin alınması (1353), Edirne’nin Fethi (1363), Çirmen Muharebesi (1371), I. Kosova Muharebesi (1389), Niğbolu Muharebesi (1396), Ankara Savaşı (1402), Fetret Devri (1402-1413), Varna Muharebesi (1444) ve II. Kosova Muharebesi (1448) verilir. Burada verilen kronolojik sıralama, öğrencilerin kronolojik düşünme becerilerini desteklemeye yöneliktir. Sıralanan olay ve olgulara ilişkin bir konu anlatımı yapılmamalı ve bunların ezberletilmesi yoluna gidilmemelidir.", "a) XIII. yüzyılın sonlarında Anadolu çevresindeki jeopolitik durum açıklanarak Osmanlı Beyliği’nin kuruluşuna ve hanedanın köklerinin Oğuz Türklerine dayandırıldığına değinilir. Konu ile ilgili detaylı"]'::jsonb, '{}'::jsonb, 34, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#35', 'yks-2026-tarih', 'yks-2026-tarih#6', '10.2.2', 'Osmanlı Beyliği’nin devletleşme sürecini Bizans’la olan ilişkileri çerçevesinde analiz eder.', NULL, '["anlatım yapılmaz.", "b) Öğrencilerin, Osmanlı Beyliği’nin sınırlarının genişlemesinin farklı fetih yöntemleri ve politikalar (Türkmen göçleri ve gaza siyaseti) izlenerek uzun sürede nasıl gerçekleştiğini analiz etmeleri sağlanır.", "a) Osmanlı’nın Anadolu’ya nispeten Rumeli’de daha hızlı hâkimiyet kurmasında, Balkanlar’daki toplulukların"]'::jsonb, '{}'::jsonb, 35, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#36', 'yks-2026-tarih', 'yks-2026-tarih#6', '10.2.3', 'Rumeli’deki fetihler ile iskân (şenlendirme) ve istimâlet politikalarının amaçlarını ve etkilerini analiz eder.', NULL, '["yaşadığı iç çekişmelerin (dinî, siyasi, sosyal) etkisi ile Osmanlı idaresinin gayrimüslimlere sunduğu imkânlara değinilir. Öğrencilerin, aynı dönemde Avrupa ülkelerindeki farklı inanca sahip olan insanların yaşam koşullarını bu imkânlarla mukayese etmeleri sağlanır.", "b) Rumeli’deki fetihlerin kalıcı olmasında rol oynayan demografik güçlerin (dervişler, aşiretler, akıncı uç beyleri, Ahiyân-ı Rûm, Bâciyân-ı Rûm) ve iskân politikasının önemine değinilir.", "c) XIV. yüzyıldan itibaren Balkanların Türk yurdu olmasıyla Rumeli Türklüğünün doğduğu vurgulanır.", "a) Osmanlı Devleti’nin beyliklere yönelik politikalarındaki değişime değinilir.", "b) Öğrencilerin, Türk dünyasındaki liderlik mücadelesini Yıldırım Bayezid ve Timur örneği üzerinden ele"]'::jsonb, '{}'::jsonb, 36, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#37', 'yks-2026-tarih', 'yks-2026-tarih#6', '10.2.4', 'Osmanlı Devleti’nin Anadolu’da Türk siyasi birliğini sağlamaya yönelik faaliyetlerini ve sonuçlarını analiz eder.', NULL, '["alarak bu mücadelenin Anadolu’daki yansımalarını sebep ve etki açısından analiz etmeleri sağlanır.", "c) Fetret Devri’ne ve Osmanlı siyasi birliğinin yeniden sağlanmasına değinilir. Bu bağlamda Türk varlığının devamı için devletin gerekliliği vurgulanır.", "ç) Sebep ve etkileri bağlamında Şeyh Bedreddin Olayı’na değinilir.", "d) Osmanlı Devleti’nin ilk dönemlerinden itibaren Türkçeyi resmi yazışma dili olarak kullandığı ve bilim dili haline getirdiği vurgulanır."]'::jsonb, '{}'::jsonb, 37, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#38', 'yks-2026-tarih', 'yks-2026-tarih#7', '10.3.1', 'Kuruluş Dönemi’nde Osmanlı askerî gücünü oluşturan farklı muharip unsurları açıklar.', NULL, '["b) Öğrencilerin, bulundukları yerleşim yerlerinde şehitlikleri ziyaret etmeleri ve bununla ilgili bir kompozisyon yazmaları sağlanır.", "c) Diğer Türk beylik ve devletlerinin aksine erken tarihte aşiret güçlerinden düzenli birliklere geçen Osmanlı’nın ilk dönem askerî teşkilatına ve bu teşkilatı oluşturan zümrelere değinilir."]'::jsonb, '{}'::jsonb, 38, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#39', 'yks-2026-tarih', 'yks-2026-tarih#7', '10.3.2', 'Tımar sisteminin özelliklerini siyasi, sosyal ve ekonomik açılardan değerlendirir.', NULL, '["Tımar Sistemi’nin siyasi, sosyal ve ekonomik yönleri kısaca açıklanarak bu sistemin Osmanlı savaş organizasyonundaki rolü vurgulanır.", "a) Kapıkulu Ocağı ile devşirme sisteminin köklerine ve ortaya çıkış sürecine değinilerek bunların merkezî"]'::jsonb, '{}'::jsonb, 39, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#40', 'yks-2026-tarih', 'yks-2026-tarih#7', '10.3.3', 'Yeniçeri Ocağı’nın ve devşirme sisteminin Osmanlı devletleşme sürecine etkisini analiz eder.', NULL, '["devlet yapısının güçlenmesindeki rolleri vurgulanır.", "b) Yeniçeri Ocağı ile birlikte profesyonel askerliğin başlamasının Osmanlı Devleti’ni askerî teşkilat ve güç bakımından diğer Türk devletleri ile dönemin Avrupa devletlerinden ayrıştırdığına değinilir."]'::jsonb, '{}'::jsonb, 40, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#41', 'yks-2026-tarih', 'yks-2026-tarih#8', '10.4.1', 'Sûfîlerin ve âlimlerin öğretilerinin Anadolu’nun İslamlaşmasına etkisini açıklar.', NULL, '["başlıca Türk âlim ve mutasavvıflarının (Ahmet Yesevî, Ahî Evran, Mevlânâ Celâleddîn-î Rumî, Hacı Bektâş- ı Velî, Yunus Emre, Hacı Bayrâm-ı Velî) temel öğretilerini araştırıp ulaştıkları sonuçları paylaşmaları sağlanır."]'::jsonb, '{}'::jsonb, 41, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#42', 'yks-2026-tarih', 'yks-2026-tarih#8', '10.4.2', 'Osmanlı devlet idaresinin ilmiye, kalemiye ve seyfiye sınıflarının birlikteliğine dayalı yapısını analiz eder.', NULL, '["Osmanlı toplum düzenindeki askerî (vergi vermeyen) - reaya (vergi ödeyen) ayrımına değinilerek ilmiye, kalemiye ve seyfiye sınıfları ana hatlarıyla açıklanır.", "a) Türk dünyasında yetişmiş olan bilim insanlarına (Akşemseddin, Ali Kuşçu ve Uluğ Bey) ve çalışmalarına değinilir."]'::jsonb, '{}'::jsonb, 42, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#43', 'yks-2026-tarih', 'yks-2026-tarih#8', '10.4.3', 'Osmanlı coğrafyasındaki bilim, kültür, sanat ve zanaat faaliyetleri ile bunlara bağlı olarak sosyal hayatta meydana gelen değişimleri analiz eder.', NULL, '["b) Ahşap ve taş işlemeciliği, dokumacılık, çinicilik, hat ve ebru sanatlarına değinilir.", "c) Sözlü halk kültürü ile saray çevresi ve belirli şehirlerde oluşan kitabî kültür ana hatlarıyla ele alınır.", "ç) Osmanlı hâkimiyetiyle birlikte Anadolu ve Rumeli’deki şehirlerin yapısındaki dönüşüme (şehir planı, mimari anlayış) değinilir. Öğrencilerin, Bursa ve İstanbul örnekleri üzerinden bir İslam şehrinin nasıl şekillendiğini analiz etmeleri sağlanır."]'::jsonb, '{}'::jsonb, 43, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#44', 'yks-2026-tarih', 'yks-2026-tarih#9', '10.5.1', '1453-1520 yılları arasındaki süreçte meydana gelen başlıca siyasi gelişmeleri tarih şeridi ve haritalar üzerinde gösterir.', NULL, '["Karamanoğlu Beyliği’ne son verilmesi (1474), Kırım’ın Fethi (1475), Boğdan’ın alınması (1476), Arnavutluk’un alınması (1479), İtalya Seferi (1480), Cem Sultan Olayı (1481-1495), İspanya’daki Müslümanların ve Yahudilerin kurtarılması (1492), Çaldıran Muharebesi (1514), Mercidabık Muharebesi (1516) ve Ridaniye Muharebesi (1517) verilir. Burada verilen kronolojik sıralama, öğrencilerin kronolojik düşünme becerilerini desteklemeye yöneliktir. Sıralanan olay ve olgulara ilişkin bir konu anlatımı yapılmamalı ve bunların ezberletilmesi yoluna gidilmemelidir.", "a) Öğrencilerin, Osmanlı Devleti’nin kurumsallaşmasında (idari, kültürel ve demografik boyutlar) İstanbul’un Fethi’nin oynadığı role ilişkin çıkarımda bulunmaları sağlanır.", "b) İstanbul’un Fethi’nin bölgesel ve küresel yansımalarına değinilir."]'::jsonb, '{}'::jsonb, 44, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#45', 'yks-2026-tarih', 'yks-2026-tarih#9', '10.5.2', 'İstanbul’un fetih sürecini sebepleri ve stratejik sonuçları açısından analiz eder.', NULL, '["c) II. Mehmet’in kara ve denizlerdeki fetihlerinin stratejik önemine değinilir.", "ç) Öğrencilerin, Haçlı Seferleri ile İstanbul’un Fethi’ni, İstanbul’a ve şehirdeki mabetlere (Ayasofya vb.) verilen değer bakımından mukayese etmeleri sağlanır.", "d) II. Mehmet’in karakteri, vizyonu, ilme verdiği önem vurgulanarak fethin gerçekleşmesinde onun kişisel özelliklerinin etkisine değinilir."]'::jsonb, '{}'::jsonb, 45, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#46', 'yks-2026-tarih', 'yks-2026-tarih#9', '10.5.3', 'Osmanlı Devleti’nin İslam coğrafyasında hâkimiyet kurmasının Türk ve İslam dünyası üzerindeki etkilerini analiz eder.', NULL, '["I. Selim Dönemi’nde Osmanlı-İran ve Osmanlı-Memlûk ilişkilerine, Türk ve İslam dünyasında liderlik mücadelesi bağlamında değinilir. Başlıca siyasi gelişmeler olarak Belgrad’ın Fethi (1521), Rodos’un Fethi (1522), Mohaç Muharebesi (1526), I. Viyana Kuşatması (1529), İstanbul Antlaşması (1533), Cezayir’in alınması (1533), Preveze Deniz Savaşı (1538), Hint Deniz Seferleri (1538-1553), Tebriz’in alınması (1548), Trablusgarp’ın Fethi (1551),"]'::jsonb, '{}'::jsonb, 46, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#47', 'yks-2026-tarih', 'yks-2026-tarih#9', '10.5.4', '1520-1595 yılları arasındaki süreçte meydana gelen başlıca siyasi gelişmeleri tarih şeridi ve haritalar üzerinde gösterir.', NULL, '["Nahçıvan’ın alınması (1553), Sudan’ın Kızıldeniz sahilinde Sevâkin Adası merkezli Habeş Eyaleti’nin kurulması (1555), Zigetvar Seferi (1566), Yemen’in alınması (1568), Kıbrıs’ın Fethi (1571), İnebahtı Deniz Savaşı (1571), Tunus’un Fethi (1574) ve Fas’ta Osmanlı hâkimiyetinin kurulması (1578) verilir. Burada verilen kronolojik sıralama, öğrencilerin kronolojik düşünme becerilerini desteklemeye yöneliktir. Sıralanan olay ve olgulara ilişkin bir konu anlatımı yapılmamalı ve bunların ezberletilmesi yoluna gidilmemelidir."]'::jsonb, '{}'::jsonb, 47, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#48', 'yks-2026-tarih', 'yks-2026-tarih#9', '10.5.5', 'Kanuni Döneminden itibaren Osmanlı Devleti’nin eriştiği olgunluğu siyasi sınırlar ve devlet teşkilatı açısından açıklar.', NULL, '["Osmanlı Devleti’nin hâkimiyet alanını genişletme çabaları bağlamında Habsburglar ve Safevilerle olan ilişkileri kısaca ele alınır.", "a) Osmanlı Devleti’nin XV ve XVI. yüzyıllardaki stratejik rakiplerine [Venedik, Ceneviz, Portekiz, İspanya, Habsburglar, Safeviler, Memlûkler] karşı uyguladığı uzun vadeli politikalar ve kurduğu stratejik ortaklıklara Osmanlı Devleti’nin Batı, Doğu ve Güney siyaseti bağlamında değinilir."]'::jsonb, '{}'::jsonb, 48, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#49', 'yks-2026-tarih', 'yks-2026-tarih#9', '10.5.6', 'Uyguladığı uzun vadeli stratejinin Osmanlı Devleti’nin dünya gücü haline gelmesindeki rolünü analiz eder.', NULL, '["b) Öğrencilerin, Osmanlı Devleti’nin batıdaki ilerleyişi karşısında Avrupa’da oluşan Türk algısını sebep ve etki açısından analiz etmeleri sağlanır.", "c) Osmanlı’nın XV ve XVI. yüzyıllarda izlediği siyasetin uzun vadeli etkilerine [Roma Katolik Kilisesi’ne karşı Ortodoksluğun ve Protestanlığın himaye edilmesi, Avrupa monarşilerinin varlıklarını devam ettirmeleri (Fransa, İngiltere ve Hollanda), Afrika’daki Müslümanların himaye edilmesi] değinilir.", "ç) Osmanlı Devleti’nin uyguladığı ekonomi politikalarından ticaret yollarının kontrolü ve kapitülasyonlara değinilerek bunlar üzerinden kurulan uzun vadeli stratejik ortaklıklara vurgu yapılır.", "a) Osmanlı Devleti’nin öncelikli olarak bir kıta (kara) gücü olduğu vurgulanır ve dönemin diğer büyük kıta güçlerine kısaca değinilir.", "b) Öğrencilerin, Osmanlı Devleti’nin denizlerde yaptığı fetihlerin Akdeniz hakimiyetine etkisini ve bu bağlamda Kıbrıs’taki Türk varlığının tarihsel önemini analiz etmeleri sağlanır."]'::jsonb, '{}'::jsonb, 49, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#50', 'yks-2026-tarih', 'yks-2026-tarih#9', '10.5.7', 'Osmanlı Devleti’nin takip ettiği kara ve deniz politikalarını analiz eder.', NULL, '["c) Coğrafî Keşifler’e ve sonrasında Asya, Afrika ve Amerika kıtalarında yaşanan katliamlara ve bu bölgelerin zenginliklerinin Avrupa’ya taşınmasına değinilir.", "ç) Coğrafi Keşifler’in Osmanlı Devleti’nin Akdeniz’deki hâkimiyetinde meydana getirdiği değişimler ile okyanus güçlerinin Akdeniz’e nüfuz etme çabalarına değinilir.", "d) Osmanlı Devleti’nin stratejik amaçlı olarak Akdeniz dışına yönelme çabaları bağlamında Hint Deniz Seferleri’ne değinilir."]'::jsonb, '{}'::jsonb, 50, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#51', 'yks-2026-tarih', 'yks-2026-tarih#10', '10.6.1', 'Topkapı Sarayı’nın devlet idaresinin yanı sıra devlet adamı yetiştirilmesinde ve şehir kültürünün gelişmesindeki rollerini analiz eder.', NULL, '["yetiştirilmesinin merkezi olduğu vurgulanır.", "b) Öğrencilerin, Topkapı Sarayı’na gezi/sanal gezi yapmaları ve Topkapı Sarayı’nın Osmanlı medeniyetine etkisine kanıtlar gösteren tanıtım rehberi hazırlamaları sağlanır. Türklerde belirgin bir veraset sisteminin olmamasına, Fatih Kanunnamesi ile padişaha kendi öz kardeşini"]'::jsonb, '{}'::jsonb, 51, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#52', 'yks-2026-tarih', 'yks-2026-tarih#10', '10.6.2', 'Osmanlı Devleti’nde merkezî otoriteyi güçlendirmeye yönelik düzenlemeleri analiz eder.', NULL, '["devletin bekası için katletme izninin verilmesine, müsadere sistemine ve şehzadelerin yetiştirilme usulüne kısaca değinilerek bunların Osmanlı devlet yönetimine etkisi vurgulanır."]'::jsonb, '{}'::jsonb, 52, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#53', 'yks-2026-tarih', 'yks-2026-tarih#11', '10.7.1', 'Osmanlı Devleti’nde millet sisteminin yapısını analiz eder.', NULL, '["Ümmet ve millet kavramlarına değinilerek farklı dinî ve kültürel kimliklere sahip toplum kesimlerini idare etmenin millet sistemi sayesinde mümkün olduğu vurgulanır.", "a) Öğrencilerin, fethedilen bölgelerdeki gayrimüslimlerin yaşadıkları toplumsal değişimi analiz etmeleri"]'::jsonb, '{}'::jsonb, 53, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#54', 'yks-2026-tarih', 'yks-2026-tarih#11', '10.7.2', 'Osmanlı Devleti’nin fethettiği yerleşim yerlerinin İslam kültürünün etkisiyle geçirdiği dönüşümü analiz eder.', NULL, '["sağlanır.", "b) Öğrencilerin, Osmanlı şehirlerindeki mahalle merkezli sosyal hayat unsurlarını (panayır ve şenlikler, dinî törenlerin günlük hayata yansımaları, yemek kültüründeki çeşitlilik, kıraathane/kahvehane ve bozahane kültürü, kıyafetlerdeki çeşitlilik) değişim ve süreklilik açısından analiz etmeleri sağlanır."]'::jsonb, '{}'::jsonb, 54, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#55', 'yks-2026-tarih', 'yks-2026-tarih#11', '10.7.3', 'Osmanlı ekonomik sistemi içerisinde tarımsal üretimin önemini açıklar.', NULL, '["Osmanlı Devleti’nde devletin toprak üzerindeki mülkiyeti ve çifthane sisteminin, zirai üretimin sürdürülmesindeki rolüne değinilir.", "a) Loncaların toplumsal hayat ve mesleki eğitimdeki yerine değinilerek Osmanlı şehirlerindeki başlıca meslek grupları kısaca ele alınır."]'::jsonb, '{}'::jsonb, 55, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#56', 'yks-2026-tarih', 'yks-2026-tarih#11', '10.7.4', 'Lonca Teşkilatının Osmanlı ekonomik sistemi ve toplum yapısındaki yerini analiz eder.', NULL, '["b) Osmanlı ekonomik sistemi içerisindeki başlıca ticaret mekânlarına (liman, kervansaray, pazar yeri, bedesten ve kapan) ve Osmanlı yönetiminin tüketici ve üreticiyi korumak için uyguladığı yöntemlere (narh, denetim ve ihracat yasakları) değinilir.", "a) Vakıfların sosyal hayatta üstlendiği rollere (imar faaliyetleri, dinî ve sosyo-ekonomik hizmetler)"]'::jsonb, '{}'::jsonb, 56, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#57', 'yks-2026-tarih', 'yks-2026-tarih#11', '10.7.5', 'Osmanlı Devleti’nde vakıfların sosyal hayattaki yerini ve önemini açıklar.', NULL, '["TARİH DERSİ (11. SINIF) ÖĞRETİM değinilerek faaliyet alanlarının çeşitliliği vakfiye örnekleri üzerinden kısaca ele alınır.", "b) Öğrencilerin, vakıf sistemine yönelik geçmişteki ve günümüzdeki uygulamaların benzer ve farklı yönlerini karşılaştırmaları sağlanır PROGRAMI"]'::jsonb, '{}'::jsonb, 57, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#58', 'yks-2026-tarih', 'yks-2026-tarih#12', '11.1.1', '1595-1700 yılları arasındaki süreçte meydana gelen başlıca siyasi gelişmeleri tarih şeridi ve haritalar üzerinde gösterir.', NULL, '["(1672), Bahçesaray Antlaşması (1681), II. Viyana Kuşatması (1683), Karlofça Antlaşması (1699) ve İstanbul Antlaşması (1700) verilir. Burada verilen kronolojik sıralama, öğrencilerin kronolojik düşünme becerilerini desteklemeye yöneliktir. Sıralanan olay ve olgulara ilişkin bir konu anlatımı yapılmamalı ve bunların ezberletilmesi yoluna gidilmemelidir.", "a) Avusturya’yla yapılan Zitvatorok Antlaşması ile Avrupa diplomasisinde"]'::jsonb, '{}'::jsonb, 58, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#59', 'yks-2026-tarih', 'yks-2026-tarih#12', '11.1.2', 'XVII. yüzyılda değişen siyasi rekabet içerisinde Osmanlı Devleti’nin izlediği politikaları açıklar.', NULL, '["mütekabiliyet esasının kabul edildiği vurgulanır.", "b) Osmanlı Devleti’nin Kazak meselesinden dolayı kuzeye yönelme politikasına (Hotin-Kamaniçe ve Çehrin seferleri) değinilir.", "c) Kasr-ı Şirin Antlaşması ile Osmanlı Devleti’nin doğu sınırının büyük ölçüde belirlendiğine değinilir.", "ç) Öğrencilerin, II. Viyana kuşatması nedeniyle kurulan Kutsal İttifak’ın etkilerini ve Karlofça Antlaşması’nın tarihsel önemini açıklamaları sağlanır.", "a) Öğrencilerin, Avrupalı güçlerin değişen denizcilik stratejilerini, küresel (askerî ve ekonomik) faaliyetlerini ve uyguladıkları sömürgeciliğin etkilerini analiz etmeleri"]'::jsonb, '{}'::jsonb, 59, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#60', 'yks-2026-tarih', 'yks-2026-tarih#12', '11.1.3', 'Denizcilik faaliyetlerinin içdenizlerden okyanuslara taşınmasının dünya siyasetine ve ticaretine etkilerini analiz eder.', NULL, '["sağlanır.", "b) Osmanlı Devleti’nin Akdeniz ve Karadeniz hâkimiyetinin zayıflamasının sebepleri üzerinde durulur. Bu bağlamda Osmanlı denizciliğinde kadırgadan kalyona geçişe değinilir.", "a) Başlıca siyasi gelişmeler olarak Prut Antlaşması (1711), Pasarofça Antlaşması (1718), Patrona Halil İsyanı (1730), Belgrad Antlaşması (1739), Kapitülasyonların sürekli hale gelmesi (1740), Çeşme Baskını (1770) ve Küçük Kaynarca Antlaşması (1774) verilir. Burada verilen kronolojik sıralama, öğrencilerin kronolojik düşünme becerilerini desteklemeye yöneliktir. Sıralanan olay ve olgulara ilişkin bir konu"]'::jsonb, '{}'::jsonb, 60, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#61', 'yks-2026-tarih', 'yks-2026-tarih#12', '11.1.4', '1700-1774 yılları arasındaki süreçte Osmanlı Devleti’nin diğer devletlerle yürüttüğü rekabeti ve bu rekabette uyguladığı stratejileri analiz eder.', NULL, '["anlatımı yapılmamalı ve bunların ezberletilmesi yoluna gidilmemelidir.", "b) Osmanlı Devleti’nin Karlofça Antlaşması’yla kaybettiği toprakları geri alma stratejisine değinilir.", "c) Safevi Türk Devleti’nde yaşanan hanedan değişikliğinin Osmanlı Devleti’nin İran ve Rusya ile olan ilişkilerindeki etkisine değinilir.", "ç) 1768-1774 Osmanlı-Rus Savaşı sebep ve sonuçları bakımından ele alınır. Bu bağlamda öğrencilerin, Kırım’ın kaybedilmesini tarihsel önem açısından analiz etmeleri sağlanır."]'::jsonb, '{}'::jsonb, 61, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#62', 'yks-2026-tarih', 'yks-2026-tarih#13', '11.2.1', 'Avrupa düşüncesinde meydana gelen değişimleri ve bunların etkilerini analiz eder.', NULL, '["b) Öğrencilerin, modern devletler hukukunun ortaya çıkması sürecinde Vestfalya Barışı’nı sebep ve etki açısından analiz etmeleri sağlanır.", "c) Bilim Devrimi’nin Avrupa’da meydana getirdiği değişime değinilir.", "a) Coğrafi Keşifler’in ardından Avrupa’ya ve dünyaya yayılan değerli madenlerin ortaya çıkardığı ekonomik değişimin Osmanlı coğrafyasında enflasyona yol açtığı vurgulanır.", "b) Kapitülasyonların sürekli hale gelmesinin Osmanlı ekonomisine etkisine değinilir.", "c) Merkantilist ekonomi ve Askerî Devrim’in, Osmanlı Devleti’nin toprak düzeninde ve buna bağlı savaş organizasyonunda yol açtığı zorunlu dönüşümler (Yeniçeri"]'::jsonb, '{}'::jsonb, 62, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#63', 'yks-2026-tarih', 'yks-2026-tarih#13', '11.2.2', 'Avrupa’daki gelişmelere bağlı olarak Osmanlı idari, askerî ve ekonomik yapısında meydana gelen değişimleri analiz eder.', NULL, '["Ocağı mevcudunun artışı ve devşirme sisteminin sona ermesi; tımar sisteminin önemini yitirmesiyle ordunun lojistik sisteminin bozulması) kısaca açıklanır.", "ç) Öğrencilerin, Avrupalıların değişen savaş stratejileri üzerine Osmanlı ordusunun kale kuşatmasında uzmanlaşırken meydan muharebelerinde tecrübe kaybetmesini ve bunun etkilerini analiz etmeleri sağlanır.", "d) Osmanlı Devleti’nde artan savaş finansmanını karşılamak için alınan tedbirlere (vergilerin arttırılması, iltizam ve malikâne sistemleri ve olağanüstü̈ savaş vergileri) değinilir.", "a) XVII ve XVIII. yüzyıllarda gerçekleşen isyanlar (Celâli ve Yeniçeri isyanları) kısaca ele alınır.", "b) İç siyasi karışıklıklara engel olmak amacıyla Ekber ve Erşed Sistemi’nin ihdas edildiğine değinilir.", "c) Layihalarda sunulan çözüm önerilerine Koçi Bey Risalesi örneği üzerinden"]'::jsonb, '{}'::jsonb, 63, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#64', 'yks-2026-tarih', 'yks-2026-tarih#13', '11.2.3', 'Osmanlı devlet idaresi ve toplum düzenindeki çözülmeleri önleme çabalarını analiz eder.', NULL, '["değinilir.", "ç) Lâle Devri olarak bilinen dönemdeki yeniliklerin Osmanlı sosyal hayatındaki etkileri kısaca ele alınır.", "d) Avrupa’da matbaanın kullanılmaya başlanmasının bilginin üretilmesi ve bilgiye erişim alanlarında sağladığı imkânlara temas edilerek Osmanlı Devleti’nde Müslüman ve gayrimüslimlerin matbaayı kullanmaya başlama süreçlerine değinilir.", "e) Öğrencilerin, dönemin ilim ve irfan geleneğini canlandıran kişilerden (Evliya Çelebi, Katip Çelebi vb.) birini araştırmaları ve bu kişinin Osmanlı ilim ve irfan geleneğindeki yerine ilişkin çıkarımlarda bulunmaları sağlanır.", "f) Öğrencilerin, 1595-1800 yılları arasında hüküm süren padişahlardan birinin idare tarzını dönem in bakış açısıyla değerlendirmeleri sağlanır."]'::jsonb, '{}'::jsonb, 64, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#65', 'yks-2026-tarih', 'yks-2026-tarih#14', '11.3.1', 'Fransız İhtilali ve Avrupa’da Sanayi Devrimi ile birlikte devlet-toplum ilişkilerinde meydana gelen dönüşümü açıklar.', NULL, '["Macaristan, Rusya ve Osmanlı) siyasi hayatlarına etkilerine ilişkin örneklere değinilir.", "ç) Geleneksel üretim tarzı ile endüstriyel üretim tarzı arasındaki farklara değinilir.", "d) Avrupa’da Sanayi İnkılabı sonrasında belirginleşen sınıflı toplum yapısının mutlakiyetçi monarşilerin anayasal monarşilere dönüşmesi üzerindeki etkisine değinilir. Öğrencilerin, Avrupa devletlerinin sömürgecilik faaliyetleri kapsamında yaptıkları"]'::jsonb, '{}'::jsonb, 65, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#66', 'yks-2026-tarih', 'yks-2026-tarih#14', '11.3.2', 'Sanayi İnkılabı sonrası Avrupalıların giriştiği sistemli sömürgecilik faaliyetleri ile küresel etkilerini analiz eder.', NULL, '["katliamların etkileri hakkında çıkarımlarda bulunmaları sağlanır.", "a) Fransız İhtilali sonrasında Avrupa’da uygulanmaya başlanan zorunlu askerlik sisteminin gerekçelerine ve sosyo-politik etkilerine değinilir."]'::jsonb, '{}'::jsonb, 66, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#67', 'yks-2026-tarih', 'yks-2026-tarih#14', '11.3.3', 'Osmanlı Devleti’nde modern ordu teşkilatı ve yurttaş askerliğine yönelik düzenlemelerin siyasi ve sosyal boyutlarını analiz eder.', NULL, '["b) Öğrencilerin, Osmanlı Devleti’nin yeni düzenli ordu kurma teşebbüslerinin (Nizam-ı Cedit, Yeniçeri Ocağı’nın kaldırılması ve Asâkir-i Mansûre-i Muhammediye) gerekçelerini analiz etmeleri sağlanır.", "a) Ulaşım ve haberleşme sektörlerindeki gelişmelerin (demiryolu, telgraf) merkezî idarelere hâkimiyet alanları üzerindeki otoritelerini arttırma imkânı vermesi Osmanlı Devleti örneği üzerinden ele alınır.", "b) Avrupa devletleriyle girilen siyasi ve askerî rekabet çerçevesinde açılan"]'::jsonb, '{}'::jsonb, 67, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#68', 'yks-2026-tarih', 'yks-2026-tarih#14', '11.3.4', 'Ulus devletleşme ve endüstrileşme süreçlerinin sosyal hayata yansımalarını analiz eder.', NULL, '["kurumlara (Hendesehane ve Mühendishaneler, Mekteb-i Harbiye, Tıbbiye, Mülkiye ve diğer meslek okulları) ve II. Mahmud Dönemi’nden itibaren zorunlu örgün eğitimin başlatılmasına değinilir. Bu kurumların ulus devletleşme süre- cindeki rolleri kısaca açıklanır.", "c) Osmanlı Devleti’nde açılan azınlık okulları ile yabancı ve misyoner okullarına değinilerek II. Abdülhamit Dönemi’nde devlet tarafından kurulan okullar kısaca ele alınır.", "ç) II. Abdülhamid Dönemi’nde gerçekleştirilen devlet hastanelerinin ve Dârülaceze gibi sosyal yardım kurumlarının kurulması, emeklilik sistemi ve yoksul aylığı uygulamaları ele alınır. Öğrencilerin, bu uygulamaların günümüzde de varlıklarını sürdürdüklerini değişim ve süreklilik açısından analiz etmeleri sağlanır.", "d) Türk tarihinde siyasi ve sosyal alanlardaki yüzyıllar boyunca süren değişime rağmen önemini devam ettiren/varlığını koruyan unsurlara (dil, aile yapısı, bayrak) değinilir."]'::jsonb, '{}'::jsonb, 68, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#69', 'yks-2026-tarih', 'yks-2026-tarih#15', '11.4.1', '1774-1914 yılları arasındaki süreçte meydana gelen başlıca siyasi gelişmeleri tarih şeridi ve haritalar üzerinde gösterir.', NULL, '["Antlaşması (1856), Kanun-î Esasi’nin ilanı (1876), Osmanlı-Rus Savaşı (1877-1878), Berlin Antlaşması (1878), Düyûn-ı Umûmiye İdaresinin kurulması (1881), ll.Meşrutiyet’in ilanı (1908), Trablusgarp Savaşı (1911), I. Balkan Savaşı (1912) ve II. Balkan Savaşı (1913) verilir. Burada verilen kronolojik sıralama, öğrencilerin kronolojik düşünme becerilerini desteklemeye yöneliktir. Sıralanan olay ve olgulara ilişkin bir konu anlatımı yapılmamalı ve bunların ezberletilmesi yoluna gidilmemelidir.", "a) Osmanlı Devleti’nin güç kaybetmesiyle birlikte büyük güçlerin Osmanlı coğrafyasına nüfuz etme, muhtemel bir dağılma durumunda Osmanlı topraklarını paylaşma (Şark Meselesi) veya işgal etme (Kuzey Afrika’daki toprak kayıpları vb.) çabaları küresel güç mücadelesi bağlamında ele alınır.", "b) 1815 Viyana Kongresi ile başlayan süreçte büyük güçlerin müdahalesiyle uluslararası boyut kazanan konular (1821 Rum İsyanı ve sonrasında Yunanistan’ın kurulması ve Osmanlı Devleti aleyhine topraklarını genişletmesi, Kırım Savaşı ve sonrasında Osmanlı Devleti’nin Paris Antlaşması ile Avrupa devletler hukukuna dâhil edilmesi, 93 Harbi ve sonrasında Berlin Kongresi ile Doğu Anadolu’daki Ermeni Meselesi) bağlamında Osmanlı Devleti’nin varlığının Avrupalı devletler tarafından tehdit edildiği üzerinde durulur.", "c) Mehmet Ali Paşa’nın Osmanlı Devleti’nin merkezi yönetimine rağmen güç"]'::jsonb, '{}'::jsonb, 69, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#70', 'yks-2026-tarih', 'yks-2026-tarih#15', '11.4.2', 'Osmanlı Devleti’nin siyasi varlığına yönelik iç ve dış tehditleri analiz eder.', NULL, '["kazanması ve nüfuz alanını genişletme çabalarına değinilir.", "ç) Rusya’nın Türk Boğazları ile ilgili talepleri karşısında Avrupalı güçlerin Osmanlı Devleti’nin yanında yer almasına ve bunun gerekçelerine değinilir.", "d) Öğrencilerin, 1768-1914 arasındaki süreçte Osmanlı-Rus rekabetini sebep- sonuç ilişkisi açısından analiz etmeleri sağlanır.", "e) Avrupa devletleri arasındaki bloklaşmalarla değişen uluslararası şartlara değinilerek Avrupa’daki topraklarını kaybeden Osmanlı Devleti’nin çeşitli büyük güçlerle ittifak arayışları ele alınır.", "f) Birinci Dünya Savaşı öncesinde ülke dışındaki Müslüman toplulukların (Arakan, Azerbaycan, Moritus vb.) Osmanlı Devleti’ne yaptığı yardımlara değinilir. Öğrencilerin, bu yardımlarda bulunanların duygu, düşünce ve amaçlarına dair çıkarımlarda bulunmaları sağlanır.", "a) Öğrencilerin, Sened-i İttifak, Tanzimat ve Islahat Fermanları ile Kanun-ı Esasî’nin (I. ve II. Meşrutiyet); uluslararası güçler, yerel siyasi aktörler ve ahalinin kriz dönemlerindeki farklı taleplerinin merkezî idare tarafından uzlaştırılmasına yönelik çabalar olduğunu değerlendirmeleri sağlanır.", "b) Mecelle ve Kanun-ı Esasi örnekleri üzerinden Osmanlı hukuk sisteminde meydana gelen değişiklikler; devlet-toplum ilişkileri ve Osmanlı Devleti’nin Avrupa siyasi sistemine entegrasyonu çerçevesinde kısaca ele alınır."]'::jsonb, '{}'::jsonb, 70, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#71', 'yks-2026-tarih', 'yks-2026-tarih#15', '11.4.3', 'Tanzimat Fermanı, Islahat Fermanı ve Kanun-ı Esasi’nin içeriklerini küresel ve yerel siyasi şartlar bağlamında değerlendirir.', NULL, '["c) Osmanlı Devleti’nin dağılmasını önlemeye yönelik Üç Tarz-ı Siyaset olarak bilinen fikir akımlarının, merkezî idarenin ve düşünce adamlarının siyasi ve toplumsal birliği koruma çabaları olduğuna değinilir.", "ç) Osmanlı Devleti’nde XIX. yüzyılda başlayan seçim ve meclis kültürünün (muhtarlıklar, taşra meclisleri, Meşrutiyet dönemlerinde yapılan mebus seçimleri, çok partili hayata geçiş denemeleri) demokratikleşme yolunda atılan adımlar olduğuna değinilir.", "a) 1876, 1909 ve 1913 darbelerinin sebeplerine ve sosyo-politik sonuçlarına ve bu"]'::jsonb, '{}'::jsonb, 71, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#72', 'yks-2026-tarih', 'yks-2026-tarih#15', '11.4.4', '1876-1913 arasında gerçekleştirilen darbelerin Osmanlı siyasi hayatı üzerindeki etkilerini değerlendirir.', NULL, '["süreçte yaşanan toprak kayıplarına değinilir.", "b) Öğrencilerin, Osmanlı Devleti’nde gerçekleştirilen darbeleri ve bunların karakteristik özelliklerini analiz etmeleri sağlanır."]'::jsonb, '{}'::jsonb, 72, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#73', 'yks-2026-tarih', 'yks-2026-tarih#16', '11.5.1', 'Osmanlı Devleti’nin son dönemlerinde endüstriyel üretime geçiş çabalarını ve bu süreçte yaşanan zorlukları analiz eder.', NULL, '["a) Osmanlı Devleti’nde sanayileşme çabalarının önündeki engellere (sermaye, bilim ve teknoloji, yetişmiş personel ve uzun vadeli strateji konularındaki yetersizlikler) değinilir.", "b) Küresel kapitalist güçlerle rekabet etme konusundaki zorluklar; 1838 Balta Limanı Antlaşması örneğinden hareketle gümrük ve ticaret antlaşmalarının sınırlayıcılığı ve yerli üretim yerine ithalatın tercih edilmesi gibi faktörler bağlamında kısaca ele alınır.", "c) 1856’dan sonraki süreçte kamu maliyesinde yaşanan borç krizleri sonucunda Düyûn-ı Umûmiye İdaresinin kurulmasına değinilir.", "ç) Öğrencilerin, Osmanlı Devleti’nin son dönemlerindeki ekonomik duruma dair göstergelerin yer aldığı verileri inceleyip analiz etmeleri sağlanır.", "d) İttihat ve Terakki Hükûmetlerinin hedeflediği Millî İktisat Politikasına değinilir."]'::jsonb, '{}'::jsonb, 73, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#74', 'yks-2026-tarih', 'yks-2026-tarih#16', '11.5.2', 'Osmanlı Devleti’nin son dönemlerindeki nüfus hareketlerinin siyasi, askerî ve ekonomik sebep ve sonuçlarını analiz eder.', NULL, '["a) Osmanlı Devleti’ndeki nüfus artış hızının büyük güçlere nispetle azalmasının uluslararası rekabette güç kaybı üzerindeki etkilerine değinilir.", "b) Öğrencilerin, Osmanlı Devleti’nin toprak kaybetmesiyle başlayan süreçte Türk ve Müslüman ahalinin maruz kaldığı katliamları, İstanbul ve Anadolu’ya yaptıkları göçler sırasında yaşadıklarını tarihsel empati kurarak analiz etmeleri sağlanır.", "a) Modern şehirlerin dokusunda yaşanan değişimin olumlu ve olumsuz sonuçları"]'::jsonb, '{}'::jsonb, 74, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
('yks-2026-tarih#75', 'yks-2026-tarih', 'yks-2026-tarih#16', '11.5.3', 'Modernleşmeyle birlikte sosyal, ekonomik ve politik anlayışta yaşanan değişim ve dönüşümlerin gündelik hayata etkilerini analiz eder.', NULL, '["kısaca ele alınır.", "b) Öğrencilerin, XIX. yüzyıldaki salgın hastalıkların etkilerini ve Osmanlı Devleti’nin buna yönelik aldığı tedbirler kapsamında edinilen tecrübeyi analiz etmeleri sağlanır.", "c) XIX. yüzyılda gazetelerin ve diğer süreli yayınların artmasıyla birlikte kamuoyunun etkin hale geldiği vurgulanır."]'::jsonb, '{}'::jsonb, 75, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00')
